INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (110071, '侵蚀', 0, '攻击速度提升10％{{颜色|烙痕橙|（属性乘区·额外攻击速度）}}，触发{{颜色|烙痕蓝|【蚀爆伤害】}}后，20秒内自身攻击目标使目标受到的伤害提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（【目标减益乘区·目标受伤害增加】）}}，每40秒最多触发一次', NULL, '0', '菱形', '0', '302', '0.2,0.35,0.5', '0.2,0.35,0.5', '0', '0', '0', 1, 4, 0, 0);
