INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (110083, '元素半衰期', 0, '登场时，提升{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|45％（等级2时）}}/{{颜色|烙痕蓝|60％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外元素伤害；经过15秒时，该效果衰减至1/2，经过30秒时，该效果衰减至1/4', NULL, '0', '菱形', '水,雷,炎,霜,风,蚀', '105', '0.1,0.15,0.2', '0.1,0.15,0.2', '0', '0', '0', 0, 4, 0, 0);
