INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (110101, '治愈加速', 0, '每次治疗自身或其他友方同调者，都会永久使自身的额外攻击速度提升2％{{颜色|烙痕橙|（属性乘区·额外攻击速度）}}，最多提升{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|40％（等级2时）}}/{{颜色|烙痕蓝|60％（等级3时）}}', NULL, '0', '三角', '0', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
