INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (110160, '自愈能量', 3, '对自身施加生命回复效果时，所有友方同调者获得2层{{颜色|烙痕蓝|【激励】}}。每20秒最多触发一次，通过该方式获得的{{颜色|烙痕蓝|【激励】}}不超过{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层', NULL, '1021', '三角', '0', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (110161, '危险预警', 0, '同调者离开{{颜色|烙痕蓝|【隐匿】}}状态时，会使场上除自身以外其他相同元素的同调者攻击速度、额外攻击力提升{{颜色|烙痕蓝|8％（等级1时）}}/{{颜色|烙痕蓝|16％（等级2时）}}/{{颜色|烙痕蓝|24％（等级3时）}}{{颜色|烙痕橙|（【属性乘区·额外攻击力加成】）}}，持续30秒，对目标重复施加该效果时将会刷新效果的持续时间', NULL, '1056', '0', '水,雷,炎,霜,风,蚀', '207', '0.08,0.16,0.24', '0.08,0.16,0.24', '0', '0', '0', 1, 4, 0, 0);
