INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120130, '受击反制', 3, '受到直接伤害会令场上所有敌方单位后续受到的伤害提高{{颜色|烙痕蓝|0％~20％（等级1时）}}/{{颜色|烙痕蓝|0％~40％（等级2时）}}/{{颜色|烙痕蓝|0％~60％（等级3时）}}（{{颜色|烙痕蓝|【防御依赖】}}）{{颜色|烙痕橙|（【目标减益乘区·目标受伤害增加】）}}，持续5秒，首领单位生效减半，相同效果无法叠加，对目标重复施加该效果时将会刷新效果的持续时间', NULL, '0', '0', '0', '302', '0.1,0.2,0.3', '0.1,0.2,0.3', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120132, '复数共振', 0, '普通攻击造成群体伤害时，伤害额外提高{{颜色|烙痕蓝|24％（等级1时）}}/{{颜色|烙痕蓝|48％（等级2时）}}/{{颜色|烙痕蓝|72％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}', NULL, '1011,1073', '三角', '0', '105', '0.24,0.48,0.72', '0.24,0.45,0.72', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120134, '手执利兵·三角', 0, '物理伤害造成暴击后，提升自身{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|45％（等级2时）}}/{{颜色|烙痕蓝|60％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·技能增伤）}}普通攻击伤害，持续10秒，每20秒最多触发一次', NULL, '1011', '三角', '物理', '103', '0.3,0.45,0.6', '0.3,0.45,0.6', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120140, '麻痹大意', 3, '触发{{颜色|烙痕蓝|【传导反应】}}时，受影响的目标受到的伤害提高{{颜色|烙痕蓝|40％（等级1时）}}/{{颜色|烙痕蓝|70％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}{{颜色|烙痕橙|（【目标减益乘区·目标受伤害增加】）}}（该效果属于{{颜色|烙痕蓝|【元素反应触发增伤】}}），持续10秒', NULL, '2023', '方块', '雷', '303', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120150, '压力反制', 3, '刻印防御不低于500时，场上每有一个敌方单位，自身获得5％{{颜色|烙痕橙|（属性乘区·刻印攻击百分比增加）}}刻印攻击的提升，最多提升{{颜色|烙痕蓝|15％（等级1时）}}/{{颜色|烙痕蓝|30％（等级2时）}}/{{颜色|烙痕蓝|45％（等级3时）}}', NULL, '0', '0', '0', '205', '0.45,0.45,0.45', '0.45,0.45,0.45', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120152, '电磁风暴', 0, '同调者重伤时，{{颜色|烙痕蓝|【眩晕】}}全场所有机械单位10秒，飞行单位则会被击落。所有受到影响的非首领单位受到相当于其生命最大值{{颜色|烙痕蓝|10％（等级1时）}}/{{颜色|烙痕蓝|30％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}的伤害', NULL, '0', '菱形', '0', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120160, '雷霆寒霜', 3, '同调者受到来自精英/首领单位的伤害后，获得{{颜色|烙痕蓝|6％（等级1时）}}/{{颜色|烙痕蓝|12％（等级2时）}}/{{颜色|烙痕蓝|20％（等级3时）}}{{颜色|烙痕橙|（属性乘区·刻印专精百分比增加）}}刻印专精提升，持续30秒，如果同调者为霜元素/雷元素，则该效果翻倍，每50秒最多触发一次', NULL, '0', '0', '0', '201', '0.06,0.12,0.2', '0.06,0.12,0.2', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120161, '距离把控', 0, '同调者对自身普通攻击范围内的敌方造成伤害时，伤害额外提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，受到来自自身普通攻击范围外的伤害减少20％{{颜色|烙痕橙|（减伤乘区·受伤害减少）}}', NULL, '0', '方块', '0', '105', '0.2,0.35,0.5', '0.2,0.35,0.5', '0', '0', '0', 0, 4, 0, 0);
