INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120170, '创痕激发', 3, '攻击处于元素区域的目标时，使目标后续30秒内受到的伤害提升{{颜色|烙痕蓝|10％（等级1时）}}/{{颜色|烙痕蓝|20％（等级2时）}}/{{颜色|烙痕蓝|30％（等级3时）}}{{颜色|烙痕橙|（【目标减益乘区·目标受伤害增加】）}}；攻击处于炎元素区域的目标时，该易伤效果翻倍，重复触发时将刷新效果的持续时间。', NULL, '2001|2002|2003', '菱形', '0', '302', '0.1,0.2,0.3', '0.2,0.4,0.6', '2002', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120180, '屏障·水', 3, '所有同调者受到的伤害减少10％{{颜色|烙痕橙|（减伤乘区·受伤害减少）}}，该效果不叠加。<br>此外，当水元素同调者在施放完屏障类技能后，所有友方同调者获得4层{{颜色|烙痕蓝|【激励】}}，通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数不超过{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层', NULL, '1042', '0', '水', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (120191, '蚀力庇护', 3, '45%刻印攻击', NULL, '0', '0', '蚀', '205', '0.15,0.30,0.45', '0.15,0.30,0.45', '0', '0', '0', 1, 4, 0, 0);
