INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130010, '状态绝佳', 3, '同调者登场后，获得额外40％{{颜色|烙痕橙|（属性乘区·刻印专精百分比增加）}}刻印专精和40％{{颜色|烙痕橙|（属性乘区·额外攻击速度）}}攻击速度的提升，并以每秒{{颜色|烙痕蓝|1.0％（等级1时）}}/{{颜色|烙痕蓝|0.5％（等级2时）}}/{{颜色|烙痕蓝|0.2％（等级3时）}}的速度衰减，该提升最多减少至10％', NULL, '0', '菱形', '0', '201', '0.2,0.3,0.4', '0.2,0.3,0.4', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130011, '能力催化', 0, '伤害造成暴击时，提高自身{{颜色|烙痕蓝|0.5％（等级1时）}}/{{颜色|烙痕蓝|1％（等级2时）}}/{{颜色|烙痕蓝|2％（等级3时）}}{{颜色|烙痕橙|（属性乘区·暴击率）}}暴击率，该效果每2秒最多触发一次，同调者换至后备队时该效果将被移除', NULL, '0', '菱形', '0', '211', '0.075,0.15,0.3', '0.075,0.15,0.3', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130020, '单点突破', 3, '持续对一个目标攻击超过6秒后，提升{{颜色|烙痕蓝|15％（等级1时）}}/{{颜色|烙痕蓝|25％（等级2时）}}/{{颜色|烙痕蓝|35％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害；若同时拥有【集中火力】，则伤害增加效果翻倍；切换攻击目标后计时会重新刷新', NULL, '0', '三角', '0', '105', '0.15,0.25,0.35', '0.3,0.5,0.7', '5001', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130021, '混合打击', 0, '对目标造成物理伤害时，会使目标后续30秒内受到来自自身的非物理伤害额外提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，对目标重复施加该效果时将会刷新效果的持续时间', NULL, '1074', '三角', '0', '105', '0.2,0.35,0.5', '0.2,0.35,0.5', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130030, '集中火力', 3, '持续对一个目标攻击超过6秒后，提升{{颜色|烙痕蓝|15％（等级1时）}}/{{颜色|烙痕蓝|25％（等级2时）}}/{{颜色|烙痕蓝|35％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害；若同时拥有【单点突破】，则伤害增加效果翻倍；切换攻击目标后计时会重新刷新', NULL, '0', '三角', '0', '105', '0.15,0.25,0.35', '0.3,0.5,0.7', '5002', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130031, '片叶不沾身', 0, '若同调者超过12秒没有受到伤害，提升{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害，受到伤害将刷新计时并移除额外伤害提升', NULL, '0', '三角', '0', '105', '0.2,0.35,0.5', '0.2,0.35,0.5', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130034, '强攻·对空', 0, '攻击生命值处于50％以上的空中单位时，提升{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害', NULL, '9999', '三角', '0', '105', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130040, '无畏者', 3, '同调者自身400范围内每增加一名敌人，提升{{颜色|烙痕蓝|10％（等级1时）}}/{{颜色|烙痕蓝|20％（等级2时）}}/{{颜色|烙痕蓝|30％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害，最多提升100％', NULL, '0', '方块', '0', '105', '0.1,0.2,0.3', '0.1,0.2,0.3', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130041, '轻车熟路', 0, '使用主动技能后，增加自身{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|53％（等级2时）}}/{{颜色|烙痕蓝|75％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·技能增伤）}}普通攻击伤害，持续40秒', NULL, '1011', '菱形', '0', '103', '0.3,0.53,0.75', '0.3,0.53,0.75', '0', '0', '0', 0, 4, 0, 0);
