INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (130051, '弱点石化', 0, '每当同调者使目标处于{{颜色|烙痕蓝|【石化】}}状态，后续20秒内目标受到来自自身的伤害额外提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，对目标重复施加该效果时将会刷新效果的持续时间', NULL, '9999', '三角', '0', '105', '0', '0', '0', '0', '0', 0, 4, 0, 0);
