INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140082, '元素残留', 0, '自动技能造成范围元素伤害时，使受影响的敌方单位后续20秒内受到该元素伤害额外提升{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|35％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}；由不同类型元素伤害造成的效果可以同时存在', NULL, '1073,1014', '菱形', '水,雷,炎,霜,风,蚀', '105', '0.2,0.35,0.5', '0.2,0.35,0.5', '0', '0', '0', 1, 4, 0, 0);
