INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140091, '失控元素', 0, '自动技能对目标造成元素伤害时，附带{{颜色|烙痕蓝|80％（等级1时）}}/{{颜色|烙痕蓝|160％（等级2时）}}/{{颜色|烙痕蓝|240％（等级3时）}}自身专精的额外伤害，每次技能对同一目标最多生效一次', NULL, '0', '菱形', '水,雷,炎,霜,风,蚀', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140100, '统筹备战', 3, '每8秒获得1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层<br>每次队伍中有同调者重伤时，移除4层所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '0', '0', '0', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140110, '寒霜雷涌', 3, '触发{{颜色|烙痕蓝|【冻结反应】}}/{{颜色|烙痕蓝|【传导反应】}}/{{颜色|烙痕蓝|【电解反应】}}时，场上同调者额外伤害提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|36％（等级2时）}}/{{颜色|烙痕蓝|50％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，持续30秒，重复触发刷新效果持续时间', NULL, '2001|2003', '菱形', '水,霜,雷', '105', '0.2,0.36,0.5', '0.2,0.36,0.5', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140120, '雷寒同调', 3, '触发{{颜色|烙痕蓝|【冻结反应】}}/{{颜色|烙痕蓝|【传导反应】}}/{{颜色|烙痕蓝|【电解反应】}}后，场上所有同调者获得1层{{颜色|烙痕蓝|【激励】}}，该效果每3秒最多触发一次，通过该效果最多获得{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层{{颜色|烙痕蓝|【激励】}}', NULL, '2001|2003', '方块', '水,霜,雷', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140130, '曲流制敌', 3, '同调者施展主动技能攻击处于水元素或霜元素区域的目标后，自身额外伤害提高{{颜色|烙痕蓝|25％（等级1时）}}/{{颜色|烙痕蓝|50％（等级2时）}}/{{颜色|烙痕蓝|75％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，同时使受攻击的目标攻击力降低10％{{颜色|烙痕橙|（目标减益乘区·目标攻击力降低）}}，持续60秒，重复触发时刷新效果的持续时间', NULL, '2001,2003', '0', '0', '105', '0.25,0.5,0.75', '0.25,0.5,0.75', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140131, '主场优势', 0, '当同调者处于与自身元素属性相同的元素地形上时，该同调者获得额外{{颜色|烙痕蓝|12％（等级1时）}}/{{颜色|烙痕蓝|20％（等级2时）}}/{{颜色|烙痕蓝|28％（等级3时）}}{{颜色|烙痕橙|（属性乘区·刻印专精百分比增加）}}刻印专精的提升', NULL, '2001|2003|2002', '0', '水,炎,霜', '201', '0.12,0.2,0.28', '0.12,0.2,0.28', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140140, '物理专精', 3, '场上物理属性同调者人数达到2名或以上时，每6秒提升所有同调者1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层；当场上物理属性同调者人数少于2名时，移除所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '4007', '0', '物理', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140150, '润物无声', 3, '场上水元素的同调者人数达到2名或以上时，每6秒提升所有同调者1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层；当场上水元素的同调者人数少于2名时，移除所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '4004', '0', '水', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140151, '屏障效应', 0, '自身制造屏障后，30秒内自身造成的伤害额外提升{{颜色|烙痕蓝|15％（等级1时）}}/{{颜色|烙痕蓝|30％（等级2时）}}/{{颜色|烙痕蓝|45％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}', NULL, '1049', '0', '0', '105', '0.15,0.3,0.45', '0.15,0.3,0.45', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140152, '水利万物', 0, '水元素同调者产生的治疗和屏障效果可以移除受治疗目标身上所有的{{颜色|烙痕蓝|【减益效果】}}，效果触发间隔{{颜色|烙痕蓝|25.0（等级1时）}}/{{颜色|烙痕蓝|8.0（等级2时）}}/{{颜色|烙痕蓝|1.0（等级3时）}}秒', NULL, '0', '0', '水', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140160, '影盾', 3, '同调者拥有护盾的情况下，受到投射物伤害时获得8％{{颜色|烙痕橙|（属性乘区·刻印专精百分比增加）}}刻印专精提升，持续20秒，重复触发时将刷新效果的持续时间。并减免受到的投射物伤害，数值相当于自身专精的{{颜色|烙痕蓝|50％（等级1时）}}/{{颜色|烙痕蓝|100％（等级2时）}}/{{颜色|烙痕蓝|150％（等级3时）}}，每0.5秒最多触发一次', NULL, '0', '方块', '0', '201', '0.08,0.08,0.08', '0.08,0.08,0.08', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140170, '人多势众', 3, '队伍中能够战斗的同调者数量不低于7人时，每6秒提升所有同调者1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层；当队伍中能够战斗的同调者数量低于7人时，移除所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '0', '0', '0', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140180, '蚀力渗透', 3, '场上蚀元素的同调者人数达到2名或以上时，每6秒提升所有同调者1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层；当场上蚀元素的同调者人数少于2名时，移除所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '4005', '0', '蚀', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140190, '水汽弥漫', 3, '触发{{颜色|烙痕蓝|【传导反应】}}/{{颜色|烙痕蓝|【冻结反应】}}后，提升场上所有同调者{{颜色|烙痕蓝|5％（等级1时）}}/{{颜色|烙痕蓝|9％（等级2时）}}/{{颜色|烙痕蓝|12％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害，持续10秒，最多可叠加5层，重复触发时将会刷新效果的持续时间', NULL, '2001|2003', '0', '水,霜,雷', '105', '0.25,0.45,0.6', '0.25,0.45,0.6', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140200, '冰冻三尺', 3, '刻印专精提升5％{{颜色|烙痕橙|（属性乘区·刻印专精百分比增加）}}，对目标造成霜元素主动技能伤害后，目标受到的霜元素额外伤害提高{{颜色|烙痕蓝|25％（等级1时）}}/{{颜色|烙痕蓝|50％（等级2时）}}/{{颜色|烙痕蓝|75％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，持续30秒，同名效果无法叠加，对目标重复施加该效果时将会刷新效果的持续时间', NULL, '0', '0', '霜', '201', '0.05', '0.05', '0', '0', '0', 1, 4, 0, 0);
