INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (140220, '共振催化', 3, '每次触发元素反应时，自身及与自身职业相同的同调者主动技能回复速度提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|30％（等级2时）}}/{{颜色|烙痕蓝|40％（等级3时）}}{{颜色|烙痕橙|（【属性乘区·主动技能回复速度】）}}，持续20秒', NULL, '0', '菱形', '0', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
