INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (150030, '信号干扰·三角', 3, '释放主动技能/异核技能后，降低全场飞行单位10％{{颜色|烙痕橙|（目标减益乘区·目标攻击力降低）}}攻击力，该效果最多可叠加5层；主动技能/异核技能施放过程中，每成功拦截一个敌方投射物，所有友方同调者获得1层{{颜色|烙痕蓝|【激励】}}。通过该方式获得的{{颜色|烙痕蓝|【激励】}}不超过{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层', NULL, '1053', '三角', '0', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (150040, '蚀入骨髓', 3, '触发{{颜色|烙痕蓝|【蚀爆伤害】}}后，额外残留20点蚀爆值，并在20秒内目标受到的蚀属性伤害额外提高{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|90％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，同名效果无法叠加', NULL, '0', '0', '蚀', '105', '0.3,0.6,0.9', '0.3,0.6,0.9', '0', '0', '0', 1, 4, 0, 0);
