INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200001, '如火如荼', 3, '场上炎元素的同调者人数达到2名或以上时，每6秒提升所有同调者1层{{颜色|烙痕蓝|【激励】}}，最多提升{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层；当场上炎元素的同调者人数少于2名时，移除所有同调者通过该方式获得的{{颜色|烙痕蓝|【激励】}}层数', NULL, '4002', '0', '炎', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200003, '意志永存', 3, '若因自身的主动技能/异核技能导致重伤时，则本场战斗结束前，所有友方同调者获得{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层{{颜色|烙痕蓝|【激励】}}', NULL, '1054', '0', '0', '101', '0.4,0.7,1', '0.4,0.7,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200004, '同步强化', 3, '对除自身外友方同调者施加{{颜色|烙痕蓝|【增益效果】}}时，可额外提升该同调者20％{{颜色|烙痕橙|（属性乘区·暴击伤害）}}暴击伤害，持续15秒；同时，提升所有同调者2层{{颜色|烙痕蓝|【激励】}}，通过此方式获得的{{颜色|烙痕蓝|【激励】}}不超过{{颜色|烙痕蓝|4（等级1时）}}/{{颜色|烙痕蓝|7（等级2时）}}/{{颜色|烙痕蓝|10（等级3时）}}{{颜色|烙痕橙|（增伤乘区·激励）}}层，每28秒最多触发一次', NULL, '1032', '三角', '0', '209', '0.2', '0.2', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200005, '源源不断', 3, '持续施法类自动技能成功施放后，返还50％该技能冷却，且获得{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害提升，持续25秒', NULL, '1076', '三角', '0', '105', '0.3,0.6,1', '0.3,0.6,1', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200006, '左膀右臂·三角', 3, '提升自身召唤物{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害', NULL, '1051', '三角', '0', '105', '0.3,0.6,1', '0.3,0.6,1', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200007, '风之庇佑', 3, '使用风元素对友方进行治疗或附加{{颜色|烙痕蓝|【增益效果】}}时，使目标提升{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外元素伤害，持续20秒，重复施加该效果时将会刷新效果的持续时间，相同效果无法叠加', NULL, '1022|1032', '菱形', '风', '105', '0.3,0.6,1', '0.3,0.6,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200008, '破碎打击', 3, '当击破敌方单位格挡时，对击破目标造成{{颜色|烙痕蓝|200％（等级1时）}}/{{颜色|烙痕蓝|400％（等级2时）}}/{{颜色|烙痕蓝|600％（等级3时）}}刻印攻击的{{颜色|烙痕蓝|【真实伤害】}}，并对目标周围400范围内其他敌方单位造成50％的伤害，该效果对每个目标40秒最多触发一次', NULL, '9999', '方块', '0', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200009, '灵感激活', 3, '同调者释放蚀属性异核技能后，主动技能和自动技能的回复速率提升{{颜色|烙痕蓝|50％（等级1时）}}/{{颜色|烙痕蓝|100％（等级2时）}}/{{颜色|烙痕蓝|150％（等级3时）}}{{颜色|烙痕橙|（【属性乘区·主动技能回复速度】；属性乘区·自动技能回复速度）}}，持续30秒', NULL, '0', '三角', '蚀', '0', '0', '0', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200010, '沉浸舞台', 3, '同调者20秒内未造成伤害时，友方同调者元素伤害额外提高{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}，该效果最多持续15秒，同名效果无法叠加', NULL, '0', '0', '水,雷,炎,霜,风,蚀', '105', '0.3,0.6,1', '0.3,0.6,1', '0', '0', '0', 1, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200011, '锻炼治疗', 3, '对友方同调者造成治疗时，提升自身10％{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害，最多提升{{颜色|烙痕蓝|30％（等级1时）}}/{{颜色|烙痕蓝|60％（等级2时）}}/{{颜色|烙痕蓝|100％（等级3时）}}', NULL, '1022', '菱形', '0', '105', '0.3,0.6,1', '0.3,0.6,1', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200012, '先破后立', 3, '战斗中每累积失去自身10％最大生命值时，使自身获得{{颜色|烙痕蓝|2.5％（等级1时）}}/{{颜色|烙痕蓝|5％（等级2时）}}/{{颜色|烙痕蓝|7.5％（等级3时）}}{{颜色|烙痕橙|（增伤乘区·额外伤害）}}额外伤害提升，该效果最多叠加10层，效果持续整场战斗', NULL, '0', '方块', '0', '105', '0.25,0.5,0.75', '0.25,0.5,0.75', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (200013, '高压雷击', 3, '触发{{颜色|烙痕蓝|【电解反应】}}/{{颜色|烙痕蓝|【爆燃反应】}}/{{颜色|烙痕蓝|【传导反应】}}时，受反应影响的目标后续受到的伤害提高{{颜色|烙痕蓝|20％（等级1时）}}/{{颜色|烙痕蓝|40％（等级2时）}}/{{颜色|烙痕蓝|60％（等级3时）}}{{颜色|烙痕橙|（【目标减益乘区·目标受伤害增加】）}}（该效果属于{{颜色|烙痕蓝|【元素反应触发增伤】}}）', NULL, '2001|2002|2003', '0', '雷', '303', '0.2,0.4,0.6', '0.2,0.4,0.6', '0', '0', '0', 1, 4, 0, 0);
