INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (340080, '焚焰血戮', 3, '战斗开始时会召唤「梦中身」，「梦中身」视为召唤物，且会跟随本体施放部分技能\n本体施放部分技能会获得[石中火]层数（每层提升1%（属性乘区·攻击力加成）基础攻击力；当生命值为100%时每层提升0.15%（属性乘区·基础减伤）基础减伤，随生命值比例降低基础减伤提升，当生命值为30%或以下时每层提升0.5%（属性乘区·基础减伤）基础减伤）\n本体普通攻击造成暴击时回复1秒【毁殇】【毁殇·重明】施放冷却，该效果每2秒最多触发一次\n\n整场战斗过程中，当本体累积减少的生命值达到最大生命值的一定比率时，会依次解封自身能力\nUI 技能描述图标 百里屠苏 1.pngⅠ：比率达到50%时解封，获得20%（属性乘区·暴击率）暴击率提升\nUI 技能描述图标 百里屠苏 1.pngⅡ：比率达到100%时解封，获得20%（属性乘区·暴击伤害）暴击伤害提升；且【业火重明】当前冷却时间减少50秒，仅非重明状态可以触发，每场战斗最多触发一次\nUI 技能描述图标 百里屠苏 1.pngⅢ：比率达到150%时解封，【毁殇】【毁殇·重明】造成伤害时，自身每有1层[石中火]，忽略目标1%（属性乘区·忽略减伤）基础减伤', NULL, '0', '0', '0', '214', '0.45', '0.45', '0', '0', '0', 0, 4, 0, 0);
INSERT INTO `skill` (`skill_id`, `name`, `level`, `desc`, `add_behavior`, `behavior`, `allow_shape`, `allow_element`, `damage`, `min_value`, `max_value`, `max_behavior`, `max_env`, `max_element`, `scope`, `scope_num`, `char_skill_index`, `del`) VALUES (340081, '焚焰血戮·三花', 3, '场上每有一名炎元素同调者（包含自己），百里屠苏造成的伤害提高6%（增伤乘区·独立增伤）', NULL, '0', '0', '0', '106', '0.06', '0.06', '1062', '0', '0', 0, 4, 0, 0);
