INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (4, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/8tfp5dxrzh0lfx0ebj4j7s8r0urnyw0_20250217115911A003.png', 11231027, '序章#灾厄中心 ＞', '主线剧情', '监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖', '1123年10月27日', '森罗', '洛天依,奈默', '我们将在「未来」重逢', '<p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/17/6xra3czbvlz96vdrje5mmx9ot2fphy4_20250217165856A012.png\" alt=\"\" data-href=\"\" style=\"\"></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-0 灾厄中心</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">未来，藏于灾厄中心。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">白荆科技首席执行官监督在完成身份验证后，突然发现自己置身于陷入一级异变警报的海临城中心商业区。刺耳的广播声宣告着天隙通道正以惊人速度扩张，整座城市陷入撤离狂潮。更令其困惑的是，记忆中本应处于1121年4月25日签署合作协议的自己，竟出现在两年后的时空——此刻的电子终端明确显示着1123年10月27日。</span><img src=\"http://r.qianqiu.info/admin/upload/2025/02/17/54xzs6ngkx6pbztyh3luxxk8zqw5144_20250217165911A013.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在废墟中与苏筱重逢时，监督敏锐察觉到异常：本应称呼自己为实习生的苏筱却以\"监督\"相称，而记忆中刚递交入职申请的阳铃、尚未调任的莫红袖等人，此刻竟都已成为并肩作战的战友。最致命的是，这个时空的自己拥有异核能力，但现实中的监督却完全无法感应任何力量波动。当他说出\"现在应该是阳铃提交入职意向书的日子\"时，众人震惊的表情证实了时空错位的猜想。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/17/r6m0bujauwpp69n1g2fq6iv4nfo74lv_20250217165935A014.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">穿过布满提丰子体的禁区外围，监督目睹了更为惊人的场景——白荆科技的无人机在扭曲能量中穿梭，九旻基地的星海小队正在执行最后撤离。在禁区核心区，他们遭遇了自称来自异世界的巨型改造体。激烈的战斗中，监督注意到高空平台上对峙的两人：本该早已卸任的前代监督曲观玄，与某个散发着不祥气息的神秘存在。当神秘存在释放出遮天蔽日的黑色根系时，监督体内突然涌现出未知能量，仿佛某种沉睡的种子即将破土。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/17/31bbzuhgwy0ywcf9y4l6p5249jb9io0_20250217165947A015.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">\"回归本源吧，我们将在未来重逢。\"神秘存在的低语化作实质化冲击波。在意识模糊的瞬间，监督看到曲观玄发动了某种时空禁术。当再次恢复清醒时，vein系统的电子音提示时间已回归1121年4月25日，仿佛长达两年的时空跳跃从未发生。然而胸口残留的能量震颤，与记忆中神秘存在那句\"血脉相连\"的宣言，都在提醒着这场时空迷局背后隐藏着更深的秘密。</span><img src=\"http://r.qianqiu.info/admin/upload/2025/02/17/7t1cv9x2l89gyljfofpcuqm6xdi1giv_20250217170146A016.jpg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场意外的时间跳跃不仅揭示了天隙通道连接多重宇宙的特性，更暴露出监督自身与神秘存在的特殊关联。当众人以为危机暂时解除时，没人注意到曲观玄望着时空漩涡消散的方向，露出了凝重的神色——这个世界的命运轨迹，或许早已因监督的这次\"意外穿越\"发生了不可逆的改变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-12 11:24:17', '2025-02-26 17:42:57', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (5, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/8i54524sbgebp4hushibf82rkjoeqs8_20250217115925A004.png', 11210425, '00#森罗 ＞', '主线剧情', '监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄', '1121年4月25日', '森罗', '洛天依,奈默', '前路迢迢，凶险未知。<br>我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——', '<p style=\"text-align: center; line-height: 2;\"><br></p><p style=\"text-align: center; line-height: 2;\"><a href=\"https://wiki.biligame.com/bjhl/%E6%95%85%E4%BA%8B%E7%BA%BF/%E6%A3%AE%E7%BD%97\" target=\"_blank\"><span style=\"color: rgb(89, 89, 89); font-size: 16px;\"><u>以下为剧情概括，点击查看原文</u></span></a></p><p style=\"text-align: center; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-1 天隙禁区</strong></span><span style=\"font-size: 16px;\"><br>现在是森罗时间1121-04-25 13:52<br>白荆科技首席执行官，身份验证成功。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱正驱车前往天隙禁区，途中得知禁区外聚集了大量示威者。这些幸存者因五年前的天隙事件而饱受创伤，如今对白荆科技及其开发的X能源充满敌意，甚至将同调者视为异类。监督心中泛起一丝怅然，回忆起昔日的城市公园如今已成为禁区的一部分。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">抵达禁区外围，监督目睹了示威者与行动组队员狄砚、克里斯汀的对峙。示威者们言辞激烈，指责白荆科技是X辐射蔓延的罪魁祸首，要求停止X能源研发并驱逐同调者。就在局势即将失控之际，禁区警报突然响起——提丰子体正从矿区涌出，对众人构成威胁。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督意识到事态异常：这些原本只在黎威尔世界出现的虫群，为何会出现在禁区？它们的行动模式也变得更为狡猾。面对突如其来的危机，监督与行动组迅速投入战斗，试图阻止提丰子体的扩散。然而，这一切似乎只是更大风暴的前兆，监督心中隐隐不安，预感着某种未知的危险正在逼近。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-2 虚实之辨</strong></span><span style=\"font-size: 16px;\"><br>假如，我们曾陷入同一场噩梦。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在激烈的战斗中，监督敏锐地察觉到苏筱对“提丰子体”的了解似乎超出了常理。面对监督的疑问，苏筱支支吾吾地表示自己曾做过一个梦，梦中得知了这种虫群的存在。监督对此半信半疑，但无暇深究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着战局推进，众人发现一处被提丰子体冲破的防线缺口，虫群正源源不断地从中涌出。狄砚提议趁敌人与机器人纠缠之际迅速清剿虫群。就在此时，一架无人机突然出现在战场上空，引起了苏筱的注意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚的沉默让苏筱意识到，这架无人机很可能与外围的示威者有关。她惊讶于示威者的行动竟已如此猖獗，甚至动用无人机介入禁区事务。监督意识到事态正在进一步恶化，必须尽快查明真相，阻止更大的危机爆发。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-3 「我」</strong></span><span style=\"font-size: 16px;\"><br>“你是普通人？你怎么会是普通人？！”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在禁区的混乱中，监督与苏筱等人正试图平息示威者的骚动。霍冉作为白荆科技的保安队长，面对示威者的挑衅，情绪激动，甚至准备动手。监督及时制止了他，并指出问题的症结并非同调者与普通人的对立，而是有人在背后恶意鼓动。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">然而，禁区的局势并未因此缓和。随着天隙通道的异常能量波动再次达到峰值，监督意识到事态已刻不容缓。他下令所有同调者立即进入禁区，并指示Vein系统封锁外围大门。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在进入禁区的过程中，监督救下了一位被挤向大门的旧城区少女，叮嘱她尽快离开危险区域。然而，示威者们并未因此罢休，甚至开始攻击那些协助白荆科技的普通人。狄砚果断采取强制措施，阻止了示威者的冲击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">进入禁区后，监督迅速部署任务，要求研究人员前往地下防御设施，战斗单位则在A-0-3区集结。面对即将到来的强大敌人，监督冷静地指挥众人，准备迎接这场未知的挑战。尽管内心仍有许多疑问，但他深知此刻必须抛开一切，直面这位来自异世界的“陌生人”。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-4 联合行动</strong></span><span style=\"font-size: 16px;\"><br>“精神深潜”接入准备——</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在禁区的深处，监督与苏筱等人正与大量提丰子体展开激战。尽管众人奋力抵抗，但虫群的数量似乎源源不断，甚至从后方也出现了新的敌人。监督果断承担起阻击任务，为团队争取时间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">战斗结束后，克里斯汀提出了疑问：以往同调者穿越天隙通道时，从未出现过如此数量的伴生物，这些提丰子体究竟从何而来？就在此时，禁区广播再次响起，天隙通道的异常能量波动已达到第三次峰值，指数飙升至171，警报等级升至高危。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">面对愈发严峻的局势，苏筱担忧人手不足，无法同时应对虫群和即将到来的异世界同调者。狄砚也指出，受异常能量波动影响，他们与外界的通讯已完全中断。监督提议前往S区，那里配备了最尖端的设备，或许能找到解决问题的办法。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">抵达S区后，监督迅速通过Vein系统启动了天隙禁区的紧急预案，并成功接入了监督办公室。狄砚、克里斯汀和霍冉则前往外围警戒，确保区域安全。随着Vein系统的“精神深潜”功能顺利接入，监督开始着手分析当前的危机，寻找破解之道。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-5 来客</strong></span><span style=\"font-size: 16px;\"><br>明明是阳光正好的午后时分，此刻的天色却暗如黑夜。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在S区的紧急行动中，监督成功通过“精神深潜”联系上了R.E.D.的田偌，后者承诺尽快赶来支援。然而，就在众人稍感安心之际，天色骤然变暗，天隙通道仿佛连接向无尽的黑暗深处。巨大的压力使得S区平台摇摇欲坠，最终彻底崩塌，众人随之坠落。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">危急关头，克里斯汀化身为巨大的“飞熊”，及时接住了坠落的监督。尽管惊魂未定，监督仍迅速恢复了冷静，询问起那位穿越天隙通道的神秘人的下落。然而，霍冉表示自己只顾着保命，无暇他顾。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着矿区照明灯的亮起，黑暗中的景象逐渐显现。然而，还未等众人找到目标，矿灯便突然闪烁破裂，机械外壳落地声传来，空气中弥漫起浓重的血腥味。一个神秘的身影在黑暗中逼近，狄砚提醒众人保持警惕。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">面对突如其来的危机，监督迅速作出决策，提议将敌人引出矿道，以避免在狭窄的空间内陷入被动。然而，苏筱指出，矿道内遍布提丰鞘，且防御机器人已难以支撑太久。就在此时，祸烨莲的攻击使得提丰鞘纷纷退避，但神秘人却步步紧逼，田偌也赶到现场，提醒众人小心应对。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-6 归人</strong></span><span style=\"font-size: 16px;\"><br>“骑士长，我可以特许你不加入这场追捕。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在A-0-3区，监督与众人遭遇了来自黎威尔的神秘人物洛特斯。昊苍及时赶到，拦截了洛特斯的攻击，并揭开了他的身份——洛特斯曾是黎威尔的居民，与昊苍有着复杂的过往。尽管两人之间气氛紧张，但洛特斯透露了一个惊人的消息：五年前被认为已死的“圣冕”其实还活着，并且他的追随者——圣殖余孽，已经潜入了森罗世界。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">洛特斯的出现与提丰子体的异常活动密切相关。昊苍解释，提丰子体的存在意味着附近必然有一只提丰母体，而豢养这种魔物的正是他们曾经的“老熟人”——圣冕的追随者。昊苍推测，提丰母体很可能隐藏在圣廷遗址中，那里是X晶石能量最浓郁的区域。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督虽然对洛特斯和昊苍之间的对话感到困惑，但意识到事态的严重性。他决定跟随昊苍前往圣廷遗址，查明提丰母体的真相。然而，监督内心也隐隐不安，因为他曾在梦境中见过提丰子体，而这一巧合让他对当前的局势产生了更多的疑虑。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着众人向圣廷遗址进发，监督和团队即将面对一场未知的挑战，而提丰母体的存在或许只是这场风暴的开始。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-7 取舍</strong></span><span style=\"font-size: 16px;\"><br>——祝我们成功。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在天隙禁区的A-0-1区，监督与团队面对提丰母体“尼米娅”的威胁，展开了激烈的战斗。尼米娅通过吞噬X晶石的能量，意图自爆并摧毁整个禁区。昊苍和洛特斯联手阻止尼米娅，但洛特斯的力量无法完全压制圣冕遗留的神力结晶。监督意识到，唯一的解决办法是提前引爆A-0-1区的X晶石，彻底消耗其能量，阻止尼米娅的自爆。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督迅速制定了计划，指派苏筱、狄砚和克里斯汀分别带队启动外围的X能防护设施，以将自爆的影响控制在禁区内。同时，监督亲自与霍冉前往矿道深处，利用霍冉的异核能力引爆晶石。尽管霍冉对毁掉自家矿区感到痛心，但最终选择信任监督的决定。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在引爆过程中，监督和霍冉遭遇了尼米娅的垂死反扑，险些被其自爆波及。关键时刻，洛特斯的力量再次介入，保护了众人。随着矿道坍塌，监督和霍冉在千钧一发之际逃出生天，成功阻止了尼米娅的自爆危机。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">然而，危机并未完全解除。禁区内外的局势依然混乱，记者和围观者蜂拥而至，舆论的压力接踵而来。监督在曲观玄的陪同下，面对外界的质疑和指责，内心却依旧坚定。监督知道，尽管付出了巨大的代价，但他们成功避免了更大的灾难。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，洛特斯和昊苍的对话也揭示了更深层的阴谋。洛特斯的目光投向远方，似乎看到了这场危机的幕后黑手。而在禁区的另一处，一名神秘女子与一名男子的对话暗示，这场风波远未结束。昊苍则独自一人，面对着即将到来的更大挑战。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和团队虽然暂时化解了危机，但他们深知，真正的风暴或许才刚刚开始。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S0-8 引路人</strong></span><span style=\"font-size: 16px;\"><br>“我们白荆既然致力于研究这些，自然也该担负起相应的责任。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昨日午间，天隙禁区核心区域突发大规模塌方，周边矿区紧急撤离、疏散作业人员近百人。据白荆科技方面透露，本次事故所造成的直接损失已达千万级别。晚间新闻进一步报道，25日下午三时前后，天隙禁区内部多次出现不明兽吼、哀鸣，空中异象与五年前天隙事件前十分相似，但白荆科技对此三缄其口。相关人士透露，禁区事件后，白荆科技内部召开会议，首席执行官曲观玄引咎辞职，消息将于近期公布。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在白荆科技监督办公室，监督醒来后与曲观玄进行了一次深刻的对话。曲观玄解释了引咎辞职的决定，并指出禁区事件中，由于监督的提前安排，同调者及时开启了防护设施，普通人员无一伤亡，但同调者中除克里斯汀外，多数重伤。克里斯汀因异化核心病变，抢救无效去世。监督对此深感自责，但曲观玄安慰道，白荆科技的道路注定了无数次挽回损失，而不是彻底杜绝损失。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">曲观玄进一步阐释了白荆科技的使命，指出天隙事件后，白荆科技收留同调者，发掘、储藏X晶石，将其转化为能源，这是处理外来能量的最佳途径。他强调，白荆科技的首席执行官需要坚定守护这条道路，探索“森罗”作为“中枢”的核心及可能导向的无数种未来。曲观玄将“森罗”命名为世界，象征着无数个世界、无数个同调者在这里汇集。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最后，曲观玄告诉监督，他将离开海临前往恩利都，退休后可能会暂时失联，但会通过邮箱回复留言。在曲观玄转身离开时，监督突然叫住他，询问是否真的可能有这样一个未来，他们会决裂甚至刀剑相向。曲观玄认为这是一个有意思的假设，但强调只要他还活着，就不会让这样的事情发生。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱也提到，监督的幻觉中包括了天隙异变、提丰子体和一个看不清模样的女人，暗示这场幻觉可能与某种阴谋有关。曲观玄叮嘱监督，如果有人刻意针对，那样的幻觉或许还会出现，但不必害怕，他会确保这一切不会发生。最后，曲观玄告别监督，叮嘱其好好休息，照顾好自己。</span></p><p><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:34:16', '2025-02-25 11:05:32', 'admin', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (6, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/ai1qy40yxg69s5de4e1gf517o822c2s_20250217115936A005.png', 11210429, '01#世出世间事 ＞', '主线剧情', '监督,瞳,苏筱,舞鹤织雪,十手卫', '1121年4月29日', '森罗', '洛天依,奈默', '那些隐藏在谎言表象之下的求救讯号，是否也需要回应。', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-1 混乱序曲</strong></span><span style=\"font-size: 15px;\"><br>今晚八点，垂花街口</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·X能源研究室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 17:54 总部81层</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瞳与监督讨论了最新的X辐射检验报告，结果显示监督的细胞异化率和异常活跃指数均为0%，异化风险等级为N级，表明监督并非细胞异化综合征的易感人群。监督对此感到失望，并询问是否存在从非易感人群转变为同调者的可能性。瞳解释，理论上可行，但早年海外实验室的尝试以失败告终，被植入者出现严重排异反应，最终死亡。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提到克里斯汀的死因让自己对体质产生了怀疑，瞳则提醒监督，曲观玄辞职后，监督的研究课题已经停摆很久，要求其一周内提交最新的实验设计和原始数据。与此同时，苏筱通过留言催促监督下班，并提到两人约定一起喝奶茶散心。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·正门</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 18:03</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱汇合，苏筱已经喝完了自己的奶茶，并毫不客气地捧起了监督的那杯。监督告诉苏筱，瞳要求他们明天一起去研究室报到，苏筱对此感到惊讶。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在这时，一个男孩突然从角落跑出来，撞在苏筱的腰上，导致她的奶茶洒在裙子上。男孩道歉后，又朝监督撞来，监督扶住了他。男孩随后鞠躬离开，监督发现衣兜里多了一张纸条，上面写着：“对不起，冒昧地用这种方式打扰您。前几天禁区的事我在新闻上看到了，思索再三，我想我必须提醒您，引发禁区事件的始作俑者就在今晚八点，垂花街口。救救我们，救救孩子。”</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱看到纸条后，惊讶地询问这是否是刚才那个男孩塞给监督的。监督对此感到困惑，意识到这可能与禁区事件的幕后黑手有关。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-2 苦难温床</strong></span><span style=\"font-size: 15px;\"><br>过往伤痛都被小心翼翼地掩盖在了这片光影之下。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·垂花街</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 19:34 熔岩烤肉</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱在垂花街的熔岩烤肉店等待与写信人见面。两人讨论了信件的内容和可能的意图，监督认为写信人可能想找的是曲观玄，而自己穿着白荆科技的衣服是为了表明自己可以代表曲观玄。苏筱提到旧城区居民对同调者和白荆科技的态度通常是“敬而远之”，不支持、不交流、不发声。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">朱阿姨为她们送上了特制冰粉，并提到最近旧城区不太平，出现了几起同调者伤人的案件，导致居民人心惶惶。朱阿姨劝她们不要再冒险开发X能源，但监督表示她们有坚持下去的理由。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱感叹旧城区仿佛被按下了暂停键，停留在天隙事件发生的那一年，与新城区的快速发展形成鲜明对比。监督认为，X能源的发掘与提取建立在旧城区居民家破人亡的记忆之上，很难治愈他们的创伤。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">时间流逝，垂花街口始终没有出现要等的人。就在两人准备离开时，监督注意到路口有一个红衣服的女孩一直看着她们。女孩突然跑过来，向她们求救，喊道：“白荆科技？求求你们……救救我！有人要——”</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-3 求救者</strong></span><span style=\"font-size: 15px;\"><br>少女闻声抬起头来，直到车子消失不见，才缓缓开口。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱在垂花街口处理了一起袭击事件，袭击者精神状态异常，最终被R.E.D.副队长十手卫带走。十手卫提到，旧城区最近发生了多起同调者伤人的案件，但凶手是否为同调者尚未确定。这些案件与一桩旧案有关，十手卫的徒弟刑舟和专案组在侦办旧案时失踪，至今下落不明。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">遇袭少女千鹤承认自己是写信求救的人，并表示找白荆科技是因为他们愿意前来帮助。十手卫希望监督和苏筱能暂时照看千鹤，并劝她到R.E.D.配合问话。十手卫透露，旧城区的情况最近变得复杂，水越来越浑。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着战术防御终端的屏障取消，周围的人群逐渐散去。千鹤向监督自我介绍，监督也表明了自己的身份。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-4 强势介入</strong></span><span style=\"font-size: 15px;\"><br>“——吾以日月星辰的名义，降至海临，审问众生！”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·垂花街</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 20:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">千鹤与监督、苏筱的对话被自称“星辰之子”的南渚打断。南渚声称千鹤陷害了他的朋友群晏（即之前的袭击者），并质疑千鹤为何不亲自带群晏去白荆科技求助。千鹤则反驳，指出群晏的精神状态异常，且两人都感染了X晶石辐射引发的怪化病，因此一直躲避R.E.D.的追查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督从中调解，指出千鹤从一开始就试图阻止报警，这一行为需要进一步解释。千鹤最终坦白，她和群晏都感染了怪化病，长期躲避R.E.D.的追查，这也是她不愿报警的原因。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">南渚对此感到震惊，千鹤质问监督和南渚是否现在可以相信她。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-5 怪化</strong></span><span style=\"font-size: 15px;\"><br>“上个冬天，海临下过一场雪。<br>就是那天，群晏回来了。“</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">千鹤讲述了群晏和她在旧城区的经历。群晏曾离开垂花街，但几个月前带着一块X晶石回来，声称能卖钱带大家搬出去。然而，晶石引来了大量“提丰子体”虫子，导致混乱。千鹤和群晏因此感染了X晶石辐射引发的怪化病。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">千鹤提供了当时拍下的提丰子体照片，并承认自己并不知道幕后黑手是谁，只是为了引起白荆科技的重视才在信中提及。她请求白荆科技帮助她和群晏。监督表示白荆科技并非医疗机构，无法治疗怪化病，建议千鹤前往医疗中心。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">南渚提到旧城区流传着关于医疗中心的负面传言，称官方将感染者聚集在一起，目的是培养新的同调者。千鹤则表达了感染者不愿去医疗中心的原因，他们希望能在亲友的陪伴下度过最后的时光，而不是冷冰冰地被处理掉。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提到，X细胞异化综合征的病程进入Ⅲ期时，患者一定会出现身体或精神的异化，而同调者只是极少数痊愈后仍保留异化核心的特殊群体。大多数患者会在病程中死亡，且死亡后体内的异核会继续生成，最终成为必须被消灭的“怪物”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱发现群晏带回的X晶石本应作为科研材料运往海隅其他城邦，不该在市面上流通。监督决定调查晶石的来源。千鹤愿意带监督去垂花街里巷，提供破碎的隔离罩作为线索。南渚则提议去泊通港实地探查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督表示不会贸然跟随千鹤或南渚去垂花街或泊通港，而是会跳出这个范围，调查旧城区是否存在涉及X晶石的非法贸易链。她提议千鹤前往白荆科技的医疗部接受治疗，但千鹤怀疑这是为了支开她，不让她参与后续调查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最终，监督提到“血露薇”，暗示了进一步的调查方向。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(0, 0, 0); font-size: 19px;\"><strong>S1-6 明暗之间</strong></span><span style=\"font-size: 15px;\"><br>“敢问小友，当你坐在这里时，你是谁？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·无名小巷</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-29 20:47</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱在十手卫的引导下，前往血露薇寻求关于X晶石走私链的情报。十手卫解释了血露薇在旧城区的特殊地位，称其为R.E.D.在秩序外的“协助者”，负责处理一些官方无法直接介入的事务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在前往血露薇的路上，监督提到曲观玄曾考虑与血露薇合作，但未能实现。十手卫对此感到惊讶，并表示旧城区的许多复杂情况本应早与白荆科技互通。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">到达血露薇后，白鸟梓（血露薇的“守门人”）迎接了他们，并带他们进入。十手卫提醒监督，血露薇虽讲规矩，但仍是旧城区的地下势力之一，进入后需谨慎行事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在血露薇内部，监督与血露薇的左補佐修进行了对话。修解释了血露薇的交易规则，强调他们只会与担任“白荆科技首席执行官”这一身份的人合作，因为身份足够安全。监督询问了关于旻望救助基金会的情报，修表示旻望救助基金会近年来影响力扩大，频繁与其他企业寻求合作，暗示其目的不仅仅是“抹黑”同调者。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">修将关于旻望救助基金会的信息作为见面礼送给监督，暗示未来会有更多合作。监督则借机提出关于X晶石走私链的情报，希望能获得更优惠的价格。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在此时，外面突然发生混乱，十手卫提醒大家注意。苏筱担心千鹤和南渚的安全，监督决定出去查看情况。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-7 一触即发</strong></span><span style=\"font-size: 15px;\"><br>“救她……求你们救救她……”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·血露薇</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 21:45</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱在血露薇内遭遇了X细胞异化综合征患者的集中发病，场面一度混乱。千鹤突然表现出异常行为，试图袭击白鸟梓，最终化作纸片消失。监督推测千鹤并非真正的求救者，而是顶替了求救者的身份，意图不明。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">修和十手卫出手平息了骚乱，并封锁了血露薇。监督意识到千鹤可能并未接触过求救信，信中提到的“救救孩子”可能另有隐情。监督推测千鹤可能是威胁到求救者与孩子的那个人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在血露薇内部，魁主与修讨论了此次事件的背后动机。魁主认为“出世间”组织可能误判了血露薇的立场，导致血露薇被卷入白荆科技与出世间之间的冲突。魁主决定暂时不将情报告知白荆科技，而是观察新任首席执行官的能力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">修提到照片可能是伪造的，但魁主认为即使是假的情报，背后也隐藏着值得挖掘的信息。魁主对出世间组织的言行不一表示讽刺，认为他们无法逃脱世间的贪嗔痴念。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-8 伏流</strong></span><span style=\"font-size: 15px;\"><br>“好在总算又见面啦~白荆科技的小~监~督~”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·垂花街口</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">1121-04-29 22:27</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和南渚在垂花街口等待可能的求救者，但夜市即将散场，仍未见到目标。南渚提到旻望救助基金会将在十点半举办招募宣讲会，监督决定前往查看。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在宣讲会现场，气氛异常热烈，监督感到不安。南渚提议溜进后台查看，但被监督婉拒。此时，一名旧城区少年偷偷接近，告诉他们有一个姐姐一直在等他们，但由于等不到，已经离开，并会在宣讲会散场时回来看看。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定换个地方等待，但突然感受到一股诡异的力量，大脑陷入混乱。在视线模糊中，监督试图摸索前进，最终被千鹤发现。千鹤调侃监督“落单很危险”，并再次出现在他面前。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(0, 0, 0); font-size: 19px;\"><strong>S1-9 世间事</strong></span><span style=\"font-size: 15px;\"><br>“这就是我所知道的故事。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在千鹤的绑架下醒来，身处一个未知的地方。千鹤承认自己是奉命行事，并提到自己并非使用异核能力，而是通过消耗生命来发动攻击。她表示自己只是执行任务的“打工人”，并试图通过讲故事来缓和气氛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">千鹤讲述了一个关于X晶石的故事：一块流落到旧城区的X晶石引发了居民之间的疯狂争斗，最终导致所有人死亡。这个故事发生在大约五年前，天隙事件后不久，旧城区的一场悲剧。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-10 真相谎言</strong></span><span style=\"font-size: 15px;\"><br>“你只是一个普通人，无法保护自己，更保护不了别人。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">千鹤（舞鹤织雪）试图说服监督与她背后的组织合作，提出以技术支持和开放天隙禁区权限为条件，换取白荆科技的同调者研究数据和X能源武器。她还提到可以为监督提供一种无须感染怪化病就能成为同调者的方法，试图以此打动他。然而，监督表示不信她，拒绝了她的提议。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">舞鹤织雪离开后，监督被困在一间废弃的病房中，南渚和苏筱赶来救援。他们发现这里是石松路第一人民医院旧址的地下一层，并在一间实验室中发现了大量生化实验数据。苏筱怀疑这些资料与曲观玄早年海外研究团队有关，但项目早已关停，资料被封存，不可能出现在这里。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">突然，实验室停电，监督等人陷入黑暗，情况更加危急。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-11 我是主角</strong></span><span style=\"font-size: 15px;\"><br>“夜深了，先回家吧。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和南渚在医院实验室遭遇追踪者，形势危急。监督试图通过Vein系统传输实验数据，但火势迅速蔓延，南渚被一名神秘人拉入火海，监督和苏筱被迫逃离。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">白鸟梓出现，救下了监督和苏筱，并告知他们“出世间”组织是禁区事件的幕后黑手，提醒监督作为白荆科技首席执行官需要更有担当。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在医院外，南渚意外生还，与一名黑衣女人对话，得知她属于“出世间”组织，但表示南渚只需执行她的命令，而非为出世间效力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在葵花福利院外，一名少女与少年对话，暗示他们可能与出世间有关。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S1-12 心之所向</strong></span><span style=\"font-size: 15px;\"><br>在这条道路上，仅仅有前进的方向是不够的。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·监督办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-05-01 10:36 总部80层</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在办公室反思自己作为白荆科技首席执行官的责任，决定明确自己的定位，成为公司的引路人。苏筱带来消息，血露薇送来拜访函，R.E.D.在爆炸现场发现火灾核心引爆点在一楼储藏室，且未发现南渚的遗体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫告知监督，舞鹤织雪的身份无法查证，但她提到的故事与1116年金铃北区的精神异化事件吻合，该事件促使官方划定天隙禁区。监督意识到作为首席执行官，必须亲自面对这些棘手问题。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">虞助理送来杜望音乐会的门票，监督在众人的“逼迫”下决定参加，暂时放松身心。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:35:12', '2025-02-25 11:09:48', 'admin', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (7, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/cn3tms8jmrh7ytdkkrosqvif3xrd907_20250217115949A006.png', 11210510, '02#雨中人 ＞', '主线剧情', '监督', '1121年5月10日', '森罗', '洛天依,奈默', '他们在帷幕之后，瞭望着一场暴雨的开始。', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-1 曲外之音</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">西旻大剧院外，人头攒动。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">西旻大剧院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-05-10 16:35</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与白荆科技的同僚们参加杜望的音乐会，剧院外人群拥挤，气氛热烈。霍冉兴奋地谈论杜望的八卦，而监督则对音乐会的人气感到意外。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">音乐会开始前，VIP席的众人轻松交谈，霍冉提到传闻中的神秘嘉宾可能是云无月。与此同时，隔壁包厢的白衣女人与神秘少年“提里”讨论一场即将发生的晶石交易，提里决定单独行动阻止交易。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">音乐会正式开始时，杜望的琴声瞬间平息了全场的喧嚣，监督试图查看曲目单，却发现周围的人已经沉浸在音乐中，无人回应。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-2 意识幻城</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">幻想，亦或是记忆。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督发现自己身处一个寂静的空间，疑似杜望的意识幻城。云无月出现，解释这是杜望的异核能力创造的幻城，需要唤醒被困的人才能脱离。监督与云无月合作，试图找到其他同调者。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和云无月在幻城中遇到了由负面情绪凝聚的敌人。通过聚光灯驱散恶意，他们逐渐接近真相。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">霍冉加入，监督解释这可能是杜望的异核觉醒事件。云无月指出杜望并非初次觉醒，可能是故意为之。霍冉虽然对杜望的行为感到失望，但仍决定帮助救人。监督和云无月继续寻找其他被困者。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-3 笼中鸟</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在触碰到那台老旧留声机的下一秒，我们被熟悉的喧嚣声淹没。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、霍冉和云无月进入另一个意识幻城，发现小鸢的朋友七叶患有X细胞异化综合征。小鸢试图通过白荆科技的关系获取阻断药，但瞳指出七叶的病情已无法逆转。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望的外力介入，试图通过负面情绪控制小鸢的意识。监督等人成功击退恶意，保护了小鸢。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">小鸢恢复清醒，监督安慰她并表示愿意帮助她。云无月解释杜望可能已经锁定他们，监督意识到杜望的意图可能是通过异核能力控制他人。小鸢最终同意监督在事件结束后拜访七叶。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-4 海醒时分</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">「是啊！你们都英勇，都伟大！」</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、霍冉、云无月和鸢进入艾摩诃的记忆幻城，发现夜摩世界的“海醒季”提前到来。艾摩诃试图阻止哥哥阿兰那出城参战，但阿兰那坚持履行战士的职责。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">艾摩诃的情绪激动，揭示了他对哥哥的深厚情感和对夜摩未来的担忧。云无月发现杜望的身影出现在城外，暗示他可能正在操控这场幻境。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">艾摩诃的内心挣扎和杜望的出现，使得局势更加复杂。监督等人必须尽快找到艾摩诃，并应对杜望的潜在威胁。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-5 恐惧回响</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一片混乱中，我听见了钢琴的声音。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">艾摩诃因过度消耗陷入深眠，霍冉和鸢决定留下照顾他。监督和云无月继续寻找苏筱，发现她的意识幻城与其他人的不同，似乎是多重幻境的交迭。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和云无月进入苏筱的意识幻城，看到她童年的记忆片段，揭示了她作为战争孤儿的过去。幻城突然崩塌，监督和云无月努力抓住苏筱，防止她坠入深渊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱逐渐清醒，意识到自己身处杜望的意识幻城。幻城再次扭曲，云无月指出杜望现身，并引导监督和苏筱跟随她，寻找离开幻城的方法。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-6 尘中网</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“欢迎，来到我的梦。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月进入杜望的意识幻城，发现他童年的记忆片段，揭示了他与父母之间的复杂关系。杜望的父母对他的期望和失望，以及他们对他的忽视和争吵，深深影响了他的成长。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督试图与杜望沟通，但杜望沉浸在自己的记忆中，无法回应。最终，杜望的“恶意”幻象攻击了他自己，导致幻城再次崩塌。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望和他的幻象消失，苏筱对杜望的行为感到困惑和担忧。云无月在迷雾中发现杜望童年时的钢琴，并弹奏《Cocooned Wanderer》，使迷雾退散，新的意识幻城开始生成。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-7 好梦时分</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">——下雨了。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月继续在杜望的意识幻城中探索，目睹了杜望童年时期在阿达德国际钢琴比赛中的失败经历。杜望的父母未能到场，导致他在比赛中临时更改曲目，最终被评委严厉批评。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望的“恶意”幻象再次攻击他自己，监督等人试图阻止，但杜望似乎沉浸在自己的悔恨和痛苦中，无法自拔。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望在比赛后的走廊上遇到了幼年的云无月，云无月试图与杜望沟通，但杜望似乎无法真正听到她的声音。云无月问杜望是否真的听见了雨声，暗示他是否真正面对了自己的内心。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-8 绝望奏鸣</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">没有人会去在意一滴雨的声音，不是么？</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月进入杜望的意识幻城，目睹了他在青年时期的钢琴比赛中的经历。杜望在比赛中演奏了自己的原创曲目《Cocooned Wanderer》，但评委们对他的表现和曲目提出了批评，导致他未能获得冠军。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望与云无月对话，表达了他对音乐和人生的绝望，认为自己的声音无法被听见。他暗示自己将不复存在，并警告监督等人，即使他消失了，其他人的绝望仍会继续。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望的身影消失，监督等人即将离开幻城。在幻城消散的过程中，监督听到了模糊的对话，暗示杜望可能受到外界的影响，导致他的力量和精神状态失控。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-9 优胜者</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">如果这是一场交易，我能得到什么？</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月进入杜望的意识幻城，目睹了杜望与一位陌生女人的对话。女人试图说服杜望接受一种神秘的力量，声称这将帮助他实现他的音乐梦想。杜望对此表示怀疑，但最终似乎被说服，决定接受这种力量。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望接受了女人的提议，开始尝试接触这种力量。监督等人意识到这可能与出世间的实验有关，担心杜望会因此失控。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望在阿达德国际钢琴比赛中获得了冠军，但他对胜利并不感到真正的快乐。黑衣女人建议他继续探索这种力量，并举办几场直击心灵的音乐会。杜望的状态逐渐失控，他的异核能力开始不受控制，最终从他的身体中脱离，预示着他可能面临严重的危险。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-10 惊蛰</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">他是茧中的流浪者。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月发现杜望的异核开始脱离他的身体，推测这与出世间的手术有关。出世间可能掌握了人为制造异核的技术，但这种方法并不稳定，杜望可能永远处于异化期的痛苦中。苏筱意识到杜望可能只是出世间的试验品，用完即弃。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人进入杜望的意识幻城，发现他在不断修改过去的记忆，试图找到一条出路。杜望被过去的记忆和质疑声困扰，逐渐失控。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望消失，留下满地的曲谱。云无月捡起一张曲谱，发现字迹正在褪色，表明杜望已经无力维持这个幻境。监督等人意识到可以离开这里，结束这场危机。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-11 种子</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一片嘈杂声中，我隐约听见了下雨的声音</span><span style=\"font-size: 15px;\">。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和云无月回到现实世界的音乐厅，发现杜望正在舞台上独自演奏钢琴。杜望平静地与他们对话，承认自己接受了出世间的手术，并利用异核能力影响了听众。杜望坦言自己始终为选择感到茫然，最终决定结束这一切。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">杜望彻底放弃对异核能力的压制，失控的力量将他拖入深渊。他宣布终曲已经奏响，鬼手般的异化力量将他紧紧抓住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人确认杜望尚未完全异化，试图说服他接受治疗。然而，杜望透露了出世间利用他筛选特定人群的计划。就在此时，一柄手术刀飞来刺中杜望，他最终倒在钢琴上，像一粒破土失败的种子。监督意识到，还有许多像杜望一样的人在黑暗中挣扎，而自己也差点成为其中之一。警笛声响起，雨声渐起，故事在悲伤与反思中落幕。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S2-12 终曲</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">音像店门口仍是熙熙攘攘，每个人的手中都捧着专辑，热烈地讨论着那首全新的曲子。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·中心商业区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年5月24日 8:34</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">半个月后，杜望的新专辑《Cocooned Wanderer》发行，吸引了大量粉丝排队购买。监督、苏筱、霍冉和元桃桃也在人群中，回想起杜望的悲剧结局。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人讨论杜望的异核能力和出世间的影响，意识到出世间仍在散播“种子”，试图利用异核控制他人。监督反思白荆科技的责任，认为除了技术研究，还需要提供心理支持，帮助那些被异核能力困扰的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱鼓励监督继续努力，共同对抗出世间。监督决定与云无月保持联系，未来可能合作。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，白汲和虞助理准备离开海临，计划给监督和苏筱一个惊喜。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">故事在阳光下的新芽中结束，象征着希望与新的开始。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:36:02', '2025-02-25 16:45:34', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (8, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/rdbwv3daiasdo8zxaugbyo6q8ucpzwd_20250217120001A007.png', 11210530, '03#恶象因果 ＞', '主线剧情', '监督', '1121年5月30日', '森罗', '洛天依,奈默', '昨日之因，结今日之果。<br>今日之因，又将导向怎样的未来？', '<blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-1 第一案·怪物</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">现在是森罗时间1121-05-30 9时整。<br>尊敬的首席执行官，您关注的主播开播了，是否进入直播间？</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">故事发生在海临医疗中心，柳业医生与病人交谈时表现出对“怪化病”（X细胞异化综合征）的歧视。白汲医生前来与柳业讨论近期误诊率上升的问题，并暗示柳业可能涉及精神异变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲被绑架，直播中他替绑匪转达了三个需求：公开天隙事件和X辐射的真实情况、公开X细胞异化综合征的真实信息、官方承诺负责感染者的医疗费用和赔偿。直播结束后，监督和苏筱尝试追踪直播地址，但未能成功。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">十手卫与监督和苏筱通话，询问绑匪针对白荆科技的可能性以及白汲的可信度。监督为白汲担保，并表示可以协助提供资料。与此同时，R.E.D.组员通知十手卫，刑侦部门抓到了一名与直播有关的嫌疑人，要求白荆科技派人协助调查。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-2 第二案·凶宅</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“这位警官，我发誓，我只是误入！”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">故事发生在雅松区的柏露园小区，逸虚（易虚舟）作为私家侦探，受雇调查柳业的婚外情。他潜入柳家，发现柳业和其夫人袁一念的尸体，现场被大火烧毁。逸虚在调查过程中发现柳业的行为异常，尤其是夜间频繁出入垂花街。与此同时，白汲被绑架的直播事件仍在进行，绑匪要求公开天隙事件和X细胞异化综合征的真实信息。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">逸虚在柳家现场发现了焦尸、血脚印、儿童水杯等线索，推测柳业可能涉及违禁药品交易。他试图逃离现场，但被巡警抓住。在R.E.D.的审讯中，逸虚向十手卫和监督汇报了自己的调查结果，推测柳家案件可能与绑架案有关联，并提出了“黑吃黑”的可能性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">十手卫决定将逸虚交给刑侦部门进一步审讯。就在此时，一名身着黑色长风衣的男人破门而入，直呼逸虚的本名“易虚舟”，暗示两人之间有过往的纠葛，案件背后的真相逐渐浮出水面。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-3 侦查方向</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“Vein，再次检测白汲是否已经重启公司内部权限。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">崔远之抵达R.E.D.，要求取回外编证，并建议将逸虚送回九旻基地。十手卫同意崔远之的征调，并安排他去解剖中心进行尸检。与此同时，R.E.D.与白荆科技合作，准备通过CHATMORE发布绑匪要求的信息。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">绑匪再次开启直播，要求公开重症者信息和提供阻断药。白荆科技通过内部通讯系统成功接收到白汲的信号，确认他安全且能够与外界联系。逸虚通过分析绑匪的言行，推测绑匪可能是柳业，尽管柳业已被认定为柏露园小区案件的死者之一。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">R.E.D.组员对逸虚的推测表示怀疑，但十手卫决定继续追踪这一线索。白荆科技和R.E.D.继续合作，试图通过绑匪的要求和内部通讯系统获取更多信息，以尽快解救白汲和人质。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-4 第三案·柳叶刀</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“行了，先来看档案，十手卫特别叮嘱的东西总该有些用处。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">崔远之抵达解剖中心，与法医一起研究柳业和袁一念的尸体。通过翻阅R.E.D.的档案，崔远之发现“柳叶刀”连环杀人案的作案手法与柳家的案件有相似之处，推测柳业可能与连环杀人案有关。与此同时，逸虚在R.E.D.会议室继续分析案件，提出柳业可能是绑匪的假设，并推测柳业的儿子柳泊远可能患有X细胞异化综合征。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲通过内部通讯系统与R.E.D.保持联系，试图与绑匪柳业谈判。白汲提出用阻断药的资料换取自己的自由，并暗示柳业可以通过他逃离海临。柳业虽然半信半疑，但最终同意交易，并决定由自己指定交易地点。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">R.E.D.成功定位到柳业的位置，准备展开行动。田偌前往福利院寻找柳业的养子小池，以获取更多信息。与此同时，逸虚通过柳业家窗外发现的糖果，推测田莹可能与柳泊远有联系。白汲的谈判策略逐渐奏效，R.E.D.团队也在紧锣密鼓地准备营救行动。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-5 背后黄雀</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“妈妈快看！下雪了诶！”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">虞助理与监督在桐音路地铁口会合，替换了柳业要求的阻断药文件中的关键数据，以防止文件泄露。与此同时，R.E.D.团队发现游行队伍未按原定路线行进，可能干扰即将进行的救援行动。逸虚和崔远之通过尸检报告分析，推测柳家案件中存在两柄“柳叶刀”，且男尸并非柳业。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督在桐音路地铁口遭遇舞鹤织雪，后者利用异核能力将监督手中的关键数据文件化为碎片并带走。舞鹤织雪宣布出世间对事件负责，并暗示接下来将有一场“竞速游戏”。R.E.D.团队迅速行动，试图追踪舞鹤织雪并保护剩余的文件。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">R.E.D.团队确认柳业尚未出现，并安排虞助理带着剩余的文件撤离。十手卫推测“竞速游戏”的终点是柳业的藏身处，并认为出世间不会赶在R.E.D.之前到达。救援队已接近柳业的藏身处，准备展开最后的救援行动。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-6 失控</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“再给你一次机会，你说谁是怪物？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业与舞鹤织雪通话后情绪失控，认为自己只是病人而非怪物，并坚信阻断药能治愈他。白汲试图安抚柳业，但柳业的精神状态持续恶化，表现出明显的异化症状。柳业通过折磨姚曼试图获取儿子柳泊远的去向信息，但姚曼声称自己并未举报，只是担心辐射问题。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业得知姚曼并未举报后，情绪进一步失控，开始对姚曼施暴。与此同时，R.E.D.团队发现柳业的精神状态异常，监督和虞助理决定直接前往救援现场。警笛声突然响起，柳业意识到自己的位置可能已暴露，愤怒地质问人质是否泄露了他的藏身处，最终发现白汲身上的微型通讯仪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业的情绪彻底失控，暴怒之下对白汲和田莹产生威胁。监督和虞助理正在赶往现场，R.E.D.团队也紧急展开救援行动，局势一触即发。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-7 营救行动</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“我会把她留在这个房间里，就看你们想不想救她了。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督和虞助理抵达工业南路，准备参与救援行动。突然响起的警笛声让监督误以为是R.E.D.的行动暴露，愤怒之下打碎了小朋友的玩具警车。R.E.D.组员确认柳业的位置，监督和虞助理迅速赶往现场。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业在绑架地点突然消失，随后以异化后的形态出现在房间内，表现出极度亢奋的状态。他声称自己获得了“神力”，并嘲笑白汲等人无法理解他的力量。柳业威胁要将白汲带回出世间，成为他们的“传道者”。与此同时，柳业通过直播向R.E.D.展示了他劫持的白汲、田莹和重伤的姚曼，威胁R.E.D.必须在5分钟内救出姚曼，否则她将死亡。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">局势紧张，R.E.D.团队必须迅速行动，救出人质并阻止柳业的进一步失控。</span></p><blockquote style=\"text-align: left; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-8 嫉妒</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“——还真是个好爸爸。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">田偌前往葵花福利院，询问柳池关于柳业一家的情况，试图获取柳泊远的去向线索。柳池表示自己与柳家关系疏远，无法提供有用信息。田偌得知柳池曾被柳业一家收养，但在柳泊远出生后遭到冷落，最终回到福利院。柳池对柳家的遭遇表现出冷漠，但对刑舟的承诺仍抱有期待。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳池帮助柳泊远隐瞒行踪，随后决定带柳泊远前往栖云商业广场观看猫头鹰战士的演出。与此同时，R.E.D.团队在会议室讨论救援失败的后续行动。崔远之通过尸检报告分析，指出柳业是近期旧城区连环案件的凶手，并推测柳业因嫉妒和恐惧而发疯。十手卫提出柳业可能藏身于其旧居银珠新苑，并派人前往搜查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">R.E.D.团队继续分析柳业的行为模式，试图找到新的突破口。柳池与柳泊远前往栖云商业广场，而R.E.D.的行动仍在紧张进行中。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-9 恐惧</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“想要活下去，你能选择的合作对象只有我。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">田莹在家中无聊，决定给柳泊远送糖。她使用弹弓将糖果射向柳家的窗户，却意外目睹了柳业行凶的场景。田莹被吓坏，随后被白汲安抚，并在柳业的威胁下回忆起自己看到的一切。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业承认自己杀害了朱伯伯，并解释了自己与出世间的合作关系。白汲试图通过分析柳业的心理，挑拨他与出世间的关系，暗示出世间可能会抛弃甚至灭口柳业。柳业逐渐意识到自己的处境，开始动摇。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲继续施压，指出柳业已经陷入孤立无援的境地，唯一的合作对象只有自己。柳业的恐惧和不安逐渐加深，局势朝着白汲的预期发展。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-10 万事通</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“我这次真的是来协助办案的！”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">逸虚使用异核能力，逐步还原柳业一家的案件线索。他通过分析柳业的心理和行为，推测出柳业隐瞒自己和儿子的病情，并试图通过白汲获取阻断药。逸虚还通过线索成像，还原了袁一念被杀害的场景，并发现柳泊远已被“柳叶刀”带走。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">逸虚通过调查游行队伍，得知柳业曾因误诊导致一名志愿者死亡，并因此与老朱家结仇。游行队伍临时更换路线，逸虚怀疑这与案件有关。与此同时，R.E.D.团队接到白汲的电话，得知柳业决定与R.E.D.合作，以应对出世间的灭口威胁。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">逸虚通过拼图般的线索还原，逐步接近真相。R.E.D.团队则准备与柳业展开合作，试图扭转局势。案件的核心线索逐渐明朗，各方势力的博弈进入关键阶段。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-11 合作愉快</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“为表合作诚意，我会亲自送他过去。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲与柳业达成合作，柳业同意与R.E.D.合作以躲避出世间的灭口行动。白汲安排虞助理协调出港时间，并为柳业申请了伊南纳的“同调者担保协议”。柳业要求获得白汲实验室的最新阻断药和管理权限，白汲同意并立即为其开通权限。白汲计划亲自护送柳业前往泊通港，确保合作顺利进行。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">R.E.D.团队迅速行动，确认柳业藏身于其五年前的住所银珠新苑。与此同时，出世间通过舞鹤织雪联系柳业，试图追踪他的位置。出世间的袭击者突入柳业的藏身处，但被崔远之及时击毙，危机解除。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲与柳业的合作进入关键阶段，R.E.D.团队继续监控局势，确保柳业安全离开海临。出世间虽然行动失败，但双方的对抗仍在持续。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-12 一触即发</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“大哥哥，我们要怎么办？”<br>“……再等等。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业在银珠新苑的藏身处被R.E.D.和出世间同时发现。柳业利用变色能力躲藏，而出世间的袭击者试图从外墙突入，被崔远之狙杀。柳业带着田莹和白汲跳窗逃跑，融入游行人群中，引发混乱。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">舞鹤织雪试图追击柳业，但因崔远之的狙击威胁而退缩。崔远之与逸虚通话，讨论柳业的逃跑和游行的背后动机。逸虚发现游行背后有人操纵，并推测柳业知道举报信息的来源可能与临时改变的游行路线有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">逸虚决定以记者身份进一步调查，试图揭开柳业和游行背后的真相。局势愈发紧张，各方势力在暗流涌动中展开博弈。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-13 疯狂</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“在它们身上……有试验成功的……”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业带着田莹和白汲闯入海临医疗中心，寻找儿子柳泊远。柳业在电话的暗示下疯狂使用异核能力，最终冲进办公室和实验室，神志逐渐失控。白汲趁机引导柳业离开，并锁上门保护田莹。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业在实验室中陷入疯狂，甚至对小白鼠进行攻击。这时，柳池打来电话，声称柳泊远在他身边，并邀请柳业到天台见面。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业的神志短暂恢复，决定前往天台与柳池会面。局势愈发紧张，柳业的疯狂与柳池的冷静形成鲜明对比，天台上的对峙即将展开。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-14 苦果</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“柳泊远，你到底想要做什么？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业在天台上与柳池的幻影对话，逐渐陷入疯狂。柳池揭露了自己通过X晶石摆件导致柳业异化的真相，并暗示柳业放火杀害了妻子袁一念。柳业精神崩溃，无法分辨现实与幻觉，最终在天台边缘与幻觉中的家人和受害者对峙。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业被幻觉中的“死者”逼至天台边缘，情绪失控。R.E.D.组员试图劝降，但柳业陷入极度恐惧，最终在幻觉的逼迫下坠楼。崔远之开枪阻止，但柳业仍然坠楼身亡。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲和田莹离开柳业的办公室，田莹调侃白汲之前给她喂的“苦糖”。白汲解释那是预防X辐射的药物，并叮嘱田莹去做全面体检。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳池和柳泊远在医疗中心外，柳泊远天真地希望家人团聚，而柳池则冷眼旁观，取消了原定的冲击医疗中心计划。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">柳业的疯狂与死亡为这场家庭悲剧画上了句号，而柳池的冷漠与算计则揭示了更深层的黑暗。</span></p><blockquote style=\"text-align: left; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S3-15 荆棘之路</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“老师总喜欢说，我们面对的是一条注定艰辛的路。<br>但我却觉得，我看见了十字路口。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">雅松区·垂花街</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督、苏筱和白汲在垂花街的“熔岩烤肉”店外，面对朱阿姨的悲痛，反思同调者与普通人之间的矛盾。白汲分享了他对未来的思考，认为阻断药可能是缓解恐惧的关键，但他并不急于回归白荆科技，而是希望监督找到自己的方向。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·飞行器内</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督在飞行器内陷入深思，回想起朱阿姨的悲痛和白汲的话，意识到自己亟需为白荆科技的未来做出决策。与此同时，白汲在垂花街发现了柳业桌面上带有“S.E.E.D.”字样的辐射屏蔽器，暗示着更深层的阴谋。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">结尾</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">白汲接到来电，拒绝了一个神秘人的合作提议。随后，他被不明人物袭击，故事在紧张的氛围中戛然而止，留下悬念。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:40:40', '2025-02-25 16:49:24', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (9, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/svex7op1dqp71n9g0eaowj2ugqrl2py_20250217120011A008.png', 11210531, '04#劣种 ＞', '主线剧情', '监督', '1121年5月31日', '森罗', '洛天依,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那人如流星般转瞬即逝，却有后来者甘愿成为逐星之人。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S4-1 始作俑者</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“至少现在，能不能给我一个答案？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日，昊苍和祸烨莲在伊南纳-沙玛什边境的阿达帕平原追踪弗雷德里克·达弗戴尔，发现他近期频繁在固定区域徘徊，似乎寻找某样东西。昊苍推测弗雷的行动可能与“出世间”有关，而祸烨莲则认为弗雷只是“圣冕”的傀儡，背后另有主导者。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，伊南纳驻军遭遇沙玛什的“沙虫”袭击，随后一场突如其来的巨大风旋引发士兵们的恐慌，认为这是神迹显灵。白荆科技的飞行器因异常能量波动失控坠毁，监督和狄砚被伊南纳士兵捕获并关押。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督在昏迷中回忆起三年前与曲观玄的对话，曲观玄坚持将X晶石能源化视为保全森罗的唯一解法，而白汲则质疑其选择的正确性，最终选择离开白荆科技。监督在坠机后醒来，发现自己身处伊南纳监狱，与狄砚一同被关押。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在监狱中，监督和狄砚遇到一名沙玛什雇佣兵，对方言语挑衅，试图试探他们的来历。监督冷静应对，但内心意识到伊南纳与海临的环境截然不同，局势更加复杂。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-2 越狱</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“临时战友，祝你们好运。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日16时41分，监督和狄砚被关押在伊南纳军营的监狱中，沙玛什雇佣兵提醒他们不要指望伊南纳士兵的仁慈，并提议合作越狱。他透露自己受沙玛什委托在阿达帕沙漠寻找“珍宝”，并认为伊南纳士兵会在消息走漏前处决他们。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督和狄砚同意合作，但狄砚试图破坏笼门时发现铁栏经过强化，无法轻易打破。沙玛什雇佣兵展现出同调者的力量，轻松击倒笼门并缴获武器。三人分头突围，雇佣兵吸引主要火力，监督和狄砚趁机逃脱。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">17时22分，监督和狄砚成功甩掉追兵，计划等雇佣兵团与伊南纳士兵交火后再伺机离开。他们发现伊南纳军营中混入了提丰子体，推测这与舞鹤织雪的行动有关。突然，监狱方向传来震动，黑色雾气开始蔓延，狄砚发现金发身影在黑雾深处，两人决定立即逃离。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-3 小小监督</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“像现在这样的动作、这样的距离……很适合袭击你哦。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日17时35分，苏筱在沙玛什的未知小巷中追捕舞鹤织雪。舞鹤织雪声称自己救了苏筱，并透露关押她们的地方是毒气室。苏筱用X能禁制手铐控制住舞鹤织雪，逼问阻断药资料的下落。舞鹤织雪声称资料已被转移，并透露自己来南半球的目的是再偷一份资料。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">苏筱试图联系昊苍和监督，但通讯信号出现问题。最终，她成功联系到昊苍，得知监督和狄砚下落不明，伊南纳军营情况混乱，到处都是尸体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督和狄砚在伊南纳的未知街道中遭遇追兵。他们利用废弃的液化气罐制造爆炸，成功击退追兵。监督发现追兵身上有奇怪的沙子屏障，但沙子可以被击散。尽管追兵不断增援，监督和狄砚仍设法脱身。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">17时44分，监督和狄砚躲藏在巷中，观察到伊南纳士兵对他们的追捕并不十分在意。狄砚推测，只要他们不在军营，伊南纳士兵并不关心他们的死活。监督和狄砚决定继续撤离，但突然，一只手从监督背后伸出，狄砚惊呼提醒。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-4 一线生机</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“你们或许还听过我的另外一个名字。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日17时52分，昊苍和祸烨莲在伊南纳军营调查风暴后的混乱。祸烨莲感知到强烈的神力残留，并发现监狱深处有黑雾涌动，黑雾对祸烨莲表现出亲昵，但被他斩散。他们发现大量伊南纳士兵和提丰子体的尸体，尸体呈现出与X晶石相似的结晶状态。祸烨莲推测这是“圣冕”在恢复自身力量，并决定离开营地寻找埃斯特班。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍因目睹惨状情绪失控，祸烨莲用巨镰逼他冷静，提醒他不要浪费力量，凶手死亡才是对亡者最好的慰藉。昊苍最终恢复理智，与祸烨莲一同离开。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督和狄砚在伊南纳的未知街道中遭遇伊南纳上尉米达斯·奈格尔图。米达斯声称自己已是伊南纳的逃兵，并透露他曾将监督和狄砚从坠毁的飞行器中救出。狄砚对米达斯保持警惕，但米达斯表示自己没有恶意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督和狄砚在米达斯的带领下逃脱追兵。监督询问米达斯是否见过苏筱，米达斯表示当时他主要救援伊南纳士兵，发现监督和狄砚只是意外。监督感谢米达斯的救命之恩，米达斯则透露自己曾是伊南纳的战神“迦路”。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-5 战神之名</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“在很多人的期许之中，日落该伴着日升。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">米达斯向监督和狄砚讲述伊南纳的“造神计划”。16年前，战神莎拉塔尔崛起，带领伊南纳取得多次胜利，但在阿达帕平原陨落。伊南纳随后启动“造神计划”，米达斯成为新的战神“迦路”。然而，因某些无法言明的原因，米达斯选择自我放逐，离开了伊南纳军队。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">米达斯带领监督和狄砚来到一个佣兵酒馆，这里是伊南纳和沙玛什之间的缓冲区。酒馆中聚集了许多雇佣兵，米达斯透露“战神迦路”的身份并不为人所知，甚至连雇佣兵都认为这只是伊南纳的宣传幌子。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督发现酒馆中有大量同调者，远超海临的比例，推测南半球可能早已出现X细胞异化综合征，且范围广泛。监督与米达斯深入交谈，试图了解伊南纳的“造神计划”是否与天隙事件有关，但米达斯认为他的力量与莎拉塔尔一脉相承，并非来自天隙事件。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，苏筱和舞鹤织雪在沙玛什的未知小巷中遭遇追兵。舞鹤织雪坚持追击，最终发现另一场战斗正在附近进行。苏筱被迫跟随舞鹤织雪行动，两人逐渐接近事件的中心。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-6 红沙</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">战区里是见不到寻常灯火的，目之所及处，唯一的光源便是这间佣兵酒馆。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日18时46分，监督与米达斯在伊南纳的佣兵酒馆外展开深入对话。米达斯透露，伊南纳的“造神计划”并非真正的神眷，而是通过一场手术赋予了他类似同调者的力量。他承认自己并非真正的“战神迦路”，而是被谎言包装的罪人，曾在战场上无差别攻击战友，导致大量士兵死亡。米达斯选择逃离军队，但在风暴中救下监督和狄砚后，他看到了控制力量的希望，决定与他们合作。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督震惊于“造神计划”实际上是人体改造实验，推测南半球可能早已出现X细胞异化综合征，且范围广泛。米达斯表示自己并不清楚有多少人参与并成功存活下来，但他不会阻止监督将此事上报给海隅理事会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">狄砚发现地平线上涌起黑雾，与之前在军营中见过的相似。监督和狄砚与晶化的伊南纳士兵交战，试图摧毁帐篷，但攻击无效。最终，他们利用液化气罐成功击退敌人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督发现晶化士兵的尸体与X晶石相似，试图采集样本进行研究。米达斯主动帮忙，但触碰晶石时，尸体化作粉末消失。米达斯透露这些士兵曾是伊南纳的士兵，监督意识到事态的严重性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">米达斯表示自己将返回军营，不希望战友因其他变故丧命。监督试图联系筱筱和昊苍，但通讯无信号，推测与风暴有关。最终，昊苍突然出现，宣告他与监督的重逢。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-7 「莎拉塔尔」</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">一只机械臂悄无声息地出现，轻轻搭在她的肩上。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年5月31日19时40分，苏筱和舞鹤织雪在沙玛什的未知小巷中目睹一场战斗。沙玛什士兵试图抓捕一名神秘女人，而雇佣兵拼死保护她。舞鹤织雪提议“美女救美”，苏筱无奈跟随。战斗中，神秘女人展现出惊人的力量，机械臂从她衣袍中伸出，瞬间击杀沙玛什士兵。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">雇佣兵团长纳加尔向神秘女人敬礼，称她为“原伊南纳月神突击队第三十三小队医护兵、现奇美拉雇佣兵团长”，并宣布归队。舞鹤织雪揭示神秘女人的身份——她的脸与早已死去的战神莎拉塔尔一模一样。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">纳加尔回忆16年前，莎拉塔尔将军在阿达帕平原与沙玛什行商的对话。行商试图说服莎拉塔尔维持战局，但莎拉塔尔坚持结束战争，渴望和平。然而，最终莎拉塔尔并未战死，而是被伊南纳和沙玛什共同设下的陷阱谋杀。纳加尔悲痛地控诉，伊南纳背叛了他们曾经誓死守护的将军。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">神秘女人自称“C-V-018，两岁”，显然并非真正的莎拉塔尔，而是某种实验产物。就在此时，苏筱的通讯仪响起，监督终于联系上了她。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-8 起始点</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">她举起手，秀出腕上的手铐，在屏幕前晃了晃。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">纳加尔解释了奇美拉佣兵团的由来，她们是被伊南纳背叛的幸存者，无法回到故土。C-V-018透露自己是沙玛什的试验产物，与莎拉塔尔长相相同，但并非她本人。舞鹤织雪提议合作，前往沙玛什的实验室，夺取莎拉塔尔的遗体和相关试验资料。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">舞鹤织雪指出，白荆科技与南半球的惨案有关，暗示当年白荆科技的内部争执与这些试验有关。监督最终同意合作，但要求苏筱全程盯紧舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍向米达斯解释，弗雷德里克·达弗戴尔是幕后黑手，他在1116年通过天隙通道来到森罗世界，并在1118年和今年4月参与了一系列事件。昊苍推测，达弗戴尔的活动轨迹与伊南纳和沙玛什的历史冲突重叠，可能推动了“造神计划”和“人形兵器”的诞生。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督回忆起三年前师兄与老师的争执，怀疑这一切与白荆科技的内部矛盾有关。狄砚指出，达弗戴尔的棋盘覆盖了伊南纳、沙玛什和海临，祸烨莲则揭示，真正的布局者是破晓圣廷的“圣冕陛下”——埃斯特班。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong>S4-9 遗产</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“迦路大人……您不来沐浴神恩吗？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">森罗历1121年6月1日00时05分，舞鹤织雪、苏筱、C-V-018和奇美拉佣兵团成员潜入沙玛什的实验室。C-V-018找到研究资料，揭示莎拉塔尔可能并未死亡，而是作为“母体”被用于实验。舞鹤织雪推测，伊南纳可能得到了莎拉塔尔的“异核”，并用于“造神计划”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，米达斯前往伊南纳的“神诞之地”，揭露了“造神计划”的残酷真相。他目睹了无数试炼者因异化而被销毁，并决定摧毁这一计划的核心。米达斯遇到一名即将异化的小女孩，试图救她，但最终女孩被守卫击碎，化为橙色晶石。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">米达斯意识到“造神计划”的本质是对人命的践踏，决定背叛伊南纳，摧毁这一计划的核心。他目睹了士兵们对晶石的狂热崇拜，更加坚定了自己的决心。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">沙玛什和伊南纳的“造神计划”均以莎拉塔尔为源头，分别进行“复制”和“创造同调者”的实验。米达斯、C-V-018和奇美拉佣兵团揭示了这一计划的残酷真相，决定联手摧毁它，阻止更多的悲剧发生。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-10 屏障</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“只有他死了，才不会再有人被困在过去，所有人都能往前走。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在阿达帕沙漠的战神遗迹，监督与昊苍、祸烨莲等人讨论了埃斯特班的背景和计划。祸烨莲解释了埃斯特班如何通过攫取黎威尔的能量篡改其法则，并自命为黎威尔的主宰。埃斯特班离开黎威尔是因为它已腐朽，他需要一个年轻且富有生命力的世界作为新的宿主，而森罗正是他的目标。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督提出疑问，为何大家只谈论埃斯特班，而忽略了弗雷德里克·达弗戴尔的存在。祸烨莲解释，达弗戴尔实际上是埃斯特班的工具，用来暂时保管权柄和蕴养力量。埃斯特班需要一个新的容器来承载他的力量，因此达弗戴尔的存在并不独立。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">狄砚尝试联系海临和筱筱，但发现已经与外界失联。祸烨莲指出，这是因为围绕此地的屏障正在崩溃。屏障的力量源自世界本身，用以维持内部稳定和抵御外部入侵。埃斯特班通过制造内部混乱，破坏了这片土地的屏障。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督意识到，埃斯特班三年前来到伊南纳和沙玛什，正是为了制造混乱，打破莎拉塔尔遗留下的保护屏障。狄砚感叹，伊南纳与沙玛什在16年前暗害莎拉塔尔后，又亲手毁掉了她留下的最后保护。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督等人遭遇了“怒蛇兵团”的埋伏，发现他们已失去神智，脚下藏有陷阱。战斗结束后，监督推测“怒蛇兵团”的老板很可能是埃斯特班，昊苍则指出这是埃斯特班的灭口手段。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍表示，这是解决埃斯特班最近的一次机会，只要他死，许多问题都能随之解决。他期待尽快结束这一切，让所有人从过去的阴影中解脱。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-11 「圣冕」</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">压人的威慑力如同高墙一般砸下，他的语气却堪称温和。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督等人终于见到了“弗雷德里克·达弗戴尔”——实际上，他是埃斯特班的化身。埃斯特班背对着他们，站在陈旧的长枪与盾牌前，语气温和却充满压迫感。昊苍的意识在埃斯特班的威压下崩溃，监督急忙呼喊他。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在回忆中，埃斯特班揭露了昊苍的过去。他指责昊苍是罪人、叛徒，甚至是他计划中的关键棋子。埃斯特班利用昊苍的血脉与黎威尔的亲近性，培养他成为打破黎威尔牢笼的“宝剑”。为了达到这一目的，埃斯特班让昊苍消灭了同族，并在反抗者中传递消息。埃斯特班冷酷地指出，昊苍最终将替他摧毁黎威尔，成为世界的背叛者。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍试图反抗，但埃斯特班指出他已陷入献祭法阵，无法逃脱。埃斯特班命令他跪下，彻底击溃了他的意志。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">埃斯特班以“弗雷德里克·达弗戴尔”的身份现身，揭露了他对昊苍的操控和利用。他通过摧毁昊苍的意志，进一步巩固自己的计划，准备彻底打破黎威尔的屏障，实现他的野心。监督等人面临着前所未有的危机，必须找到办法阻止埃斯特班的最终计划。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-12 被放逐者</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“还真是……一如既往的不听话。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">“圣冕”埃斯特班的现身与昊苍的崩溃几乎同时发生。祸烨莲迅速展开攻势，但埃斯特班轻松化解，盾牌压制了暴风眼区域的所有法术波动。狄砚感到异核能力调用受阻，监督则尝试用X能源武器协助战斗。埃斯特班召唤出大量提丰子体，局势变得更加危急。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍从混乱中挣脱，但埃斯特班踩住了他的巨剑，逼迫他再次效命。埃斯特班利用契约项圈控制昊苍，要求他通过献祭抹除前代主人对神器的驯服。昊苍痛苦不堪，但无法反抗，被迫接受埃斯特班的命令。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-13 反抗的心</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“不，我的经历是可怨，可笑，可恨，唯独没有可悲。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在「永昼之庭」，C-V-018带领众人找到了被囚禁的莎拉塔尔。她虽然保留了半个异核，但伤势严重，周围布满了实验器械。众人试图解救她，但舞鹤织雪察觉到了不对劲，怀疑之前闯入的人另有目的。突然，实验室发生震动，莎拉塔尔苏醒，展现出强大的力量。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，在阿达帕沙漠，昊苍被埃斯特班的契约控制，被迫绘制献祭法阵。监督等人试图阻止，但埃斯特班的力量过于强大。昊苍最终决定反抗，利用血脉的力量开启通道，试图与埃斯特班同归于尽。然而，埃斯特班依然展现出压倒性的实力，局势危急。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">监督决定赌一把，冲向莎拉塔尔的神器，成功将其拔出。神器回归莎拉塔尔手中，她的力量瞬间恢复，向埃斯特班发起攻击。然而，莎拉塔尔的状态似乎并不正常，她的愤怒与怨恨让她对伊南纳与沙玛什充满了敌意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">最终，莎拉塔尔带着神器离开，埃斯特班也消失无踪。监督等人意识到必须尽快撤离，避免被伊南纳与沙玛什的战斗主力发现。昊苍与祸烨莲留下处理善后，其他人则先行离开。</span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 19px;\"><strong> S4-14 自我意识</strong></span><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br></span><span style=\"color: rgb(59, 59, 59); font-size: 16px;\">“我想要留在这里，亲自看一看……”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">伊南纳的局势愈发紧张，监督等人接到撤离的通知，准备跟随第一批撤侨队伍离开。元桃桃和霍冉的通讯中充满了担忧，十手卫也提醒他们尽快行动，避免被伊南纳和沙玛什的全境封锁困住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">C-V-018和米达斯决定留在伊南纳，前者想要见证兵器成为人的过程，后者则作为伊南纳的战神迦路，决心保护自己的国家。苏筱为他们留下了联系方式，承诺在必要时提供帮助。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，舞鹤织雪与黑衣女人的对话揭示了任务的不顺利和潜在的危机。黑衣女人警告舞鹤织雪离开南半球后不要返回海临，以免引来杀身之祸。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在返回海临的航班上，监督发现昊苍和祸烨莲并未同行，心中充满疑问。她回忆起与老师和师兄的过往，试图寻找答案，但最终选择了撤回未发送的消息。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">昊苍在沙玛什继续与埃斯特班周旋，决心将风险消除在海临以外的地方。他给R.E.D.发了一封辞职信，表达了对过去的歉意和对未来的决心。红玉无奈地按下辞职信，希望昊苍不要断了回家的路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">与此同时，弗雷德里克·达弗戴尔的声音突然出现，似乎被某人绑住。祸烨莲和昊苍感到意外，局势变得更加复杂。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">在海临医疗中心，白汲的名字出现在住院部VIP5065病房的名单上，暗示着新的故事即将展开。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\">南半球的局势愈发紧张，监督等人准备撤离，而C-V-018和米达斯选择留下。昊苍继续与埃斯特班对抗，决心保护海临。舞鹤织雪和黑衣女人的对话揭示了潜在的危机，而白汲的住院则暗示着新的故事线即将展开。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59); font-size: 15px;\"><br><br><br><br></span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:42:13', '2025-02-25 16:53:37', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (10, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/0icyqbmj2p3ynlixn5czdokrzl739ng_20250217120022A009.png', 11210602, '05#非自愿幸存 ＞', '主线剧情', '言御,言雀', '1121年6月02日', '森罗', '洛天依,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">在无声中呼救，于缄默中幸存。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-1 迷雾重重</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这么巧，你也在这儿。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱在医疗中心探望受伤的白汲，心中充满了对南半球事件和阻断药研发的疑虑。白汲的伤势虽然稳定，但尚未苏醒，虞行邈作为助理，一直守在病房，显得疲惫不堪。他提到SCOPE的临时代理人郑景，这位公司元老级成员在新闻发布会上曾与白汲并肩出现。郑景的温和气质和过往的善举让虞行邈感到安心，但监督却对此产生了警觉，决定将信息同步给R.E.D.，以防万一。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在医院走廊，监督和苏筱偶遇了苏筱的学长言御，他是御雀通信的负责人。言御的出现引起了监督的注意，尤其是在看到他手中的同调者体检报告后，监督决定进一步调查御雀通信的背景。言御提到公司最近遇到了一些麻烦，包括空调报废和警察上门调查，但他并未详细说明。监督注意到言御的言行中有些许矛盾，尤其是他之前提到是来找人，后来却说是来取体检报告。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，医院内的病人们谈论着X细胞异化综合征和医疗中心的情况，监督意识到关于综合征的科普工作仍需加强。她听到病人们讨论综合征的传染性和医疗中心的隔离政策，感到有必要推动更多的公众教育和信息透明化。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在离开医院时，监督听到一位打电话的女人提到“御雀通信”和“基金会捐款”，这让她更加怀疑御雀通信的背景和动机。她决定联系R.E.D.，进一步调查这家公司的活动。监督意识到，南半球的事件和白汲的受伤背后，可能隐藏着更大的阴谋，而她必须尽快揭开这些谜团，以保护白荆科技和阻断药研发的未来。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-2 疑云</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“祝各位旅行愉快。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和田偌警官前往御雀通信公司，协助调查与白汲袭击案有关的异常信号源。言御作为御雀通信的负责人之一，表现得十分配合，但监督注意到他的言行中存在诸多不一致之处。言御提到公司曾多次遭受黑客攻击，但并未造成实际损失，且他对异常信号的出现表示无法解释。监督对言御的空间类异核能力产生了兴趣，询问了其具体表现。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在对话过程中，言御的通讯仪不断响起，但他始终未接听。随着气氛逐渐紧张，言御突然对监督出手，将他推入一个突然出现的黑色旋涡中。田偌警官见状，立刻抓住言御的衣带，一同被卷入旋涡。苏筱试图阻止，但为时已晚。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">司旸作为御雀通信的另一位负责人，全程表现得冷静且寡言。他在走廊与田偌闲聊时，话题突然转向家庭，显得有些不自然。当旋涡消失后，司旸只是淡淡地叹息，似乎对这一切早有预料。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在跌入旋涡前，脑海中闪过对言御动机的怀疑。言御提到的“监督先生想找的答案，就在这里”暗示了他可能掌握着某些关键信息。整个事件充满了谜团，言御的真实意图和御雀通信的背景令人捉摸不透。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，R.E.D.和白荆科技的合作仍在继续，但昊苍的下落和南半球的局势依然悬而未决。监督的失踪使得调查工作陷入了新的困境，而司旸的冷静态度则让人感到不安。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-3 童话王国</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“又或者……是你我之间混进了什么。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱被言御推进了他的能力空间——“甜蜜幻境”，一个由硬纸板和棉花构筑的童话世界。田偌警官也紧随其后进入空间，质问言御的意图。言御解释自己被监视，无法在外界公开求助，只能通过这种方式与白荆科技接触。他透露自己手中掌握着旻望基金会和思柝药业的相关资料，并暗示这些信息可能与白荆科技正在调查的事件有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在“甜蜜幻境”中，他们遭遇了一群玩具锡兵的袭击，这些锡兵高喊着“排除异己”“为了红皇后陛下”，似乎是在执行某种命令。战斗结束后，言御透露他的能力空间已经失控，所有权可能转移到了他的妹妹言雀手中。他请求监督等人帮助拯救言雀，并解释了近期的体检数据显示他的能力出现了异常。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">空间突然剧烈震动，远处出现了一只大鸟和鱼形生物的对峙，言御推测那只鸟可能就是他的妹妹言雀。他恳求监督等人救她，暗示言雀的处境与能力空间的失控有关。言御的行为和空间中的异常现象，表明他正面临着巨大的危机，而这场危机可能与旻望基金会和思柝药业有着深层次的联系。监督等人意识到，他们不仅要揭开言御的秘密，还要应对即将到来的更大威胁。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-4 幸福一家</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“公主殿下最喜欢听故事了~”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人跟随小鸟骑士进入“甜蜜幻境”深处，逐渐揭开了言御与妹妹言雀之间的复杂关系。小鸟骑士作为言雀的“代言人”，要求他们通过一系列考验才能继续前进。言御在考验中表现出了对妹妹的陌生，甚至无法回答关于她喜好的简单问题，暗示兄妹之间关系疏远。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在通过考验后，他们遇到了“信箱大臣”，要求交换故事才能继续前进。言御提交了一幅画，描绘了一只小鸟和一座房子，信箱大臣则回赠了一段关于“幸福家庭”的故事。故事中，小鸟女儿因为与众不同而被孤立，但依然坚强地依赖着家人。与此同时，全息屏幕前的少女（言雀）正在与一只怪鱼生物对抗，并在网络上与朋友交流，透露出她对孤独的恐惧和对陪伴的渴望。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在现实世界中，某人与郑景的对话暗示着御雀通信的未来可能面临变动，而郑景的介入可能带来新的危机。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御与言雀的关系在“甜蜜幻境”中逐渐浮出水面，兄妹之间的疏离和言雀对孤独的恐惧成为故事的核心。通过交换故事和网络交流，言雀的内心世界被揭示，而现实世界中的阴谋也在悄然酝酿。监督等人不仅要面对能力空间的失控，还要解开言雀的内心困境，同时应对即将到来的更大威胁。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-5 甜蜜灾难</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">远远地，我好像看见地平线的那边出现了一个巨大的身躯，又很快消失。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人在“甜蜜幻境”中继续前进，逐渐揭开了言雀内心世界的秘密。小鸟骑士和信箱大臣透露，王国中的居民大多是言雀现实中认识的人，包括背叛她的锡兵和红皇后。信箱大臣提到，言雀最珍贵的朋友“小鲸鱼”失踪了，导致她茶饭不思。监督推测，王国中的“居民”都是言雀现实生活中的投射，而天空中的怪鱼则是整个事件的根源。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在交换故事的过程中，他们获得了一段关于“糖果森林”的绘本故事，讲述了小鸟和她的家人在一场灾难中失去家园的经历。监督意识到，这段故事实际上是言雀对天隙事件的隐喻，用“糖果粘上奶油”来象征异化综合征对家庭的破坏。言御承认，这些故事确实反映了他们家庭的遭遇，并透露了父母在天隙事件后被确诊为异化综合征的经历。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着故事的展开，言御的态度逐渐从冷漠转为复杂，他对妹妹的疏离和对家庭悲剧的无奈逐渐浮出水面。监督等人意识到，要解决“甜蜜幻境”的危机，不仅需要面对空间中的敌人，还要解开言雀内心的伤痛。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S5-6 奶油小鸟</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你不要从房间里出来，就当自己是个聋子，听见了么？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在R.E.D.总部，十手卫与组员讨论言御的背景，揭示了言御父母在天隙事件中的遭遇以及言家兄妹的艰难处境。十手卫回忆起当年向言御传达父母死讯的情景，言御的冷漠态度让他印象深刻。与此同时，监督等人在“甜蜜幻境”中继续前进，通过交换故事逐渐揭开了言御与言雀之间的复杂关系。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御在与监督的对话中，表达了对同调者身份的复杂情感，认为“同调者”的幸运可能掩盖了更深层的痛苦。他承认自己无法正面回答言雀关于“奶油”的问题，暗示他对妹妹成为同调者的事实感到矛盾。监督推测，言御希望言雀能过普通人的生活，而非卷入同调者的世界。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在回忆中，言雀质问言御为何疏远她，言御则以疲惫和无奈回应，强调自己并非讨厌她，而是无法解决当前的困境。言雀在“甜蜜幻境”中感到孤独，试图通过与网友的交流来缓解情绪，同时继续对抗入侵的怪鱼。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-7 鲸鱼朋友</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“简直像是在……做给别人看一样。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人在“甜蜜幻境”中继续前进，通过交换故事逐渐揭开了言雀与小鲸鱼之间的友谊。小鸟骑士和信箱大臣提到，言雀最珍贵的朋友“小鲸鱼”失踪了，导致她茶饭不思。监督推测，小鲸鱼可能是言雀现实生活中的朋友，而天空中的怪鱼则与御雀通信遭受的黑客袭击有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御透露，黑客多次攻击御雀通信，但并未造成实质损失，反而对公司账务和股权表现出浓厚兴趣。监督联想到白汲受伤后SCOPE的股价波动，猜测黑客的行动可能与SCOPE的代理董事郑景有关。言御提到，黑客使用了6进制技术，暗示对方可能是一名技术高超的同调者。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在讨论中，田偌注意到草丛中有异常动静，提醒众人小心。监督等人意识到，他们不仅要面对空间中的敌人，还要解开言雀与小鲸鱼的秘密，同时应对即将到来的更大威胁。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">言雀与小鲸鱼的友谊成为“甜蜜幻境”中的关键线索，而天空中的怪鱼则与御雀通信的黑客袭击密切相关。言御对黑客技术的分析揭示了对方可能是一名同调者，且其行动可能与SCOPE的代理董事郑景有关。监督等人意识到，要解决“甜蜜幻境”的危机，不仅需要面对空间中的敌人，还要揭开黑客的真实身份和意图。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-8 红皇后与猫</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“每年这天，他总是关机的。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人在“甜蜜幻境”中继续前进，通过交换故事逐渐揭开了言雀与红皇后之间的复杂关系。小鸟骑士和信箱大臣透露，红皇后曾经是言雀信任的客人，但后来背叛了她，试图占领王国。言御承认，红皇后的原型是旻望基金会的高层管事海伦，并透露自己曾向她提供过医疗中心的死亡数据，导致旧城区出现抹黑同调者的谣言。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御进一步揭露，旻望基金会可能背靠一个隐秘组织，暗示其与“出世间”有关。他还推测，旻望基金会的资金流动可能与SCOPE的阻断药开发有关，甚至可能涉及更大的阴谋。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在战斗中，红皇后出现并试图吞噬一切，最终被监督等人击败，留下了一张纸立牌。小鸟骑士和白猫爵士继续引导监督等人前进，信箱大臣则因体内信件增多而痛苦不堪。最终，鱼形生物变得庞大，巨鸟下落，言御展开长伞飞向高处，试图拯救言雀。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言雀与红皇后的关系揭示了旻望基金会的阴谋，言御的调查则指向了更大的隐秘组织“出世间”。监督等人不仅要面对空间中的敌人，还要揭开旻望基金会的真实意图，同时应对即将到来的更大威胁。言御的举动表明他决心拯救妹妹，而天空中的鱼形生物则成为整个事件的关键。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-9 内外交困</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“哥哥，那些开心的回忆，都是假的么？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人在“甜蜜幻境”中面临空间崩塌的危机，言雀与怪鱼的对峙揭示了她们之间的友谊破裂。言雀质问怪鱼为何背叛她，怪鱼则疯狂攻击四周，最终击中言雀，使她化为光点消散。言御赶到，试图说服言雀离开，但言雀坚持要弄清真相，不愿逃避。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着空间的崩解，言御将苏筱和田偌送出空间，但监督被怪鱼卷入漆黑的海水中，陷入昏迷。与此同时，御雀通信的办公室内，言御等人被十手卫发现，十手卫怀疑言御的同调者身份有问题，并试图控制他。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言雀与怪鱼的冲突揭示了友谊的破裂和信任的崩塌，言御的介入则展现了兄妹之间的复杂情感。空间的崩塌和怪鱼的出现成为事件的高潮，监督被卷入海底，命运未卜。与此同时，现实世界中，言御的同调者身份受到质疑，十手卫的调查可能揭示更大的阴谋。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S5-10 脱困方法</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“擒贼先擒王。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在御雀通信办公室，十手卫质疑言御的同调者身份，认为真正的同调者是其妹妹言雀。言御承认自己多年来顶替了言雀的身份，并解释了原因——言雀的异化相性指数过低，可能被隔离。言御请求警方不要公开言雀的身份，并表示愿意配合调查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，监督在“甜蜜幻境”的海底与一只系着蓝色蝴蝶结的小鸟相遇。小鸟自称是“小鸟骑士”，但监督推测它可能是言雀的化身。小鸟表示要追捕怪鱼，监督决定陪同。在深入海底的过程中，他们遭遇了捕鲸枪和莫名的黑暗，最终在战斗后，小鸟骑士与公主殿下重逢，信箱大臣也赶到现场。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-11 缸中怪物</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这就对了。你要学会吞噬，学会破坏。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与小鸟骑士在海底重逢，小鸟骑士揭穿了言雀的真实身份。言雀承认自己就是“甜蜜幻境”的主人，并透露她与小鲸鱼是在网上认识的《星之艾斯黛尔》粉丝。言雀表示自己从未告诉小鲸鱼自己是同调者，担心对方会因此疏远她。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在对话过程中，捕鲸枪再次刺下，地面震动，黑暗弥漫。言雀回忆起小鲸鱼曾是个神秘的黑客，两人关系亲密，但言雀始终隐瞒了自己的同调者身份。随着捕鲸枪的破坏，黑暗中的声音催促着“吞噬”和“破坏”，暗示着更大的危机即将到来。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-12 幸存者</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“无论是多弱小的生命，也总是为了活着竭尽全力的。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与言雀在海底继续探索，言雀回忆起她通过监听发现海伦阴谋的经过。海伦的目标似乎是言御的异核，而非御雀通信公司。言雀意识到哥哥可能陷入危险，情绪崩溃。在监督的引导下，言雀回忆起与小鲸鱼的友谊，并试图通过祈祷寻求安慰。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言雀提到她曾发现言御行为异常，便通过黑客朋友黑入通讯器监听，听到了海伦与富运集团高层的对话。海伦表示自己准备通过“弱肉强食”的方式夺取言御的能力，甚至计划取代江昙的地位。言雀将此事告知言御，但言御却表示不需要她插手。言雀随后在御雀通讯布置了“巢”，试图抓捕海伦，却意外抓到了正在骇入公司内网的小鲸鱼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督指出，海伦的目标是言御的异核，而言雀却表示言御并非同调者，没有异核。言雀担心言御的安危，但空间内没有信号，无法与外界联系。在小鸟骑士的安慰下，言雀回忆起《星之艾斯黛尔》中的情节，决定像艾斯黛尔一样向星星许愿。就在言雀闭眼祈祷时，海底突然出现光亮，魔法少女艾斯黛尔如奇迹般现身，询问言雀的愿望。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S5-13 弱肉强食</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我的梦想就快实现了，你也是。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">海伦回到出世间据点，试图与“蚕食计划”的关键人物接触，但被守卫阻拦。她随后参加出世间例会，发现自己的名字再次未出现在荣誉名单上，愤而质问柳池。柳池暗示她可以通过异核移植手术成为同调者，条件是她带一个异核过来。海伦决定铤而走险，将目标锁定为言御。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，言御在旧城区与海伦会面，试图从她口中获取关于“蚕食计划”的线索。然而，海伦早已布下陷阱，言御被袭击并失去意识。海伦将他带到一个秘密房间，准备进行异核移植手术。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御醒来，发现自己被铐在椅子上，周围是手术设备。海伦直言她的目标是言御的异核，并解释了异核移植手术的原理。她表达了对同调者身份的渴望，以及对现状的不满。言御试图劝说海伦放弃，但海伦态度坚决，认为这是她改变命运的唯一机会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">海伦的野心与言御的安危形成强烈对比，异核移植手术的威胁让局势更加紧张。言御能否化险为夷，海伦的阴谋是否会得逞，成为故事的关键悬念。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S5-14 她的决心</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“一直……一直……都可以？”<br>“永远都是。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-02 18:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在出世间·未知据点，言御与海伦之间的气氛逐渐紧张。言御以异核捐赠人的身份试图与海伦交谈，但海伦的态度显得冷淡且戒备。言御提到自己即将进行的手术，并质疑主刀医生的意图，暗示手术可能存在的风险。海伦对此保持沉默，但在言御的追问下，她透露了目标“小同事”的位置——总部的一个废弃电子厂地下仓库。言御随后展示了自己隐藏的能力，成功摆脱了束缚，并以威胁的方式迫使海伦提供更多信息。海伦在恐惧中透露了具体地址，言御则带着目的离开了据点。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，在甜蜜幻境·海底渊，言雀正经历着情感上的挣扎。她为故事中的恶意感到痛苦，直到信箱大臣递给她最后一封信。信中提到了“朋友”的重要性，以及保护朋友的决心。言雀在信中找到了一丝希望，并决定寄出一封未完成的信，象征着与朋友和解的决心。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">战斗后，在海底渊的场景中，小鲸鱼终于挣脱了束缚，与言雀化身的雀鸟紧紧挨在一起，象征着友谊的重建和希望的回归。最终，言御接住了变成雀鸟的言雀，场景在一片白光中结束。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在漆黑的房间内，监督与苏筱对话，苏筱提到他们根据海伦提供的地址找到了据点，但现场已人去楼空，并发现了打斗的痕迹。监督对此表示疑惑，但并未得到更多线索。整个事件在神秘和未解的谜团中告一段落。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S5-15 温暖时节</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“等到，温暖的时候，还会再见的。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">海临中央警局·R.E.D.办公室内，十手卫坐在桌前，目光锐利地扫过言御和言雀。言御面无表情地承认了自己与言雀体检数据互换的事实，言雀则低着头，手指紧紧攥着衣角，眼中满是担忧。十手卫轻哼一声，语气中带着几分戏谑，却也透着一丝宽容。他提醒言御，以后若有麻烦，大可找R.E.D.帮忙，别再让监督为难。言御微微点头，言雀则松了口气，紧绷的肩膀稍稍放松。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">清晨的第一班公交车上，言御和言雀并肩而坐，车内空荡荡的，只有引擎的轰鸣声在耳边回响。言御侧头看向言雀，语气平淡却带着关切：“两天没吃饭了吧，饿不饿？”言雀轻轻“嗯”了一声，声音低得几乎听不见。言御挑眉，问她：“想吃什么？”言雀犹豫片刻，小声说道：“馄饨，多放肉不要胡萝卜，你做。”言御无奈地笑了笑，却还是答应了下来。言雀抿了抿嘴，眼中闪过一丝狡黠，仿佛在这一刻，所有的阴霾都被这简单的对话驱散。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">另一处，爱丽丝靠在一人肩上，脚步虚浮，却倔强地摇了摇头。她轻声说道：“等到温暖的时候，还会再见的。”她的声音轻柔却坚定，仿佛在黑暗中点亮了一盏微弱的灯。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">天台上，司旸仰头望着晴朗的天空，嘴角扬起一抹淡淡的笑意。他低声自语：“今天天气真不错啊，希望是和平的一天。”随后，他转身离开，似乎准备继续他的工作。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">海临医疗中心病房内，监督和苏筱站在病床旁，白汲刚刚醒来，脸色还有些苍白。他勉强笑了笑，语气轻松：“头有点晕，被打的地方似乎还肿着，其他还好。”监督皱眉，眼中带着关切，而苏筱则急匆匆地表示要去买吃的，却被白汲拦下。白汲看着苏筱离去的背影，无奈地摇了摇头，低声说道：“还是老样子，哭完就找个借口溜走。”</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，在海临中央警局·特殊审讯室内，海伦蜷缩在椅子上，神情慌乱。她喃喃自语，语无伦次地提到出世间、圣女，甚至质问“教主”的身份。突然，她像是看到了什么可怕的东西，瞳孔猛然收缩，声音变得尖锐：“别过来！你要做什么！别过来！！”审讯室内的空气仿佛凝固，只剩下她绝望的呼喊在回荡。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一日，温暖的晨曦洒在海临的街道上，似乎预示着新的开始。然而，在这平静的表象之下，暗流涌动，未知的危机正悄然逼近。</span></p><p><br></p><p><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:43:11', '2025-02-25 16:57:35', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (11, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/l8fmr8kyc4al3piq1u5719nr18nxd6y_20250217120032A010.png', 11210605, '06#如我垂怜 ＞', '主线剧情', '鸢', '1121年6月05日', '森罗', '洛天依,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">夜晚荒凉，万物静寂。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">你将内心的一切说给花丛，随后摘下一朵——</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">送给了我。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-1 黑与白</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“黑与白的界限，往往在故事中才会分明。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·中心商业街</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 10:20</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱在拥堵的街道上交谈，苏筱对白荆科技内部可能存在的“内鬼”感到困惑，尤其是涉及到白汲被袭击的事件。监督回忆起与白汲的对话，白汲提到“黑与白的界限，往往在故事中才会分明”，并提醒监督不要过度思考，专注于解决当前的问题。监督推测，出世间可能并非单纯针对白荆科技，而是有更大的目标。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院·正门</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 10:56</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱来到葵花福利院，目的是寻找失踪的员工鸢。福利院的孩子们对陌生人表现出戒备，但整体气氛和谐。院长简·坎贝尔接待了他们，并提到鸢与七叶关系密切。七叶是鸢的密友，但院长透露七叶已于上个月去世。监督对此感到震惊，尤其是联想到之前在意识幻城中看到的七叶。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在离开福利院时，监督突然感受到一股奇异的目光和歌声，随后在口袋中发现了一张求救纸条，内容与之前收到的求救信相似，要求他们“救救七叶姐姐”。监督意识到福利院可能隐藏着更大的秘密，决定回公司进一步调查。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院·某房间内</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">粉发少女七叶站在窗边，注视着监督和苏筱的离开。她神色复杂，似乎对福利院的现状有着深刻的理解。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节在紧张与疑惑中展开，监督逐渐接近真相，但出世间与葵花福利院的秘密依然笼罩在迷雾之中。黑与白的界限，似乎在现实与故事之间变得愈发模糊。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-2 夜间行动</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“找到……你了……”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">旧巷·葵花福利院后门</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 22:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与十手卫进行通讯，表达了对葵花福利院进行调查的迫切需求。尽管十手卫警告这是非法入侵，且可能引发严重后果，但监督坚持认为这是获取关键情报的唯一途径。十手卫最终默许了行动，但强调以安全为首要任务，并承诺尽量派人支援。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯作为行动的主要执行者，准备潜入福利院。监督则留在外面接应，等待霍冉的到来。在观察福利院后墙时，监督注意到墙体的异常，似乎近期经过修缮。当他触碰墙壁时，突然感受到一阵奇异的感觉，仿佛进入了一个模糊的幻境，耳边响起歌声，眼前出现一扇门和一条长廊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，十手卫在R.E.D.办公室中试图拨打电话，似乎对某个关键时刻的通讯是否畅通感到担忧。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节在紧张的氛围中展开，监督和苏筱等人决定冒风险深入调查，而十手卫则在背后默默支持，整个行动充满了未知与危机。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-3 两种游戏</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“如果是好朋友，一直不结束也不错吧？”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在模糊的幻境中听到了孩子们的歌声，随后被一只小手拉住，参与了一场“捉迷藏”游戏。游戏的紧张氛围中，监督被催促着选择方向，最终来到一扇门前。直觉告诉他门后隐藏着危险，但他还是被推动着推开了门，进入了一片白光中。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院三楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1091-03-10 10:40</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督的意识似乎穿越到了过去，化身为一名新入住福利院的孩子。与室友罗莎莉亚的对话中，监督感受到了一种莫名的熟悉感。罗莎莉亚提议玩翻花绳，监督选择了参与，但就在准备开门时，眼前的景象再次消失。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院一楼·活动室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 22:40</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯在福利院的活动室内进行调查，发现了《作息时间表》和一些关于圣西尔大人的涂鸦与书籍。马尔斯对圣西尔的信仰表示疑惑，苏筱则提到这是福利院的守护神。两人讨论着福利院的严格宵禁和孩子们的生活，逐渐察觉到这里的诡异氛围。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在他们准备离开时，马尔斯突然察觉到门外有异样。推开门后，一团难以名状的黑影正静静伫立着，仿佛早已等待多时。苏筱和马尔斯陷入了一场突如其来的危机。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过监督的幻境与苏筱、马尔斯的现实调查交错展开，揭示了葵花福利院背后的神秘与危险。捉迷藏与翻花绳两种游戏象征着孩子们的生活与福利院的规则，而黑影的出现则预示着更大的威胁正在逼近。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-4 阴影</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“过去的答案，过去的犯人，就在阴影背后。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯在福利院的走廊中与黑影对峙，黑雾逐渐退入阴影中，但恶意依然弥漫在空气中。苏筱感到一种无形的寒意，联想到之前在杜望的意识幻城中遇到的“恶意”。马尔斯则提醒她，这些黑影可能是某种棘手的敌人，甚至可能与出世间有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">尽管马尔斯建议撤退，苏筱坚持继续调查，认为这是找到真相的唯一机会。两人最终达成共识，决定寻找那个递消息的男孩。然而，就在他们准备行动时，突然听到金属碰撞的声音，似乎有什么东西正在靠近。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院三楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1091-09-24 07:58</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督的意识再次穿越到过去，化身为福利院的一名孩子。他与室友罗莎莉亚的对话揭示了福利院新院长郝琳的到来。郝琳的严厉言辞让孩子们感到不安，尤其是罗莎莉亚，她对未来充满了恐惧。监督试图安慰她，但内心也感到困惑，似乎对某些事情有着模糊的记忆。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过苏筱、马尔斯的现实调查与监督的幻境交错展开，揭示了福利院背后的阴影与孩子们的恐惧。黑影的出现象征着出世间的影响力，而郝院长的到来则为福利院带来了新的压迫感。监督在幻境中的经历则暗示了福利院的过去与未来的某种联系。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-5 我曾垂眸</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">天下没有免费的午餐，也没有免费的爱。<br>——然后，让自己变得有用吧</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院一楼·走廊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 22:55</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯在走廊中目睹了坎贝尔院长穿过黑雾，毫发无伤。黑影在走廊中游荡，试图引诱孩子们开门，仿佛在进行一场“捉迷藏”游戏。苏筱和马尔斯意识到，这些黑影的目的是找到违反宵禁的孩子，并将他们视为“不守信的孩子”。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院三楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1099-10-05 09:25</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督的意识再次穿越到过去，化身为福利院的一名孩子。他与室友罗莎莉亚的对话揭示了福利院内部的黑暗与压迫。郝院长以“捉迷藏”为名，实际上是在进行一场残酷的筛选，表现好的孩子可以获得“领养机会”，而失败的则可能面临未知的命运。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">罗莎莉亚对圣西尔的信仰逐渐加深，她相信圣西尔会保护她。然而，当“捉迷藏”游戏再次开始时，罗莎莉亚在绝望中向圣西尔祈求，最终陷入了一种恍惚的状态，仿佛被某种力量控制。监督意识到，罗莎莉亚已经无法分辨现实与幻觉，而他自己也逐渐被卷入这场无法逃脱的噩梦。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过苏筱、马尔斯的现实调查与监督的幻境交错展开，揭示了福利院背后的黑暗与孩子们的绝望。黑影的“捉迷藏”游戏象征着福利院的压迫与筛选，而罗莎莉亚的信仰则成为了她最后的希望，却也成为了她的枷锁。监督在幻境中的经历则暗示了福利院的过去与未来的某种联系，真相逐渐浮出水面。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-6 在花园中</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“直到钟声敲响，直到神圣的宝座从高空坠落，坠入永恒的梦乡。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院二楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 23:20</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯救下了金发男孩克里斯，并从他口中得知了福利院的更多秘密。克里斯透露，七叶和鸢最近行为异常，甚至发生了争吵。七叶的身体状况恶化，被坎贝尔院长秘密安置在某个地方，而鸢则在某天突然消失。克里斯还提到，福利院中有许多孩子突然失踪，疑似被“领养”，但没有任何领养人上门的迹象。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯意识到，福利院背后隐藏着更大的阴谋，可能与出世间有关。克里斯提供了宝贵的情报，但他对福利院的黑暗真相并不完全了解。就在他们继续讨论时，门外传来了敲门声，打断了他们的对话。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院·庭院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1100-04-10 10:36</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督的意识再次穿越到过去，化身为福利院的一名孩子“江昙”。她坐在庭院中，思绪飘忽不定。葵的出现打破了她的平静，葵告诉她，院长推荐她作为领养对象，但江昙对此感到困惑与不安。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在院长室，江昙面对两位领养人，表现出异常的冷静与疏离。葵极力推荐江昙，声称她是“最符合期望的孩子”。然而，江昙对葵的动机感到疑惑，尤其是葵曾经对院长的不满与如今的顺从形成鲜明对比。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最终，江昙同意被领养，但她并不知道这将带来怎样的命运。在领养过程中，江昙经历了极度的痛苦与折磨，身体被切割，意识逐渐模糊。在濒死之际，她感受到了一道熟悉的光芒，仿佛看到了葵的身影。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过苏筱、马尔斯的现实调查与监督的幻境交错展开，揭示了福利院背后的黑暗与孩子们的绝望。克里斯的求救信与七叶、鸢的失踪暗示了福利院的阴谋，而江昙的经历则揭示了福利院对孩子们的残酷对待。真相逐渐浮出水面，监督的幻境与现实交织，预示着一场更大的风暴即将来临。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-7 乐园伊始</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“——神拒绝垂听的愿望，我会帮你实现。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院三楼·走廊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1106-06-25 12:50</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">简·坎贝尔在福利院的走廊中巡视，回忆起过去的种种。七叶的提问让她陷入沉思，尤其是关于院长郝琳的罪行以及福利院的未来。简意识到，自己多年来对郝琳的默许让她成为了帮凶，但她依然希望保护福利院的孩子们。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在庭院中，简向圣西尔雕像祈祷，祈求神明怜悯孩子们。就在这时，葵出现了，她带来了足以挽救福利院的资金，并提出由简来管理福利院，将其打造成一个纯粹的乐园。简虽然对葵的能力感到疑惑，但最终选择信任她，接受了她的提议。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院·庭院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1107-07-19 15:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">简正式成为葵花福利院的院长，福利院的运营逐渐步入正轨。她努力为孩子们创造一个温馨的环境，处理孩子们之间的矛盾，尤其是新来的女孩鸢与男孩乔治的冲突。简希望通过自己的努力，让每个孩子都能把这里当成家。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">七叶与鸢的相处让简想起了过去的江昙，她希望鸢能像江昙一样，逐渐融入福利院的大家庭。简的回忆与现实的交织，揭示了她在福利院中的成长与对孩子们的深切关怀。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过简的视角，展现了她在福利院中的挣扎与努力。她从一个旁观者逐渐成为孩子们的守护者，试图在郝琳的阴影下为孩子们创造一个更好的未来。葵的出现与简的信任，象征着福利院的新生，而简的誓言与行动则预示着她将为孩子们打造一个真正的乐园。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-8 愿你平安</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“小鸢也有自己的颜色，日子还长着呢，别急呀。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院二楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 23:25</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯在克里斯的房间中躲避坎贝尔院长的检查。克里斯巧妙地用噩梦的借口应付了院长的询问，成功掩护了两人。坎贝尔院长离开后，克里斯提到自己收藏了一些旧报纸，其中有许多关于“极光”的报道。马尔斯对这些报道有印象，提到这是他6岁时发生的新闻。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯决定继续调查，克里斯则留在房间中为他们打掩护。克里斯将自己的护身符——一个吊坠交给两人，希望圣西尔大人能保佑他们。马尔斯接过吊坠，表示会妥善保管。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">（车内）</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">霍冉在车内回忆起与鸢的对话，意识到鸢当时可能正面临某种困境。她后悔没有多问几句，试图联系监督但未成功。下车查看时，霍冉发现监督的车还在，但人却不见了，心中充满疑惑与担忧。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过苏筱、马尔斯的行动与霍冉的回忆交错展开，揭示了福利院背后的秘密与鸢的困境。克里斯的护身符象征着福利院孩子们的信仰与希望，而霍冉的回忆则暗示了鸢可能面临的艰难抉择。监督的失踪则预示着更大的危机即将来临。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-9 暗潮</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“——R.E.D.不再负责此案，你无权过问，十手副队长。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">泊通港·26号码头</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年6月5日 22:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">田偌在泊通港进行常规调查，目标是富运集团。他在码头偶遇了鹿路运输的经理唐路遥，两人交谈中，唐路遥透露了关于富运集团的一些内幕。富运集团虽然没有通过公开招标，却成功加入了官方X晶石运输的合作名单，暗示其中可能存在不为人知的交易或权力运作。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局·R.E.D.办公室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫与副局长岳重山进行了一场紧张的对峙。十手卫质问岳重山为何将重要案件转移给其他部门，并提到海伦和刑舟的案件。岳重山则暗示十手卫与白荆科技的老板走得太近，提醒他及时收手。十手卫对岳重山的回答感到不满，意识到R.E.D.可能被有意限制在无关紧要的案件中，无法触及真正的核心问题。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过田偌的调查与十手卫的对峙，揭示了海临警局内部的权力斗争与复杂的利益关系。富运集团的秘密与R.E.D.的困境暗示了更大的阴谋正在酝酿，而出世间的影子似乎无处不在。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-10 月光舞曲</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“从此以后，这里有一根线，连在我们中间。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">“我”</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">（这是……我？）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">“我”</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">（为什么……有种奇怪的感觉……）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">感受到脖子上的重量，我下意识摸了摸胸前，是一个装饰着翅膀的吊坠。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">福利院三楼·房间内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1112-07-06 22:10</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢与七叶在深夜偷偷溜出房间，来到庭院中。月光下，七叶提议跳舞，尽管两人都不擅长，但在彼此的配合下，她们逐渐放松，跳得越来越开心。鸢在跳舞后向七叶展示了她手臂上的疤痕，透露了她在前一个福利院遭受的暴力。七叶安慰鸢，表示无论好坏，她们都会一起承担。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">两人玩起了翻花绳，七叶用丝线将她们的小指绑在一起，象征着她们之间的约定。鸢感受到七叶的温暖与支持，内心的孤独感逐渐消散。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">然而，就在这温馨的时刻，鸢的意识开始模糊，眼前的景象扭曲变形。她听到了一段模糊的对话，似乎涉及某个“教主”和一场实验。对话中提到七叶的愤怒以及“优质材料”的优待，暗示着福利院背后隐藏的黑暗。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最终，鸢的意识陷入混沌，她感受到某种力量在召唤她，似乎要与她融合。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过鸢与七叶的互动，展现了她们之间的深厚友谊与信任。然而，福利院背后的阴影逐渐浮现，对话中的“教主”与“实验”暗示了更大的阴谋。鸢的意识模糊与融合的预感，预示着她可能被卷入一场无法逃脱的命运。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-11 恶鬼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你不知道么？我是住在你心里的鬼呀。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">意识飘忽沉浮，长廊不断重组又破碎，仿佛整个世界都陷入了混沌。恍惚中似乎有光点飞过，我想要伸手去触碰它，却感到一阵无力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">“我”从出生起就与常人不同，面对欺凌和虐待，内心最大的感受不是恐惧，而是复仇的欲望。只有通过报复，才能让“我”感到片刻的平静。这种思考方式似乎不正确，但“我”无法抑制内心的恶念。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院四楼·祈祷室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-05-22 23:18</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢来到祈祷室，将一副手铐交给柳池，后者自称“柳叶刀”。鸢表示，后天她将按照他们的要求去袭击白汲，这是她答应的最后一件事。柳池对鸢的决定感到意外，调侃她连刀都没拿过，但鸢坚定地表示自己已经选好了武器。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">柳池提到，每个人心里都住着一只鬼，暗示着内心的黑暗。鸢请求柳池不要将她的计划告诉七叶，柳池则嘲讽鸢的软弱，并表示嫉妒她们的感情。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢提到“全新阻断药”，希望它能治好七叶的病，但柳池对此不置可否，表示自己只是“杀人刀”，不是“救命神药”。鸢威胁柳池，表示如果七叶的数据达到稳定线，她才会告诉他们纯晶浓缩液的位置。柳池冷笑着回应，表示鸢的威胁毫无意义，出世间不会在意她的死活。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">柳池最后提醒鸢保重身体，并自称是“住在你心里的鬼”，暗示着鸢内心的黑暗与挣扎。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过鸢与柳池的对话，揭示了鸢内心的矛盾与挣扎。她为了保护七叶，不惜与出世间合作，但内心却充满了对黑暗的恐惧与抗拒。柳池的言辞则进一步揭示了出世间对鸢的利用与漠视，暗示着鸢可能无法逃脱的命运。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-12 救赎之门</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“他们已经在这里藏了足够久的时间，需要有人去找到他们，结束这场游戏了。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">无数的记忆片段在脑中交叠摇曳，不同的面孔在眼前飘忽闪烁，可我却抓不住任何切实的影子。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">？？？</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">■■■，不要被那些记忆和过去困住。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">？？？</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">回想起来，你是谁？</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">“我”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">我……是谁？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">行动间一个徽章掉在地上，清脆的碰撞声响顿时清空了脑中的杂音。</span></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">老师……筱筱……</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">想起来了，我是白荆科技的执行官，来这里是为了找到鸢，调查葵花福利院的秘密……</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">我不是他们中的任何一个……</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">我是监督！</span></p><p style=\"line-height: 2;\"><br></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在找回自己的身份后，监督意识到自己身处一个异常的意识空间，四周的雾气逐渐消散。云无月以蜉萤的形态出现，帮助监督理清现状。云无月解释，这里并非寻常的意识空间，而是由两种不同的混沌力量交汇而成，监督需要在这里寻找线索才能脱身。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督回忆起自己在福利院门口听到歌声后昏倒的经历，开始怀疑那些“梦境”是否真实。云无月指出，这里的每一扇门后都藏有一段记忆，且这些记忆并非由单一的同调者构筑，暗示着福利院背后隐藏着更大的秘密。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在走廊中追上一个男孩的身影，却发现他并非罗莎莉娅，而是一个陌生的孩子。男孩自称是福利院的一部分，并引导监督打开一扇门。门后是一具与男孩长相一模一样的孩子的尸体，手中紧握着猫头鹰战士的徽章。男孩解释，这孩子直到最后一刻都在祈祷与家人团聚。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">男孩告诉监督，这里还有其他孩子的尸体，并暗示他们的死亡与一场“游戏”有关。监督意识到，这些孩子的死亡可能与福利院的秘密实验有关，而男孩的目的似乎是让监督揭露真相。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在监督准备追问时，身后突然传来了敲门声，暗示着更大的危机即将来临。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过监督与云无月的互动，揭示了福利院背后的黑暗与秘密。男孩的引导与门后的尸体象征着福利院对孩子们的残酷对待，而监督的任务则是揭露真相，结束这场“游戏”。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-13 匣中信仰</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“莹蓝色的希望，就在我的手上。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院·二楼·走廊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-05 23:32</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯在福利院的走廊中小心前行，准备前往院长室调查。马尔斯提到坎贝尔院长对官方的不信任与“神眷”的说法，暗示她的背景不简单。两人在院长室门口遇到云无月，得知监督失踪的消息。云无月解释，她进入福利院是为了确认一些东西，但并未与苏筱等人碰面。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯开始调查院长室，发现了坎贝尔院长的日记、合影、老照片以及一张巨额支票。日记中揭示了坎贝尔院长曾是恩利都普洛实验室的实验员，参与过关于人类进化的实验。她的女儿奥罗拉在实验中死亡，成为她一生的伤痛。坎贝尔院长后来来到葵花福利院，试图通过信仰赎罪，但最终与出世间合作，试图通过实验让孩子们获得“神眷”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和马尔斯推测，坎贝尔院长与出世间有密切联系，而福利院的秘密可能与“神眷”实验有关。他们决定前往祈祷室寻找更多线索。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在意识空间中与鸢相遇，鸢坦承自己袭击了白汲，并将屏蔽器、手铐和纯晶浓缩液交给了出世间。她解释，自己是为了救七叶才与出世间合作，但如今意识到出世间可能只是在利用她。监督指出，出世间如果真的掌握了新型阻断药，为何不公开，暗示他们可能另有目的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">“柳泊远”出现在意识空间中，解释这个空间是为了保护孩子们而存在，但最终他们被困死在这里。他提到“她”的力量正在失控，希望监督能在空间崩溃前找到真相并阻止悲剧。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和鸢在“柳泊远”的指引下，准备推开一扇门，寻找最后的真相。监督意识到，自己曾在无数个门后扮演过“他们”，而这场悲剧的罪人不止一个。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过苏筱、马尔斯的调查与监督在意识空间中的经历，揭示了福利院背后的黑暗与出世间对孩子们的利用。坎贝尔院长的过去与她的赎罪之路交织在一起，而“柳泊远”的出现则暗示了更大的阴谋与悲剧。监督的任务是找到真相，阻止空间的崩溃，拯救那些无辜的孩子。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-14 忏悔者</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">烛光仍在摇晃，影子打在神像沉默垂眸的脸上，仿佛一滴眼泪。——不知为谁而流。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">葵花福利院·祈祷室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-06 00:05</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在意识空间中与鸢相遇后，意识重新回到现实，发现自己与鸢躺在祈祷室的地上。苏筱、马尔斯和云无月赶来，解释他们从坎贝尔院长的日记中推测出她可能将重要物品藏在祈祷室，因此前来调查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督注意到圣西尔雕像的裂纹中透出蓝色光芒，推测雕像内可能藏有X晶石。通过机关，他们打开了雕像背后的暗门，发现了躺在手术台上的七叶。七叶的身体遍布切割痕迹，血液不断涌出，场面令人震惊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">坎贝尔院长突然出现，解释七叶正在接受“试炼”，试图成为“杰作”，即人类进化的顶点。她声称七叶是心甘情愿的，为了守护身边的人而献身。鸢无法接受这一说法，情绪失控。坎贝尔院长指责鸢背叛了七叶，并宣布葵花福利院不再欢迎他们。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">坎贝尔院长在生命的最后时刻回忆起自己的女儿奥罗拉，似乎将她与江昙混淆，流露出深深的悔恨与痛苦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">七叶突然苏醒，身上的伤口开始愈合，但体内却生出无数藤蔓，迅速蔓延整个房间。七叶在短暂的停顿后夺门而出，监督等人决定追上去，防止她跑到外面造成更大的危害。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节揭示了坎贝尔院长的疯狂与忏悔，她试图通过X晶石和实验让孩子们获得“神眷”，但最终导致了七叶的悲剧。七叶的异化与失控则预示着一场更大的危机即将来临，监督等人的任务是阻止她，拯救无辜的生命。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-16 当枯萎来临</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我好像做了一个噩梦。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">七叶在庭院中停下，体内涌出的藤蔓迅速蔓延，释放出强大的威压。马尔斯和云无月都意识到七叶的力量远超普通同调者，且她的精神已经异化，难以控制。监督等人试图找到阻止她的方法，但云无月表示无能为力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢陷入深深的自责，认为是自己的错误导致七叶陷入如此境地。她决定不再逃避，准备用自己的力量救七叶。鸢凝聚出一支紫色的箭，象征着她的决心与勇气，她誓言无论结果如何，都要承担一切后果。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢和七叶在梦境般的花海中相遇，七叶安慰鸢，表示自己并未离开。鸢意识到自己必须面对现实，决定与七叶一起离开这个虚幻的地方。七叶最终在鸢的怀中安详地闭上了眼睛，花瓣随风飘散，象征着七叶的离去与鸢的解脱。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人联系了R.E.D.和海临医疗中心，等待警方的到来。崔远之作为外援出现，他推测七叶可能是森罗第一例“高级”同调者，但因肉体无法承受强大的异核力量而衰竭。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">未知地点</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">江昙与琴初（出世间圣女）就葵花福利院事件展开激烈争论。江昙质问琴初为何没有及时制止福利院的悲剧，琴初解释自己无法控制下属的行动，并表示七叶的失控是意外。琴初透露自己即将接受手术，试图通过进化登上顶点，让世界无条件接受“她”。江昙对琴初的计划表示担忧，但琴初坚信自己走在正确的道路上。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">柳叶刀（柳池）出现，暗示他与琴初之间有某种交易。琴初提醒柳叶刀小心行事，并决定调查袭击白汲的真相。</span></p><p style=\"line-height: 2;\">总结：</p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过鸢与七叶的告别，揭示了七叶的牺牲与鸢的成长。琴初与江昙的对话则揭示了出世间的野心与内部矛盾，预示着更大的阴谋即将展开。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S6-17 长路难行</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">欢迎返岗。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临医疗中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-06</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">鸢在医院中准备出院，并向监督正式提出辞职，表示愿意为自己的行为承担后果。监督接受了她的辞呈，但表示白荆科技随时欢迎她再入职。白汲也前来探望鸢，两人进行了简短的交谈，白汲对鸢的变化感到意外，认为她的觉醒之路走得太突然。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临医疗中心·走廊</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与白汲在走廊中交谈，讨论同调者的定义。白汲认为同调者与普通人无异，只是他的病人。监督则提到自己被问及“同调者是什么”时无法回答，白汲的答案让她感到安心。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">医院外</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">霍冉、苏筱和狄砚陪同鸢前往警局，霍冉表示大家会等她回来。鸢感受到众人的温暖，心中充满感激。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">泊通港·客运码头</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-08 10:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与十手卫在码头会面，十手卫透露北三岛有出世间的动静，并交给监督一张前往凛阳的船票，暗示北三岛可能有更大的阴谋。十手卫提醒监督要低调行事，避免被盯上。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督得知白荆科技在北三岛有成员接应，十手卫也安排了血露薇的人协助。十手卫强调监督的“聪明脑袋”是最厉害的武器，鼓励她在北三岛挖掘更多信息。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在登船前，唐路遥突然出现，成为监督的同行人。监督在船上收到鸢的返岗申请，欣然批复。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过鸢的觉醒与监督的北三岛之行，揭示了角色的成长与新的挑战。鸢选择面对自己的错误，而监督则踏上了前往北三岛的未知旅程，预示着更大的冒险即将展开。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:44:01', '2025-02-26 19:22:53', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (12, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/lm3epnssunl5murcltixqvpg445df70_20250217120043A011.png', 11210608, '07#瘾 ＞', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,奈默,鸿雁于飞,冰舞ぜ紫灵猫', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"><strong> S7-1 “邂逅”</strong></span><span style=\"font-size: 15px;\"><br>“愿你得到宁静与长眠 愿你的意念如同不熄的炬火。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·九旻海域</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-08 11:26</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督站在甲板上，迎着海风，享受着难得的海上时光。唐路遥端来两杯茶和甜甜圈，两人闲聊间提到此次出行的原因。唐路遥透露自己此行是陪一位白衣少年回凛阳，因其家中有人病重。监督对此感到意外，询问少年的身份，唐路遥暗示其家境显赫，与北三岛的本土组织“天鹿”有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 轮船广播通知即将靠岸，但临时出现机械故障，乘客需在船上等待。监督注意到岸边有一群黑衣人和一辆豪华的黑色老爷车，猜测是来接应少年的。果然，一名戴口罩的黑衣少女带着两名黑衣人上船，直接走向白衣少年，邀请他上车。少年虽不情愿，但在唐路遥的劝说下还是跟随他们离开。监督则混入人群，准备下船。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 在安检时，监督担心行李箱中的防身物品无法通过，但一名工作人员暗中切断金属探测仪电源，顺利放行。监督认出这名工作人员竟是失踪已久的南渚，两人在小巷中短暂交谈。南渚暗示自己与出世间有关，但否认加入他们。监督并未深究，只是感叹他还活着。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 余音突然出现，用长枪拦住南渚的去路。监督解释这是白荆科技外勤小组γ小队的队长余音，南渚则趁机离开。余音递给监督一张邀请函，邀请白荆科技代表参加天鹿五代首领玄戈的葬礼。监督意识到北三岛的气氛比想象中更加复杂，决定深入调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-2 夜巡</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我应该相信自己的大脑和判断。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·夜巡大道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 10:24</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在凛阳的街道上漫步，虽然北三岛的寒意仍未散去，但夜巡花的点缀让空气清新了不少。监督回忆起前日与余音的对话，余音提醒他北三岛的势力复杂，外人难以介入。监督意识到此行可能是个陷阱，但仍决定依靠自己的判断力。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·旅馆内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">前日入夜 21:05</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与余音讨论北三岛的局势，余音提到出世间可能隐藏在幕后，难以追踪。监督推测出世间可能设下陷阱，但南渚的出现让他感到意外。南渚似乎与出世间有关，但监督认为出世间不会深谋远虑到用南渚引他上钩。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 凛阳·默希港</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 15:03</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到默希港，发现港口因特殊原因关闭，所有民用海航停止服务。监督询问港口工作人员，得知封锁可能与天鹿有关。监督意识到北三岛的气氛紧张，决定继续调查。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·小巷</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 21:55</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与南渚在小巷中再次见面。南渚透露自己在北三岛的身份是天鹿的新人，负责默希港区。监督推测出世间可能有人想帮助他，但南渚并未透露更多信息。监督决定继续利用南渚的情报，同时保持警惕。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·旅馆内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 21:55</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱通话，讨论海临的产品举报事件。苏筱提到调查已结束，监督则分享了自己在北三岛的复杂情况。监督提到南渚的出现，苏筱感到惊讶。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·旅馆内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 23:17</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在整理行李箱时发现一张陌生的金属牌，上面镶嵌着类似骨质的花瓣。正当监督疑惑时，一只千纸鹤出现在窗外。监督打开窗户，千纸鹤飞入房间，随后舞鹤织雪出现在窗外。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-11 23:17</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">舞鹤织雪带监督体验凛阳的夜生活。两人在街道上漫步，舞鹤织雪提到北三岛的X晶石随处可见，监督感到担忧。舞鹤织雪提议去酒吧，监督决定前往。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-12 00:23</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入酒吧，发现唐路遥也在场。唐路遥与富运工作人员和天鹿打手交谈，提到天鹿首领被炸死的事件，以及血露薇的嫌疑。监督听到这些信息，感到震惊。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-12 00:23</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在酒吧中遇到之前在船上见过的红衣男子，对方自称宁先生，并询问监督是否收到了他的委托品。监督感到困惑，意识到自己可能卷入更大的阴谋中。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-3 黑桃A</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“其名为「谒声」。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-12 01:06</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与自称“宁先生”的男子在酒吧中玩牌，宁先生通过牌局向监督透露了关于天鹿组织内部的秘密。宁先生提到“谒声”是天鹿的独立部门，负责在首领死亡时主持葬礼并宣布继任者。监督通过牌局逐渐了解到“谒声”的地位和作用，并得知自己手中的金属牌是“谒声”身份的象征。宁先生希望监督能够利用这张牌，帮助他延期继任仪式，以救下某人。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·墓园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-13 09:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到天鹿墓园，准备主持五代首领玄戈的葬礼。墓园内，天鹿的干部们低声议论着白荆科技的代表和继任者的人选。监督注意到白荆科技的首席执行官已经到场，但对方并未认出自己。监督通过通讯仪与唐路遥联系，得知唐路遥会迟到。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 凛阳·天鹿墓园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-13 10:14</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">葬礼即将开始，天鹿的干部们继续讨论继任者的问题，大多数人认为左枢是最有可能的继任者。监督注意到左枢的耳饰和博金斯爵士车前的坐像，意识到左枢在天鹿中的地位非同寻常。左枢与监督交谈，询问“谒声”的身体状况，并希望监督能够主持葬礼。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">葬礼中断</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督开始宣读玄戈的遗嘱，宣布天鹿的新任首领人选。然而，就在监督即将宣布继任者时，玄戈的弟弟北洛突然出现，打断了仪式。北洛质疑玄戈的死亡真相，并暗示左枢可能与此有关。左枢并未表现出愤怒，而是冷静地处理了这场突发状况。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">继任延期</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督根据宁先生的请求，宣布继任仪式延期15天，以便进一步调查玄戈的死亡真相。左枢支持监督的决定，并表示天鹿不可长久无人掌舵。仪式结束后，监督准备离开墓园，柚理跟随在侧。突然，柚理察觉到危险，命令监督趴下。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-4 灼烧</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“有时候，镁光灯下才是最安全的。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-14</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫与刘警官在警局内讨论关于白荆科技的举报事件。刘警官提到最近持续接到关于白荆科技的举报，甚至有人闹事。十手卫表示白荆科技并未出现在他们的调查名单上，暗示白荆科技的问题可能与外部势力有关。刘警官提到自己最近忙于调查白荆科技的举报事件，十手卫则调侃刘警官的健忘和秃头问题，气氛轻松。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">特殊事件处理小队R.E.D.</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-14</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫与监督通话，讨论关于旻望基金会的调查情况。十手卫表示旻望基金会与北三岛没有明显的活动痕迹，但也不排除他们隐藏得很深。十手卫调侃监督在天鹿的新身份，提醒她不要带回奇怪的东西。监督提到自己已经与南渚和舞鹤织雪见过面，暗示出世间在北三岛的活动可能与天鹿内部有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿某室内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-14 半小时前</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在天鹿大楼内与柚理会面，柚理提供了关于玄戈死亡案件的调查资料。监督仔细阅读了案件的细节，发现玄戈在罗兰花园酒店的爆炸事件中身亡，现场的证据指向血露薇的代表白鸟梓。监督决定亲自与白鸟梓会面，了解事件的真相。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">与白鸟梓的会面</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入关押白鸟梓的房间，白鸟梓起初表现出敌意，但监督表明自己的身份后，白鸟梓放松了警惕。白鸟梓表示自己与玄戈的死亡无关，爆炸发生时她只是奉命与玄戈谈生意。监督相信白鸟梓的证词，但意识到案件的复杂性远超表面，可能与天鹿内部的权力斗争有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">与左枢的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与左枢讨论案件进展，左枢提供了关于车辆爆炸的调查结果，暗示天鹿内部的混乱局势。左枢提到炸药来源未知，但只有他和玄戈有能力接触到车辆和墓园的雕像。监督意识到左枢可能在暗示自己也是嫌疑人之一，决定加快调查进度。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 车辆的爆炸</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督乘坐左枢提供的专车离开天鹿大楼，柚理原本要随行，但监督以行程不便为由让她留下。车辆行驶途中，监督回想起左枢的暗示，意识到自己可能已经卷入天鹿内部的权力斗争。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">戴医生与左枢的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">左枢与戴医生讨论自己的健康状况，戴医生发现左枢的病情没有好转，怀疑他私自更换了药物。左枢否认了这一说法，但柚理承认自己擅自更换了药物，担心左枢的身体状况。左枢对柚理的行为感到失望，但并未责怪她。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·监督办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-14</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱与余音通话，得知监督乘坐的车辆爆炸，苏筱感到十分担忧。余音安抚苏筱，表示监督已经提前得知车辆可能存在隐患，爆炸事件在她的计划之中。苏筱逐渐冷静下来，决定相信监督的判断。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">瞳的出现</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瞳来到监督办公室，与苏筱讨论监督的处境。瞳表示袭击不一定是坏事，暗示监督可能已经掌握了某种主动权。苏筱对瞳的突然出现感到惊讶，瞳则轻描淡写地表示自己只是来“看看”。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-5 海盐</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“有人要切除毒瘤，就要先找到病灶。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-15 00:14</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督再次来到GOLDEN QUILL酒吧，与宁先生会面。宁先生提到天鹿内部存在许多“毒瘤”，需要有人找到并切除这些病灶。监督意识到自己不仅要调查玄戈的死亡真相，还需要深入了解天鹿内部的复杂局势。宁先生表示希望监督能在15天的延期期间调查天鹿的“影子”，监督最终同意了他的请求。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-15 01:06</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督离开酒吧后，在街道上遭遇袭击。虽然成功躲过，但监督意识到天鹿内部的局势远比表面看起来更加复杂。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·天鹿总部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-15 10:20</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与左枢讨论袭击事件，左枢表示天鹿内部人人都有可能接触到袭击所用的子弹，无法确定嫌疑人。监督拒绝左枢提供的保护，表示自己需要更多的权限来调查玄戈的死亡真相。左枢同意开放权限，并安排羽林带监督前往档案室。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿档案室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在档案室查阅天鹿的历史和内部资料，发现天鹿的初代首领维克多·卡修斯·奥尔恩与长垣共同创立了天鹿，二代首领长垣则进一步壮大了组织。三代首领弗吉利奥·杰诺维斯通过血腥手段上位，四代首领昴则重新找回了被驱逐的「谒声」，并褫夺了三代的权力。五代首领玄戈在昴死后继位，但突然离世，留下许多未解之谜。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 监督在系统中搜索“出世间”、“旻望基金会”等相关信息，但一无所获。搜索“南渚”时，发现他的档案非常简短。监督还注意到羽林和岚相的调动发生在玄戈出事之后，暗示天鹿内部的权力斗争。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">与羽林的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与羽林讨论玄戈的死亡真相，羽林表示玄戈的离开非常突然，许多人对此感到意外。监督试探性地询问羽林是否认为玄戈真的死了，羽林沉默片刻，没有给出明确回答。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督逐渐意识到天鹿内部的权力斗争和复杂局势，决定继续深入调查玄戈的死亡真相，同时也要揭开天鹿内部的“影子”。通过与宁先生、左枢和羽林的对话，监督逐渐掌握了更多的线索，但也面临更大的危险。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-6 苦橙</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这里到处都是玄戈的「遗产」。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·玄戈宅邸外</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-16</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到玄戈的宅邸，宅邸气势恢宏，庭院广阔，显示出天鹿首领的地位。监督在宅邸外观察到左枢离开后，才进入宅邸。宅邸内部装潢豪华，但有些年代感，显示出历史的沉淀。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 与「洛少爷」的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与玄戈的弟弟北洛会面，北洛对天鹿内部的权力斗争表现出不屑。北洛提到自己被叫回凛阳的原因，暗示天鹿内部有人想推他上位以制衡左枢。监督意识到北洛在天鹿内部的地位比想象中更加复杂。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 调查玄戈的书房</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在玄戈的书房内进行调查，发现了一些线索。书架上堆满了各种语言的晦涩名著，桌上放着玄戈的全家福，抽屉里有一把装了消音器的手枪和几板药片。监督还发现了一个装有橙色砂砾的密封罐，推测这可能与玄戈的死亡有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">与罗尼亚夫人的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督询问罗尼亚夫人关于密封罐的来源，罗尼亚夫人表示这是玄戈一周前带回来的。她还提到玄戈在带回砂砾后突然发烧，戴医生建议进行手术，但玄戈拒绝了。监督怀疑玄戈的死亡与这些砂砾有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿总部·档案室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-17</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在天鹿总部的档案室查阅戴医生的资料，发现戴医生在1118年曾为左枢进行过手术，左枢因此成为同调者。监督还发现左枢在三年间接受了多次手术，怀疑戴医生可能与玄戈的死亡有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 与柚理的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与柚理交谈，得知左枢的病情再次发作，柚理提到戴医生曾为左枢注射过一种名为“纯晶浓缩液”的药剂，效果显著，但现在已经无法获得。监督意识到这种浓缩液可能与出世间有关。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督逐渐揭开了天鹿内部的复杂局势，发现玄戈的死亡可能与橙色砂砾和戴医生有关。通过与北洛、罗尼亚夫人和柚理的对话，监督掌握了更多线索，但也意识到自己面临的危险。监督决定继续深入调查，揭开天鹿内部的“影子”和玄戈死亡的真相。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>S7-7 好朋友<br></strong></span><span style=\"font-size: 16px;\">“现在”即将成为“过去”，我们每时每刻都要做好迎接“未来”的准备。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-17 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在酒吧中思考着天鹿内部的复杂局势，意识到玄戈的死亡可能与橙色砂砾和戴医生有关。她通过查阅资料和与柚理的对话，逐渐揭开了天鹿内部的“影子”和玄戈死亡的真相。监督决定利用手中的线索，继续深入调查。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 与唐路遥的偶遇</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在酒吧中偶遇唐路遥，唐路遥借监督的通讯仪发了几条消息后离开。监督回到酒店后，发现唐路遥在通讯仪上留下了简短的留言，提到北洛的情况，并表示如果有需要，北洛可以交给他处理。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 与余音的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督回到酒店后，与余音讨论调查进展。余音表示已经整理好今天的调查信息，并同步至监督的终端。监督意识到自己已经掌握了大量线索，但依然无法触及出世间。她决定制定一个计划，需要余音的帮助。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·默希港口</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-18 凌晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">南渚和舞鹤织雪在港口监视着进出港口的船只。南渚提到自己在港口巡逻时发现了一些奇怪的药物，舞鹤织雪暗示这些药物可能与怪化病有关。两人讨论出世间的计划，舞鹤织雪提到自己将一些“有趣的东西”给了需要的人，暗示她可能在暗中推动某些事件的发展。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督逐渐揭开了天鹿内部的复杂局势，发现玄戈的死亡可能与橙色砂砾和戴医生有关。通过与唐路遥、余音的对话，监督掌握了更多线索，但也意识到自己面临的危险。监督决定继续深入调查，揭开天鹿内部的“影子”和玄戈死亡的真相。与此同时，南渚和舞鹤织雪在港口监视着进出港口的船只，暗示出世间可能在暗中推动某些事件的发展。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S7-8 灯下黑</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"color: rgb(140, 140, 140); font-size: 16px;\">“枪不会自己扣动扳机,凶手才会。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·左枢办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音代表白荆科技与左枢会面，提出与天鹿合作开发X晶石技术的提议。左枢表示天鹿目前正处理内部事务，暂时无法考虑合作。余音提到白荆科技即将发布一项新技术，暗示这可能对天鹿产生影响。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技发布会现场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">白荆科技举行发布会，宣布成功研发“纯晶浓缩液”技术，该技术能将X晶石的利用率提高至3至3.5倍，并将固态X晶石转化为液态，未来有望广泛应用于能源领域。发布会由瞳主持，遥城研究院的巫炤教授也出席并发表意见。记者们对这项技术表现出极大兴趣，询问其量产时间和潜在影响。瞳表示技术尚在实验阶段，无法确定量产时间，并拒绝回答与白荆科技近期舆论风波相关的问题。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">发布会幕后</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱在发布会后感到紧张，担心白荆科技的处境。瞳安慰她，表示发布会只是个开始，接下来还有很多工作要做。巫炤对白荆科技的决定表示不赞同，但尊重他们的选择，并希望监督不要让他失望。孔秘书提到姬轩辕已安排好巫炤的行程，巫炤则表示要回酒店休息。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·夜市</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫与田偌在夜市吃烧烤，讨论R.E.D.的现状。十手卫提到R.E.D.暂时被调往其他科室工作，田偌对此感到担忧。十手卫安慰他，表示这只是暂时的调整，R.E.D.依然存在。丁苑青与十手卫通话，表达想加入特殊事件处理小队的愿望，十手卫鼓励她保持平常心，等待机会。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">白荆科技通过发布会公开了“纯晶浓缩液”技术，试图通过扩大影响力来应对出世间和其他势力的威胁。与此同时，天鹿内部的权力斗争仍在继续，左枢对白荆科技的提议持保留态度。在海临，R.E.D.的成员们也在调整心态，面对未来的不确定性。监督的计划逐渐展开，各方势力在这场博弈中暗自角力。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>S7-9 铁锈</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“死亡并不能摧毁一个人，但\'不受控\'可以。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">新闻播报</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">新闻主播们纷纷报道白荆科技发布的新技术“纯晶浓缩液”，讨论其潜在的应用前景和对能源领域的革命性影响。白荆科技发言人表示已与遥城研究院展开合作，计划在未来几个月内进行更深入的研究和测试。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿总部·走廊</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在天鹿总部内行走，逐渐适应了“谒声”的身份。她通过余音的消息得知左枢对浓缩液的兴趣并不高，心中疑惑加深。她决定继续调查天鹿内部的复杂局势，特别是戴医生的角色。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">戴医生办公室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在戴医生办公室内发现了一份关于“纯晶浓缩液”的研究报告，日期显示为1121年5月，与柚理的说法不符。她意识到戴医生可能私藏了部分浓缩液，并未全部用于治疗左枢。监督决定进一步调查戴医生的背景和动机。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">秘密电梯与弗吉利奥·杰诺维斯的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督通过戴医生提供的电梯卡进入了一处隐秘的房间，见到了天鹿的三代首领弗吉利奥·杰诺维斯。杰诺维斯透露他曾建议左枢通过控制手段对付玄戈，导致玄戈的死亡。杰诺维斯对天鹿的未来充满悲观，认为这艘巨轮注定沉没。监督试图从杰诺维斯口中获取关于出世间的信息，但杰诺维斯表示对此一无所知。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督逐渐揭开了天鹿内部的复杂局势，发现玄戈的死亡可能与左枢和杰诺维斯的阴谋有关。通过与杰诺维斯的对话，监督意识到天鹿内部的权力斗争远比表面看起来更加复杂。她决定继续深入调查，揭开天鹿内部的“影子”和玄戈死亡的真相。与此同时，白荆科技的新技术发布会成功吸引了各方的关注，监督的计划逐渐展开，各方势力在这场博弈中暗自角力。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-10 酸柠檬</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“他和「天鹿」一起长大，没人比他更在乎「天鹿」。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·玄戈宅邸</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-21</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛站在玄戈宅邸的客厅中，手中拿着通讯仪，背包随意扔在地毯上，显示出他随时准备离开的意图。他的猫“陀螺”在一旁玩耍，北洛与它互动，心情复杂。罗尼亚夫人出现，与北洛进行了一番深入的对话。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">与罗尼亚夫人的对话</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">罗尼亚夫人提到玄戈曾试图拯救天鹿，但最终认为如果无法治愈，应该亲手结束它。北洛对罗尼亚夫人的话感到震惊，意识到自己和玄戈的想法相似。罗尼亚夫人鼓励北洛参加继任仪式，并表示如果他真的认为玄戈没死，应该采取行动。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛逐渐理解了玄戈的意图，决定参加继任仪式，并准备在仪式上采取行动。罗尼亚夫人的话让北洛意识到自己与玄戈的相似之处，也让他对天鹿的未来有了新的思考。北洛决定不再被动接受命运，而是主动出击，揭开天鹿内部的真相。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-11 未染</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我会记得每一个为出世间所害的人，也会努力救下每一个因出世间误入歧途的人。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·暗巷</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-23 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与南渚潜入一处天鹿的工厂，发现这里大量加工X晶石，将其制成晶砂并广泛应用于生活用品和药品中。监督意识到北三岛已经成为一个天然的“培养皿”，而天鹿可能早已被出世间渗透。在工厂深处，他们发现了被囚禁的旻望基金会管事海伦，她精神崩溃，口中喃喃自语，暗示出世间正在进行人体实验。几只畸形的鸟形生物袭击了监督和南渚，余音及时赶到，救下了他们。监督决定带回怪鸟的尸体作为证据，继续调查出世间在北三岛的活动。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局·R.E.D.</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-23</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫在办公室内观看白荆科技发布会的新闻，感叹白荆科技的影响力。刘警官提醒他明天还有外勤任务，十手卫准备离开。监督通过通讯仪告知十手卫，她已经找到海伦，暗示调查取得了重大进展。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-12 北风</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“明天，天鹿终于可以重新开始了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿·墓园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-27 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">左枢在墓园内与玄戈的墓碑对话，透露自己对玄戈动过杀心，但玄戈的“死亡”让他意识到天鹿的未来需要一个新的领袖。左枢提到自己身上的药味和金属味，暗示他已经深陷异化综合征的困扰。他决定在继任仪式上支持玄戈，尽管他知道自己已经无法摆脱病症的影响。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">GOLDEN QUILL酒吧</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-27 同一时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在酒吧与姜宁会面，揭穿了姜宁的真实身份——血露薇的魁主。姜宁承认了自己与玄戈的合作，并透露玄戈仍在与异化综合征斗争。监督请求血露薇在未来为白荆科技提供支持，姜宁同意并表示合作愉快。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·车内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-28</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">左枢在前往天鹿总部的路上，意识到自己已经无法继续支撑天鹿的未来。他决定在继任仪式上支持玄戈，尽管他知道自己已经无法摆脱病症的影响。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天鹿总部·继任仪式</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-28</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在继任仪式上，玄戈突然现身，揭露了戴医生的阴谋。戴医生试图使用浓缩液和橙色晶体引发左枢的异化，但左枢最终选择牺牲自己，阻止了戴医生的计划。玄戈在左枢的请求下，开枪结束了左枢的生命。柚理目睹了这一切，感到无尽的悲伤。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">继任仪式以左枢的牺牲和玄戈的重返结束，天鹿内部的阴谋被彻底揭露。监督在这场斗争中发挥了关键作用，与血露薇的合作也为白荆科技的未来提供了保障。玄戈重新执掌天鹿，但异化综合征的阴影依然笼罩着他。柚理在左枢的离去后，陷入了深深的悲痛。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-13 归</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这场牌局，你的确是赢家。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·旅馆内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督终于结束了在北三岛的任务，准备返回海临。她与余音一起收拾行李，决定在离开前享受一顿早餐。余音推荐了一家网络好评的咖啡店，监督欣然接受。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凛阳·港口</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和余音来到港口，准备登船返回海临。在等待检票的过程中，监督遇到了南渚，得知他已经正式加入天鹿，并成为七区的新任队长。南渚决定暂时留在北三岛，监督则提醒他去做体检，确保身体健康。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 与玄戈的会面</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在港口附近遇到了玄戈，两人进行了简短的交谈。玄戈感谢监督在天鹿内乱中的帮助，并表示天鹿已经重获新生。监督提到自己会尽快研究那张身份牌，并将结果同步给玄戈和姜宁。玄戈表示监督可以暂时保留那张牌，作为报酬的一部分。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">登船</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和余音顺利登船，监督终于可以放松下来，享受归途的宁静。她摸了摸口袋，发现装着砂砾的小瓶子还在，决定回到海临后拜托唐经理将其送回北三岛。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">北三岛·街头</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">唐路遥、北洛和无咎在北三岛的街头闲逛，准备返回海临。北洛提到自己对天鹿的未来并不完全在意，但他仍然选择插手，积点德也不亏。唐路遥则调侃北洛是“祖宗”，两人之间的互动轻松愉快。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">未知地点</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">舞鹤织雪与江昙通过通讯器交谈，提到教主的手术成功，并暗示出世间内部的复杂局势。舞鹤织雪表示自己并不在乎出世间内部的争斗，只关心自己的任务是否完成。江昙则派人去接舞鹤织雪，暗示出世间内部的清算即将开始。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督顺利结束了在北三岛的任务，准备返回海临。南渚选择留在北三岛，加入天鹿继续他的冒险。玄戈重掌天鹿，天鹿的未来充满了新的希望。舞鹤织雪与江昙的对话揭示了出世间内部的复杂局势，清算即将开始。监督的旅程暂时告一段落，但未来的挑战依然在等待着她。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> S7-14 不生</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">\"放心，只要过了今天，我就成功了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·富运集团仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-28 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫带领警员在富运集团仓库进行搜查，尽管一无所获，但他敏锐地察觉到异常。在最后一个房间，他发现了一扇半开的门，进入后遭遇了出世间派来的处刑人。两人展开激烈战斗，十手卫最终不敌，身受重伤。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">出世间·手术室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">琴初、江昙和柳叶刀在手术室内进行秘密对话，琴初提到她计划通过“流放”十手卫来观察人性的底色。柳叶刀对琴初的计划表示不屑，但琴初自信满满，认为出世间即将成功。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫的命运</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">处刑人将重伤的十手卫拖走，岳重山出现并接手了十手卫。琴初计划通过改变十手卫的身份和记忆，让他永远无法回到原来的生活。岳重山虽然曾是十手卫的同窗，但为了出世间的大局，他选择执行琴初的计划。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 头条新闻</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">白荆科技因涉嫌技术违规被有关部门要求彻查，暗示出世间已经开始对白荆科技采取行动。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫在调查中遭遇出世间派来的处刑人，最终不敌重伤。琴初计划通过改变十手卫的身份和记忆，让他永远无法回到原来的生活。岳重山虽然曾是十手卫的同窗，但为了出世间的大局，他选择执行琴初的计划。白荆科技因涉嫌技术违规被有关部门要求彻查，出世间对白荆科技的行动已经开始。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/akkhyvaymhwssel1fp6gij3433x6j45_20250214112458A009.jpg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/0klwiygv5xca96tvstwh310dh61tkc5_20250214112553A010.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b2xedfm7lotuxjxavl43thnpoqcflhu_20250214112710A011.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b7eaqdw9ch05xvoeh7iqohoosmtkx4i_20250214112817A012.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/ebnqmop9zuwepoo2wb81i0dko47bcip_20250214112902A013.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/qo3nkdpbzh3hvy032bdqe073lsbgmjj_20250214112932A014.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/7wwl6nbvwm3agw4bxo2mgmkqoaxf8r5_20250214113020A015.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', '2025-02-14 09:45:38', '2025-02-25 17:58:01', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (13, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/8rrhas47zrz5e3rjt55f9pqmhpgwp4s_20250219095347A035.png', 11210609, '炉·心·缇诗 ＞', '间章剧情', '缇诗', '1121年6月09日', '森罗', '洛天依,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">噩梦在将醒未醒时缠身。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">但只要你睁眼。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-1 烈日之下</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我将代表沙玛什，向伊南纳开战。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">伊南纳-沙玛什边境小镇 安那基</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年6月9日，14:47</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">沙玛什士兵在边境发现伊南纳的入侵踪迹，指挥官下令支援。突然，一个白色身影出现在战场，迅速击溃了伊南纳的突击队。伊南纳士兵认出她是莎拉塔尔，曾经的伊南纳战神，但她却宣布自己将代表沙玛什向伊南纳开战。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">沙玛什境内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年6月16日，13:37</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">奇美拉佣兵团的成员们在沙漠中逃亡，讨论着最近的追击行动。他们发现沙玛什的追击方式发生了变化，似乎更注重观察而非直接攻击。纳加尔推测沙玛什人对缇诗有所顾虑，可能因为她的特殊能力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 缇诗表示自己不愿再使用那种“吃人”的能力，纳加尔支持她的决定，强调奇美拉佣兵团将依靠真本事应对敌人。卡拉玛提到几天前出现的“莎拉塔尔”，引发了团队的沉默。纳加尔坚信那个“莎拉塔尔”并非真正的将军，因为真正的莎拉塔尔绝不会与伊南纳或沙玛什合作。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">奇美拉佣兵团围坐在篝火旁，分享食物和水。卡拉玛质疑纳加尔对莎拉塔尔的看法，纳加尔则强调自己亲眼见证了莎拉塔尔的“复生”，并坚信她的怒火将席卷整个厄亚大陆。缇诗表示自己将与纳加尔站在一起。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在此时，米达斯的通讯请求接入，预示着新的任务或危机即将到来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过奇美拉佣兵团的逃亡与讨论，揭示了莎拉塔尔的身份之谜与团队的内部矛盾。沙玛什的追击与缇诗的能力成为故事的关键点，而米达斯的通讯则暗示着更大的挑战即将展开。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-2 飞鸟余温</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">她能感受到一点温热，从掌心跨越冰冷的金属材料，穿过与身体连接的部分，最后流到心脏。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆开始）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">米达斯与纳加尔讨论“战神迦路”的出现，以及“莎拉塔尔”公开背叛对伊南纳的影响。米达斯决定返回伊南纳，前往宁胡尔塔哨站寻找线索。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆结束）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">奇美拉佣兵团在沙漠中讨论“莎拉塔尔”的真实身份。卡拉玛认为可能是沙玛什复制了莎拉塔尔，但纳加尔和缇诗对此表示怀疑。缇诗提到沙玛什的实验进展，并讨论了如何通过破坏芯片后台来解放其他克隆体。纳加尔指出，即使芯片失效，战争也不会停止，因为战争并非由武器发动或终结。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">沙玛什边境小镇 安那基</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">佣兵团在安那基解救被伊南纳士兵抢劫的沙玛什平民。平民们对莎拉塔尔的崇拜让卡拉玛感到不适，缇诗则对平民的盲目信仰感到困惑。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗在废墟中发现一只受伤的隼鸟，感受到生命的脆弱与温暖。她决定带着隼鸟离开，与同伴们继续他们的任务。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过佣兵团的讨论与行动，揭示了战争的无情与人们对莎拉塔尔的盲目崇拜。缇诗的内心挣扎与对生命的感悟，象征着她对自我与使命的深刻思考。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-3 硝烟尽头</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“战争不是兵器带来的，也不会因为它的消失而终结。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">奇美拉佣兵团在沙玛什边境小镇安那基遇到一名逃兵萨鲁，他请求佣兵团带他离开沙玛什。萨鲁透露，沙玛什军队正在征召普通人入伍，并提到“莎拉塔尔”并非真正的战神，而是沙玛什实验室的产物。缇诗对战争的本质感到困惑，认为“兵器”并非战争的必需品。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 在佣兵团准备离开时，缇诗突然冲向战场，试图阻止双方的战斗。她展现出强大的机械臂能力，摧毁了沙玛什的战车，并警告双方停止战斗。缇诗的容貌与莎拉塔尔一模一样，震惊了战场上的士兵。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过萨鲁的逃亡与缇诗的行动，揭示了沙玛什军队的秘密实验与战争的残酷。缇诗对战争的反思与她的行动，象征着她对自我使命的重新定义，试图通过自己的力量终结无意义的杀戮。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-4 一线希望</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“但至少，应该给她们选择。就像我一样。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗在战场上以“莎拉塔尔”的身份震慑了双方军队，成功阻止了战斗。沙玛什指挥官试图邀请缇诗会面，但被她拒绝。伊南纳士兵对缇诗的身份感到困惑，最终选择撤退。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">佣兵团成员对缇诗的行动感到震惊，纳加尔指出，缇诗的力量而非身份才是让双方退兵的关键。缇诗表达了对莎拉塔尔的复杂情感，并希望找到其他克隆体，给她们选择的机会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">埃贝赫透露自己是沙玛什“永昼”计划的研究员，试图逃离实验室。他提到有一个实验体取出了芯片，可能成为另一个“同调者”。缇诗决定找到这个实验体，并希望通过破坏芯片后台来解放其他克隆体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">佣兵团前往沙玛什的“永昼之庭”实验室，发现气氛异常，似乎发生了不寻常的事情。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过缇诗的战场行动与对克隆体的思考，揭示了她的成长与对自由的理解。埃贝赫的出现为寻找其他克隆体提供了线索，而实验室的异常则预示着更大的阴谋即将揭晓。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-5 荡然无遗</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“只要C-V-018小姐愿意和我们站到一起，未来的沙玛什，将会立起无数歌颂你的塑像。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">沙玛什 “永昼之庭”实验室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">佣兵团在埃贝赫的带领下进入实验室，发现档案室被洗劫一空，实验资料被转移。纳加尔推测实验室内部出现了叛徒，可能故意放走了实验体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在总控台前，佣兵团发现实验室内的克隆体被屠戮殆尽，芯片信号全部消失。缇诗注意到屏幕上短暂出现的信号源，推测可能还有幸存的克隆体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">沙玛什指挥官突然出现，表示实验室被一个自称“莎拉塔尔”的异常实验体摧毁。他试图说服缇诗加入沙玛什军队，帮助沙玛什取得战争胜利，并承诺给予她与莎拉塔尔相当的荣耀。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗拒绝了他的提议，表示自己不是C-V-018，而是缇诗。纳加尔指出沙玛什只是将缇诗视为武器，最终会像对待莎拉塔尔一样背叛她。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节揭示了“永昼”计划的失败与沙玛什的野心。缇诗的拒绝象征着她对自我身份的坚持与对自由的追求，而沙玛什的提议则暴露了他们对战争与权力的冷酷算计。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-6 破碎镜像</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“所以，谁成为最强的兵器，谁就是莎拉塔尔。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">黄昏时分，佣兵团在沙漠中行进。卡拉玛向缇诗道歉，承认自己曾因缇诗的外貌对她抱有偏见，但看到缇诗拒绝沙玛什的提议后，她对缇诗的态度有所改变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">突然，自称“莎拉塔尔”的异常实验体出现，攻击了缇诗。她声称自己是真正的莎拉塔尔，并认为其他克隆体都是不该存在的复制品。“莎拉塔尔”的目标是彻底摧毁伊南纳与沙玛什，让厄亚大陆重归宁静。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在战斗中，缇诗与“莎拉塔尔”交手，双方都受了伤。“莎拉塔尔”认为缇诗因情感而脆弱，最终选择暂时离开，约定在更安静的地方与缇诗决斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节揭示了“莎拉塔尔”的疯狂与她对莎拉塔尔身份的扭曲理解。缇诗的坚持与情感象征着她对自我身份的认同，而“莎拉塔尔”的离去则预示着更大的冲突即将爆发。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-7 温柔月光</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你有家了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆开始）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">埃贝赫回忆起“永昼”计划的早期实验，特别是第一个克隆体A-A-001的诞生。A-A-001的生理机能与莎拉塔尔高度吻合，但因缺乏痛觉而无法被电击控制，最终被冷冻封存。埃贝赫不甘心放弃，偷偷重启了对A-A-001的改造，试图将她打造成最接近莎拉塔尔的存在。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆结束）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">篝火旁，埃贝赫向佣兵团讲述A-A-001的故事，并透露自己一直在暗中改造她。纳加尔质疑埃贝赫的动机，认为他只是为了追求科学成就，而非真正的信仰。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗独自坐在篝火旁，陷入对自我身份的思考。卡拉玛走近她，分享了自己曾是沙玛什士兵的经历，并坦白自己曾试图刺杀纳加尔。卡拉玛的坦诚让缇诗意识到，每个人都有过去与挣扎，但重要的是选择成为谁。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗最终明确表示，她不想成为莎拉塔尔，而是想成为缇诗，遵循自己的意志。纳加尔向缇诗道歉，表示她不再需要害怕，因为她已经有了家。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过埃贝赫的回忆与卡拉玛的坦白，揭示了“永昼”计划的黑暗与角色的内心挣扎。缇诗的自我认同与纳加尔的接纳象征着她找到了属于自己的归属与使命。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-8 苦痛根源</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“痛苦的是你们。明明只是仿冒品，却背负着要’成为莎拉塔尔‘的愿望。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">纳加尔与米达斯通话，讨论“战神迦路”的消失与如何终结这场闹剧。与此同时，缇诗独自进入埃贝赫的秘密实验室，准备与A-A-001对决。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">A-A-001是“永昼”计划中的第一个克隆体，因痛感缺失而无法被控制，被冷冻封存。埃贝赫暗中继续改造她，试图将她打造成最接近莎拉塔尔的存在。A-A-001在漫长的实验中精神扭曲，自认为是真正的莎拉塔尔，并开始猎杀其他克隆体。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗与A-A-001在实验室中相遇。A-A-001声称自己是唯一的莎拉塔尔，并试图说服缇诗接受她的“帮助”，结束克隆体的悲哀人生。缇诗坚定地拒绝了她，并表示自己会回到纳加尔她们身边。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节揭示了A-A-001的疯狂与她对莎拉塔尔身份的扭曲理解。缇诗的坚定与对自我身份的认同象征着她与A-A-001的根本不同，而她的承诺则预示着她将为自己的选择而战。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-9 永昼终幕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这里没有人是武器。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">A-A-001在与缇诗的战斗中彻底败北，机械外壳破碎，失去了行动能力。她挣扎着试图继续战斗，但最终意识到自己并非真正的莎拉塔尔。缇诗告诉她，她们都不是兵器，而是人。A-A-001在生命的最后时刻，终于意识到自己被埃贝赫操控，但为时已晚。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">埃贝赫出现，试图说服缇诗成为新的“莎拉塔尔”，为沙玛什效力。他声称缇诗是莎拉塔尔的继承者，可以终结战争。缇诗拒绝了埃贝赫的提议，明确表示自己不是武器，也不会成为莎拉塔尔。她选择成为缇诗，遵循自己的意志。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">埃贝赫的野心破灭，他试图用枪威胁缇诗，但最终意识到自己从未真正理解莎拉塔尔的力量与意义。缇诗离开实验室，走向自由。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">恩利都研究员出现，揭示了他们才是幕后操纵者，试图利用莎拉塔尔和克隆体来清理厄亚大陆。埃贝赫意识到自己只是他们计划中的一枚棋子，最终被恩利都研究员终结。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过A-A-001的失败与埃贝赫的崩溃，揭示了“永昼”计划的彻底失败。缇诗的坚定选择象征着她对自我身份的认同与对自由的追求，而恩利都研究员的出现则预示着更大的阴谋即将浮出水面。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-10 晨曦微露</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“——只要我知道真正的自己是谁、要做什么就可以了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆开始）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">纳加尔回忆起莎拉塔尔将军离开时的场景。莎拉塔尔告诉纳加尔，她要去寻找一个能帮助她复仇的人，并期待看到这片大陆未来的变化。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆结束）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗从昏迷中醒来，卡拉玛等人告诉她，又有自称莎拉塔尔的人出现。纳加尔询问缇诗的身体状况，并提到沙玛什提出为她进行体检和基因修复。缇诗拒绝了沙玛什的帮助，但表示愿意与他们谈谈其他事情。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗向纳加尔表达了自己的决心：她不再害怕作为战争兵器而生的身份，而是想利用自己的力量保护大家。她决定成为沙玛什的“兵器”，但并非为了沙玛什，而是为了延长和平的时间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">太阳升起，缇诗与纳加尔站在沙漠中，隼鸟飞过，象征着新的开始。缇诗提到自己做了个梦，梦中有人告诉她，只要知道自己是谁、要做什么就可以了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，弗雷德里克与曲观玄出现在被毁的实验室中。弗雷德里克对实验室的混乱感到厌恶，而曲观玄则在操作台上调取实验数据，并放置了定时炸弹。两人讨论了莎拉塔尔与克隆体的事，弗雷德里克质疑曲观玄的真正目的，曲观玄则暗示他的计划远未结束。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最后，曲观玄摧毁了A-A-001手中的金属片，象征着“永昼”计划的彻底终结。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过缇诗的觉醒与决心，揭示了她的成长与对未来的希望。弗雷德里克与曲观玄的出现则暗示了更大的阴谋仍在继续，而森罗的命运仍未尘埃落定。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-11 白荆之行</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“虽然以后还会来做机体维护，不过……你想不想去城区里看看？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技 医疗部</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗在白荆科技接受治疗，情况逐渐好转。苏筱告诉她，第一阶段的治疗即将结束，并建议她适当活动。缇诗提到医生建议她多休息，但苏筱表示适当走动也有利于恢复。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技 第二食堂</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱带缇诗去食堂用餐，遇到了瞳。缇诗问瞳是否也是从实验室出生的，瞳回答称，如果从广义的“实验”角度，森罗世界的每个人都是实验品。缇诗虽然不太明白，但还是表示感谢。瞳提到白荆科技感谢缇诗提供了珍贵数据，并表示这是自己应该做的。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技 观景天台</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱和缇诗在天台晒太阳，苏筱提到缇诗的血液检查报告已经出来，结果应该没问题。缇诗表示自己很快就要离开，苏筱提议她可以去城区看看，或者在白荆科技内逛逛。缇诗决定去城区看看，站在围栏边俯视远方的街道。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过缇诗在白荆科技的治疗与交流，展现了她逐渐融入新环境的过程。瞳的哲学性回答让缇诗对“实验”有了新的思考，而她对城区的好奇则象征着她对未来的探索与期待。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>RB-T-12 寻常烟火</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“人呐，活着就是要好好过日子，没别的。”</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">缇诗在苏筱的陪同下外出，初次体验了海临的现代都市生活。她对周围的一切充满好奇，尤其是新店开业的礼花炮，这让她想起了厄亚的炮火声，但在这里却象征着喜庆与热闹。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在旧城区，缇诗感受到了一丝熟悉的气息，仿佛回到了厄亚。一位老妇人提醒她们这里即将拆迁，并感慨生活的变迁。老妇人的话语让缇诗若有所思，她意识到自己虽然身处异乡，但对厄亚的思念却愈发强烈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱提到监督曾预言缇诗会想念厄亚，缇诗坦言自己确实很想念纳加尔等人。苏筱表示飞行器随时待命，并提醒缇诗有需要时可以联络白荆科技，但希望与沙玛什或伊南纳无关。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这一章节通过缇诗对海临的探索与对厄亚的思念，展现了她对新旧世界的认知与情感。老妇人的话语则揭示了海临的变迁与人们对生活的态度，而缇诗的归乡之心则象征着她对归属的渴望。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:47:31', '2025-02-25 18:46:22', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (14, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/mbgsui47r9b4xfnc9qg8k04sqk14hqn_20250219095340A034.png', 11210616, '炉·心·米达斯 ＞', '间章剧情', '米达斯', '1121年6月16日', '森罗', '洛天依,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">这是一位胆小鬼的葬身之地，空空的棺椁正在等待它的主人。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-1 橙月</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">「神眷」伸出手，向着他最后挣扎所见的亮光。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在伊南纳与沙玛什边境的夜晚守夜时，回忆起过去与战神的种种关联。他遇到一名小女孩齐齐和她的父亲巴布姆，巴布姆曾是伊南纳的士兵，因伤退役。齐齐天真地询问米达斯是否是战神，米达斯否认了这一身份。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">随后，枪声打破了宁静，米达斯赶到现场，发现一群伊南纳士兵正在围捕一名身上覆满橙色晶石的男人。米达斯认出了其中一名军官卡尔布，曾是自己的副官。卡尔布对米达斯表现出极大的崇敬，称他为“迦路大人”，并试图说服他回归伊南纳军队。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯拒绝了卡尔布的提议，并质问他将人命视为何物。卡尔布开枪杀死了那名被围捕的佣兵，声称这是为了米达斯的回归。米达斯深感愧疚，最终决定将佣兵的遗物交给他的团长，履行他的遗愿。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">这一章节通过米达斯与卡尔布的对话，揭示了米达斯对战神身份的挣扎与对战争残酷的反思。卡尔布的狂热信仰与米达斯的人性关怀形成鲜明对比，而米达斯对佣兵遗愿的承诺则象征着他对自己道路的选择。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-2 保重</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">伊卢姆在上，祝「您」前路顺利。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·阿达帕平原营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月16日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯在营地平民的协助下安葬了西姆。这位佣兵的遗体被斗篷严密包裹，未引起他人注意。米达斯用匕首刻写碑文时，思绪逐渐清晰——他决定先寻找怒蛇的下落，再前往宁胡尔塔哨站。与巴布姆的对话中，米达斯得知怒蛇的兵团曾在边境酒馆活动，而巴布姆对佣兵的敌意源于过往的背叛与伤痛。巴布姆提到，怒蛇曾收拾了“鬣狗佣兵团”，这让他对怒蛇的行踪产生了兴趣。米达斯在告别巴布姆父女后，悄然留下了一把老式手枪、子弹和创伤膏，附上一张写着“路上小心”的纸条。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·边境酒馆</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月16日10:02</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯踏入酒馆，空气中弥漫着辛辣的气息。酒馆老板费尔南多冷眼旁观，指出米达斯的通缉令虽被撤下，但悬赏仍在。米达斯以五瓶金砂酒的价格换取了情报，得知怒蛇及其兵团因寻找莎拉塔尔的神器而被伊南纳士兵押送至宁胡尔塔。酒馆老板暗示，怒蛇的兵团成员拥有与米达斯相似的力量，这或许是他们被送往哨站的原因。米达斯用一枚士兵荣勋领章换取了防身的手枪和子弹，酒馆老板额外赠送了一瓶创伤膏和一枝塔木紫花，低声说了句“保重”。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·边境酒馆</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月16日14:54</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">酒馆内忽然出现了一位打扮古怪的红发女人，她手上趴着一只乖巧的蜘蛛，吸引了所有人的目光。女人与酒馆老板费尔南多交谈，暗示她因米达斯的到来而省下了一笔费用。她留下了一颗红色珠子作为谢礼，随后打着伞离开。珠子滚落地面，露出其真身——一枚珍珠。与此同时，巴布姆父女回到营地，发现帐篷前放着一个灰扑扑的布袋，里面是米达斯留下的手枪、子弹和创伤膏，以及一张写着“路上小心”的纸条。巴布姆低声祈祷：“伊卢姆在上，祝您前路顺利，战神大人。”</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-3 难归</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">有人问起我去向何方，请不要告诉她，月亮会带我回家。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·盖什提小镇</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月18日，夜</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">（回忆开始）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统回溯米达斯的记忆片段，看到他与亚兰加布和朱舒尔在葡萄树下的童年时光。亚兰加布试图用一首新学的小调吸引朱舒尔的注意，而米达斯则在一旁默默配合。朱舒尔对亚兰的歌声毫不留情地评价，却对米达斯的陪伴充满关心。这段回忆揭示了米达斯与朱舒尔、亚兰加布之间深厚的情感纽带。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">（回忆结束）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯站在盖什提小镇的边缘，看着这片荒芜的土地。十年未归，小镇已面目全非。他试图鼓起勇气进入小镇，却被一群盗寇拦下。战斗一触即发，米达斯凭借出色的格斗技巧迅速控制了局面，却在对方首领的惊呼中认出了朱舒尔。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">朱舒尔揭示了小镇的现状——青壮年被强制征召，老弱妇孺被迫拿起武器自卫。亚兰加布在前线阵亡，朱舒尔独自抚养他们的女儿南尼亚。米达斯感到深深的自责，但朱舒尔安慰他，战争带来的苦难并非他一人能改变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">久别重逢的姐弟二人拥抱在一起，朱舒尔温柔地抚摸着米达斯的金发，欢迎他回家。米达斯将酒馆老板赠送的塔木紫花交给朱舒尔，尽管这朵花已不再鲜艳，却承载着他无法言说的愧疚与思念。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">在朱舒尔的指引下，米达斯来到亚兰加布的墓前——一棵枯死的葡萄树下。他坐在坟旁，轻声与亚兰对话，回忆着过去的点滴。夜风中，枯木的吱呀声仿佛是对他的回应。米达斯拿出西姆的笔记本，决定在这片寂静中翻开这位陌生佣兵的过往，试图理解自己为何会卷入这场命运的漩涡。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-4 垃圾</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">垃圾还是幌子，标签正等待它的主人。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">沙玛什-边境小镇</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1105年10月7日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆的日记从他被鬣狗佣兵团围殴的场景开始。他因揭露鬣狗的双重交易而被报复，绝望之际，H.F.S.兵团的怒蛇、风广陌和衡宁意外出现，救下了他。西姆在日记中详细记录了这场惊险的遭遇，尤其是他拔下保险栓引爆罐子的瞬间，以及他如何决定跟随H.F.S.兵团逃离鬣狗的魔爪。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1105年10月8日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆正式加入H.F.S.兵团，成为“垃圾新人”。他对兵团的初次印象是混乱但充满温暖。怒蛇的直率、风广陌的冷静和衡宁的温和让他逐渐融入这个新集体。西姆在日记中调侃了兵团的“垃圾”文化，但也表达了对这个新家的喜爱。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1105年10月29日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆逐渐适应了兵团的生活，但也开始意识到兵团内部的复杂性。他记录了一次任务中的混乱场面，怒蛇的冲动和风广陌的冷静形成鲜明对比，而衡宁则总是扮演调和者的角色。西姆在日记中调侃道：“这个家没有衡哥得散。”</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1106年1月1日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">新年伊始，西姆记录了兵团成员们的庆祝活动。维尔德普喝醉后的唠叨、怒蛇的梦话、风广陌的冷静幽默，让西姆感受到兵团生活的温馨与荒诞。他逐渐意识到，H.F.S.兵团不仅仅是一个佣兵组织，更像是一个大家庭。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1106年5月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">风广陌的妹妹风晴雪来到兵团，她的可爱和天真让所有人感到温暖。西姆在日记中详细记录了风晴雪的生日庆祝活动，以及她在狙击枪上的惊人天赋。怒蛇和风广陌的互动也让西姆感到兵团内部的深厚情谊。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1108年4月10日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆逐渐了解到兵团与鬣狗佣兵团的恩怨。他通过集市上的大婶得知，“怒蛇”这个名字并非团长首创，而是与十几年前的某位传奇人物有关。西姆在日记中调侃道：“团长要是知道自己重名了会不会不高兴？”</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1110年5月13日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">莎拉塔尔的死讯传来，伊南纳与沙玛什的战争再次陷入僵局。西姆在日记中记录了兵团成员们的反应，尤其是风广陌与怒蛇的激烈争吵。风广陌的冷静分析让西姆意识到，战争并非个人力量能够终结。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1110年5月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">衡宁带回了一个病恹恹的小孩，但小孩最终不治身亡。西姆在日记中记录了兵团成员们的悲伤与无奈，尤其是衡宁的沉默和怒蛇的暴躁。小孩的死亡让西姆更加深刻地意识到战争的残酷。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·宁胡尔塔哨站</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月19日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到怒蛇被关押在宁胡尔塔哨站。卡尔布的出现让怒蛇意识到，H.F.S.兵团的成员们依然在为他而战。卡尔布的冷酷与怒蛇的愤怒形成鲜明对比，揭示了“战神迦路”名号背后的权力博弈。怒蛇在卡尔布的威胁下，依然坚定地守护着兵团成员的安危。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆的日记不仅记录了H.F.S.兵团的成长与变迁，也揭示了战争背景下人性的复杂与坚韧。从最初的“垃圾新人”到兵团的忠诚成员，西姆的成长历程与兵团的命运紧密相连。怒蛇、风广陌和衡宁的互动展现了兵团内部的深厚情谊，而卡尔布的出现则揭示了更大的阴谋与权力斗争。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-5 神诞</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">是战神留下神诞之地，还是神诞之地创造战神。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳-H.F.S.佣兵团据点</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1110年10月10日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆的日记从清晨的对话开始。衡宁带回肉饼，与西姆谈论“造神计划”的荒谬。衡宁冷静分析了神诞之地的吸引力——安全、复仇、名利，但也指出这种计划的不可靠性。西姆对此感到不安，尤其是理特班等兵团成员也动了心。怒蛇、风广陌和衡宁的互动揭示了兵团内部的深厚情谊，尤其是怒蛇对兵团成员的坚定保护。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(191, 191, 191); font-size: 15px; font-family: 宋体;\">H.F.S.兵团营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(191, 191, 191); font-size: 15px; font-family: 宋体;\">森罗历1111年3月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆记录了一次小镇之行。他们路过一个以葡萄酒闻名的小镇，团长怒蛇提议尝试当地葡萄酒，但风广陌拒绝，引发了一场小争执。西姆在日记中调侃了团长的“酒蒙子”行为，并记录了他与一个准备前往神诞之地的金发少年的偶遇。怒蛇的直言让西姆思考了“战神”的真正意义，他逐渐意识到，战神并非必须出自神诞之地，而是源于个人的信念与行动。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉边界附近</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗历1121年6月21日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯与朱舒尔、南尼亚的对话揭示了神诞之地的真相。南尼亚对神诞之地充满好奇，而米达斯则用简短的描述掩盖了其中的残酷与阴谋。朱舒尔敏锐地察觉到米达斯的隐瞒，但选择不深究。南尼亚的天真与希望让米达斯感受到久违的温暖，他决定不再逃避，而是直面自己的恐惧与罪孽。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯的坦白</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">在阳光下，米达斯向朱舒尔坦白了自己“战神迦路”的身份。他承认自己是个逃兵，因无法控制力量而选择逃避。但如今，他决定站起来，对抗恐惧，保护需要保护的人。朱舒尔的反应复杂，她请求米达斯暂时隐瞒身份，显然意识到这一身份带来的危险与责任。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">西姆的日记不仅记录了H.F.S.兵团的成长与变迁，也揭示了“战神”名号背后的复杂真相。从最初的“垃圾新人”到兵团的忠诚成员，西姆的成长历程与兵团的命运紧密相连。米达斯的坦白则揭示了神诞之地的黑暗与阴谋，以及他在逃避与责任之间的挣扎。最终，他选择直面恐惧，承担起“战神迦路”的责任，为保护他人而战。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-6 白星</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">无风的今夜，胆小鬼无处躲藏。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉边界附近</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月21日21:08</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯与朱舒尔一行人抵达恩古拉边界，准备在篝火晚会后进入恩古拉。米达斯在篝火旁翻阅西姆的笔记，逐渐了解到H.F.S.兵团的历史与怒蛇的过往。篝火晚会上，南尼亚的歌声唤起了米达斯对亚兰加布的回忆，朱舒尔则在与米达斯的对话中透露了亚兰加布被战神迦路杀害的真相。米达斯内心的愧疚与痛苦被彻底揭开，他决定直面自己的罪孽，并在朱舒尔的协助下前往宁胡尔塔哨站。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·宁胡尔塔哨站外</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月21日，夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯与朱舒尔抵达宁胡尔塔哨站，米达斯计划将西姆的遗物交给怒蛇，并试图救出被囚禁的H.F.S.兵团成员。朱舒尔则负责在哨站外狙击，以防米达斯失控。米达斯进入哨站后，发现怒蛇已被改造成半人半兽的怪物，正因失控而痛苦挣扎。卡尔布的出现揭示了更大的阴谋——他试图利用米达斯的力量清除怒蛇，以巩固战神迦路的神话。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">宁胡尔塔哨站内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月21日，夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯与失控的怒蛇展开激烈战斗，H.F.S.兵团的成员在卡尔布的控制下逐渐结晶化，最终选择自我了断以保全尊严。米达斯在战斗中逐渐失去控制，体内的力量开始吞噬他的意识。关键时刻，他抓住了一缕银色的蛛丝，暂时恢复了清醒，成功阻止了怒蛇的暴走。然而，卡尔布的阴谋并未结束，他计划利用怒蛇的力量继续操控局势。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在宁胡尔塔哨站的行动揭示了战神迦路背后的黑暗真相。H.F.S.兵团的牺牲与怒蛇的失控让米达斯意识到，自己不仅是战神迦路的替身，更是这场阴谋的棋子。卡尔布的冷酷与算计让米达斯陷入了更深的困境，他必须在力量与良知之间做出选择。与此同时，朱舒尔的狙击为米达斯提供了最后的防线，但她的内心也在挣扎，是否应该亲手终结自己的弟弟。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-7 随风</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">卷着风，带起砂，秘密于清晨下葬。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·H.F.S.兵团据点</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1114年8月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到H.F.S.兵团成员维尔德普向怒蛇汇报神诞之地的情况。怒蛇决定潜入神诞之地救出衡宁，尽管风广陌坚决反对。风广陌认为神诞之地的守备过于森严，且民众的信仰已成为最强大的护盾，潜入行动几乎不可能成功。然而，怒蛇坚持己见，认为必须救出衡宁，即便这意味着巨大的风险。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·神诞之地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1114年8月22日05:36</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">怒蛇潜入神诞之地，经过一番周折，终于找到了被囚禁的衡宁。衡宁的身体已经开始结晶化，他的脸和部分身体被奇怪的晶体覆盖，甚至有些部分已经透明化。衡宁告诉怒蛇，这种晶体是神诞之地的实验产物，一旦扩散，他的整个身体将变成晶体，除非他死亡。衡宁请求怒蛇开枪结束他的生命，以免这种力量被有心人利用，成为控制民众的工具。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·神诞之地中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1114年8月22日06:19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">怒蛇与衡宁在逃出神诞之地的过程中遭遇了守卫的追击。衡宁在战斗中逐渐失去力量，最终请求怒蛇开枪结束他的生命。怒蛇无法下手，风广陌在关键时刻出现，开枪击中了衡宁。衡宁的身体崩解成细沙，消失在风中。风广陌带着重伤的怒蛇逃离了神诞之地，前往恩古拉医院。 </span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">衡宁的死亡揭示了神诞之地背后的黑暗实验与力量操纵。怒蛇的潜入行动虽然失败，但他与风广陌的坚持展现了H.F.S.兵团成员之间的深厚情谊。衡宁的牺牲不仅是为了避免晶体力量被滥用，更是为了守护伊南纳的未来。怒蛇在重伤中逐渐恢复意识，回忆起与衡宁的过往，意识到自己曾在神诞之地见过米达斯。这段经历让米达斯逐渐明白，真正的战神并非源自神诞之地，而是源自内心的力量与信念。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-8 痛觉</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">“这需要等价交换，先生。”女士这样说。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉医院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月22日10:39</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯在恩古拉医院苏醒，院长玛丽娜为他处理了伤口，并告知他左手伤势得以保全要归功于两位神秘女士的帮助。米达斯逐渐恢复意识，回忆起与红发女人波丝的对话。波丝提出两个选择：一是结束米达斯的生命，彻底终结他的痛苦；二是取出他体内的异核，解除神诞之地赋予他的力量，让他回归平凡的生活。米达斯陷入沉思，暂时未做出决定。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉医院休息室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月22日傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在休息室陪伴南尼亚和其他孩子，翻阅着西姆的笔记，回忆着H.F.S.兵团的过往。南尼亚写下心愿书，表达了对未来的美好憧憬。米达斯与朱舒尔的对话中，透露出他对未来的迷茫与责任感。朱舒尔回忆起小时候写下的“心愿书”，感慨这片大陆上的人们都在为生存而挣扎。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉医院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月22日夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯决定返回宁胡尔塔哨站，面对卡尔布和怒蛇的威胁。波丝与灰锈同意随行，但提醒米达斯，拯救他人并非易事，他将付出巨大的代价。米达斯坚定地表示愿意承担一切后果，终结这场始于16年前的神恩。红珠小姐接受了米达斯的请求，交易成立。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·未知地点</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月22日夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">卡尔布在荒地上仰望星空，手中握着一块碎晶，等待着米达斯的到来。怒蛇被囚禁在特制的牢笼中，无法逃脱。卡尔布透露，他的目的是为了让米达斯重新接受“战神迦路”的身份，结束伊南纳的混乱。蜘蛛的出现预示着米达斯的行动，卡尔布相信米达斯即将重返神位。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在恩古拉医院逐渐恢复，面对波丝提出的两个选择，他决定先解决卡尔布和怒蛇的威胁，终结神诞之地的阴谋。南尼亚的心愿书让米达斯更加坚定了保护他人的决心。卡尔布在荒地上等待着米达斯的到来，计划利用米达斯的力量重新巩固战神迦路的神话。米达斯与红珠小姐的交易达成，他将在这场最后的战斗中付出一切，终结这场始于16年前的神恩。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-9 姓名</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">「神眷」伸出手，握住了橙红色的心脏，和红沙下的金子。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉边界</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">森罗1121年6月23日4:56</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯与怒蛇的最终对决。米达斯在红珠小姐的帮助下，成功压制了失控的怒蛇，并终结了他的痛苦。怒蛇在生命的最后一刻，回忆起H.F.S.兵团的过往，表达了对米达斯的认可。卡尔布的出现揭示了更大的阴谋，他试图利用米达斯的力量重新巩固战神迦路的神话。然而，米达斯坚定地拒绝了卡尔布的提议，选择以自己的方式守护伊南纳。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉边界</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月23日清晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯与卡尔布的对话揭示了卡尔布对米达斯的忠诚与信仰。卡尔布认为米达斯是伊南纳的希望，但米达斯却表示，他成为战神的初衷是为了守护平凡的人们，而非追求权力与荣耀。卡尔布最终选择结束自己的生命，以成全米达斯的使命。米达斯在卡尔布的遗体旁鞠了一捧细沙，表达了对这位旧友的哀悼。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉边界</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月23日清晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">恩古拉的民众目睹了米达斯的胜利，纷纷高呼“战神迦路”与“米达斯”的名字。米达斯在曙光中重新戴上军帽，迎接新的使命。他明白，真正的战神并非源自神诞之地，而是源自内心的力量与信念。米达斯决定以自己的方式守护这片土地，终结这场始于16年前的神恩。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在与怒蛇的对决中取得了胜利，终结了神诞之地的阴谋。卡尔布的牺牲让米达斯更加坚定了守护伊南纳的决心。恩古拉的民众将米达斯视为新的战神，高呼他的名字。米达斯明白，真正的战神并非源自神诞之地，而是源自内心的力量与信念。他决定以自己的方式守护这片土地，终结这场始于16年前的神恩，迎接新的未来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-10 晨嚣</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">愿「我们」前路顺利。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉医院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月25日晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯在恩古拉医院逐渐恢复。红珠小姐波丝与灰锈为他进行了手术，将他的异核分割并封印在行李箱中，以帮助他控制力量。米达斯决定不再逃避，而是以清醒的姿态继续承担战神的责任。他与朱舒尔的对话中，表达了对过去的歉意与对未来的决心。朱舒尔虽然无法完全原谅米达斯，但她选择支持他的决定，并留在恩古拉医院照顾南尼亚。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">伊南纳·恩古拉医院空地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月26日15:32</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯与纳加尔通话，确认了接下来的计划。齐齐送给米达斯一幅画着火焰的纸板，表达了对他的关心与祝福。米达斯与朱舒尔告别，准备前往海临感谢墨惜雨，并处理遗留的问题。朱舒尔看着逐渐远离的飞行器，心中充满了复杂的情感。她手中捏着亚兰加布的陈旧心愿书，回忆起过去的点滴，决定继续守护这片土地。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在恩古拉医院逐渐恢复，接受了红珠小姐的手术，成功控制了体内的异核力量。他决定以清醒的姿态继续承担战神的责任，守护厄亚的每一片土地。朱舒尔选择留在恩古拉医院，照顾南尼亚并守护亚兰加布的遗愿。米达斯与朱舒尔的告别充满了复杂的情感，但他们都在为未来而努力。米达斯将继续前行，完成他的使命，直到厄亚不再需要战神的那一天。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-11 结实的朋友</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">让食物变得更好吃的两三种方法</span><span style=\"font-size: 15px; font-family: 宋体;\">。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">白荆大厦</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月27日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯在白荆大厦的第一天。由于睡过了头，米达斯错过了早餐，艾摩诃主动带他前往食堂用餐。米达斯在艾摩诃的引导下，摒弃了过多的思考，专心享受早餐。餐后，艾摩诃带米达斯前往作战训练室进行对战训练。尽管米达斯在战斗中击飞了艾摩诃，但艾摩诃并未受伤，反而对米达斯的实力表示赞赏。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">白荆大厦医疗部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月27日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">艾摩诃在训练中受伤，被送往医疗部。方兰生医生检查后确认艾摩诃并无大碍，只需休息即可。苏筱带着蛋糕前来探望，艾摩诃罕见地分享了蛋糕，表达了对米达斯和苏筱的感谢。米达斯在与艾摩诃的互动中，逐渐融入了白荆科技的生活，结识了新的朋友。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在白荆大厦的第一天充满了意外与惊喜。艾摩诃的直率与热情帮助米达斯迅速适应了新环境，并在对战中展现了强大的实力。尽管艾摩诃在训练中受伤，但他并未因此退缩，反而对米达斯的实力表示认可。苏筱的关心与艾摩诃的分享让米达斯感受到了白荆科技团队的温暖。米达斯逐渐融入了新的生活，结识了结实的朋友，为未来的使命做好了准备。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px; font-family: 宋体;\"><strong>RB-M-12 最好的归宿</strong></span><span style=\"font-size: 15px; font-family: 宋体;\"><br></span><span style=\"font-size: 16px; font-family: 宋体;\">倘若我的生命在梦想实现前便已终结，<br>不必为我感到悲伤，我的朋友，<br>那是最好的归宿。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">海临·白鹊湖广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月28日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">监督通过监控系统观察到米达斯在海临白鹊湖广场与《森罗时报》记者闻人羽的会面。米达斯将阿拉斯泰的遗物——一枚记忆卡交给闻人羽，并表达了想去阿拉斯泰墓前献花的愿望。在交谈中，米达斯意外发现了衡宁的著作《风沙记事》，并得知阿拉斯泰因这本书而前往厄亚。闻人羽提到衡宁的父母已去世，并询问如何处理H.F.S.兵团汇给衡宁父母的钱款。米达斯建议将钱捐给有需要的人，闻人羽同意并将《风沙记事》赠予米达斯。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">海临·临港公墓</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px; font-family: 宋体;\">森罗1121年6月29日11:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯来到阿拉斯泰的墓前，献上一束百合花。他与阿拉斯泰的墓碑对话，表达了对阿拉斯泰和衡宁的感激之情。米达斯坦言，他不后悔得知真相，并希望阿拉斯泰和衡宁能活着看到这一切。一阵风拂过，白鸟振翅飞向天空，一片羽毛落在阿拉斯泰的墓碑旁，指向墓碑上的墓志铭：“倘若我的生命在梦想实现前便已终结，不必为我感到悲伤，我的朋友，那是最好的归宿。”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\">米达斯在海临完成了对阿拉斯泰的承诺，将遗物交给闻人羽，并在墓前献花。他通过《风沙记事》再次回忆起衡宁与H.F.S.兵团的过往，感慨命运的巧合与无常。阿拉斯泰的墓志铭让米达斯明白，生命的价值不在于长短，而在于是否实现了梦想。米达斯将继续前行，背负着逝者的期望，守护这片土地，直到厄亚不再需要战神的那一天。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px; font-family: 宋体;\"> </span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:48:25', '2025-02-26 19:24:22', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (15, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/pmo2du7a7kxsx4zf7ur6i0ch219ki7s_20250219094953A023.png', 11210803, '人世行者 ＞', '幕间剧情', '伊琅相思,监督,苏筱,瓦卡莎,艾摩诃,莫莫', '1121年8月03日', '森罗,夜摩', '洛天依,鸿雁于飞,奈默', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那些停驻于记忆中的温暖瞬间，便是支撑她存活至今的救命良药。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-1 《人世》</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">拍摄开始。<br>镜头前的人们面目模糊，而这出不完美的剧目需要寻求新的突破。<br>与此同时，天隙禁区，新的同调者危机似乎正在酝酿。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">剧本讨论会</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">编剧小甲、小乙、小丙和小丁正在讨论新剧本《人世》。小乙对剧本中主角与“死亡”对峙的情节提出质疑，认为仅靠对白无法充分展现主题。小丙建议从“死后”的角度挖掘故事，但小丁则提出了蹭现实热点的方案。小甲最终决定，剧本必须保持原创性，不能依赖现实事件。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-2 《魂归》</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">镜头推进。<br>随着异世界同调者的降临，亡者归来——海临似乎陷入了前所未有的异变。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·天隙禁区外围</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">天隙禁区突发异常能量波动，海水涌入居民区，全城警报拉响。R.E.D.警员迅速组织居民撤离，现场混乱不堪。一名指挥现场的少女与同事讨论着禁区内的情况，提到钟表时间异常，似乎受到了某种力量的影响。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">随着异常能量波动的持续，街道上出现了许多亡灵。他们与生者交谈，甚至试图回家。负责指挥的少女苏助理与同事讨论着这些亡灵的出现，感叹街道因亡灵而变得热闹，但也意识到这只是一场短暂的幻梦。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·未知地点</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">一名夜摩王族的少女在歌唱，她的歌声中充满了对亡灵的迷茫。她的母亲告诉她，夜摩王族从未见过亡灵回归，但她们依然坚持唱着这支为亡者祈求长眠的歌。少女质疑这种传统的意义，认为自己应该用王族的力量去守护生者，而不是为亡灵祈求未知的安宁。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-3 《懵懂》</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">海临的异变还在不断加深，摄像机竟拍摄到了异世界的景象。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思和她的团队在街道上发现了一缕不完整的魂灵。伊琅相思决定唤醒并补全这缕魂灵，同时让它跟随他们。苏筱对任务进展感到担忧，担心白荆科技的表现会影响与夜摩王族的赌约。伊琅相思提出借用森罗世界的力量来排除异变，但需要找到最纯粹的生与死之地。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-4 《混乱》</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">海临的异变程度进一步加深，原先那些看似无害的“鬼魂”们似乎也在异变的影响下开始表现出了它们的攻击性。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·医院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人跟随一缕魂灵来到医院，发现这里是一个能同时体验到生与死的地方。伊琅相思对森罗人的行为感到惊讶，而苏筱则对医院的环境感到不适。他们遇到了一位老人，医生建议她住院观察。伊琅相思注意到老人的灵魂异常活跃，并觉得她有些熟悉。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-5 《清醒》</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">多方唤醒之下，作为视角主体的“我”终于开始清醒。<br>但是，在这一片混乱之中，这份清醒显得多少有些无关紧要。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">夜摩·海岸防线</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思和团队在夜摩的海岸防线遭遇了不明生物的袭击。战斗结束后，他们意识到自己被某种力量盯上了。伊琅相思决定带领团队迅速撤离，避免进一步的冲突。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>YM-6 戏里戏外</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">时间回到一切开始之前。<br>此前的海临并非真正的海临，而是导演莫莫的“生死之间”。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临·旧城区互助小组</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年4月1日 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">《人世》剧组的导演莫莫带领团队来到旧城区的一个互助小组进行取材。这些居民是天隙事件的幸存者，他们坚信天隙通道的另一端存在一个亡者的世界，终有一天会与逝去的亲人重逢。莫莫对这种信念感到复杂，既认为这是一种自欺欺人，又理解它对幸存者的慰藉作用。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> YM-7 她的责任<br>在“生死之间”相逢的夜摩众人短暂谈起他们的过去与未来。<br>原来有些选择即使不说出口，也已经足够分明。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">夜摩·生死之间</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思和她的团队在夜摩的“生死之间”中穿行。艾摩诃和瓦卡莎回忆起夜摩的生活，伊琅相思则告诉他们，夜摩的族人正在经历一场艰难的迁徙，奢黎耶祭司带领族中孩童前往新的王城，而她则率领战士死守海岸。伊琅相思鼓励他们在森罗继续活下去，并暗示她已经知道他们的选择。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-8 二创世界</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">起因渐渐明晰，此前的一切混乱均来自于导演莫莫天马行空的想象，她的异核正在生成，且，难以自控。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">莫莫的精神海域</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">莫莫在精神海域中构建了一个荒诞的“二创森罗”，监督以摄像头的形象出现，试图引导她回到现实。然而，莫莫的想象力过于旺盛，甚至具现化了牛头马面和黄牛。监督无奈地要求她停止想象，莫莫则用橡皮擦擦掉了这些具现化的角色。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-9 渡往森罗</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">热闹而混乱的虚假世界归于平静，创造一切的导演离开了这里。她无法选择她的生死，但她可以掌控“选择”本身。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">夜摩·双世海</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思带领团队来到双世海，准备通过天隙通道将莫莫送回森罗。然而，莫莫的想象力再次干扰了现实，她的潜意识将双世海变成了一个老太太的形象。监督催促她尽快回到现实，莫莫则调侃自己第一次“死”没经验。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"text-align: left; line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-10 决意</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">莫莫决定直面自己的现状，只是在那之前需要屏除杂念。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">夜摩·双世海</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思回忆起夜摩的历史，提到前代女王在无归日化身为太阳，率领族人对抗巨兽乌那迦。她告诉团队，夜摩的每一任女王都会在关键时刻成为族人的太阳，守护他们的生存。莫莫被这段记忆震撼，意识到伊琅相思的责任与使命。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-11 太阳</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜摩的女王与白荆的监督会面于故事间隙，也是故事开始。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">夜摩·双世海</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 深夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">伊琅相思带领团队与乌那迦展开战斗。她化身为太阳，消磨乌那迦的力量，最终将其击败。莫莫在这场战斗中看到了老太太的形象，调侃自己看到的场景与其他人不同。战斗结束后，伊琅相思告诉团队，莫莫会竭尽全力回到现实。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> YM-12 行者</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">前一日的太阳坠下海岸，新一轮圆日冉冉升起。<br>从今往后，伊琅相思将是夜摩的新王。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">白荆科技总部45层</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">森罗历1121年8月4日 凌晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">莫莫在医疗室中苏醒，伊琅相思和监督在一旁守候。伊琅相思宣布她将放下夜摩女王的身份，成立“夜摩股份责任公司”，并决定让瓦卡莎和艾摩诃继续留在森罗。监督祝贺她摆脱王族的宿命，伊琅相思则感慨森罗为夜摩人提供了无限的可能性。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-14 09:50:15', '2025-02-26 19:25:36', 'admin', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (16, 0, 'http://r.qianqiu.info/admin/upload/2025/02/17/7zn8uhp4v37mzk7a1lrj0a1p5lleayd_20250217113838A002.png', 11110201, '雪中春信·魔盒 ＞', '幕间剧情', '百里屠苏,十手卫，红玉,欧阳少恭', '1111年2月1日', '森罗', '墨惜雨,奈默', '<p>你想要去“外面”吗？</p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-1】0710</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这里拥有秩序。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">恩利都·乌尔生物实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 森罗1111年2月1日18:33</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督通过监控系统观察到UR09-0710在乌尔生物实验室的检定过程。研究员甲报告了0710的检定结果：体能素质A，专项能力A，心理评估A。然而，研究组长将心理评估下调为B，以符合实验室的标准。0710在检定过程中始终保持沉默，目睹了其他“产品”因不合格而被销毁的场景。研究员甲和研究组长对0710的表现进行了讨论，研究组长最终决定将0710的心理评估下调，以确保实验室的“产品”符合标准。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">恩利都·乌尔生物实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗1111年2月1日18:40</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">实验室内的气氛冰冷而机械，研究员们对“产品”的处理毫无情感波动。UR09-0692号“产品”因精神状态异常和认知问题被申请销毁，研究组长迅速批准了销毁请求。0710目睹了这一切，内心虽无明确情绪波动，但似乎对实验室的残酷运作有了更深的认知。研究员甲对0692号“产品”的销毁表示惋惜，认为这种“小事”影响了数据留存的质量。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">UR09-0710在乌尔生物实验室的检定过程中，经历了冰冷而残酷的现实。实验室对“产品”的处理毫无情感，任何不符合标准的行为都会导致销毁。0710虽然表面上保持沉默，但内心可能已对这些规则产生了疑问或认知。实验室的运作逻辑无情且机械，研究员们将“产品”视为可替换的物品，而非独立的个体。0710的存在与行为，或许将成为未来打破这种冰冷规则的关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-2】0205</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“等见面的时候，月亮就该圆了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临，中央警局 </span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗1111年2月5日 0:37</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督通过监控系统观察到九旻基地成员与海临中央警局的联合行动会议。十手卫作为本次行动的现场指挥官，向九旻基地的成员传达了任务目标：彻底摧毁恩利都的研究资料与研究成果，而非将其带回。九旻基地成员对任务安排感到不满，但红玉安抚了同伴，表示应服从命令。十手卫随后私下与红玉交谈，透露了她的父亲——红姓先遣队领队——也在本次行动中，并邀请九旻基地成员一同体验海临的食堂文化。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">本次联合行动的目标是彻底摧毁恩利都的研究资料与成果，而非将其带回。十手卫作为现场指挥官，展现了冷静与自信，而红玉则在与十手卫的对话中得知了父亲参与行动的消息。尽管任务安排引发了一些争议，但团队成员最终决定服从命令，准备执行任务。十手卫的轻松态度与红玉的复杂情感交织，为即将展开的行动增添了一丝人情味。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-3】0818</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“凡我所见处，皆是囚笼。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">恩利都·乌尔生物实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 森罗1111年2月6日 6:27</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监控广播宣布晨检结束，所有产品合格率100%，批准入库。UR09-0710与其他产品在走廊中静默前行，准备进入库房。这条路上没有人类工作者，只有隐藏的武器系统在监控下随时准备销毁不合格的产品。UR09-0818在队伍中试图与UR09-0710交谈，询问“出去”的含义，并推测成色最好的样本会被买家预定带走。UR09-0710起初保持沉默，但在进入监控盲区后，回头警告UR09-0818不要多话。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">此时，一名少年研究员出现在走廊尽头，正在与外界的买家通话。他向买家保证这些产品是最先进的人形兵器，接受了严格的训练，战斗技巧深入骨髓，且不知生、不畏死。通话结束后，少年研究员注意到UR09-0710的存在，与它短暂对视，并礼貌地询问是否打扰了它。UR09-0710没有回应，只是继续跟随队伍前行。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这段场景揭示了实验室中产品的日常流程，以及研究员与产品之间微妙的关系。UR09-0818的好奇心与UR09-0710的警惕形成了鲜明对比，而少年研究员的出现则为这场沉默的对话增添了一丝神秘感。整个过程中，实验室的冷漠与产品的压抑氛围贯穿始终，暗示了更深层的权力结构与人性缺失。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-4】0208</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你想要去“外面”吗？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">恩利都·乌尔生物实验室 </span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗1111年2月8日 23:06</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在少年研究员与UR09-0710的对话中，少年研究员引导它思考“外面”、“生”与“死”的含义。他暗示，这些概念与命运和未来息息相关。与此同时，实验室内的产品们开始觉醒自我意识，对“产品”这一身份产生质疑，并逐渐表现出人类的情感和反抗意图。UR09-0818向UR09-0710表达了不满，质疑为何它们要被随意支配和销毁，甚至开始思考“人”与“产品”的区别。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">实验室内的气氛逐渐紧张，产品们的情绪波动愈发明显。突然，一名受伤的研究员闯入，声称有产品失控并引发暴动。他命令其他产品销毁失控者，但产品们却无动于衷，甚至表现出对研究员的冷漠。UR09-0818明确表示，它的目标是“去外面”，暗示了产品们对自由和未来的渴望。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，少年研究员与另一名神秘人物的对话揭示了更深层的计划。他们提到，实验室的“开放日”即将到来，一些产品被提前带出实验室，而实验室内部的混乱也在加剧。少年研究员坦言，他的目标是让整个实验室彻底毁灭，以确保他们的逃离行动不会受到任何威胁。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">实验室的监控广播发出警报，宣布启动应急预案，封闭程序即将启动。产品们的觉醒与反抗，以及少年研究员的计划，似乎正在将整个实验室推向毁灭的边缘。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-5】0209</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“是人。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌尔生物实验室，外围走廊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗1111年2月9日 17:03</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉带领的第一小组成功潜入实验室外围，但很快遭遇了一场令人震惊的展示。实验室主持人向参观者展示了所谓的“产品”——一个赤手空拳的孩子与三名全副武装的特战队员。主持人命令产品们动手，红玉立即下令救援，但为时已晚。笼中人的眼神成为了她记忆中无法抹去的片段。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉回忆起十手卫曾提到她的父亲也参与了这次任务，并递给她一盒烟作为化解尴尬的礼物。她下令打开笼子，尽管小队成员提醒她笼中人已经无法挽救。与此同时，九旻基地成员与十手卫就实验室内部的封锁展开争论。九旻基地成员坚持突破封锁，认为放任不管会导致绝密研究泄露，而十手卫则认为实验室内部已被封锁，最理智的做法是等待内部的东西彻底消失。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在实验室内部，UR09-0818与UR09-0710试图逃离，却发现所有出口都被封锁。UR09-0818因体内被激活的“种子”而逐渐衰弱，他坦然面对死亡，但仍对生命充满渴望。他询问UR09-0710的特化类型，希望自己在变成怪物后不会太难对付。UR09-0710保持沉默，但表现出对同伴的关心。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉不顾指令，带领小队突入实验室内部，决心摧毁这里。在途中，他们遇到了UR09-0710，后者表示不会攻击他们，并愿意带路前往中央控制室。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">实验室中央控制室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉与小队成员跟随UR09-0710前往中央控制室，寻找实验室的自毁程序。UR09-0710的配合为他们的行动提供了关键帮助，但实验室内部的危机仍在加剧。红玉的决心与UR09-0710的觉醒交织在一起，为这场毁灭行动增添了复杂的情感与意义。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【UR-6】1121</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“现在，生日快乐。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌尔生物实验室，核心区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 森罗1111年2月9日 18:16</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">九旻基地成员找到少年研究员欧阳少恭，催促他尽快撤离，因为实验室即将被引爆。然而，十手卫突然出现，揭露了九旻基地成员的真实身份——他并非完全属于九旻基地，而是接受了更高层的额外任务。十手卫指责欧阳少恭通过提供不完整情报导致海临方面损失惨重，并威胁要废掉他的双手作为惩罚。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉与十手卫交换了各自的违规行为，十手卫承认自己违背纪律，试图开枪废掉欧阳少恭的双臂，但被九旻基地成员阻止。十手卫向红玉交代后续任务，强调保护UR09-0710的重要性，并让她将欧阳少恭带回海临，交由胤局处理。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">UR09-0710苏醒后，十手卫以轻松的语气欢迎他来到这个世界，并称这一天为他的“生日”。红玉则交给UR09-0710一份来自实验室自毁前的操作界面照片，显示他的编号被从销毁名单中删除，暗示有人希望他幸存。UR09-0710对此表示理解，并在十手卫的引导下尝试回应。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">后续 - 森罗1121年</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">欧阳少恭与瞳在多年后再次会面，讨论当年实验室的遗留问题。欧阳少恭提到白荆科技从伊南纳带回的研究资料，认为九旻基地的海外行动并未完全成功。瞳则强调两人已各走各路，不应再有交集。欧阳少恭质疑瞳是否也想从“魔盒”中分一杯羹，暗示双方对实验室遗留资料的争夺仍在继续。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">实验室的自毁行动标志着UR09批次的终结，但UR09-0710的幸存为这场悲剧带来了一丝希望。十手卫与红玉的违规行为揭示了任务背后的复杂性与矛盾，而欧阳少恭与瞳的对话则暗示了实验室遗留问题的深远影响。UR09-0710的“新生”象征着新的开始，但围绕实验室秘密的争夺仍在继续，为未来埋下了未知的伏笔。</span></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 22:29:12', '2025-02-25 15:48:41', '洛天依', '2972930843');
