INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (20, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/t8hk8uydo376p815avyanhxjvurjc6p_20250219094824A020.png', 20540114, '不逢「缘」 ＞', '幕间剧情', '珑，林，旒珠，崔远之，易虚舟（逸舟），叶秉谦，焰响，赫九逸，北洛（黑曜）', '2054年1月14日', '黑曜', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">创伤、污秽、鲜血与未流出的眼泪——<br>雨水如死亡般湮没所有。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-1 无赢家</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“欢迎来到‘世外桃源’”。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·天街十二楼·赌坊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到一叶城的天街十二楼，寻找能够解答他疑问的人。他遇到了自称“判官”的珑，珑提出与他进行一场赌局，赌注是回答任何问题或完成任何要求。监督接受了赌局，准备掷骰。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-2 无常事</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">日常即无常。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·居民区街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和小陈在街道上遇到了豆腐摊主周老伯，老伯为他们准备了豆腐脑作为夜宵。林提醒老伯最近城内不太平，注意安全。小陈则兴奋地分享了自己在天街赢钱的经历，并表达了对成为一叶城正式居民的渴望。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-3 无约人</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“‘背叛’过的人，身上就像打了烙印般，洗不尽，抹不掉，永远如影随形。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·居民区街道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林从噩梦中惊醒，梦见了过去的队友吴队和磷灰小队的失败。小陈来找林，两人决定外出散步。在街道上，他们听到了关于“怪物”和城内实验问题的传言。小陈发现了两个可疑的人，决定跟踪他们。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和小陈跟踪可疑人物，发现了一个正在尸化的人。珑突然出现，用骰子击倒了小陈和尸化者。珑对林的身份表示怀疑，暗示他可能与一叶城的异动有关。林否认了珑的指控，但珑仍然对他保持警惕。珑提议，如果林觉得生活无望，可以找她帮忙结束生命。林没有回应，珑离开后，林独自面对内心的挣扎。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"color: rgb(0, 0, 255); font-size: 19px;\"><strong> </strong></span><span style=\"font-size: 19px;\"><strong>BO-4 无路去</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“要不要暂时同路？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 明庭市天江区银沙路上云雅苑</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年6月10日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和约斐尔在一个废弃的建筑物内休息。约斐尔表现出对红茶的强烈渴望，林无奈地为他寻找茶包。查尔斯准备了一顿简单的晚餐，众人围坐在一起吃饭。约斐尔不喜欢胡萝卜，林和查尔斯试图说服他吃下去。夏生作为新加入的成员，观察着这个小队的互动，感受到了一种久违的“家常”氛围。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 野外·区域MT-G-9</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月16日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和小陈在执行任务时遇到了诺亚的逃亡者蒋了和他的同伴。蒋了透露诺亚遭遇了“怪物”袭击，行尸潮即将到来。林决定引开行尸潮，小陈和其他队员则返回一叶城报信。在危急时刻，珑出现并利用异能驱散了行尸潮，救下了林。珑将蒋了和林带回一叶城，队员们则返回城内，面对即将到来的大雨和未知的威胁。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-5 无可解</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">不是磷灰，是“我们”。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 郊外·未知区域</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2050年2月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林、夏生、查尔斯和约斐尔组成的“磷灰”小队在郊外执行任务，清理行尸。任务结束后，夏生对林的行为表示不满，认为他过于同情弱者，导致任务时间延误，增加了团队的风险。林辩解说自己的行为是可控的，但夏生依然坚持认为林的行为可能会危及整个团队。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 诺亚幸存者基地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2050年2月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">小队返回诺亚基地，夏生与林之间的关系依然紧张。夏生担心林的无条件善意会最终伤害团队，而林则坚持认为帮助他人是必要的。与此同时，诺亚城主莱文特与林进行了一次谈话，暗示林的行为可能会导致团队的裂痕，甚至背叛同伴的信任。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·望楼</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月17日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和小陈在一叶城的望楼上发现了一些异常现象，随后潜入了一处秘密实验室，发现诺亚的蒋了和其他人被用作实验对象。小陈对一叶城的做法感到震惊和愤怒，而林则意识到一叶城的实验背后隐藏着更深的阴谋。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·城墙</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月17日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">珑与旒珠在城墙上进行了一次谈话，珑表达了对林的不信任，认为他身上没有生气，像是个死人。旒珠则暗示一叶城可能会面临更大的威胁，决定召开全城大会，向居民说明情况。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·秘密实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月17日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">蒋了在实验室中醒来，意识到自己仍然活着，并试图向一叶城传递关于“怪物”的消息。然而，他的行动被一道黑影打断，预示着一场更大的危机即将到来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-6 无从问</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">敌人，或者盟友。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·中央广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月18日10:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林和小陈抵达中央广场，参加由城主旒珠主持的全城大会。旒珠宣布了关于劣质升阶药泛滥和“尸化阻滞针剂”研究进展的消息，试图安抚民众的不安情绪。然而，一名队员突然公开质疑旒珠的说法，并指控判官珑能够操纵行尸。珑在众人面前承认了自己并非人类，并暗示城内还有其他“同类”。这一举动引发了民众的恐慌和混乱。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·中央广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月18日10:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">旒珠展示了“尸化阻滞针剂”的效果，证明行尸可以恢复“人性”。珑则进一步揭露自己是从行尸身上研究出的成果，并宣布自己将留在城内，等待“同伴”的到来。民众的情绪从恐慌转为对珑和旒珠的依赖，认为一叶城是人类唯一的希望。林和小陈在混乱中保持冷静，小陈指出一叶城已成为人类的盟友或敌人，而真正的敌人将需要一叶城永远消失。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-7 无奈何</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“人类之间的情感关系可是很复杂的，可能要学习很久……归来者们。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 诺亚幸存者基地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">诺亚基地内，莱文特与一名神秘人物对峙。神秘人试图从莱文特口中获取关于一叶城的情报，但莱文特指出他们的计划注定失败，因为他们不了解珑与旒珠之间的深厚情感。神秘人最终决定改变计划，意图彻底摧毁一叶城。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·城主办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">珑与旒珠在办公室内讨论当前的局势。旒珠确认诺亚已被敌人控制，并推测敌人的目标最初是珑。她宣布一叶城将静观其变，等待敌人的下一步行动。林询问诺亚的情况，旒珠表示一叶城暂时无法提供援助，但建议林在局势稳定后返回诺亚。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-8 无生路</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“用刀，用枪，用什么都行，只要一下，就都结束了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·回忆片段</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2050年2月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林回忆起过去与约斐尔的经历，自责未能救下他。夏生与林发生激烈争执，指责林的过度善意导致了约斐尔的死亡。夏生最终选择离开磷灰小队，留下林的铭牌作为纪念。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·现实</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月18日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">林与小陈讨论即将到来的行尸潮。小陈透露自己对一叶城的态度，并暗示自己并非人类。林试图通过回忆过去的错误来寻找答案，但最终陷入更深的迷茫。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-9 无尽雨</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“……一叶城会成为他们的墓地。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·城门内</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月21日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">一叶城进入全面戒严，等待敌人的进攻。行尸潮如期而至，旒珠指挥城防部队全力迎战。珑试图操纵行尸，但未能成功。战斗进入白热化阶段，城内气氛紧张。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-10 无归处</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“可名字叫归来，实际又该归去哪里呢。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·战斗结束</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年1月21日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">行尸潮被击退，城内欢呼声四起。小陈在战斗结束后与林对峙，揭露自己是“归来者”的身份，并解释自己杀死同伙的原因。小陈最终离开一叶城，留下林独自面对内心的挣扎。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·晴天</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2054年7月17日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">旒珠与珑在城墙上看日出，讨论未来的计划。珑决定延长与旒珠的赌约，直到自己生命的尽头。与此同时，夏生与一名红瞳少年相遇，少年自称“归来者”，邀请夏生加入他们的行列。夏生最终选择跟随少年离开。</span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 22:55:07', '2025-02-26 18:16:30', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (21, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/nlk4z5i2j4icff2ov45alcgjo2s3dr6_20250219095042A027.png', 11210604, '格兰索历险记 ＞', '幕间剧情', '花时，乐无异，雪长夏，筱筱，监督，风清洛，卯绒绒，风晴雪', '1121年6月04日', '森罗', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">尽情体验吧，这全新的人生。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>按两下试试然后呢<br></strong></span><span style=\"font-size: 16px;\">风清洛找上白荆科技，希望得知友人下落，你循着乐无异的终端信号，终于在格兰索高中的天台发现了异常。正当你与R.E.D.联络之时，风清洛做出惊人之举——</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-06-28</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">花时报警称她的朋友雪长夏被吸进了电脑里。警局将电话转接到特殊事件处理小队，但接电话的十手卫正在执行任务，未能及时回应。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">格兰索私立高级中学</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和风清洛在格兰索私立高级中学的礼堂天台发现了雪长夏的电脑。电脑屏幕上显示着“11111……”的代码，暗示雪长夏可能被困在游戏空间中。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何成为一名勇者</strong></span><span style=\"font-size: 19px;\"><br></span><span style=\"font-size: 16px;\">在奇怪的字幕后，你化身史莱姆，与失去异核能力的苏筱一人一姆孤立无援，被一群热切寻找勇者的怪人团团包围……</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、苏筱和风清洛被吸入了游戏空间《格兰索历险记》。监督变成了史莱姆，苏筱成为了勇者，风清洛则昏迷不醒。他们在游戏空间中遇到了花时、乐无异和风晴雪，逐渐揭开了游戏空间的真相。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何避免嫁给王子</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">公主想要离开王子，王子想要公主留下。在王子公主二选一的选择题中，你的选择是……</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人遇到了被森林王子逼婚的花时。花时表示自己是来找乐无异和雪长夏的，但森林王子坚持要她嫁给王子。监督通过史莱姆分身术帮助花时脱身，并与森林王子展开战斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何摆脱王位继承<br></strong></span><span style=\"font-size: 16px;\">幽暗森林的王子们漏洞百出，满是虚假。身为公主的花时却被他们协助寻人的谎言说动，即将坠入王子们的阴谋之中……</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人进入森林王子的领地，发现森林王子实际上是卯卯和绒绒。卯卯被鸡啄中后变成了狗，绒绒则继续与监督等人合作。监督通过修改任务条件，帮助卯卯和绒绒脱身。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何不被魔女毒死</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一行人遵循地图指引，做客魔女茶会，在处处危机、无比诡谲的气氛间，有人识破了魔女的身份。然而身为魔女的她，此行却并非为公主而来……</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人来到魔女茶会，遇到了风晴雪。风晴雪透露自己也在寻找离开游戏空间的方法，并表示自己并不是反派。监督通过修改任务条件，将风晴雪的任务改为“保护公主”。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何拒绝强买强卖</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">欲速战速决的你，遇上了势均力敌的对手——守卫着荒漠之心的砂之女。她一直呼唤着的泉水仙女的身份竟是……</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人来到荒漠之心，遇到了砂之女。砂之女要求他们留下公主，否则会杀死风清洛。监督通过史莱姆分身术帮助花时脱身，并与砂之女展开战斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何防止被鸡啄死</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">花时与凤凰谷中公鸡似乎颇有渊源。是非尚未分明时，涂卯卯便因鸡而死……？！</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人来到凤凰谷，遇到了花时养的公鸡“母鸡”。母鸡透露自己是花时小时候养的鸡，并提到雪长夏制作这个游戏是为了帮助花时复习考试。监督通过史莱姆分身术帮助花时脱身，并与母鸡展开战斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>初遇之章·如何叩开圣山之门</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">请神明准许我，叩开圣山之门，前往巨龙的巢穴！</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督等人来到圣山之门，通过圣像的试炼后，成功叩开了圣山之门，准备前往巨龙的巢穴。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"> </span><span style=\"font-size: 19px;\"><strong>初遇之章·如何坦然面对成败</strong></span><strong><br></strong><span style=\"font-size: 16px;\">踏上巨龙巢穴的众人，被可疑宝箱吸引了注意力。正当你们为试探其真身，踌躇不前时，巨龙？登场——！</span></blockquote><p style=\"text-align: center; line-height: 2;\"> <span style=\"color: rgb(140, 140, 140); font-size: 15px;\">礼堂</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到礼堂，发现台阶上有一个宝箱。花时提到宝箱怪的概念，监督决定由史莱姆分身去开启宝箱。就在此时，巨龙乐无异出现，众人意识到乐无异被巨龙控制。风晴雪提议屠龙，但监督指出他们的任务是捍卫巨龙的荣耀，双方阵营对立。巨龙要求交出公主，监督拒绝并决定与巨龙决一死战。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙巢穴</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在与巨龙的战斗中，众人失败。游戏提示“胜败兵家事不期，包羞忍辱是勇者”，苏筱和花时意识到游戏可能结束了，但花时希望游戏能读档重来。众人开始反思失败的原因，并讨论如何面对接下来的挑战。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样打出不同结局</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">二周目，巨龙抢先降临，你决定依照圣者的预言，让花时成为斩落巨龙的勇者。古怪的是，一周目时遭遇的怪人与村长并未如期而至……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140);\">起始之地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140);\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱、监督、花时、乐无异等人意外回到了游戏的起始点，发现游戏的时间线发生了变化。原本的剧情被提前，巨龙在村长出现之前就降临了。监督迅速指挥花时拔出勇者之剑，成功击退了巨龙。众人意识到他们进入了游戏的“二周目”，虽然部分记忆保留，但剧情走向已经发生了改变。监督决定不再按照游戏的既定规则行事，而是主动寻找村长，试图破解游戏的机制。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样不按牌理出牌</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">阻止了正要按部就班跑村长剧情的勇者·公主·花时，对规则提出挑战的你，做下了一个决定——？！</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">强盗窝</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督利用村长身份，直接与NPC对话，打破了游戏的规则。通过威胁和质问，监督成功从恶霸口中获取了地图的位置。众人前往强盗窝，发现风晴雪曾在此活动，并毁掉了雪长夏留下的石刻。监督推断风晴雪可能与雪长夏的失踪有关，但暂时没有证据。众人决定继续前进，寻找更多的线索。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样推断谁是卧底</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">强盗窝外的一块石头引起了你们的注意，只是石上原本刻有的字迹早早被人毁去，你对此有所猜测……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">强盗窝战斗后</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在强盗窝的战斗中，众人遇到了被游戏控制的雪长夏，他变成了教学关卡的NPC。战斗结束后，众人发现风晴雪曾在强盗窝活动，并毁掉了雪长夏留下的石刻。监督推断风晴雪可能是反派，但风晴雪解释说她只是为了自保才毁掉石刻。众人暂时接受了她的解释，但对她保持警惕。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样修改游戏规则</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">森林王子们果然还在原地，只是他们似乎更喜欢身为史莱姆的你……？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">幽暗森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督利用村长身份，修改了森林王子卯绒绒的任务条件，成功帮助她摆脱了狗叫的诅咒。众人获得了神圣之钥，继续前进。监督的举动让众人意识到，他们可以通过修改游戏规则来掌控局面。众人决定利用这一优势，继续寻找雪长夏的下落。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>再战之章·怎样进行团队建设</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">森林王子们获得了自由，按照一周目的流程，下一站是魔女茶会。可是，真的要这么做吗……？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">魔女茶会</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到魔女茶会，与风晴雪对峙。风晴雪解释说她并非反派，而是为了保护雪长夏才进入游戏。她透露雪长夏是游戏的开发者，游戏中的每个关卡BOSS都有现实中的原型。风晴雪还提到，雪长夏在游戏中留下了秘籍：“一往无前”。监督决定信任风晴雪，并将她的任务修改为“保护公主”。众人团结一致，决定继续前进，寻找雪长夏并揭开游戏的真相。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样活跃伤感气氛</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">再次来到荒漠之心，你决定先下手为强……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">荒漠之心外围</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到荒漠之心，回忆起一周目的经历。花时提到他们曾在这里找到风清洛，并将他装进背包里带走了。众人调侃了一番，气氛逐渐轻松。在与砂之女的对话中，花时和乐无异回忆起雪长夏制作游戏的初衷，以及他们五人小时候的故事。虽然气氛一度伤感，但众人通过调侃和回忆，重新找回了前进的动力。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样应对突然社死</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">导游·勇者·公主·花时在带领乐无异环游格兰索高地的旅途中遭遇了有史以来的最大危鸡。在乐无异的异议与个人的大危机之间，花时——！</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">凤凰谷</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到凤凰谷，遇到了花时在学校养的公鸡“母鸡”。母鸡突然开始背诵花时对乐无异的赞美之词，场面一度尴尬。花时试图阻止母鸡，但乐无异却表示愿意听完。最终，花时无奈地与母鸡战斗，成功拿到了神圣之钥。战斗结束后，花时和乐无异的互动让气氛再次活跃起来，众人继续前进。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 再战之章·怎样做一名NPC</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">你们终于再次走到旅途的终点，站在了圣像脚下。长久不曾说话的涂卯卯此时却发生了惊人异变，危险，从未离去……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">圣山之门</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到圣山之门，发现涂卯卯的同化率达到了100%，已经完全认同了游戏世界的身份。监督推断同化率与留在游戏世界的时间成正比，死亡会导致同化率暴增。众人决定加快进度，尽快找到雪长夏并离开游戏世界。在与圣像的对战中，花时成功通过了试炼，获得了最后一把神圣之钥。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>再战之章·怎样赢得人生游戏</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在巨龙面前，一向胆小的花时退缩了。但在关键时刻，神秘的宝箱中传出了熟悉的声音……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙巢穴</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人来到巨龙巢穴，花时因为害怕失败而退缩。雪长夏通过宝箱与花时对话，鼓励他勇敢面对巨龙。花时最终鼓起勇气，与巨龙展开战斗，并成功将其击败。战斗结束后，雪长夏被解救出来，众人成功逃离了游戏世界。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>别随便按两下试试</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">雪长夏苏醒，狄砚赶来，遥城五人组时隔多年再次团聚。而你与苏筱在病房外遇到的是前来告别，又像是前来问候的那个人……锦上添花的是，今天天气非常不错。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">医院</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">众人在医院重逢，监督公布了大家的体检报告。雪长夏的异化相性指数已经稳定，花时则觉醒了时间切片的能力。风晴雪也来到医院，向大家告别。她透露自己将离开海临，继续寻找真相。监督邀请风晴雪加入白荆科技，风晴雪欣然接受。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">格兰索私立高级中学</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">警员们找到了雪长夏的电脑，发现它正是开启游戏空间的源头。尽管电脑看起来普通，但他们决定谨慎行事，不再随意尝试操作。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 22px;\"><strong>格兰索历险记·姆丽叶绘本</strong></span></blockquote><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 初见<br></strong></span><span style=\"font-size: 16px;\">我们的不合群使我们相聚。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 在一场婚礼上，花时、乐无异、风清洛和雪长夏初次相遇。花时试图与乐无异搭话，却被对方以“没礼貌的小孩”为由拒绝。风清洛在树上调侃乐无异“欺负小孩”，而雪长夏则安静地坐在树下打游戏，对周围的事漠不关心。花时爬上树失败后，乐无异主动介绍自己和其他人，并提议教花时爬树，条件是花时叫他“乐哥”。花时最终妥协，称呼乐无异为“乐哥”，几人由此结识。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>研发日志</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">再重复一遍，不要把研发日志当日记写。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 雪长夏被确诊为X细胞异化综合征，开始住院治疗。为了在有限的时间内完成《格兰索历险记》，他夜以继日地工作，多次熬夜被护士发现并没收电脑。他将游戏剧本改编自《屠龙传说》，并加入了朋友们作为角色原型。尽管身体每况愈下，雪长夏仍坚持完成游戏，甚至在发病期出现幻觉，看到游戏中的像素小人“往外蹦”。最终，他在花时生日前完成了游戏打包，并计划重新加入联机模式。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>参观</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">这世上没有完美的人，只有迷弟的完美滤镜。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 乐无异带花时参观他的实验室，介绍自己正在组装的新机甲。实验室内，乐无异的主管禺期突然出现，严厉批评乐无异未完成工作。花时误以为禺期是“童工”，乐无异解释禺期是武器技术部的负责人，是一位厉害的铸造大师。禺期离开后，花时问乐无异是否生气，乐无异表示自己确实有错，无需生气。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 补课<br></strong></span><span style=\"font-size: 16px;\">子曰：因材施教。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 风清洛为花时补习历史，发现花时对南半球的历史知识几乎一无所知。雪长夏通过游戏提示帮助花时回忆历史事件，风清洛决定用历史题材游戏作为教材，帮助花时备考。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 礼物<br></strong></span><span style=\"font-size: 16px;\">最需要的不是最想要的，最想要的不是最需要的，人生之苦莫过于此。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 风清洛和狄砚为花时的生日礼物发愁。狄砚提议送钢笔或手表，但风清洛认为花时对这些不感兴趣。最终，风清洛决定购买金铃游乐园的门票，邀请大家一起为花时庆祝生日。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 牢骚</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">有些话和鸡说是没有用的，得和人说。</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 花时在鸡圈旁向大公鸡“母鸡”倾诉烦恼，抱怨自己历史考试不及格，羡慕乐无异和雪长夏的才华，感叹与朋友们的疏远。他怀念小时候的时光，感到孤独。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 告别</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">不打不相识，收了我的礼物就是我的朋友了哦~</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">风晴雪在离开前送给花时一枚手榴弹作为生日礼物，花时哭笑不得。风晴雪离开后，花时联系R.E.D.处理手榴弹。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 彩虹</strong></span><span style=\"font-size: 19px;\"><br></span><span style=\"font-size: 16px;\">风雨过后见彩虹，勇敢地朝着明天出发吧，少年！</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 花时在考试结束后联系监督，分享自己考试时的波折和考完后的喜悦。他提议大家一起去金铃游乐园玩，监督答应并准备带上筱筱。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:05:05', '2025-02-26 11:17:51', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (22, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/iw5s1aykmp1ierxm46s543ge7kpe8b2_20250219095119A028.png', 11210504, '远航者与不朽之影 ＞', '幕间剧情', '岑缨，监督，凤无梦，琉辛', '1121年初夏某日', '森罗', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">游荡在馆中深处的影子先生已经悄悄离开，而岑缨这边则迎来了几位令人头疼的新成员。</span></p>', '<p style=\"text-align: center; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>调查历程00 引</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 22:30</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·特殊品应对仓库</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨在博物馆的特殊品应对仓库中，正为一件新到的特殊物品进行登记。这是一件皮革与合金制成的手提箱，附有罕见的炼金回路。她在完成登记后，准备将箱子放入藏品柜，却突然听到门外的响动。她探出头查看，发现走廊空无一人，只在地上捡到一个小巧的木人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">同事前来询问是否需要帮助，岑缨表示工作已接近尾声，催促同事回家休息。确认物品安全后，她输入密码锁好藏品柜，离开了博物馆。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">翌日 10:30</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆正门</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">周末的海临博物馆人潮涌动，许多人排队等待参观新展“远航者之歌”。展览围绕几百年前的沉船“圣希尔德”号展开，展示了著名航海家塞尔索·蒙特兹的遗物与手稿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到博物馆，并非为参观展览，而是为了取回一件从天隙禁区送来的手提箱。根据狄砚的报告，这件物品与一桩无从查起的事件有关。尽管博物馆事务繁忙，博物学会已同意随时交接物品。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督拨通了博物学会负责人的电话，但无人接听。无奈之下，他决定独自进入博物馆，完成任务。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程01 启航</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 10:45</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入博物馆，接过导览册后，注意到展厅内人流量并未达到限流的程度。他决定在等待负责人期间，先参观展览。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在一枚老式航海罗盘前，监督仔细端详，发现背后有塞尔索·蒙特兹的签名。这时，一名博物馆员工前来，告知负责人因紧急工作无法立即接待，并引导监督前往一号展厅等待。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程02-1 异变</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·一号展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 11:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在一号展厅内闲逛，沉浸在展览的历史介绍中。突然，他听到奇怪的声音，转身发现装饰用的陶罐竟在移动，并向他冲来。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在陶罐即将撞上监督时，岑缨及时出现，击退了陶罐。她自我介绍为博物学会的考古学者，并提到这些陶罐的异常行为并非首次发生，但其他同事和游客似乎并未遇到类似情况。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督捡起一块陶片，发现其表面有微光，但因手帕被洗而无法擦拭。岑缨递给他一次性手套和密封袋，监督将陶片收好。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨随后告知监督，手提箱已失踪。她详细解释了手提箱的存放过程、安保系统的严密性以及陶罐活动的监控记录，推测手提箱的失踪与一名未知同调者有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与岑缨讨论后，认为手提箱可能仍留在博物馆内。岑缨提到，博物馆的安保系统未检测到X辐射异常，且手提箱上的磁贴定位显示其仍在馆内。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定使用X辐射探测仪进行地毯式搜索，岑缨则前往其他展厅协助排查。两人约定分头行动，确保手提箱不会在眼前消失。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程02-2 检测</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 11:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督使用X辐射探测仪在一号和二号展厅进行检测，但未发现任何能量反应。他感到搜索效率低下，正思索对策时，注意到岑缨正在与一名陌生女子交谈。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程03 并行</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 11:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与岑缨汇合，双方均未在各自负责的区域发现异常。监督询问岑缨关于那位陌生女子的情况，岑缨解释她只是对一幅名为《幻梦》的画作感兴趣，并提到这幅画曾被误放在临时仓库，险些错过展览。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督被画作中的人鱼形象吸引，但岑缨的提醒让他从恍惚中清醒。岑缨提到关于这幅画的传闻，称有人曾目睹画面内容发生变化。监督对此感到好奇，但认为这更像都市传说。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">两人决定前往特殊物品应对仓库进一步调查。路上，监督表达了对未知同调者能力的担忧，并提到自己认识的一位空间类能力者目前从事快递工作。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程04 显迹</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·特殊物品应对仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 初夏某日 11:45</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和岑缨来到仓库，尝试接入安保系统但失败。岑缨成功启动能力，复制出一个与现实完全相同的影像空间。她解释自己的能力是通过照片创建影像空间，但目前尚不稳定，只能同时维持一个空间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提议进入影像空间调查，但岑缨担心能力的不稳定性可能危及两人安全，决定独自进入。她解释影像空间中会有一条随机位置的“通路”，可以用来传递物品。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督鼓励岑缨在事件结束后前往白荆科技进行能力训练，并提醒她小心行事。岑缨进入影像空间后，监督发现照片中的展柜门是锁着的，而现实中的展柜门却开着，这让他感到疑惑。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程05 影像</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 未知时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨进入影像空间后，发现自己并未出现在仓库，而是站在博物馆门口。她感到空间范围异常扩大，且无法离开。在探索过程中，她遇到了一些模糊的人影和对话片段，内容涉及船长和小偷的争执。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在特展区，岑缨看到一位被称为“船长”的人影站在十字星胸针的展柜前，表现出强烈的怀念情绪。她试图与之交谈，但被其他人影阻拦。船长离开后，岑缨听到脚步声，意识到还有其他人存在于影像空间中。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨前往仓库，发现《幻梦》画作出现在临时仓库中。她捡到一枚十字星胸针，并回忆起与监督的对话。灯光闪烁时，她看到一个黑影手持箱子跑过，立即追赶。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程06 帮手</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 未知时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨回到十字星胸针展柜前，确认手中的胸针与复制品不同。她意识到影像空间的形成时间可能与昨晚有关，并推测手持箱子的人可能早已进入空间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">为了抓住黑影，岑缨决定利用胸针与“船长”交易。她大声呼唤，吸引黑影们聚集，并请求他们帮忙。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程07 奇遇</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·特殊品应对仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 12:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在仓库中寻找影像空间的通路，尝试了多个柜子但未成功。他注意到照片中的影像空间已扩大到整个博物馆，推测通路的范围也随之扩大。由于一个人无法完成搜索，监督决定寻求工作人员的帮助。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 12:15</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">监督在展厅中寻找工作人员，途中遇到一位打扮奇异的蓝发少女。工作人员正在盘查她，但少女声称有人在追杀她。监督注意到少女的衣着和装饰与特默里恩世界相似，决定暂时保护她，并带她前往餐厅进一步了解情况。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程08 流星</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·餐厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 12:25</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与蓝发少女琉辛在餐厅角落交谈。琉辛透露自己来自特默里恩，正在寻找朋友“流星”。监督推测琉辛可能是通过天隙通道来到森罗的同调者，且与手提箱的失踪有关。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">琉辛提到她的行李由“流星”保管，但在穿越过程中丢失。监督注意到她裙摆上的丝线与陶片上的痕迹相似，推测这些线索可能与袭击事件有关。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 12:40</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与琉辛在展厅中遇到发光的蝴蝶，随后被一群陶罐袭击。战斗后，监督发现新的陶片碎片上也有丝线，进一步确认了这些线索的关联。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督推测，袭击事件可能与手提箱的争夺有关，且穿越天隙通道的同调者至少有三人。他决定尽快将这些信息传达给岑缨，同时带琉辛去处理伤口。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程09 通路</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 12:50</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与琉辛交谈，进一步了解她的背景。琉辛透露自己被许多人追杀，但她并不清楚对方的身份。监督推测这可能与炼金术有关，尤其是琉辛提到的“让流星活过来”的能力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">琉辛提到她在穿越过程中看到了发光的蝴蝶，并跟随它们来到博物馆。监督意识到这些蝴蝶可能与袭击事件有关，决定测试对方的真实目标。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·走廊</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 13:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督故意引诱陶罐袭击自己，确认对方的目标是手提箱而非琉辛。琉辛及时出现，帮助监督击退陶罐。监督随后向琉辛展示手提箱的照片，确认她确实拥有一个类似的手提箱。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 海临博物馆·楼梯角落</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 13:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">琉辛带监督来到一个电箱前，展示了电箱作为影像空间通路的特性。监督将汉堡放入电箱，确认其消失后，终于找到了通往影像空间的通路。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程10 现影</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·特殊物品应对仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 未知时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨在影像空间中抓住了捣乱的黑影，发现它竟是一只玩具熊。玩具熊通过比划和动作与岑缨交流，透露自己与朋友在穿越过程中失散，手提箱原本属于它。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨推测影像空间的形成时间是在昨晚，且与手提箱的拍照有关。她意识到手提箱可能具有特殊功能，并决定与小熊合作，寻找离开影像空间的方法。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程11 脱困</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·特殊物品应对仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 未知时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨通过柜子收到了监督传来的纸条，得知监督已找到手提箱的主人琉辛，并确认了另一名同调者的目标仅为手提箱。岑缨与小熊进一步交流，确认了画中的蝴蝶是追杀他们的同调者之一。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督推测手提箱可能是一种高阶能源，代替岑缨成为影像空间的能源。岑缨尝试握住手提箱的把手，成功恢复了对影像空间的控制，准备离开。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与琉辛在《幻梦》画作前等待，利用Vein监控周围区域，确认目标出现后，准备将对方引至游客止步的区域进行交涉。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程12 设陷</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与琉辛在《幻梦》画作前伪装成普通游客，等待目标出现。Vein监测到目标下楼后，监督推测岑缨已离开影像空间，准备与目标进行交涉。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 调查历程13 终局</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 海临博物馆·临时仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与凤无梦在临时仓库内对峙，双方通过对话逐渐化解误会。凤无梦解释她并非为手提箱而来，而是在寻找另一个相似的箱子。琉辛和流星的出现进一步缓和了紧张气氛，大家最终达成共识。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·展厅外</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 17:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与岑缨在闭馆后总结一天的经历。岑缨提到琉辛和流星已加入博物学会，凤无梦也决定暂时留在森罗。监督对事件的圆满解决感到欣慰，并表达了对旅行的向往。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·特殊品应对仓库</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 22:03</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨在仓库中完成最后的准备工作，拍下手提箱的照片作为留念。她将手提箱放回藏品柜，确认一切无误后离开，准备迎接新的一天。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">事件最终以和平解决告终。琉辛和流星加入博物学会，凤无梦也决定暂时留在森罗。监督与岑缨的合作成功化解了危机，手提箱的秘密得以保留，同时为未来的故事埋下了伏笔。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这段经历不仅加深了监督与岑缨的默契，也为来自特默里恩的同调者们开启了在森罗的新篇章。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 蒙尘之章00 凝寂之馆</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 海临博物馆·影像空间</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 22:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨再次进入影像空间，准备兑现与船长和大副的承诺。她与船长交谈，得知船长对自己身份的困惑，并提到塞尔索·蒙特兹的胸针。船长委托岑缨调查大副的真实身份。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 蒙尘之章01 平凡的姓名</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·蒂尔莫海滨城市</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 22:45</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨在大副的指导下，尝试通过石板重现记忆。她成功进入四百年前的蒂尔莫，目睹了幼年塞尔索、卢修斯和克里奥菲斯的对话。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">记忆结束后，岑缨确认了大副的真实身份——卢修斯·弗朗，圣希尔德号的大副。卢修斯建议继续前进，寻找更多真相。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 蒙尘之章02 交叠的身影</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·银版相片前</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 23:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨、塞尔索和卢修斯来到银版相片前，岑缨通过石板重现了塞尔索和卢修斯的回忆。她目睹了塞尔索与卢修斯在圣希尔德号上的对话，以及他们对未来的憧憬与无奈。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>蒙尘之章03 理想之路与十字星</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·圣希尔德号沉船事件</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 23:15</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨进入塞尔索的记忆，亲身体验了圣希尔德号沉船事件的恐怖与绝望。她感受到塞尔索在生死关头的挣扎与对克里奥菲斯的思念。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 蒙尘之章04 触不可及的真实</strong></span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临博物馆·影像空间·克里奥菲斯的记忆</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 23:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨进入克里奥菲斯的记忆，目睹了她对塞尔索的思念与痛苦。克里奥菲斯在绝望中创作了《幻梦》，寄托了她对塞尔索的深情与等待。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨通过影像空间的能力，深入了解了塞尔索、卢修斯和克里奥菲斯的故事。她见证了圣希尔德号的沉船事件、克里奥菲斯的痛苦与思念，以及塞尔索对理想的坚持。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 这段经历让岑缨深刻体会到历史的复杂与人性的真实，也坚定了她继续探索真相的决心。塞尔索和卢修斯的告别，标志着这段跨越时空的对话圆满结束，但岑缨的旅程才刚刚开始。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:16:44', '2025-02-26 18:22:17', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (23, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/cneguq5qjtqvk5x6ogpx76odo0nto2k_20250219095332A033.png', 11210715, '底色', '间章剧情', '十手卫', '1121年7月', '森罗', '洛天依', '<p><span style=\"font-size: 14px;\">浮生过眼，要去记住那些平凡的、永远不会出现第二次的瞬间。</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:21:11', '2025-02-19 09:53:33', '洛天依', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (24, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/kwa9rfjae9ifgqd9azt3w91b1lbdz8o_20250219095029A026.png', 11210701, '苍蓝的达加兹 ＞', '幕间剧情', '监督，苏筱，岚岚，尤尼', '1121年夏', '森罗', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">当晨光穿透乌云的瞬间，将会有一个更宽广的新世界在你眼前展开。<br>——Bless you, last&amp;best.</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Re：孤蓝沉默之日</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">神秘少女与一段匆忙奔赴的航行。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临码头·速溶美梦号登船口</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在苏筱的安排下，登上了速溶美梦号豪华游轮。尽管此次行程的主要目的是前往乐园岛调查同调者厉小棠，但苏筱坚持让监督在船上享受难得的休闲时光。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督登上速溶美梦号，发现船上气氛热闹非凡。速溶美梦剧团刚刚完成内部重组，此次巡演备受瞩目。监督在船上遇到了岚岚，后者热情地邀请他体验演出和各类活动。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·演出厅</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 19:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督观看了速溶美梦的演出，被其精湛的表演和独特的艺术风格深深吸引。演出结束后，岚岚与监督交谈，提到速溶美梦的重组并非因为资金问题，而是为了提升艺术水平和扩大影响力。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 21:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在甲板上思考此次行程的下一步计划。他意识到，尽管此行的主要目的是调查厉小棠，但速溶美梦号的经历也为他提供了新的灵感。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Re：共坠猩红之梦</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">酣沉梦境与名为速溶美梦的船只。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 14:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督登上速溶美梦号，发现船上气氛异常，甲板上空无一人。他感到一阵晕眩，随后遇到了一群自称是“死人”的船员，包括船长德尔波特、木匠雷提诺和船员梅弥。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 15:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督被带到船舱，德尔波特解释了他们是一群遭遇海难后死而复生的船员，并且陷入了以4天为单位的轮回中。监督意识到自己可能也被卷入了这场轮回，无法轻易离开。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 16:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">德尔波特提到，唯一可能打破轮回的方法是帮助桅杆上的少女尤尼完成她的航行。尤尼的出现让监督感受到一股莫名的恶意，但德尔波特迅速挡住了她的视线。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 17:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督独自留在船舱中，检查随身物品后发现通讯器和终端均无信号。他意识到自己必须面对这场“密室逃脱”般的困境，并决定探索船舱，寻找线索。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>Re：迷途交错之夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">旧日碎片与用真心交换的真心。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·客船</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年，夏</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在速溶美梦号上继续探索，试图找到打破轮回的方法。他与船员梅弥交谈，了解到这艘船的轮回机制和海妖的存在。随后，监督遇到了神秘的少女尤尼，得知她来自巴达本加，并且与斯奈菲尔的海尔维格家族有着某种联系。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 23:00</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与尤尼在甲板上对话，尤尼透露她参与了斯奈菲尔的光荣之战，但时间线似乎与监督所知的斯奈菲尔历史不符。监督意识到尤尼可能来自一个与已知斯奈菲尔不同的平行世界。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 23:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">德尔波特打断监督与尤尼的对话，要求他们回去休息。监督回到船舱，思考如何应对即将到来的海妖和轮回。他决定利用现有的材料制作一个简易信号发射器，尝试与外界取得联系。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·梦境</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 未知时间</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入尤尼的梦境，目睹了斯奈菲尔的辉煌景象和光荣之战的准备。他意识到尤尼的过去与斯奈菲尔的命运紧密相连，而这场航行可能是她寻找归宿的关键。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>Re：浊海锈蚀之心</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">傲慢飨宴与沉默离席的某人。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 早晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督醒来后，发现尤尼和德尔波特正在讨论如何帮助他离开这艘船。尤尼决定寻找海豚，但监督提出了一个新的计划——利用信号发射器与外界取得联系。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船尾</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 中午</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">海妖突然袭击了船尾，梅弥受伤，尤尼情绪失控，导致船体出现裂缝。在大家的努力下，梅弥得到了救治，但尤尼因自责而躲到了桅杆高处。监督找到尤尼，安慰她并鼓励她继续航行。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入尤尼的梦境，目睹了巴达本加王国的凯特施图家族长女奥德的回忆。奥德在“光荣之战”中面临道德困境，最终选择保护船员和尤尼，拒绝参与对斯奈菲尔殿下的攻击。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Re：银辉凛然之枪</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">欢愉船歌与被长枪刺破的泡沫。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 早晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督醒来后，发现尤尼和德尔波特正在讨论如何应对即将到来的海妖。尤尼情绪低落，担心自己无法保护船员，监督鼓励她继续战斗。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船尾</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 中午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">海妖突然袭击了船尾，尤尼与海妖展开激烈战斗。监督目睹了海妖的强大，意识到尤尼的力量正在减弱。他决定帮助尤尼，寻找击败海妖的方法。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·船舱</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督进入尤尼的梦境，了解了波卡纳达加兹号的历史和尤尼的过去。他意识到尤尼不仅是船的名字，也是她身份的象征。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与尤尼并肩作战，最终成功击败了海妖。尤尼的力量得到了恢复，船上的危机暂时解除。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Re：重拾晨光之愿</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"color: rgb(140, 140, 140); font-size: 16px;\">慷慨馈赠与纠缠真实的决意。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 早晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">尤尼在船员们的支持下，逐渐恢复了对力量的掌控。她开始吸收海妖的力量，试图打破轮回。然而，风暴并未停止，海妖仍在不断出现。尤尼陷入了自我怀疑，船员们则坚定地站在她身边，表示愿意为她献出一切。</span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>Re：再见孤蓝之海</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"color: rgb(0, 0, 0); font-size: 15px;\">苍蓝苦痛与将驱散黑暗的晨光。。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在最终的战斗中，尤尼成功吸收了海妖的力量，但风暴仍未停止。船员们纷纷挺身而出，与海妖展开激战。监督也加入了战斗，最终在大家的努力下，海妖被彻底消灭，风暴平息。</span></p><blockquote style=\"text-align: left; line-height: 2;\"><span style=\"color: rgb(0, 0, 0); font-size: 19px;\"><strong>Re：敬新世界<br></strong></span><span style=\"color: rgb(0, 0, 0); font-size: 15px;\">圆满航程与光辉灿烂的新世界。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 黎明</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">风暴结束后，太阳升起，晨光照耀海面。船员们举行了盛大的庆祝活动，德尔波特在尤尼和监督身上画下了速溶美梦号的标志。大家举杯庆祝，敬速溶美梦，敬新世界。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">蒂尔莫·希罗诺港</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 早晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和尤尼在蒂尔莫港分别。监督前往乐园岛执行任务，而尤尼则决定前往一个新的地方，继续她的航行。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">尤尼在船员们的支持下，成功吸收了海妖的力量，打破了轮回。风暴平息后，大家举杯庆祝，敬速溶美梦，敬新世界。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 监督在蒂尔莫港与尤尼分别，前往乐园岛执行任务，而尤尼则决定继续她的航行，寻找新的方向。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这段经历不仅让监督和船员们收获了友谊和勇气，也让尤尼找到了新的使命。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Me：当钟摆摇晃</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“可笑的王冠，可耻的仪式，可悲的国家，可怜的你们。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">安提利亚中心广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 中午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">翡作为蒂尔莫商人之子，随父母来到安提利亚参加国王的落冕仪式。他对这场盛大的仪式毫无兴趣，甚至感到厌烦。在仪式上，德尔波特突然出现，砸碎了象征王权的王冠，引发骚乱。翡趁机离开，试图逃离这场闹剧。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>Me：当闹剧启幕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“别自以为是了，他以为他能改变什么，不过一场闹剧。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">安提利亚贫民窟</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">翡在贫民窟遇到德尔波特，后者救了他。德尔波特是个麻烦制造者，但他有着自己的正义感。翡对德尔波特的行为感到不解，认为他的反抗毫无意义。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Me：当咖啡入喉</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“速溶咖啡的味道，勉强能接受。至少比蒂尔莫咖啡馆里的强。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 傍晚</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">德尔波特带领船员们逃离安提利亚，决定前往蒂尔莫。翡被迫加入他们的队伍，尽管他对德尔波特的计划持怀疑态度。船员们为这艘船取名为“速溶美梦号”，并开始了他们的伟大航程。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> Me：当美梦苏醒</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“睁开眼的时候，发现只有我还停在原地。但好消息是，有了新方向。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">速溶美梦号·甲板</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 夜晚</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">在航行的第四天，安提利亚护卫军再次发动袭击。德尔波特决定让翡离开，独自面对追兵。翡被迫离开速溶美梦号，目送船只在火光中燃烧。他意识到，这场航行虽然短暂，却让他看到了改变的可能性。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海上·小船</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年某日 黎明</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">翡独自坐在小船上，看着速溶美梦号在火光中消失。他回想起德尔波特和船员们的笑声，意识到这场航行虽然结束了，但他的旅程才刚刚开始。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">翡在安提利亚的经历让他看到了德尔波特和船员们的反抗精神，尽管他认为这些反抗毫无意义。在速溶美梦号的航程中，他逐渐理解了德尔波特的信念，并意识到改变的可能性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">虽然速溶美梦号的航行以失败告终，但翡的旅程才刚刚开始。他带着对未来的期待，继续前行，寻找属于自己的答案。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这段经历不仅让翡看到了世界的另一面，也让他明白了反抗与坚持的意义。接下来的旅程将充满未知与挑战，但他已经准备好迎接一切。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:23:47', '2025-02-26 09:29:23', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (25, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/nxjausmu6zeplbuj1ahwv9y4ve8qnno_20250219095016A025.png', 11210705, '不要惊醒奈奥格 ＞', '幕间剧情', '监督，提提亚，景', '1121年夏', '森罗', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">服从我，或者，规训我。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-1 第一日·码头·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">暴风雨要来了。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 夏 14:22</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与狱警·M469乘坐“生命号”游艇前往乐园岛，途中遭遇暴风雨。M469提到乐园岛有三艘游艇：“秩序号”、“真言号”和“生命号”。监督询问乐园岛是否一直在移动，M469确认了这一点。途中，他们发现“秩序号”游艇失去动力，船上空无一人，船舱内有翻滚挣扎的痕迹和漆黑的污渍。监督从秩序号上勾住了一件C315的制服，制服口袋里有一张字条，上面潦草地写着“不要……惊醒……”。M469对此感到困惑，并决定先上岛汇报此事。靠岸后，M469用铁链固定游艇，恰好是14:30整点，一秒不差。码头上，M469遇到另一位狱警·M411，M411因未带手环而被派来送手环给访客。然而，M411突然情绪失控，驾驶“生命号”离开，声称受够了乐园岛的规则。监督戴上乐园岛的专属手环，手环显示访客规则，包括访客必须在规定时间内离岛，否则将被视为囚犯。监督意识到自己已暂时被困在乐园岛，并感到不安。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-2 第一日·会客室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">会客室中传来了争执声。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 夏 15:00</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与M469进入乐园岛内部，发现监狱设施老旧但功能齐全。会客室内，一名访客布朗先生因超时未离岛与狱警·C465发生冲突。布朗先生袭击C465后，会客室灯光闪烁，一只由黑雾组成的怪物出现并吞噬了布朗。监督试图用电击棒阻止怪物，但未成功。刑狱长及时赶到，用剑术击退了怪物。刑狱长向监督解释，乐园岛目前处于异常状态，所有人都必须遵守规则，违反规则会引来怪物或被怪物杀死。布朗先生因袭击狱警触犯规则，导致怪物出现。刑狱长建议监督尽快离岛，但M469告知“生命号”已被M411开走，岛上已无可用船只。监督意识到自己可能无法按时离岛，将成为囚犯。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-3 第一日·会客室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">会客室陷入了沉默，死亡的阴影在头顶盘旋。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">森罗历1121年 夏 15:00后</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督向刑狱长询问乐园岛的异常情况。刑狱长解释，异常始于两天前，所有人都必须遵守身份规则，违反规则会引来怪物或被怪物杀死。M469主动提出协助调查，监督也表示愿意参与，并提出利用白荆科技在X能研究方面的优势提供帮助。刑狱长起初拒绝，认为监督缺乏自保能力，但在监督的坚持下，决定测试监督和M469的实力。测试通过后，刑狱长同意让M469协助监督调查。监督询问岛上同调者的情况，刑狱长表示狱警中只有M469是同调者，囚犯中有三位同调者。监督推测异常可能与X能有关，并询问岛上是否有X能相关设施。刑狱长提到乐园岛的发电装置和引擎均为X能驱动，并提醒监督不要轻易信任任何人。监督表示理解，并决定从会客区开始调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-4 第一日·会客室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">布朗先生还静静地躺在地上……</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定查看布朗先生的情况，M469主动上前翻看布朗的遗体，并从他的衣兜里找到了一些杂物，包括名片、通讯器、打火机等。M469发现布朗的手环已经损坏，推测可能是袭击导致的。监督注意到沙发角落里的手提箱，打开后发现里面是一些狱警候选人的简历档案。M469解释，这些候选人是为填补退休狱警的空缺，但由于东流地区已有较多狱警，这些候选人可能没机会被选中。监督发现这些候选人都有案底，M469坦言乐园岛的狱警大多是从外界的罪犯中挑选的，她自己也不例外。监督意识到刑狱长的提醒有道理，但仍选择信任M469，并希望与她合作愉快。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-5 第一日·大厅·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">最先开始发疯的，就是岛上的警犬。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和M469回到大厅，查看电子屏上的《乐园岛基础规则》。规则中新增了几条诡异的内容，如“小心恶犬”“有光的地方更安全”等。C465提到，最先发疯的是岛上的警犬，它们变成了长满眼睛的怪物。监督推测，警犬可能因违反规则而变成怪物。C465还提到，狱医和监控室值班狱警也因异常事件死亡或发疯。监督决定调查医务室和监控室，并询问岛上是否有特殊动物。M469展示了自己的狱警规则，监督发现狱警规则没有新增内容，但C465表示狱警之间的冲突和不守规则导致了不少人死亡。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-6 第一日·监狱外部·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">大雨和狂风席卷了整片海域，巨浪凶猛地冲向码头。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和M469、C465在监狱门口遇到维修师C312，他刚完成安全隐患排查。M469提到，岛上只有C312一名维修师。C465提醒M469不要向访客透露太多信息。监督注意到C312的态度嚣张，但M469和C465并未多言。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D1-7 第一日·大厅·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">检测到访客超时未离岛，身份已改变。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">时间到达18:00，监督因超时未离岛被手环识别为囚犯，编号L148-14。囚犯规则显示，囚犯行动范围仅限于囚室，且不得顶撞狱警。M469表示囚犯规则没有新增内容，但C465提醒，违反规则的囚犯会被怪物杀死。监督决定与囚犯接触，M469建议去食堂，但C465让M469先回宿舍确认值班表。M469离开后，C465的态度变得冷淡，监督意识到C465可能故意惹怒访客。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N1-1 第一日·食堂·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">开饭了，请勿浪费粮食。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督在食堂排队打饭时，C465突然消失。一名囚犯试图插队并威胁监督，但被另一名囚犯L147-9吓退。L147-9自称是“天使屠夫”，并提到监狱中的囚犯分等级，但规则并不涉及“人与人之间的约定”。L147-9还提到，监督的囚室前一位住户因挑食触犯规则被怪物杀死。监督与L147-9交谈后，发现他对规则和怪物有独特见解。与此同时，M469回到值班室，得知自己当晚不值班，无法外出保护监督。值班狱警M322安慰M469，表示会帮忙照看监督。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N1-2 第一日·囚室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">这里就是你的囚室了。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 夏 18:45</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督被囚犯L147-9带到自己的囚室，L147-9解释晚上六点到七点半是囚犯吃饭和放风的时间，放风区没有特别限制，只要遵守基础规则即可。监督注意到L147-9非常困倦，L147-9表示自从规则出现后，他很久没睡好觉了。隔壁囚室的南希透过小窗与监督打招呼，她也是访客变囚犯的倒霉蛋，因低血压晕倒错过了离岛时间。南希提到带她上岛的“真言”号被逃跑的狱警开走，监督推测信息可信，但南希情绪崩溃，无法进一步交流。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N1-3 第一日·放风区·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">明明是放风时间，放风区却没什么人。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与L147-9在放风区交谈，发现大多数囚犯因恐惧规则而躲在囚室里。L147-9对规则似乎并不恐惧，甚至表示满意目前的生活状态。监督询问L147-9为何认为规则是“怪物”的规则，L147-9含糊其辞，表示这只是大家的普遍说法。监督希望L147-9分享更多信息，但L147-9拒绝透露更多。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N1-4 第一日·囚室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">今晚会是个平安夜吗？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 夏 19:20</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督回到囚室，南希提醒他晚上不要关灯。监督进入囚室后，隔壁的L147-9敲墙提醒他保持警惕。不久后，监狱突然停电，陷入黑暗。囚犯们因恐惧而骚动，怪物的声音逐渐逼近。南希因恐惧而哭泣，监督感到绝望。手环突然播报《乐园岛基础规则》第6条更新为“有光的地方更安全，长期处在黑暗中会成为食物”。与此同时，M469因不值班无法离开宿舍，C465冷嘲热讽后离开。M469试图前往囚室保护监督，但被怪物袭击。刑狱长及时出现，击退怪物并组织狱警恢复秩序。监督和其他囚犯被带到放风区，刑狱长安排狱警提灯保护大家，并派人修复电路。监督推测手环可能是规则监视的“帮凶”，刑狱长证实破坏手环的人都会因违反规则而死亡。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N1-5 第一日·刑狱长办公室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">异常简单的办公室，但充满了安全感。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督、南希和刑狱长在办公室休息。刑狱长展示了自己的规则，其中第4条赋予她修改规则的权利，但她认为目前没有修改的必要。监督对第3条规则（狱警人数不得低于40人）感到在意，刑狱长表示不希望知道违反规则的后果。M322报告停电是人为造成的，电箱附近发现烧焦的金属线，推测是狱警所为。刑狱长表示岛上情况越来越混乱，监督认为人在绝望中什么都做得出来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-1 第二日·刑狱长办公室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">天亮了，新的一天开始了。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">森罗历1121年 夏 早晨</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督在刑狱长办公室醒来，刑狱长一夜未睡。南希从噩梦中惊醒，精神状态糟糕。M469前来接监督开始调查，刑狱长给予M469所有区域的准入许可。M469为昨晚未能保护监督道歉，监督表示理解。刑狱长让M469将南希送回囚室，南希对M469表现出戒备。监督注意到南希比昨天更加沉默，推测她的精神状态进一步恶化。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-2 第二日·档案室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">这里是档案室，乐园岛自建成以来所有的文书档案全都在里面。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督、M469和南希进入档案室，档案室内存放着乐园岛自建成以来的所有文书档案。监督通过电脑检索与X能及同调者相关的档案，发现岛上共有6名同调者，其中3名是囚犯，2名已越狱（阿斯塔和厉小棠），1名是狱警（M469）。监督发现厉小棠的档案，意识到她曾在白荆科技工作，心情复杂。此外，监督还查看了其他同调者的档案，包括茜茜（言灵能力）、拉波（听觉类通感能力）和阿苧（操纵文字能力）。监督推测阿苧的能力可能与规则有关。随后，监督查阅了乐园岛大事件和财务记录，发现去年乐园岛引擎组和发电室改造为X能驱动，推测这可能与规则有关。监督决定先与阿苧接触。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-3 第二日·图书室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">有些凌乱的图书室，书籍散了一地。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和M469来到图书室寻找阿苧，发现她正在阅读新刊。阿苧对监督和M469的到来毫无反应，直到M469试图踩她的书，阿苧才暴怒发动攻击。阿苧的能力“操纵文字”让M469陷入困境，监督利用《少女与人偶2》吸引了阿苧的注意力，成功让她冷静下来。然而，监督和M469因与阿苧的冲突触犯了“囚犯间禁止私斗”的规则，黑雾开始侵袭。C439及时出现，以违反规则为由将监督和阿苧带往禁闭室。M469决定陪同，并表示会保护监督。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-4 第二日·禁闭室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">黑雾如影随形，直到进入禁闭室。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">C439将监督、提提亚和阿苧带到禁闭室，解释只要及时将违规囚犯带到禁闭室，怪物就不会出现。禁闭室内充满腐朽湿冷的气息，墙上挂着陈旧的刑具。C439要求监督等人抄写“乐园岛是我的家，我要遵守这个家的规则”100遍，否则禁闭不能结束。提提亚情绪低落，自责未能保护好监督。监督安慰提提亚，并开始抄写。不久后，囚犯L113-13因浪费水资源被关入禁闭室。他在抄写过程中被黑雾侵蚀，变成怪物。阿苧和提提亚合力击败怪物，监督推测怪物是由违反规则的囚犯变化而成。两小时后，C439将三人放出禁闭室。监督决定前往监控室调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-5 第二日·禁闭室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">又有谁进来了？</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">在禁闭室内，监督发现抄写规则时会感到耳鸣和寒意，推测抄写规则可能导致精神侵蚀。L113-13在抄写过程中被黑雾侵蚀，变成怪物。阿苧和提提亚合力击败怪物，监督推测怪物是由违反规则的囚犯变化而成。两小时后，C439将三人放出禁闭室。监督决定前往监控室调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-D2-6 第二日·医务室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">消毒水混着铁锈味的刺鼻味道扑面而来。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚来到医务室，发现M403在药品柜前鬼鬼祟祟。M403离开后，监督发现药品柜中有Scope出品的精神改善剂，甚至还有青玉坛的临床试验药物。监督推测M403可能有问题。提提亚的伤口处理完后，监督提醒她不要逞强，提提亚感动于监督的关心。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-1 第二日·走廊·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">天色渐渐变暗，乐园岛再一次迎来了夜晚。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督发现南希不在囚室，前往监控室的途中路过L147-9的囚室，发现他在睡觉。监督感到疑惑，继续前往监控室。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-2 第二日·监控室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">空无一人的监控室，本该在此时值班的狱警已经遇难。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚进入监控室，发现值班狱警的笔记本上记录着“它醒了！！！”的字样，且周三的笔记被撕掉。监督推测值班狱警C315在监控中看到了可怕的东西。监督决定查看监控，提提亚担心监督被侵蚀，提出由她来看。监督坚持自己查看监控，提提亚同意但全程紧盯监督。监督在监控中看到狱警打翻水杯，逐渐被黑雾侵蚀，提提亚及时打断监督的查看。监督意识到规则的危险性，决定立即前往值班室。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-3 第二日·值班室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">黑雾散去，值班室地面上留下一具残缺的躯体。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚赶到值班室，发现值班狱警已被黑雾侵蚀死亡。监督检查值班室，发现值班表上C465的名牌颜色异常变淡，推测她可能处于危险中。监督决定立即前往狱警宿舍确认C465的安全。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-4 第二日·狱警宿舍·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">M469和C465的宿舍，虽然简陋但干净整洁。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚来到狱警宿舍寻找C465，发现她不在。提提亚提到C465的能力是“测谎仪”，监督意识到C465一直在撒谎。C465回来后，承认自己故意将监督留在食堂，并激怒布朗先生导致其死亡。她还承认制造了昨天的停电事件。C465的手臂上出现了一只眼睛，她逐渐被黑雾侵蚀，变得疯狂。她声称要让所有人陪葬，并再次引发停电。监督和提提亚试图控制她，但C465逃脱，导致发电机室爆炸，C312死亡。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-5 第二日·发电室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">漆黑的发电室里安静得吓人，似乎有人在暗中窥视。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和刑狱长前往发电室，发现发电机被炸毁。监督成功修复发电机，并推测规则只认可直接造成的损坏。监督还发现乐园岛的监控系统独立供电，推测规则可能通过监控系统监视所有人。修复发电机后，监督获得“转换资格”，推测刑狱长规则中的“狱警人数不得低于40人”可能允许囚犯被提拔为狱警。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-N2-6 第二日·放风区·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">应该拿失去理智的C465怎么办呢？</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和刑狱长返回放风区，发现C465逃脱并引发混乱。M322试图开枪击杀C465，但被刑狱长制止。监督询问M403关于医务室中精神改善剂的事，发现M403并未去过医务室。监督推测有人在冒充M403。提提亚自愿成为狱医，使用青玉坛的精神改善剂成功治愈C465。刑狱长要求保密此事，避免引发更多混乱。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-1 第三日·囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">又一次，你从噩梦中惊醒。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚开始第三天的调查。监督询问南希的下落，发现她不在囚室。L147-9表示未见到南希。监督决定前往负一楼调查，提提亚提到自己的“测谎仪”能力，并表示只有C465、刑狱长和B112-2知道她的能力。监督相信提提亚是被冤枉的，并表示支持她。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-2 第三日·负一楼囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">负一楼的气氛比起地上更加怪异，即使开着灯也仍觉得幽暗不详。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚前往负一楼，发现囚犯们行为异常。提提亚解释负一楼的囚犯大多精神不稳定，不被允许离开房间。监督注意到茜茜在喂食一只小狗，提提亚提到茜茜曾偷偷养过一只狗，但后来失踪了。茜茜告诉监督，一个多月前她听到了奇怪的声音并看到了浓雾，雾的来源是厉小棠的囚室。监督推测厉小棠可能与克图尔特有关，事情变得更加复杂。茜茜还提醒监督不要欺负提提亚，监督笑着答应。茜茜的锡纸盘中的面包不知何时消失了，暗示岛上仍有未知的存在。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-3 第三日·负一楼囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">检测仪在尖叫，这里发生过什么？</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚进入B104号囚室，发现里面空无一人，但监督的警报器检测到X能量波动。提提亚检查后发现并无异常，监督推测可能是残留的能量。B103-3的囚犯突然发狂，提提亚解释他不喜欢她，因为她的“情感”太吵。监督提到青玉坛的精神改善剂，提提亚回忆起B103-3和厉小棠都曾使用过这种药物，但B103-3出现了耐药性。监督推测B103-3可能参与了厉小棠的越狱计划，并被B112-2欺骗。B103-3提到“第二次回来”，监督推测B112-2可能已经回到乐园岛，并冒充了M403。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-4 第三日·发电室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">发电机正轰隆隆地运转着。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚前往发电室，发现发电机虽然运转正常，但电量存储始终为空。监督推测有东西在X能转换成电能之前截取了能量，导致发电机无法正常供电。两人决定前往引擎室进一步调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-5 第三日·引擎室门前·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">引擎室的大门紧闭，里面藏着乐园岛最大的秘密。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚来到引擎室门前，发现门被锁上。灯光突然闪烁，黑雾再次出现，监督和提提亚被迫逃离。手环播报新增规则：“所有人禁止进入引擎室”，监督确认规则背后存在自我意识。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-K3-6 第三日·值班室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">情况在恶化，时间不多了。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚返回值班室，发现多名狱警被黑雾侵蚀，变成怪物袭击同事。提提亚和监督试图救人，但被侵蚀的狱警战斗力极强。刑狱长及时赶到，击退怪物。监督推测“规则”背后是一个有自我意识的生物，可能来自克图尔特。手环播报警告狱警数量降至39人，刑狱长任命监督为狱警C485，警报解除。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-7 第三日·医疗室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">咚咚咚，是谁在敲门。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚在医疗室为受伤的狱警治疗。提提亚提到“规则”似乎在加速侵蚀进程，监督推测“它”可能着急了。提提亚提出“惊醒”可能指“它”在睡觉，监督认为这可能是一个重要线索。突然，一只怪物敲门进入医疗室，提提亚根据“狱医不得见死不救”的规则为怪物包扎。监督推测怪物的求救也是狱医工作的一部分。提提亚最终击败怪物，监督通过假装生病避免了违反规则，确认“它”遵守规则且不够聪明。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-3-8 第三日·医务室·夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">已经后半夜，医务室又迎来了新的“病人”。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督在医务室守夜时，M411突然出现，声称自己需要精神改善剂。监督发现M411的手臂受伤，并推测他可能被侵蚀。M411提到C315曾说过“不要惊醒”，监督意识到C315可能知道更多信息。M411离开后，监督和提提亚讨论规则背后的“克图尔特”生物，推测它可能在筛选特定的人。手环突然播报：“不要相信规则，不要成为规则的朋友。”黑雾再次聚集，监督和提提亚意识到事态升级。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-1 第四日·医务室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">又是新的一天，但留给所有人的时间已经不多了。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督向刑狱长汇报了阿斯塔的真实身份和假药事件。刑狱长确认引擎室是“它”的藏身之处，推测“它”需要引擎室的X能维持控制。提提亚提出如何进入引擎室的问题，刑狱长提出修改规则或变成“它”的同类两种方案，但监督认为这两种方法风险过高。</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">突然，刺耳的警报声响起，手环播报新增规则：“在这里，永远只有一个‘你’”。监督和刑狱长意识到阿斯塔尝试欺骗规则失败，导致“它”被激怒。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-K4-2 第四日·大厅·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">咦，有两个刑狱长？</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">阿斯塔试图修改规则，允许所有人离开乐园岛，但规则反噬，黑雾聚集，阿斯塔被怪物围攻。监督和提提亚赶到大厅，帮助阿斯塔击退怪物。阿斯塔透露“它”的名字是“NYOG”，并解释厉小棠让她回来取“卵”，但“卵”已变异。阿斯塔被侵蚀，刑狱长用精神改善剂救了她，但刑狱长自己也被侵蚀。提提亚成为新任刑狱长，监督注意到乐园岛的速度变慢，推测“它”在消耗大量能量。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-3 第四日·大厅·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">让开吧，大家有自己该做的事。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">刑狱长决定修改规则，允许任何人进入引擎室。规则修改成功后，刑狱长被黑雾侵蚀，提提亚试图用精神改善剂救她，但无效。刑狱长将刑狱长职位交给提提亚，最终被完全侵蚀。提提亚和监督合力击败被侵蚀的刑狱长，但黑雾仍在扩散。监督发现乐园岛的速度进一步变慢，推测“它”正在消耗更多能量。提提亚和监督决定制定计划，进入引擎室解决“它”。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-4 第四日·大厅·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">要怎么才能进入引擎室呢？</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚决定通过废弃的施工管道进入引擎室，提提亚坚持自己进入，认为作为新任刑狱长，她应该承担风险。监督同意后，提提亚表示如果失败，她会修改规则，让所有人离开乐园岛。监督注意到乐园岛的速度变慢，推测“它”在消耗大量能量。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-5 第四日·狱警宿舍·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">帮手之一——C465。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">提提亚找到C465，要求她制作威力更大的延时炸弹，C465虽然疑惑，但仍同意帮忙。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-6 第四日·放风区·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">帮手之二——M322和阿苧。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督让M322将所有囚犯和狱警集中到有光的地方，并特别要求带上阿苧，以确保安全。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-7 第四日·囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">帮手之一——B103-3。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定动员B103-3的力量，提提亚主动提出与B103-3交涉，监督同意后，两人约定在发电室集合。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-8 第四日·囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">帮手之一——阿斯塔。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">提提亚找到阿斯塔，询问她的变形能力是否可以用来帮助刑狱长。阿斯塔最终同意协助。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-9 第四日·发电室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一切准备就绪。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚引爆发电室的X能量源，迫使“它”回到引擎室吸取能量。监督解释，毁掉发电室能量源后，“它”会回到引擎室，乐园岛的移动速度会进一步降低，最终停泊。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-4-10 第四日·引擎室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">成败在此一举。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督和B103-3在引擎室外等待，提提亚和阿斯塔成功进入引擎室后，引擎停转，怪物消失。提提亚和阿斯塔打开引擎室门，监督进入后发现黑雾仍在盘踞。茜茜突然出现，挡在监督面前，阻止了“它”的攻击。茜茜试图与“它”沟通，但“它”最终进入茜茜体内。刑狱长赶到，吞下“它”，成功控制了“它”，并恢复了茜茜的意识。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-5-1 第五日·刑狱长办公室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">事情解决了，你也该离开了。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">刑狱长与监督交谈，表示已恢复通讯，蒂尔莫将派船接监督离开。刑狱长感谢监督的帮助，并提供了同调者档案资料。提提亚归还刑狱长徽章，刑狱长赞扬了她的表现。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-S5-1 第五日·囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“阿斯塔小姐，早上好。”</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与阿斯塔告别，试图询问关于奈奥格和特默里恩的信息。阿斯塔拒绝透露，但暗示他们未来会再见。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-S5-2 第五日·放风区·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">比起前两天，在放风区自由活动的犯人多了些。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与L147-9告别，L147-9表示感谢监督帮助乐园岛恢复平静，并暗示自己对越狱事件的态度。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-S5-3 第五日·图书室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">无论什么时候，岛上的图书室总是那么安静。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与阿苧告别，阿苧提醒监督不要让比木老师的作品烂尾，否则她会杀了监督。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-S5-4 第五日·囚室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">虽说也算是患难之交，但以后还是尽量别见了吧。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与B103-3告别，B103-3表现出对监督的异常兴趣，监督感到不适，迅速离开。</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-S5-5 第五日·医务室·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">医务室静悄悄的，只有茜茜一个人躺在病床上。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督与茜茜告别，承诺未来会再见，茜茜露出笑容。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>PR-5-2 第五日·码头·昼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">再见了，乐园岛。</span></blockquote><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">监督在码头与提提亚和刑狱长告别，提提亚表示未来会来海临玩。监督登上蒂尔莫的船，离开乐园岛。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">尾声</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><span style=\"font-size: 15px;\">神秘人与L147-9的对话揭示，L147-9将“它”送给了别人，暗示乐园岛的未来仍有未知的变数。</span></p><p style=\"text-indent: 25pt; line-height: 2;\"><br></p><p style=\"text-indent: 25pt; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:24:35', '2025-02-27 10:45:26', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (26, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/h5m7w6dsevcibghtgsctz8gtpcpvqvq_20250219095007A024.png', 11210710, '通往「斑斓」的信号灯 ＞', '幕间剧情', '监督，苏筱，北洛，Sweeper-EX，提提亚，景，唐路遥，霍冉，长谣，元桃桃，瓦卡莎，狄砚，尤尼，风晴雪，琉辛，豹富，卡洛琳，莉缇亚，无咎，马尔斯，龙晴，言御，司旸，言雀，岚岚，修', '1121年夏', '森罗', '洛天依,奈默', '<p>有时候……人脉也没有想象中那么复杂……</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-1 即将到达！宝石海滩！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">是久违的假期。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">蒂尔莫·宝石海滩度假区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督站在椰子树荫下，茫然四顾。这里是蒂尔莫著名的宝石海滩度假区，以清澈如宝石的海水和夏季斑斓的星潮闻名。苏筱的声音从远处传来，她正和北洛驾驶一辆蓝白相间的接驳车赶来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 回忆片段：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在乐园岛事件结束后，监督本应直接返回海临，却临时接到苏筱的通知，计划有变——白荆科技决定组织一次团建活动。苏筱已经安排好一切，监督只需前往蒂尔莫码头，乘坐游艇前往度假区。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">现实场景：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛驾驶的接驳车稳稳停在监督面前，苏筱热情地招呼他上车。车内，苏筱兴奋地讲述她是如何策划这次团建的，包括确定地点、安排食宿交通等。北洛则对白荆科技的改装车赞不绝口，尤其是其新型车载动力装置。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">意外发现：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督注意到车载语音系统的声音异常熟悉，仔细辨认后发现竟是Sweeper-EX。原来，乐无异对Sweeper进行了改造升级，使其具备变形车功能。Sweeper-EX通过车载系统与监督互动，并表示白荆科技武器技术部会继续努力。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">抵达目的地：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">车子停在沙滩上，苏筱拉着监督下车。沙滩上游客们嬉戏玩闹，远处摩托艇乘风破浪，空气中弥漫着海水和阳光的味道。苏筱兴奋地宣布，监督可以放下一切包袱，尽情享受这次绝美假日。监督则思考着如何正式开启度假模式，苏筱自信地表示，这一切交给她来安排。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-2 哇哦哇哦！好多人啊！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">今日宜会友。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">蒂尔莫·宝石海滩商业区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">宝石海滩作为蒂尔莫最大的休闲度假中心，拥有完善的商业区设施。苏筱为监督精心挑选了一套度假装扮，试图彻底清除他的“社畜气息”。监督戴上平光眼镜，略显不习惯，但苏筱对自己的审美搭配非常满意。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">偶遇岑缨与阿棘：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在商业区，监督和苏筱遇到正在帮游客拍照的岑缨。岑缨的摄影技术让游客赞不绝口，她随后与监督和苏筱汇合。阿棘从监督身后探出头，显得害羞又紧张。岑缨提到她打算去拍摄海边岩洞的光影，邀请阿棘同行。阿棘犹豫后决定独自留在商业区，监督和苏筱则继续前往沙滩。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">沙滩上的奇遇：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">沙滩上游客熙熙攘攘，监督发现一只寄居蟹在沙滩上自由穿梭。苏筱介绍，景区非常注重海洋生物保护，这些蟹类几乎成了吉祥物。监督与寄居蟹互动后，它迅速钻进沙子里消失不见。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">元桃桃与小伙伴们的登场：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">元桃桃突然扑向监督，兴奋地表达对监督归来的喜悦。长谣和瓦卡莎也加入其中，瓦卡莎因炎热显得精神萎靡。元桃桃提议玩水上项目，但被年龄限制劝退。监督建议他们去水上儿童乐园，最终三人达成一致前往。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">栈桥上的重逢：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱来到木质栈桥，遇到刚下船的霍冉和狄砚。霍冉调侃监督的肌肉变化，狄砚则推荐斑斓星潮作为最佳观赏期。监督提到精神海域的稳定区域，苏筱和霍冉忍不住大笑，监督尴尬地转移话题，提议去买西瓜冰。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">Stella Coffee&amp;Bar的悠闲时光：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱在人气饮品店Stella Coffee&amp;Bar享用西瓜冰，苏筱感叹这是森罗的伟大发明。监督感慨假期的幸福，苏筱笑称监督的“主角光环”总是让他卷入奇怪事件。两人举杯相碰，苏筱安慰监督安心享受假期。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-4 组队集结！蟹蟹友你！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在蒂尔莫，谐音梗不扣钱。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">蒂尔莫·宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱回到沙滩，苏筱支起遮阳伞和躺椅，享受绝佳观海位置。Sweeper-EX换上一身可爱的沙滩装扮，以“专属万能女仆”的身份提供沙滩服务，包括鲜榨果汁、防晒霜和蒂尔莫古法精油按摩。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">正当监督准备享受按摩时，刑狱长和提提亚突然出现。提提亚兴奋地提到「蟹蟹友你」杯夏季沙滩趣味锦标赛，监督和苏筱迅速了解比赛规则。比赛分为沙滩排球、公路赛车、原创调饮、模拟枪战和海滩寻宝五项，每项需两人组队参加，且同一组人只能报名一项。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚组队报名模拟枪战，北洛与监督组队参加公路赛车，唐路遥与监督组队参加原创调饮。苏筱和刑狱长则负责剩下的沙滩排球和海滩寻宝。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">Sweeper-EX表达了他想与监督一起参加海滩寻宝的愿望。尽管规则上未明确允许机器人参赛，但苏筱巧妙说服工作人员，最终成功为Sweeper报名。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-5 忙碌一天！来点烧烤！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">团建的重头戏当然是——</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">蒂尔莫·宝石海滩烧烤区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱完成比赛报名后，与白荆科技的同事们汇合，享受海滩烧烤。霍冉、狄砚、长谣、元桃桃、瓦卡莎、艾摩诃、尤尼和风晴雪等人齐聚一堂，气氛热烈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">霍冉展示了自己带来的烧烤装备，包括帐篷、折叠椅和充气床垫。风晴雪为大家分发饮料，尤尼则专注于烤制美食，监督品尝了她烤制的鱼和烤肠，赞不绝口。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">尤尼得知监督报名参赛后，鼓励他全力以赴，并表示自己因规则复杂而选择不参加。监督感受到肩上的责任，决心在比赛中取得好成绩。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">夕阳渐渐靠近海平线，众人享受着美食和海风，期待即将到来的斑斓星潮和明天的比赛。元桃桃兴奋地指着海面，长谣则提醒她小心手中的奶茶。监督和同事们共同期待一个美好的假期和成功的比赛。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S1 公路赛车 Session1</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和北洛进行赛前的场地适应时，遇到一个不太讲理的车手。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩园区公路</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午10:47</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">离开赛还有一段时间，监督和北洛领取了比赛专用的越野车，进行场地适应。赛场是宝石海滩内特意开辟的一段公路，连接了度假区入口和海滨岩洞，中间有一些岔路，但主路只有一条。除了固定弯道和路障，还会有随机投放的障碍物，需要车手注意躲避。北洛驾驶技术娴熟，轻松避开路障，监督则根据实际路况在路书上做了详细标记。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛对监督的专业性表示认可，尽管他自认并非专业赛车手。监督提到Sweeper的改装车，北洛表示对Sweeper的车很感兴趣，但比赛只能用主办方提供的统一车型。两人在适应场地时，遇到了一辆改装过的赛车，北洛通过引擎声判断出对方擅自改装，但并未多言。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">上午的适应结束后，监督和北洛在路边短暂休息。北洛提到黑曜的赛车手常通过改装提速，但宝石海滩的安全措施很完善，改装车的风险并不高。随后，一辆车停在他们旁边，司机自称是今年环北蒂尔莫拉力赛的第四名，挑衅北洛比试。北洛拒绝，但对方紧追不舍，最终被北洛轻松甩开。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> BA-6-S2 公路赛车 Session2<br>和北洛一起赢得了公路赛车的冠军。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩园区公路</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午12:58</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">比赛正式开始，监督和北洛的赛车迅速占据领先位置。然而，途中遇到一群螃蟹横穿马路，北洛停车让行，第四名趁机超车。北洛随后加速追赶，最终以创纪录的成绩夺得冠军。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">第四名因擅自改装赛车被取消成绩，愤怒地质问工作人员，但工作人员确认北洛的赛车并无问题。北洛对夺冠并不意外，表示今天过足了瘾，并邀请监督未来再做他的领航员。监督送给北洛一个钥匙扣作为谢礼，北洛欣然接受。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>BA-6-S1 海滩寻宝 Session1</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和Sweeper在沙滩上展开了地毯式搜索，一番努力后，收集到的瓶子数量却落后于琉辛豹富组合。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 清晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和Sweeper-EX在海边享用丰盛的早餐后，开始了海滩寻宝比赛。比赛目标是收集“海星之瓶”，数量越多，成绩越高。Sweeper-EX干劲十足，凭借超高清摄像头高效寻找空瓶，同时还清理了沙滩上的其他杂物，甚至帮路人找回了丢失的物品。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和Sweeper-EX在比赛中遭遇了一群螃蟹的“袭击”，Sweeper-EX被螃蟹追赶，最终启动清洁模式成功脱身。比赛结束后，监督和Sweeper-EX以99个空瓶的成绩夺得第一名，远超其他参赛者。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S2 海滩寻宝 Session2</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和Sweeper一起赢得了海滩寻宝的冠军。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩服务中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午16:49</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和Sweeper-EX回到服务中心结算成绩，工作人员宣布他们以99个空瓶的成绩创下了比赛记录，夺得第一名。Sweeper-EX兴奋不已，监督也为他们的努力感到欣慰。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">工作人员为监督和Sweeper-EX颁发了“闪耀之匣”的钥匙，匣子埋在海滩的落日观赏点。监督和Sweeper-EX在沙滩上寻找匣子时，Sweeper-EX送给监督一枚银粉色的贝壳作为礼物，监督则将一只橡胶小鸭子送给Sweeper-EX。两人在海边享受落日，Sweeper-EX表示这将成为他记忆芯片中最闪耀的瞬间。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S1 模拟枪战 Session1</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和提提亚在沉浸式作战时发现了意料之外的“干扰项”。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩海滨岩洞</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午15:16</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和提提亚躲在一个隐蔽的海蚀洞中，屏息留意外面的动静。几名游客在附近搜索，抱怨水枪的重量和比赛的难度。提提亚对水枪表现出浓厚的兴趣，虽然她还没有持枪证，但她偷偷学过持枪姿势，渴望展现自己的帅气。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督发现高处有狙击手限制他们的行动，推测这是为了防止某支队伍过于强势。两人决定合作突围，提提亚负责吸引火力，监督则用水枪干扰狙击手。在移动过程中，提提亚发现一只巨大的螃蟹，提议用它作为掩护。监督同意后，提提亚扛着螃蟹狂奔，成功吸引了狙击手的注意力，两人顺利进入仓库安全区。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S2 模拟枪战 Session2</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和提提亚一起赢得了模拟枪战的冠军。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩海滨岩洞</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午16:19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">比赛接近尾声，监督和提提亚在运送物资的路上遇到其他参赛选手的袭击。突然，岩洞中涌出白烟，烟雾发射器启动了比赛的后半段“清扫机制”。监督和提提亚迅速撤离，但一名参赛选手趁乱偷袭，提提亚准备反击时被另一方向的枪声干扰。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">偷袭者逃入岩洞后，监督推测对方可能是白荆科技的同事。比赛结束后，监督和提提亚以最高积分夺得第一名。其他参赛选手对比赛规则提出质疑，工作人员表示会继续优化规则。比赛结束后，参赛游客们开始用水枪互相扫射，提提亚成为众矢之的，但她毫不示弱，举枪反击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">风晴雪和狄砚送来毛巾，监督得知她们在度假区兼职，负责维持比赛平衡。狄砚为监督和提提亚盖了水枪形状的印章，作为第一名的奖励。两人前往伴手礼商店挑选纪念品，提提亚最终选择了一个螃蟹玩偶，监督则偷偷买下了她喜欢的泡泡枪。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S1 沙滩排球 Session1</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和景进行了充分的赛前热身，但比赛由于对手的缺席，并未按时开始。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩排球场地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午9:10</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和刑狱长景在比赛开始前进行热身。景提到她曾学过沙滩排球，但从未打过比赛。监督邀请景与游客们打友谊赛，景详细讲解了沙滩排球的战术，展现出她对比赛的理解和掌控力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在比赛进行得如火如荼时，工作人员通知监督和景，他们的对手因故无法参赛，直接判定两人为胜者。景询问对手的情况，工作人员提到一对姐弟因姐姐失踪而退赛。监督和景决定帮助弟弟寻找姐姐，弟弟情绪激动地讲述了他与姐姐的矛盾和旅行中的摩擦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">景冷静地分析情况，监督则建议弟弟先给姐姐打个电话。弟弟恍然大悟，意识到事情可能比他想象的简单。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> BA-6-S2 沙滩排球 Session2</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩服务中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午10:13</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和景在服务中心找到了失踪的姐姐。姐姐正悠闲地喝着果汁，弟弟则一脸紧张地站在一旁。监督和景鼓励弟弟向姐姐道歉，弟弟犹豫片刻后终于鼓起勇气走了进去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">隔着玻璃，监督和景看到姐弟俩的互动。姐姐起初有些生气，但在弟弟的诚恳道歉后，两人很快和好。姐姐得知监督和景是原定对手后，主动提出认输并让出积分，但景和监督坚持要公平比赛。姐姐被两人的态度打动，决定认真应战。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩排球场地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午10:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">比赛开始，姐姐展现出强大的实力，弟弟也在姐姐的鼓励下逐渐进入状态。景和监督则默契配合，尽管姐姐的扣杀极具威胁，但景的防守和扣球同样出色。最终，景和监督以微弱的优势赢得了比赛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">比赛结束后，姐姐和弟弟向监督和景表示感谢，并邀请他们一起喝饮料。景在监督的帮助下戴上了一对蒂尔莫手工艺人制作的耳环，监督称赞她戴上后非常好看。景表示会准备回礼，监督则对即将到来的回礼充满期待。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S1 原创调饮 Session1</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和唐路遥商定好饮品的具体制作，只是还缺了一种材料。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩Stella Coffee&amp;Bar</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午9:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和唐路遥在酒吧集合，准备参加原创调饮比赛。唐路遥对假期表现出极大的享受，感叹没有工作的压力。两人决定调一杯以葡萄汁为基底的饮品，命名为“Lucky Stella”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在调饮过程中，唐路遥意外加入了一瓶神秘的淡金色液体，导致饮品迅速膨胀溢出。酒吧服务员解释这是客人落下的物品，监督推测这可能是卡洛琳的“杰作”。两人清理现场后，决定去购买葡萄汁重新开始。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-6-S2 原创调饮 Session2</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">和唐路遥一起赢得了原创调饮的冠军。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩商业中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午10:46</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和唐路遥在商业中心购买葡萄汁时，唐路遥表现出对工作的焦虑，尽管他嘴上说着享受假期，但内心始终无法完全放松。监督提议扭蛋机带来好运，唐路遥尝试后却只扭到普通款，而监督则幸运地扭到了限定款。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">两人回到酒吧后，唐路遥重新调制饮品，最终完成了一杯名为“Lucky Stella”的葡萄汁威士忌调饮。饮品受到围观游客的称赞，两人带着奖品转移到视野更好的地方享用。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>BA-8 斑斓驰夏</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜幕降临后，应北洛之邀去栈桥上看斑斓星潮。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩栈桥</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督按照约定到达栈桥，北洛早已在此等候。北洛送给监督一顶帽子作为冠军回礼，两人一起等待斑斓星潮的到来。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">夜幕下，潮水泛起蓝色荧光，景象壮观。北洛提到有人讨论斑斓星潮的传说，称可以对着大海许愿。监督问北洛是否有什么愿望，北洛表示自己已经拥有了一切，只是享受这种漫无目的的闲逛时光。两人约定下次再来看斑斓星潮，为这次假期画上了完美的句号。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-8 闪耀的每一瞬</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜幕降临后，应Sweeper之邀去海边看看“闪耀之匣”里装的东西。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(191, 191, 191); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(191, 191, 191); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督按照约定到达海边，看到Sweeper正站在沙滩边缘，手忙脚乱地准备着什么。监督悄悄靠近，发现Sweeper正在摆弄“闪耀之匣”里的烟花棒。Sweeper被监督的突然出现吓了一跳，烟花棒掉在地上，被海浪冲走。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">Sweeper委屈地哭了起来，监督连忙安慰他，并变魔术般拿出两根烟花棒点燃。Sweeper兴奋地接过烟花棒，在沙滩上挥舞，划出亮晶晶的轨迹。监督告诉Sweeper，其实准备了很多烟花棒，今天可以尽情放个够。Sweeper欢呼雀跃，监督也陪着他一起享受这闪耀的瞬间。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-8 浪沫托起的珍珠</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜幕降临后，应提提亚之邀去海边进行适应性训练。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩码头</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督按照约定到达码头，发现提提亚坐在一条小船上，显得弱小无助。监督小心翼翼地上了船，尽量保持船身稳定。提提亚送给监督一个穿着黑白囚服的小人吊坠，作为伴手礼店的礼物。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 提提亚正在进行晕船的适应性训练，监督提议用晕车药或晕车贴，但提提亚表示这些方法对她无效。两人聊着天，提提亚突然扣动了泡泡枪的扳机，泡泡飘散在空中，提提亚表示很喜欢这份礼物。尽管晕船的问题还未解决，但提提亚决定继续努力。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-8 清澄季风</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜幕降临后，应景之邀去海边散心。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督按照约定到达海边，看到景正站在潮水中，目光飘向远方。景提到自己小时候曾在蒂尔莫生活过，回忆起与父母一起度过的短暂时光。监督感到惊讶，景则表示这并不算乐园岛的机密，只是她个人的回忆。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">景送给监督一段特殊频段，表示这是她的私人联系方式，监督可以随时联系她。两人一起看着漆黑的海面，远处的灯塔在夜间为航船引路。景提到自己很喜欢这个名字，因为它让她能够站在更多角度思考，而不仅仅是乐园岛的立场。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-8 致星夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">夜幕降临后，应唐路遥之邀去Stella Coffee&amp;Bar喝一杯。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩Stella Coffee&amp;Bar</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督按照约定到达酒吧，发现店内人满为患，大家都在等待流星的降临。监督找到唐路遥，两人一起坐在冠军专属的座位上，享用唐路遥调制的“Lucky Stella”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">尽管流星并未出现，但两人依然享受这最后的夜晚。唐路遥提到老家西垂会寄来一些土特产，邀请监督到鹿路运输做客。监督欣然同意，两人约定未来再一起看流星。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-8 最后一晚！早点休息！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">独自到海边走走……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督意识到明天就是返程的日子，行李和伴手礼还未收拾好。监督决定早点回房间休息，调整状态，准备重新投入工作。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-9 返程在即！假期告急！</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">再见，宝石海滩。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">「蟹蟹友你」杯锦标赛颁奖现场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 上午10:57</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">颁奖仪式上，主持人宣布来自遥城的卜众耀先生获得冠军，监督则因海滩寻宝比赛不符合“双人组队”的规定，只能获得特别「蟹蟹」奖。监督在领奖台上发表简短感言，提到感谢白荆科技和所有朋友的支持。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱突然告知监督，航班已改签至晚上，大家还可以多留一个下午。监督决定利用这最后的时间体验摩托艇，大家纷纷离开颁奖现场，继续享受假期的最后时光。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> 返程</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">宝石海滩至机场的路上</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">森罗历1121年夏季中旬 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和同事们乘车前往机场，准备返程。唐路遥因假期综合征显得无精打采，北洛则表示无咎即将落地，唐路遥很快就会恢复。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">车窗外，夕阳余晖洒在路面上，沙滩上的人影渐渐远去。监督感慨假期的结束，但也对未来充满期待。尽管大家都不想上班，但监督表示未来还可以约着一起出来玩。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">再见啦，宝石海滩。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-39 一只螃蟹</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">霍冉、长谣、元桃桃三个人在海滩边举办了堆沙雕比赛，第一名作品的独家秘诀原来是……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督远远看到元桃桃、长谣、霍冉和瓦卡莎聚在沙滩上，正在进行沙雕比赛。元桃桃自封评委，监督则被拉来担任裁决。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督仔细查看几位选手的作品：一号作品被霍冉解释为瞳先生的侧脸，二号是瓦卡莎的“超大碗咖喱牛肉饭”，三号是霍冉的怨气满满的脸，四号则是元桃桃的寄居蟹沙雕。监督最终选择寄居蟹沙雕为第一名，结果发现沙雕里藏着一个仿真寄居蟹摆件，元桃桃作弊被抓现行。霍冉追着元桃桃要告状，监督则收获了元桃桃“赠送”的寄居蟹摆件。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-40 一张照片</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">无咎听到海里传来奇怪的呓语……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督看到北洛和无咎在海边，无咎似乎被某种声音吸引，正往海里走。北洛及时阻止了他，无咎解释自己可能是幻听或梦游。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和唐路遥走近，唐路遥递给无咎一双新的拖鞋，无咎感激不已。无咎用相机拍下了监督的照片，监督要求查看照片，但无咎已经跑开，准备去吃晚饭。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> BA-41 一杯冷饮</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩小道</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在岛上偶遇马尔斯，两人一起欣赏了长势极好的海芋。马尔斯提到自己被嫘祖强制休假，监督则邀请他一起去买西瓜冰。马尔斯婉拒后，监督送他去了纪念品商店。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">临别时，马尔斯提议请监督喝西瓜冰，监督欣然接受。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-42 一个瓶子</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在海滩上意外捡到了一个装着纸条的大玻璃瓶。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督捡到一个漂流瓶，里面装着一张纸条，记录了一位住院孩子的心愿和许多陌生人的留言。监督在纸条上写下祝福，并将漂流瓶重新扔回大海。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-43 一次救援</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">晴在沙滩上拾了一些贝壳，正要离开时，海面传来呼救声……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督看到龙晴在捡贝壳，龙晴提醒监督小心脚下的贝壳。两人正准备离开时，听到有人呼救。龙晴迅速跳入海中，救起了一名溺水的工作人员。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">工作人员为表示感谢，送给龙晴一张人鱼表演的门票。监督邀请龙晴一起去看表演，龙晴欣然同意。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-44 一段小憩</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">走累了，就停下来。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩沙滩</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在沙滩上找到正在打瞌睡的苏筱，两人一起躺在躺椅上休息。苏筱醒来后，拿出雪长夏的游戏机，邀请监督一起玩双人模式。两人回忆起童年的夏天，苏筱表示会努力支持监督，监督则感谢苏筱的陪伴。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-45 一顿烧烤</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">当各种意义上的鸟类凑到了一起……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩露天广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在美食广场遇到言御和司旸，三人一起买了海鲜炒饭和鱿鱼。言雀和岚岚带着大米饭出现，大家讨论了薯片的口味，言雀和岚岚最终达成一致。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">言御和司旸提议干杯，监督欣然加入。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BA-46 一把钓竿</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">修的钓鱼策略是，愿者上钩。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">宝石海滩栈桥</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年夏季中旬 下午</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在栈桥上遇到修，修正在用无饵的钓竿钓鱼，表示自己等待的是“机缘”。不久，一艘贴着血露薇纹样的快艇靠近，修向监督告别，准备离开。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:26:54', '2025-02-26 11:43:54', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (27, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/dfnvibins55iclp3g1nxi78tpcgkgiv_20250219094916A021.png', 11210901, '第二天性 ＞', '幕间剧情', '余音，监督', '1121年', '森罗', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">因您的“英勇事迹”，对方已撤回一个合奏邀请。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-1 开始播放</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">越是庞大精密的机械，越需要重视那些微小的故障。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·数据中心</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">熹尔正在耳机中收听电台节目，突然被同事告知白荆科技的数据中心遭到攻击。她匆忙赶到数据中心，发现同事们并没有像往常一样焦急抢修，反而显得异常平静。原来，外勤行动组γ小队的队长余音已经介入处理。余音以惊人的速度识别并修复了数据冲突，成功恢复了系统的正常运行。熹尔对余音的能力感到震惊，甚至怀疑她是否是人类。余音随后解释了艾达的复阶文字，并决定编写一个智能识别插件，以帮助白荆科技更好地处理艾达数据。在插件的帮助下，白荆科技开始排查并追回丢失的存储盘，余音则亲自前往市中心执行任务。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-2 导入</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">那源头不明、不讲道理的心动……亦或是心悸。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临市中心·冬红广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音来到市中心，寻找最后一枚丢失的存储盘。她来到一家音乐制作人的工作室，得知存储盘可能被惊栗乐队带走。制作人建议余音前往冬红广场的演出现场寻找乐队。余音抵达广场后，发现自己陷入了一系列幻觉和回忆中，仿佛回到了艾达的世界。她回忆起与仿生机器人乔一的对话，以及她对艾达规则的执着。最终，余音确认这些异常现象与惊栗乐队的演出有关，并决定进一步调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-3 渐强音</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">人生的转折来得无声无息，以至于你一直以为那只是一个风和日丽的寻常午后。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">艾达·机器人修理停放处</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音来到机器人修理停放处，探望她的老师——一台即将下线的初代机器人。老师教导余音如何面对告别，并鼓励她继续前行。随后，余音找到了被拆除机件的乔一，她因多次违规行为被处罚。乔一向余音解释了她逃跑的动机——为了观看一场未经审批的演唱会。乔一认为，演唱会代表了一种不受束缚的自由，而她愿意为此打破规则。余音虽然不理解乔一的选择，但也意识到自己内心深处对自由的渴望。乔一预言，余音未来也会需要她的帮助。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-4 桥段</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">脱离既定乐轨的三枚小小音符，再度合奏。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·旧城区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音来到旧城区，寻找惊栗乐队的线索。她通过邻居阿姨的情报网得知乐队曾在南苏广场演出，并决定前往调查。在旧城区的家中，余音遇到了司危和梅德。司危是来自艾达的机器人，因违规改装而与余音发生冲突。梅德是余音的挂名家庭服务型机器人，虽然余音否认自己是她的主人，但梅德依然坚持为余音服务。余音向梅德寻求帮助，希望利用她的社交能力找到惊栗乐队。梅德通过电话联系了一位熟人，得知乐队将在南苏广场再次演出。余音和梅德决定一同前往。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-5 交响</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">向虚空呼喊，回声相互叠加，早已忘了开口是为了什么。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·南苏广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音和梅德抵达南苏广场，试图与惊栗乐队接触。余音通过梅德的社交能力成功进入后台，但乐队成员对余音的突然出现表现出敌意。贝斯手认出余音是艾达的机动协理执行员，慌乱逃离。主唱和副吉他手试图阻止余音，双方发生冲突。在混乱中，余音发现乐队携带的行李袋中装满了存储盘，并试图夺回。然而，副吉他手突然袭击余音，导致她受伤。就在余音即将控制局面时，乐队的鼓手通过鼓点引发了强烈的情绪波动，余音陷入昏迷。在昏迷前，她抓住了一张写着惊栗乐队时间表的便签。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">（回忆开始）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音被带回艾达，接受自纠委员会的调查。委员会认为乔一的行为可能是感染了某种病毒程序，并通过声音传播。余音被要求提供乔一的异常行为报告，以帮助修复她。余音虽然感到困惑，但为了乔一和艾达的安全，她同意协助调查。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-6 倒带</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">止损、解构、重启。你好，新的我。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·南苏广场演出后台</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">惊栗乐队的成员们对贝斯手的逃跑行为感到不满，键盘手抱怨道这一闹会影响他们未来的演出机会。贝斯手解释自己是因为看到余音而慌乱，并提到维莱救了他们。维莱是乐队的新成员，穿着玩偶服，性格内向，几乎不开口说话。主唱从维莱那里得知，余音的目标并非贝斯手，而是他们手中的存储盘。乐队成员们开始检查存储盘的内容，发现里面不仅有复阶文字的信息归档框架蓝图，还有许多注释信息，像是日记或个人备忘录。主唱决定继续查看这些内容，试图理解余音为何如此执着于追回存储盘。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·旧城区快餐店</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音独自坐在快餐店的角落，沉浸在存储盘的编码工作中。她通过编写程序来整理信息，试图从森罗的混乱中找到秩序。余音回忆起自己刚到森罗时的迷茫与不安，以及她对乔一的思念。就在此时，白荆科技的研究员联系了她，告知她梅德（乔一的正式编号）也在森罗，并邀请她参与一项紧急任务。余音毫不犹豫地答应了，心中燃起了希望。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·旧城区信号基站</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音、监督和梅德前往旧城区的信号基站，处理居民强拆基站的事件。监督希望通过谈判和平解决问题，而梅德则被安排作为武力支援。余音的任务是通过她的超阅症排查损坏的电线，确保区域电压稳定。然而，梅德的行为让余音感到陌生，她发现梅德似乎失去了乔一的人格，变得冷漠且机械化。余音强制关闭了梅德的系统，并尝试修复她的脑模块，却发现梅德在19天前被格式化，从属协议也被清空。余音震惊之余，意识到乔一已经不复存在，她独自离开了现场。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-7 过载</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一枚小小齿轮的悲鸣。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·某儿童公园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音独自坐在儿童公园的滑梯上，沉浸在存储盘的编码工作中。监督找到了她，询问她为何会在这里。余音坦言自己只是在无目的地行走，最终来到了这座公园。监督安慰她，并提到自己曾试图帮助她融入森罗，但没想到会伤害到她。余音向监督坦白了自己对乔一的自责与痛苦，她意识到自己背叛了乔一，并抹除了她们之间的友谊。监督则指出，委员会利用余音的报告来围剿乔一，试图通过这种方式打击所有渴望脱轨的机器人。余音感到深深的内疚与无助，但监督鼓励她，告诉她希望依然存在，并邀请她一起面对未来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-8 混响</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">让这个世界安静，或是重新鼓噪。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·商场后台</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音在昏迷后醒来，发现监督已经赶到现场。监督为她进行了基础检查，并询问了事情的经过。余音提到惊栗乐队的能力可能影响了在场所有人的情绪。梅德突然上线，并透露自己签署了一份从属协议，但协议的另一方是乔一——一个在她脑模块中尖叫的女孩。梅德感到困惑，不知道自己是否成为了乔一的幽灵。余音意识到乔一的存在可能并未完全消失，而是以某种方式与梅德共存。监督决定协助余音追查惊栗乐队，并帮助梅德解决她的异常状态。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-9 降噪</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">世界的声音从这句呼唤开始衍生。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·百货广场</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">余音和监督来到百货广场，准备与R.E.D.合作抓捕惊栗乐队。余音为监督提供了稳定剂药贴，以防止受到惊栗乐队能力的影响。然而，惊栗乐队提前开始演出，并通过音乐放大了观众的情绪，导致现场陷入混乱。监督在帮助一名小女孩时，失去了自己的稳定剂，陷入了情感过载的状态。余音决定独自前往舞台，阻止惊栗乐队。在击败乐队后，余音迅速返回监督身边，将降噪耳机戴在监督的耳朵上，试图唤醒他/她。最终，监督恢复了意识，两人在混乱中找到了彼此。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 193-10 余音</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">还好余音未曾断绝。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗·白荆科技</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和方部长讨论余音的体检报告，发现她身体状况良好。监督意识到余音可能独自离开了，并猜测她去了儿童公园。监督找到余音，发现她正坐在滑梯旁，戴着耳机听放声电台的直播。余音将一只耳机递给监督，电台中播放的正是惊栗乐队的新歌。监督明白，余音已经找到了自己的方式去面对过去与未来。监督邀请余音一起回到白荆科技，余音默默地接受了邀请，两人一同离开公园。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:42:41', '2025-02-26 19:26:28', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (28, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/a8wvt4wp5ea6yduv7iji0wakwfm2onc_20250219094928A022.png', 11210815, '了不起的乌瑞亚 ＞', '幕间剧情', '监督，苏筱，晴雪，紫都，明月尘，巫昭（乌瑞亚）', '1121年', '森罗,乌瑞亚', '洛天依,奈默', '<p><span style=\"font-size: 14px;\">千钧的命运，书中不过薄薄一页。</span></p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-1 命运</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“监督，找到你了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗 血露薇</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年 秋季</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和苏筱来到血露薇，等待明先生。明先生出现后，提到安斯朵拉之书对监督的名字有反应，并表示时间即将闭合。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">突然，一页残卷从文书中飞出，监督的身体开始变得透明。明先生告诉监督，他/她需要拯救世界。监督在意识的模糊中听到明先生自我介绍为明月尘，随后失去了知觉。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-2 法则</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“大的吃小的，强的吃弱的，这是世界的法则。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督醒来，发现自己身处乌瑞亚的森林中，与一个名叫厄里斯的亡灵相遇。厄里斯告诉监督，亡灵通过吞噬其他亡灵来变强，而监督拒绝了这个法则。厄里斯试图吞噬监督，监督在危急时刻逃脱。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-3 巨龙</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“真好呀，今天是非比寻常的一天，今天是有飞天小猪的一天！”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督再次醒来，发现自己被困在同一天。他/她遇到了巨龙领主晴雪，晴雪告诉监督，只有龙才能闭合时间裂隙。监督意识到自己可能是龙，并试图寻找拯救世界的方法。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">在太阳祭典上，监督被误认为黑暗遗民，与辛西亚的小队发生冲突。最终，晴雪出面保护监督，承认他/她是巨龙一脉。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-4 熄灭</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“飞天小猪，真希望你能拯救世界呀。我的世界每天都要毁灭一次，我好伤心呀。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 太阳祭典</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与晴雪、紫都等人一起参加太阳祭典。莫丘利试图向监督推销商品，但太阳突然熄灭，亡灵军团开始侵袭。阿曼纳塔请求晴雪点燃新的太阳，但晴雪表示无能为力。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督意识到，乌瑞亚的世界每天都在重复毁灭，晴雪希望监督能够拯救这个世界。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-5 恶鬼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“什么明月尘，他是恶鬼王！”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 太阳祭典</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和晴雪在太阳祭典上遇到了亡灵军团的厄里斯，她声称找到了黑暗君主巫炤。巫炤出现后，质问监督关于明月尘的事，并表示明月尘必须亲自来求他。巫炤离开后，监督和晴雪决定去寻找始祖龙的气息，试图找到拯救世界的方法。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在战斗中，监督和晴雪击败了一群亡灵，发现明月尘竟然是乌瑞亚历史上的恶鬼王索尔伯德·冯·卢明贝尔格。晴雪提议通过明月尘找到安斯朵拉的冠冕，点燃新的太阳，拯救乌瑞亚。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-6 冠冕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我在下个今天等你。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 巨龙巢穴</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪告诉监督，安斯朵拉的冠冕可以点燃新的太阳，但冠冕已经失落多年。她们决定通过明月尘找到冠冕，并用他的心脏点燃太阳。尽管监督对此感到不安，但晴雪表示这是安斯朵拉的意志，也是拯救乌瑞亚的唯一方法。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和晴雪多次尝试与明月尘沟通，试图取得他的信任。她们尝试了各种方法，包括假装求助、提供美食、甚至“英雄救英雄”，但都未能成功。最终，监督决定直接告诉明月尘真相，说明亡灵大军将袭击他，并请求他帮助寻找冠冕。明月尘出乎意料地相信了监督的话，同意加入她们的冒险。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-7 自由</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“自由、自由就是有代价的！自由是要买的！”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 眠羊部落</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、晴雪和明月尘来到眠羊部落，寻找安斯朵拉的冠冕。他们遇到了眠羊族长赫勒，赫勒告诉他们冠冕的碎片在她手中，但她不愿意轻易交出。赫勒提到，眠羊一族被囚禁在围栏中，剪毛等于剪命，她希望通过延绵草增加羊毛产量，拯救族群。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘提出条件，要求赫勒派人手跟随他们去采摘延绵草。赫勒最终同意，但在途中遇到了她的哥哥佛里克索斯，眠羊的监管者。佛里克索斯指责赫勒背叛族群，赫勒在明月尘的鼓励下，拿起刀反抗，最终杀死了佛里克索斯，获得了自由。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-8 馈赠</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“亲爱的，你总需知道一句话：命运总会为馈赠标注价格。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 眠羊部落</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">赫勒将冠冕的碎片交给了晴雪，晴雪与安斯朵拉之书达成交易，用她的翅膀换取冠冕的完整。安斯朵拉之书警告晴雪，命运总会为馈赠标注价格，晴雪失去了她的翅膀。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">夜幕降临，巫炤出现，试图夺取冠冕。他与明月尘对峙，最终晴雪在战斗中受伤，监督决定牺牲自己以阻止巫炤。明月尘在关键时刻出手，成功阻止了巫炤，保护了冠冕。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-9 代价</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“如果孤独是自由的代价，那是我应付的代价。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督和晴雪在森林中醒来，晴雪的翅膀因与安斯朵拉之书的交易而消失。两人遇到勒普商人莫丘利，他假装受伤以骗取金币，但被监督识破。晴雪为了隐藏巨龙身份，一直使用扫帚伪装飞行。监督发现自己能操控飞行魔法，帮助晴雪让扫帚飞了起来。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督对继续寻找冠冕感到犹豫，担心晴雪会因此付出更多代价，尤其是安斯朵拉之书可能提出的苛刻条件。晴雪坚持认为拯救世界是值得的，并表示她愿意用其他方式换取冠冕，而非牺牲明月尘。两人决定继续寻找冠冕，同时尝试保护明月尘。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-10 死生</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“落幕之前，保持完美。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪在瓦尔浦斯剧团的演出中表演魔术，吸引了大量观众。监督发现冠冕碎片被剧团用作道具，试图与剧团长托德里克交易，但被拒绝。托德里克坚持剧团的传统，拒绝任何改变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">雪怪袭击了剧团，托德里克在保护剧团招牌时受伤。菲诺拉和费斯克对剧团的僵化传统感到不满，希望进行创新。明月尘用匕首威胁托德里克，最终导致剧团招牌断裂。菲诺拉和费斯克决定创作新的剧本，托德里克也逐渐接受了改变。晴雪鼓励他们分享真实情感，吸引了更多观众。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-11 内鬼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“有幸成为你的对手。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督因与安斯朵拉之书的交易失去了说话能力，只能发出“吱吱”声。晴雪决定继续寻找冠冕，尽管监督试图阻止她与明月尘接触，但晴雪坚持认为这是拯救世界的责任。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督发现明月尘与巫炤有联系，试图阻止晴雪与明月尘合作，但晴雪认为即使明月尘立场不明，他们仍需他的帮助。监督最终妥协，决定继续与明月尘合作，但保持警惕。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-12 坏龙</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“飞天小猪，有你真好。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪向监督解释了她寻找冠冕的原因：她是乌瑞亚最后一条巨龙，肩负着拯救世界的责任。监督理解了晴雪的决心，决定继续支持她。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘再次出现，监督发现他能听懂自己的“吱吱”声，但明月尘似乎对拯救世界并不关心，甚至对监督的“真情实感”表示嘲讽。监督开始怀疑明月尘的真实意图。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-13 利益</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“或许……为了利益结伴而行，迟早会为了利益分道扬镳吧。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 勒普营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 黄昏</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、晴雪和明月尘潜入勒普营地，试图找到冠冕碎片。他们发现勒普商会会长佛图娜意图通过冠冕成为乌瑞亚之王，而副会长席统则因反对她的计划而退出商会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘在搜寻冠冕碎片时，只找到了一箱金币。监督和晴雪感到失望，但明月尘似乎并不在意，反而对金币的收获感到满意。亡灵军团再次袭来，三人不得不准备应对新的战斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-14 朋友</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“只要和朋友们在一起……迟早，勒普商会还会东山再起！”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 勒普营地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">勒普营地被亡灵大军袭击，佛图娜和席统在混乱中陷入危险。晴雪和明月尘及时赶到，救下了他们。佛图娜意识到自己一直忽视了友谊的价值，决定将冠冕碎片交给明月尘以换取席统的生命。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">安斯朵拉之书再次出现，要求晴雪交出帽子作为代价，但晴雪拒绝了，因为帽子承载着她与乌乌和蛙蛙的友谊。安斯朵拉之书最终让步，允许晴雪保留帽子，但提醒她冠冕需要恶鬼之心才能点燃太阳。晴雪拒绝剜出明月尘的心脏，认为这是不道德的。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-15 好人</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“明月尘好像被我气坏了，‘咻——’一下就不见了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督恢复了说话能力，发现晴雪并没有剜出明月尘的心脏。明月尘承认自己的心脏不在心口，只有一片鳞片，剜出鳞片会让乌瑞亚堕入永夜。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪坚持认为明月尘是个好人，拒绝牺牲他。明月尘虽然否认自己是好人，但最终也放弃了让晴雪剜出心脏的计划。监督意识到明月尘并非真正的恶人，而是为了某种目的在引导他们。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-16 绑架</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我再说一遍，我是恶鬼王索尔伯德，我不是好人。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘承认自己一直在引导晴雪剜出他的心脏，但晴雪拒绝为了拯救世界而牺牲他人。明月尘最终放弃了计划，承认自己无法欺骗晴雪和监督。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪表示，她宁愿不成为王，也不愿牺牲他人。监督和晴雪决定寻找其他办法拯救世界，而不是依赖明月尘的心脏。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-17 救世</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“割舍一切，始成为王。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 辛西亚草原</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪、监督和明月尘来到辛西亚草原，发现勒普商会的佛图娜和莫丘利性格发生了巨大变化，变得更加友善和团结。晴雪意识到，她的牺牲（失去自由、欲望和友谊）换来了他人的幸福。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">紫都拒绝了晴雪的邀请，表示她必须履行保护辛西亚草原的责任。明月尘指出，责任与自由是相互矛盾的，晴雪则开始思考如何在不牺牲他人的情况下拯救世界。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-18 飞鸟</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“这个世界的自由是有限的，一些人得到，一些人就失去。我不过是唯恐天下不乱，偏要摆正自由的天平而已。“</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 眠羊部落</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、晴雪和明月尘来到眠羊部落，发现这里已从游牧民族转变为定居城市。赫勒和佛里克索斯误以为他们是偷羊毛的贼，双方发生冲突。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">冲突解决后，赫勒和佛里克索斯认出明月尘是当年赐予他们匕首的“圣者”，热情邀请他们参加宴会。晴雪逐渐意识到，明月尘并非真正的恶人，而是推动了乌瑞亚的自由与变革。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-19 叛徒</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我将无私献给我所爱者，我所爱者爱我；而你将无私献给所有人，所有人都只会恨你。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘回忆起自己被始祖巨龙击败并封印的往事，承认自己曾试图违逆安斯朵拉的意志，但最终失败。晴雪对巨龙一族的“光荣”感到质疑，认为明月尘才是真正的明君。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘表示自己已不再关心权力和公平，只希望晴雪能小心她的朋友，因为安斯朵拉的意志终将实现。晴雪则提议与明月尘一起尝试修复与巫炤的友谊，但明月尘拒绝了。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-20 末日</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我们要去明天了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 辛西亚草原</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督发现冠冕碎片失踪，三人赶到辛西亚草原，发现紫都和其他辛西亚族人被亡灵袭击致死。阿曼纳塔误以为是明月尘所为，双方发生冲突。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">厄里斯出现，承认是巫炤庇护亡灵来到此地，并拿走了冠冕。巫炤通过厄里斯传话，要求明月尘前往厄伯雪峰与他决斗，否则将毁掉冠冕。明月尘决定前往雪山，晴雪和监督意识到，这可能是他们离开时间裂隙、走向明天的唯一机会。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-21 加冕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“就算所有人都误解你，乌瑞亚为你加冕。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘、监督和晴雪来到卢明贝尔格庄园，明月尘解释了“大沉眠”事件的真相——他和巫炤为了追求力量，盗取了诸始祖的力量，导致他们陷入沉睡。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘告诉晴雪，要取回被封印的力量，必须剜出他心口的巨龙之鳞。晴雪犹豫不决，担心乌瑞亚会因此陷入永夜。明月尘鼓励晴雪做出无私的决定，并提醒她“割舍一切，始成为王”。晴雪最终决定剜出明月尘的鳞片，解除封印。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-22 心脏</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你可是恶鬼王索尔伯德，你什么都割舍得了，难道还怕我死了？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘与巫炤展开决斗，监督意识到自己可能是明月尘失落的心脏。监督决定牺牲自己，让明月尘恢复力量，拯救世界。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与明月尘告别，表示自己愿意成为明月尘的心脏，帮助他战胜巫炤。明月尘最终接受了监督的牺牲，准备全力以赴与巫炤决斗。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-23 凭我</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">自此始，恶鬼之心坐于冠冕，乌瑞亚再无新王。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘与巫炤的决斗以明月尘的胜利告终。巫炤承认明月尘的强大，并将冠冕归还。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪发现明月尘心口的鳞片并没有封印魔法，真相是明月尘自己封印了冠冕，以阻止安斯朵拉之书控制乌瑞亚。明月尘意识到自己并非被安斯朵拉剥夺了自由，而是自己选择了牺牲自由来保护乌瑞亚。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-24 破晓</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“旧王亲手将冠冕交给了我，我还需要你为我加冕吗？”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘意识到自己无法选择自由，因为他无法忽视乌瑞亚的命运。他决定让晴雪剜出他的心脏，点燃太阳，拯救世界。晴雪最终同意，并在剜出明月尘的心脏后，将冠冕的力量归还给世界，终结了安斯朵拉之书的控制。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">安斯朵拉之书试图阻止晴雪，但晴雪反抗并击败了她。晴雪宣布，从今以后，冠冕将不再属于任何人，力量将归还给众生，乌瑞亚进入了一个新的时代——共生时代。太阳重新点燃，乌瑞亚迎来了新的黎明。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-25 未来</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“晴雪，你找到我了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗 海临</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督从安斯朵拉之书的残页中回到了森罗，与苏筱和明月尘会合。明月尘解释，他追踪安斯朵拉的残页而来，确保监督安全返回。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督得知，明月尘的心脏因晴雪的举动而恢复，他并未真正死去。晴雪最终将冠冕的力量归还给世界，乌瑞亚进入了共生时代。监督与晴雪在海临重逢，晴雪终于找到了监督，两人再次相认。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-1 旅人</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我就是忽然很想看日出。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 辛西亚草原</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">巨龙晴雪在辛西亚草原的雨季中遇到了一位神秘的女孩帕拉丝。帕拉丝似乎迷失在黑暗中，只有晴雪的篝火能给她带来一丝光明。晴雪邀请帕拉丝一起休息，并得知她正在寻找回家的路。帕拉丝的家在“太阳脚下的村庄”，晴雪决定陪伴她前往。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-2 扑火</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“如果你再不放开我的朋友，我们恐怕就没办法做朋友了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 辛西亚草原</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">帕拉丝透露自己是亡灵，但她并不畏惧光明。她告诉晴雪，自己渴望回到阳光下的家，即使这意味着她可能会在阳光下消散。晴雪决定不再阻止她，而是支持她的选择。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-3 交界</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“不要紧的，最多不过是再死一次，我就可以回家了。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 辛西亚草原</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪和帕拉丝来到辛西亚的篝火晚会遗址，遇到了晴雪的旧友科洛米斯。科洛米斯热情地招待了她们，并重新点燃了篝火。帕拉丝在篝火旁感受到了温暖和友谊，但她仍然坚定地想要回到阳光下的家。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-4 朋友</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“别怕，咱们都是晴雪的朋友，所以咱们当然也是朋友啦。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪和帕拉丝继续她们的旅程，帕拉丝教晴雪用草绳编织手链。帕拉丝告诉晴雪，她的家在太阳脚下的村庄，她渴望回到那里。晴雪感受到帕拉丝对家的思念，并决定支持她的选择。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-5 结绳</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我们是朋友，真好。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪和帕拉丝来到守林人小屋，遇到了守林人奥内托。奥内托告诉她们，附近有一座慰灵碑，纪念多年前在一场灾难中消失的人们。帕拉丝认出了这里是她的家，并意识到自己的父母可能也在那场灾难中消失了。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-6 慰灵</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“你知道，我这一路就是要回家的。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">帕拉丝和晴雪来到慰灵碑前，帕拉丝决定在阳光下消散，回到她的家。晴雪虽然不舍，但尊重帕拉丝的选择，并决定陪伴她直到最后一刻。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-7 流星</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“不要紧。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 夜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">晴雪和帕拉丝在慰灵碑前等待黎明。帕拉丝告诉晴雪，她害怕自己消失后晴雪会孤独，但晴雪安慰她说，自己并不孤单，因为有乌乌和蛙蛙陪伴。两人在星空下默默等待黎明的到来。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-8 风晴</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我们下次，再一起旅行吧。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 德里亚德森林</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">巨龙时代 624年 第221个太阳日 昼</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">黎明到来，帕拉丝在阳光下逐渐消散。晴雪用魔法在天空中创造了绚丽的朝霞，作为送给帕拉丝的告别礼物。帕拉丝在消散前与晴雪约定，下次再一起旅行。晴雪将帕拉丝送给她的小花珍藏起来，默默告别了她的朋友。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-1 牢笼</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">面对阿玛辛一族……人类的堡垒，就是人类的牢笼。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">阿玛辛·卢明贝尔格通过特殊力量创造了阿玛辛一族，并带领他们扩张与掠夺。人类为自保筑起堡垒，却反被阿玛辛困在其中。人类勇者盖里格带领队伍奋起反抗，但力量悬殊，前路无望。盖里格的妹妹埃理为哥哥祈祷，希望他能平安归来。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-2 出路</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">这世上有通向光明的出路，亦有通向黑暗的出路。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 卢明贝尔格庄园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘为获取阿玛辛的力量，背叛了人类，将盖里格献给卢明贝尔格。盖里格被转化为阿玛辛，明月尘也通过杀死盖里格证明了自己的忠诚，获得了阿玛辛的力量。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>82-3 欲望</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">欲望使人无所不为，即使所为是要拒绝欲望本身。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 卢明贝尔格庄园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘通过克制食血的本能，逐渐适应了阳光。卢明贝尔格对他的能力表示赞赏，并让他成为自己的副手。明月尘在卢明贝尔格的考验中表现出色，获得了信任和权力。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-4 银匕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">除了阳光，还有什么能置阿玛辛们于死地？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 卢明贝尔德庄园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">卢明贝尔格将能够杀死阿玛辛的银匕首赐予明月尘，赋予他执掌本族生死的权力。明月尘在狩猎中表现出色，获得了卢明贝尔格的进一步信任。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-5 选择</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">道路一旦选定，就要不顾一切地向前走，绝不回头。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘帮助人类逃离了阿玛辛的牢笼，给予他们自由的选择。埃理认出了明月尘，希望他能一起离开，但明月尘拒绝了，选择留在雪山。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-6 敬黑暗</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">向黑暗致意，因为一天中最黑暗的时候，也最接近光明。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 卢明贝尔格庄园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘在幽夜蓝花田中悉心照料花朵，象征着他为阿玛辛一族带来的新生。卢明贝尔格逐渐消失，明月尘成为了阿玛辛一族的实际掌控者。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-7 日出</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在雪山之巅告别过去，在日出之地眺望未来。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘带领人类逃离了阿玛辛的牢笼，给予他们自由的选择。埃理认出了明月尘，希望他能一起离开，但明月尘拒绝了，选择留在雪山。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> 82-8 最初</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一个背水一战而又从长计议的计划，最初总显得格外疯狂</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">乌瑞亚 欧尔瑞德雪山</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">初醒时代 第???日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">明月尘回忆起与盖里格的计划，盖里格为了人类的自由牺牲了自己。人类最终在日出之地建立了新家园，勇者的故事被代代传颂。明月尘在瓦尔浦斯剧团的演出后，得知人类并未忘记他们的英雄。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-15 23:53:44', '2025-02-26 17:10:18', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (31, 0, NULL, 10210000, '苏卢帕克事变', '其他剧情', NULL, '1021年', '森罗', '洛天依', '<p style=\"line-height: 2;\">海临重型机械厂创建。</p><p style=\"line-height: 2;\">苏卢帕克事变，伊南纳与沙玛什分裂。</p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:40:14', '2025-02-28 09:59:38', '洛天依', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (32, 0, NULL, 10820000, '南半球事件', '其他剧情', NULL, '1082年', '森罗', '洛天依', '<p>战争蔓延至九旻海。西陵重工被委以重任，成为海隅理事会所主导的建设战时防御体系的主力军之一。</p><p><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:42:49', '2025-02-28 10:01:47', '洛天依', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (33, 0, NULL, 11050000, '莎拉塔尔', '角色故事', NULL, '1105年', '森罗', '洛天依', '<p>1105年，莎拉塔尔成为同调者，被伊南纳人尊称为战神。</p><p>1108年，莎拉塔尔遭到背刺，身体被用来制造克隆体，异核被用来执行造神计划。</p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:43:17', '2025-02-18 16:27:20', '洛天依', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (34, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/g4zhut1bd34cxhe70hvqmcf67of2cae_20250219095129A029.png', 11210209, '雪中春信 ＞', '幕间剧情', '十手卫,红玉,百里屠苏,监督,苏筱,唐路遥,狄砚,乐无异,昊苍,田偌,紫都,北洛,风清洛,无咎,岑缨,襄铃', '1121年2月9日', '森罗', '奈默', '<p><span style=\"font-size: 14px;\">灿烂的瞬间会在记忆中永远闪耀，直到蜷缩的心重新开始期待，直到往后每日皆是庆典。</span></p>', '<blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-0 故地，故人】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">R.E.D.实习警员百里屠苏将于今日结训归队，可飞机一落地海临，人就不见了踪影……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临机场 - 通讯中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫联系红玉，告知未能接到百里屠苏。红玉担心是否出了意外，但十手卫解释百里屠苏已经入境，并独自购买了前往银铃路的机场快列车票。十手卫请求红玉前往银铃路车站接人，并表示自己会尽快赶到。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·监督办公室 - 通讯中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫联系监督，请求他帮忙拖延时间，以便为归队的百里屠苏准备惊喜。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">银铃路地铁站</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏在地铁站被一名旅游推销员搭讪。推销员试图拉他加入雪终节三日游的旅行团，但百里屠苏冷漠拒绝，并表示自己不需要朋友。推销员不依不饶，最终惹恼了百里屠苏，他严厉警告推销员离开。推销员悻悻离去，并暗自嘲讽百里屠苏的孤僻。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">银铃路车站</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫与红玉赶到车站，发现了百里屠苏的身影。红玉高声呼唤他的名字，百里屠苏转身确认了他们的身份。他向R.E.D.正式报到，完成了归队。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏结束了在九旻基地的训练，独自返回海临。尽管他在途中表现出冷漠与孤僻，但十手卫与红玉的热情迎接为他的归队增添了一丝温暖。R.E.D.的成员们为他准备了惊喜，展现了团队之间的默契与关怀。百里屠苏的归队标志着新的任务与冒险即将开始。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-1 花车巡游始发站】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">十手卫将红玉与屠苏托付给了白荆科技，难道另有打算？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">义卖会现场</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">十手卫询问百里屠苏为何独自来到义卖会，百里屠苏解释是从群里得知这里有治安管理任务。红玉提醒他刚归队应休假调整，但百里屠苏表示不需要。十手卫调侃红玉的话从她口中说出显得幽默，红玉则强调百里屠苏与自己不同。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱与监督赶到现场，十手卫解释自己因临时有事无法陪同百里屠苏，便拜托白荆科技代为照顾。红玉提议百里屠苏跟随白荆科技的花车，以便认识更多合作伙伴。百里屠苏起初犹豫，但在红玉的劝说下同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉本打算去查看执勤安排，但十手卫早已与监督商量好，让她与百里屠苏一同登上白荆科技的花车。监督与苏筱以幽默的方式说服红玉放下工作，享受节日。红玉最终同意，百里屠苏也表示愿意参与。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在十手卫的安排下，红玉与百里屠苏登上了白荆科技的花车，准备参与雪终节的花车巡游。监督与苏筱的热情邀请为这场巡游增添了轻松愉快的氛围。红玉的妥协与百里屠苏的配合展现了团队之间的默契与关怀，也为接下来的节日活动拉开了序幕。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-2 好人？怪人？】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">众人聊着各地雪终节的过法，白荆科技参加海临义卖会的目的却引起了屠苏的疑问……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱询问百里屠苏是否曾在海临过雪终节，百里屠苏表示只在九旻基地经历过。监督推测他可能是军人出身，苏筱好奇基地如何过节。百里屠苏简单回答“禁枪一天”，苏筱追问更多细节，但百里屠苏保持沉默。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉接过话题，描述了九旻基地的雪终节传统：每人配发一枝雪终花，插在枪口，次日零点全体列队宣誓“捍卫和平”。苏筱感慨战争已远去，差点忘了雪终节原本是停战纪念日。红玉对比了九旻与海临的过节方式，强调海临的雪终节更加轻松愉快，并用“春风送暖入屠苏”形容节日氛围。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督介绍今年海临的雪终节活动是义卖会，所得款项将捐给相关组织。苏筱补充说明义卖会的运作方式：游客购买物品后，摊主会按比例赠送雪终币，晚上四家花车游街收集雪终币，最终统计获胜者。百里屠苏询问获胜的意义，监督解释获胜者会以十倍计的海隅点数捐款，但强调捐款过程透明，最终匿名给到相关组织。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏质疑这种活动的实际意义，认为除了损失经费外，参与者并无明显好处。监督幽默地回应：“好处大概是——让我觉得我是个好人？”百里屠苏对此沉默，红玉调侃白荆科技的行为“怪得很”，百里屠苏则淡淡回应：“和你们也差不多吧。”红玉追问“你们”指谁，百里屠苏回答：“你们R.E.D.”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了百里屠苏的军人背景与对节日的独特理解，也展现了红玉、监督与苏筱对雪终节的不同态度。百里屠苏的质疑与监督的幽默回应形成鲜明对比，而红玉的调侃则拉近了彼此的距离。这场对话不仅为节日增添了趣味，也为百里屠苏融入团队提供了契机。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-3 早起的鸟儿好几只】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">众人提前四小时来到会场，却发现已经有位对手更早抵达……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱抱怨收到的雪终币太少，红玉指出巡游还未正式开始，不必着急。监督解释，为了赢得比赛，他们需要提前行动，抢占先机。百里屠苏简洁地道：“先下手为强。”苏筱称赞他与监督的想法一致。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">意外相遇</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">正当苏筱得意于他们的“早起”策略时，紫都突然出现，打破了他们的计划。紫都是鹿路运输的大股东，原本声称因忙碌可能缺席，却意外出现在义卖会现场。监督与苏筱尴尬地承认自己“抢跑”，紫都则反讽他们“人不可貌相”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏注意到紫都手上的鹿路运输标识，并提到刚才有一辆同标志的机车路过。监督与苏筱意识到鹿路运输也在提前行动。苏筱突然发现前方出现北洛的身影，红玉则提醒紫都注意安全，暗示鹿路运输也在暗中行动。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">紫都狡辩称北洛只是在配送物流，否认抢跑行为。监督无奈地表示“我信了你的邪”，并下令加快速度，试图超过北洛。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了各方为了赢得雪终节义卖会的竞争，纷纷提前行动。紫都的突然出现与北洛的机车行动表明，鹿路运输也在暗中抢占先机。监督与苏筱的尴尬承认与紫都的狡辩为这场竞争增添了戏剧性。最终，白荆科技决定加速追赶，试图反超对手，展现了比赛的激烈与紧张。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-4 刹车！待避？】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">白荆科技的花车被老熟人别停，恐怕事出有妖……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督质问北洛为何别他们的车，苏筱也表达不满。北洛的出现让监督怀疑鹿路运输的花车已经到达。北洛询问红玉与百里屠苏的身份，两人自我介绍后，北洛提到十手卫曾联系唐路遥，但他被苏筱打断，强调“人要讲义气”。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">北洛的策略</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛解释自己为了讲义气，连夜加班并赶到现场。红玉追问具体情况，北洛却避而不答，反而频繁看表。苏筱指出北洛今天的行为反常，平时他从不讲废话。监督决定派人堵住北洛，防止他超车，但北洛表示时间已差不多。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">鹿路运输的胜利</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">就在此时，唐路遥的声音传来，鹿路运输的花车成功超车。苏筱惊呼，红玉与百里屠苏意识到北洛的行为是为了拖延时间，为鹿路运输争取优势。北洛淡然回应：“初次见面，见笑。”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛的出现与行为揭示了鹿路运输的策略：通过拖延时间，为花车争取超车机会。红玉与百里屠苏的敏锐观察与北洛的冷静应对形成了鲜明对比。最终，鹿路运输成功超车，展现了他们在竞争中的机智与团队协作。这场对话不仅为比赛增添了紧张感，也展现了各方在雪终节义卖会中的巧妙博弈。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游01-5 抢路，超车！】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">怎样赶超计分板榜首的鹿路运输，众人各有想法……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱发现鹿路运输的雪终币数量远超白荆科技，监督决定采取激进策略：“追上去，抢过来。”苏筱对此感到惊讶，但监督态度坚决。红玉提醒他们下手要轻，避免惹出乱子。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">行动与结果</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">经过一番行动，唐路遥无奈认输，将雪终币交给白荆科技。监督以胜利者的姿态表示感谢，但百里屠苏提出更极端的建议：“永绝后患。”红玉与唐路遥对此感到震惊，唐路遥更是惊呼：“永绝后患？！什么意思啊？！”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话展现了白荆科技在竞争中的果断与决心，监督的“抢”策略为团队赢得了胜利。然而，百里屠苏的极端建议为接下来的行动埋下了伏笔，暗示了可能的更大冲突。唐路遥的震惊与红玉的担忧为这场竞争增添了紧张感，也为故事的发展留下了悬念。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游02-0 乘客，一程旅伴】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">击败鹿路运输后，百里屠苏与众人的关系悄悄产生了微妙的变化……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">唐路遥愤怒地追赶白荆科技的花车，要求归还鹿角。众人哄笑，苏筱称赞百里屠苏的机智，将鹿路运输的花车装饰拔光，使其无法翻身。红玉调侃鹿路运输的花车被拔得光溜溜的，显得可怜。监督则得意地表示，百里屠苏的策略实现了“永绝后患”。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">重新认识</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提议与百里屠苏重新认识，这次不再以职务身份，而是以个人姓名结交朋友。百里屠苏对此感到困惑，红玉解释这是以朋友身份相交，而非警官身份。百里屠苏起初表示不需要朋友，但苏筱突然发现前方出现狄砚的身影，打断了对话。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚的出现</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱认出狄砚站在遥城四姓的队伍中，惊讶于每一家似乎都在抢跑。红玉注意到狄砚神色不对，暗示可能发生了意外情况。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话展现了白荆科技在花车巡游中的胜利与团队之间的默契。监督与苏筱以朋友身份与百里屠苏重新认识，为他的融入提供了契机。然而，狄砚的出现与异常神色为接下来的剧情埋下了伏笔，暗示了可能的变故与挑战。这场对话不仅为节日增添了趣味，也为故事的发展留下了悬念。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游02-1 废弃站台的滞留者】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">义卖会热火朝天进行之时，一位神秘人的出现却让众人停下了前进的脚步……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚焦急地询问监督与苏筱是否遇到闹事者，提到那些人脸上涂着油彩，像马戏团的小丑。红玉察觉到狄砚的异常，众人顺着她的视线望去，发现人群中有一个静止不动的小丑，脸上涂着油彩，目光直直地盯着他们。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏的反应</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏突然表现出强烈的反应，试图追赶小丑。监督阻止他，提议开车走大路去前方路口堵截。百里屠苏同意，但红玉与苏筱对他的反应感到困惑。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚的拒绝</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督邀请狄砚一同行动，但狄砚拒绝，表示已联系四哥，对方马上就到。红玉与监督对狄砚的行为产生怀疑，认为她可能试图支开他们。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">红玉的疑虑</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉指出雪终节义卖会的治安管理任务优先级很高，任何情况都应迅速响应，但至今未收到任何警报。监督推测狄砚可能想引导他们进入冷僻小路，影响雪终币的收集。苏筱也认为可能是反应过度，监督提醒她不要在别人面前说悄悄话，以免露馅。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了狄砚的异常行为与百里屠苏对小丑的强烈反应，为接下来的剧情埋下了伏笔。红玉与监督的怀疑为故事增添了悬疑色彩，暗示了可能存在的阴谋与变故。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游02-2 旧物，旧人？】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">听闻神秘人正在打听百里屠苏的下落，众人做了一个大胆的决定……</span><span style=\"font-size: 15px;\"> </span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉确认昊苍未接到任何报警，百里屠苏怀疑狄砚也未报警。监督推测狄砚可能像北洛一样试图拖延时间。乐无异突然出现，提到有人向他打听“眉心一点红痣的男人”，百里屠苏立刻联想到小丑。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">线索与怀疑</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱描述小丑的穿着，乐无异确认细节，红玉与监督对此产生怀疑。百里屠苏急切询问小丑的去向，乐无异指出方向，但监督怀疑他是否在欺骗他们。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏的决定</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏要求下车，监督提醒他车道禁止行人，建议开车一起行动。百里屠苏坚持此事与他人无关，红玉追问原因。百里屠苏透露“恩利都可能在找我”，红玉对此反应紧张。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">行动方向</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉邀请乐无异上车带路，乐无异表示未看清具体方向。百里屠苏再次要求下车，监督决定开车行动，苏筱询问具体方向。乐无异对众人的紧张感到困惑。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了百里屠苏对小丑的强烈反应与对“恩利都”的警惕，暗示了可能存在的危险与过往的纠葛。红玉与监督的怀疑为故事增添了悬疑色彩，乐无异的出现为寻找小丑提供了线索。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游02-3 花车进站，请勿接打电话】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">正当众人向风清洛打听神秘人下落之时，风清洛却做了件出人意料的事……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱与红玉确认一路未看到小丑，监督注意到前方路口的风清洛，提议询问他。苏筱呼唤风清洛，风清洛回应并提到他们来得很早。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">线索中断</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与苏筱描述小丑的特征，风清洛表示见过，但突然接到通讯申请，打断对话。风清洛与对方确认位置，并提到看到白荆科技的花车，暗示遥城的花车即将到来。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">遥城花车的出现</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚与乐无异的通讯接入，狄砚指挥乐无异超车，乐无异报告超过监督的花车。百里屠苏对此感到惊讶，红玉怀疑狄砚之前的举动是否真的在欺骗他们。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">行动与追赶</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提醒众人不要发呆，迅速追赶遥城的花车。苏筱附和，决定开车追上去问清楚。风清洛在后方为遥城花车加油，鼓励他们不要丢人。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了遥城花车的突然出现与狄砚的策略，为比赛增添了紧张感。风清洛的线索中断与狄砚的指挥行动为故事增添了悬疑色彩，暗示了可能的竞争与冲突。这场对话不仅推动了情节发展，也为后续的比赛结果与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游02-4 不讲武德！遥城号】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">众人正在为神秘人之事焦灼之时，趁火打劫的对手悄然而至……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚提议公平竞争，乐无异质疑白荆科技车头鹿角的来源。监督追问狄砚是否在拖延时间，乐无异犹豫不答。红玉询问小丑寻找百里屠苏是否属实，狄砚与乐无异开始倒数，准备偷袭。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">战斗与揭示</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">战斗结束后，监督追问真相，狄砚承认拖延时间，红玉指出他们的策略是将白荆科技从主干道支开。监督怀疑是老卫安排的计划，红玉追问另一只“鸟”是什么，狄砚暗示监督知晓内情。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">小丑的真相</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督确认狄砚未遇到闹事者，狄砚承认是唬人的。百里屠苏坚持自己没看错小丑，狄砚解释确实有小丑从她身边经过，她顺势演了一出戏。红玉对此表示怀疑，苏筱要求狄砚补偿。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">乐无异的线索</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">狄砚担心白荆科技会像对鹿路运输一样对待遥城的花车，乐无异突然提到他真的遇到一个小丑，向他打听眉心红痣的人。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了狄砚的策略与乐无异的线索，为故事增添了悬疑色彩。狄砚的承认与乐无异的坚持为接下来的剧情埋下了伏笔，暗示了可能存在的阴谋与真相。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-0 雪天路滑】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">事有蹊跷！正当疑惑之际，危险的信号却再度响起……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱质疑乐无异是否在装傻，提到老卫计划为百里屠苏举办接风会，但阴差阳错未能实现。红玉与监督认为老卫不会拿恩利都的事情开玩笑，苏筱询问百里屠苏是否确定看到小丑，乐无异确认有人向他打听百里屠苏。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">小丑的出现</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱突然看到人群中出现了几十个小丑，分布在整个义卖会中央区。乐无异再次确认询问他的人穿着类似的服装，但监督注意到这些小丑没有戴着药瓶。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">联系老卫</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉提议联系老卫确认情况，但通讯无人接听。乐无异注意到下雪，感叹雪终节又下雪了，与“雪终春来”的预期不符。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了老卫为百里屠苏举办接风会的计划与意外失败，同时出现了大量小丑的异常现象。红玉与监督的怀疑为故事增添了悬疑色彩，乐无异的线索与苏筱的观察为接下来的剧情埋下了伏笔。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-1 同行人】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">未来近在眼前，但旧日的噩梦却挡住了他往明天的去路……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱安慰红玉，认为老卫休假联系不上是正常的。红玉表示自己并非生气，而是担心恩利都的事情。她尝试定位老卫的信号，但失败了。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏的提议</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏提出要引开小丑，认为他们是在找他。红玉质疑他的计划，百里屠苏解释小丑认识十手卫和她。红玉坚决反对百里屠苏的牺牲计划，强调R.E.D.的使命与正义。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">R.E.D.的立场</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉回顾当年秘密行动，强调救百里屠苏是为了良心天理，而不是为了让他牺牲自己。她表示R.E.D.会妥善解决所有问题，不需要个人牺牲。百里屠苏坚持自己的决定，认为R.E.D.没有他也一样。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">监督的介入</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督提醒百里屠苏不要说伤人的话，苏筱与乐无异也劝解两人不要争吵。红玉重申R.E.D.的立场，认为献祭式的自我牺牲是对R.E.D.的羞辱。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍的消息</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍发来消息，已找到描述中的男子，并发送了定位，要求红玉按定位即刻前来。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话展现了百里屠苏与红玉在应对危机时的不同立场与价值观。红玉坚持R.E.D.的集体力量与正义使命，反对个人牺牲；百里屠苏则认为自己应该独自承担风险。昊苍的消息为接下来的行动提供了方向，为剧情的发展埋下了伏笔。这场对话不仅推动了情节发展，也深化了角色之间的情感与冲突。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-2 逼近】<br></strong></span><span style=\"font-size: 16px;\">到达通讯指示之地，众人终于达成一致的决定……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱发现小丑与昊苍、田偌在对峙，红玉决定带领百里屠苏前往查看。监督提醒红玉白荆科技与R.E.D.有合作协议，红玉同意大家一起行动。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">战斗与逃脱</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">田偌试图阻止小丑逃跑，监督决定追击。战斗后，小丑逃脱，百里屠苏提议继续追击，田偌表示自己去追。昊苍对小丑的反应感到奇怪，提到他们之前在与小丑对话。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">调查与线索</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍解释小丑的装扮来自一家服化店，都是来义卖会玩的散客，彼此不认识。红玉询问谁订了十几套服装，昊苍回答是鹿路运输的唐路遥。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了小丑的装扮来源与鹿路运输的关联，为故事增添了悬疑色彩。昊苍的调查为接下来的行动提供了线索，暗示了可能的阴谋与真相。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-3 痛击我方队友】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一番追击后，众人逼近了最终的真相……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉根据田偌的定位找到目标，昊苍发现小丑，监督与苏筱决定绕后。红玉倒数后，田偌试图阻止小丑逃跑，监督指挥苏筱拦截。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">战斗与揭示</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">战斗结束后，田偌发现之前与他们对话的并非这两个人。监督觉得有些熟悉，苏筱认出其中一人是唐路遥。唐路遥解释自己是在打工，苏筱惊讶于他的装扮变化。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">真相大白</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱猜测另一个人是北洛或风清洛，昊苍与百里屠苏也感到惊讶。红玉认出另一个人是老卫，十手卫笑着打招呼。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-4 故障排除，安全到站】</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">众人面对着真相有些不知所措，可不知不觉中，最后的对手却已悄然登场……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">唐路遥抱怨老卫被抓，红玉追问事情经过。十手卫解释是为百里屠苏办接风会，红玉澄清并非抓他。百里屠苏表示是自己看错了，红玉质疑十手卫的定位信号问题。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">真相揭示</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍与田偌确认只知接风会计划，唐路遥承认小丑是他安排的，目的是拖时间。监督质疑乐无异的证词，唐路遥解释是他向乐无异打听百里屠苏。苏筱感叹整个事件是场大乌龙。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏的疑虑</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏询问是否有人戴药瓶，唐路遥否认。百里屠苏承认自己看错了，红玉与监督安慰他，百里屠苏表示过去的事情已经过去，但监督提醒他过不去也没关系。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨的出现</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">岑缨突然出现，提到带了东西在车上。苏筱想起义卖会的比赛，监督询问博物学会是否来了。岑缨匆忙离开，十手卫试图阻止，苏筱惊讶于花车会飞，十手卫呼唤岑缨留下东西。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【花车巡游03-5 无止息地驶向未来】<br></strong></span><span style=\"font-size: 16px;\">博物学会以出人意料的方式出场，一场前所未有的战斗即将打响……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\"> 花车内 - 对话中</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱提议用飞的方式，监督决定放无人机逼博物学会下来。岑缨表示博物学会不会放弃，监督与苏筱决定要赢。战斗后，监督感谢博物学会送货上门，苏筱兴奋于收获。岑缨抱怨他们拆车，十手卫赶来要求留下蛋糕。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">冠军与庆祝</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">主持人宣布白荆科技为冠军，监督感谢百里屠苏的帮助。百里屠苏表示自己没做什么，苏筱提到他帮他们解决了鹿路运输。监督推测百里屠苏想保护R.E.D.，百里屠苏解释他们活着能保护更多人。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">生日惊喜</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉与众人欢迎百里屠苏正式加入R.E.D.，十手卫提到今天是他的生日，也是他离开实验室的日子。百里屠苏回忆起十手卫当年说的“生日快乐”。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">红玉的启示</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏询问红玉之前说的“不一样”是什么意思，红玉解释自己在R.E.D.成立前有过很多经历，而百里屠苏刚从实验室出来，值得拥有自己的使命与故乡。百里屠苏表示不需要时间，监督祝贺他。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">药瓶的线索</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏发现十手卫掉了药瓶，上面有青玉坛的标识。神秘人提到UR09-0710，百里屠苏认出他。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这场对话揭示了百里屠苏加入R.E.D.的意义与他对保护R.E.D.的决心。红玉的启示为百里屠苏的未来指明了方向，药瓶的线索为故事增添了悬疑色彩。这场对话不仅推动了情节发展，也为后续的冲突与揭示奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·红玉·引】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">摊主将收集册交给红玉，提到是一个熬夜的小伙子留下的。红玉感谢摊主。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·百里屠苏·引】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">陌生老者告诉红玉有几位小友为她准备了惊喜，红玉感谢老者。苏筱邀请百里屠苏一起逛义卖会，百里屠苏沉默。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【木头面具】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">百里屠苏被木头面具吸引，人偶解释面具是恩利都的仿制品，并推销面具。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【小泥人】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">店铺老板邀请苏筱捏泥人，苏筱拉上百里屠苏一起参与，百里屠苏沉默配合。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 16px;\"><strong>【巡游见闻·【铜制勋章】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">老者将红玉父亲的勋章交还，讲述红玉父亲救了他一家的故事。红玉感谢老者，并表示父亲一定很高兴勋章发挥了作用。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【陈旧枪套】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">皮具摊主认出红玉的枪套，提到有人让她帮忙清理。红玉感谢摊主，并猜测是谁安排的。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 16px;\"><strong>【巡游见闻·【芦花鸡崽】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">襄铃想套小鸡，苏筱与监督表示不擅长，百里屠苏接过任务并成功套中。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【纪念章】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛将快递交给百里屠苏，百里屠苏沉默签收。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【雪终花束】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">小孩将花束送给红玉，提到红玉在天隙事件中救了他的朋友。红玉感谢小孩并称赞雪终花。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·【彩色风铃】】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">陌生人认出红玉，提到她父母曾买过风铃帮助他家。红玉感谢陌生人并再买一串风铃送给朋友。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong>【巡游见闻·此心安处】</strong></span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱感叹晚上的活动很开心，十手卫发现街尽头有摊位。众人看到竹编高墙后的彩色气球，监督提议绕到正面看看。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">苏筱提议打气球，乐无异与北洛参与，无咎鼓励北洛。苏筱宣布白荆科技携R.E.D.出战，百里屠苏被推到前面。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">店铺老板惊慌，流星逃跑，十手卫指出老板弄虚作假。众人沉默，苏筱询问是否结束，监督认为这符合一天的调性，觉得挺好。</span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:47:51', '2025-02-25 15:53:37', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (35, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095157A030.png', 11191005, '万象·回忆', '幕间剧情', '监督,苏筱,曲观玄', '1119年10月05日', '森罗', '洛天依', '<p>现在回想起来……就是在这一天，我们第一次代表这个世界——</p><p>——成功触摸到“回廊”。</p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:51:48', '2025-02-28 09:58:56', '洛天依', '洛天依');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (36, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095207A031.png', 11210426, '万象 ＞', '幕间剧情', '监督', '1121年4月26日', '森罗', '洛天依,奈默', '<p>我触摸到了那个世界。</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"><strong> </strong></span><span style=\"font-size: 19px;\"><strong>R1-1 回廊漫巡</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">那一天，我们看到“流星”匀速坠落……</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">天隙禁区·S-0-1区</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1119-10-05 14:22</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督与团队在天隙禁区的S-0-1区进行“回廊漫巡”设备的铺设工作。设备调试完毕后，团队检查了电路、网络和X能辐射等各项指标，确认一切正常运行。然而，在准备启动深潜系统时，系统突然触发了多次警报，检测到天隙通道内出现了异常能量波动，疑似有异世同调者出现。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督通过“回廊漫巡”系统，意外看到了自己的记忆片段，回忆起1119年天隙禁区的设备铺设现场。这次实验的目的是通过深潜系统将操纵者的精神海域与天隙通道相连，从而探索通道内部的秘密。尽管遭遇了突发状况，团队在艾摩诃的指挥下迅速应对，最终成功解决了问题。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">实验成功后，白荆科技首次触摸到了“回廊”，为后续的探索奠定了基础。监督意识到，这次实验不仅是对天隙通道的探索，更是对精神海域与意识连接的突破。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次“回廊漫巡”实验标志着白荆科技在天隙通道探索中的重要突破。尽管遭遇了突发状况，但团队通过高效的协作成功完成了任务，为后续的深入研究奠定了基础。监督在实验过程中意外触发了自己的记忆片段，意识到“回廊漫巡”不仅是对天隙通道的探索，更是对精神海域与意识连接的突破。这次实验的成功为白荆科技未来的研究提供了重要的数据和经验。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-2 监测</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">唯没有异常，等于没有方向</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·高层医疗室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1119-10-06 18:35</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督前往医疗室查看体检报告，与医疗部部长方兰生进行了交谈。方兰生确认了监督的体检结果，显示其身体状况良好，精神共鸣和X辐射对其几乎没有影响。监督对此表示疑惑，方兰生解释这种现象仍在研究中，可能与身体素质有关，并提到遥城研究院和白汲的Scope对此也有相关研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督询问了与他一同从S-0-1区回来的同调者的情况。方兰生表示，他们的身体状况总体稳定，但“异化相性指数”在刚送来时曾出现大幅波动，虽然很快恢复正常，但仍需继续观察。方兰生推测，这与他们在天隙禁区的高辐射环境有关，同调者对X辐射的敏感度较高，容易受到影响。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督意识到，自己参与的那次“回廊漫巡”实验是唯一一次全员存活的实验，尽管实验风险极高，但最终成功完成了任务。然而，之后“回廊漫巡”项目被叫停，直到最近才重新启动。监督推测，老师曲观玄可能私下对系统进行了调整，以确保安全性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在谈话过程中，瞳突然到来，取走了监督的体检数据，并要求将其保密等级提升至最高。这一举动让监督感到疑惑，意识到自己的体检数据可能涉及某些未公开的机密信息。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次体检结果揭示了监督对X辐射的异常免疫能力，而与他一同参与实验的同调者则因高辐射环境出现了短暂的“异化相性指数”波动。监督回忆起“回廊漫巡”实验的细节，意识到实验的风险和重要性。瞳的突然出现和对体检数据的保密要求，暗示了监督的身体状况可能隐藏着更深层次的秘密，为后续的剧情埋下了伏笔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-3 绝缘体</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“对X辐射完全免疫的人”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·深潜实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 19:45 总部81层</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在“回廊漫巡”过程中接连两次看到过去的记忆片段，开始思考这种现象的原因。他推测，这可能与“深潜”系统捕捉到的“记忆烙痕”有关，但发现自己看到的并非完全属于自己的记忆，而是夹杂了许多视角之外的内容，仿佛被旁观者记录了下来。监督进一步猜测，这些记忆可能是事件中所有人的记忆合集，而自己作为亲历者触发了这些片段的回放。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">与此同时，监督注意到方兰生与瞳的对话，得知自己的体检数据被提升至最高保密等级。他决定有意识地追查这份体检报告背后的秘密，以解开其中的谜团。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在深潜实验室，监督回忆起老师曲观玄引咎辞职的那一天。瞳与曲观玄的对话揭示了“精神深潜”系统的危险性，即使是曲观玄这样的资深操作者也无法多次承受深入精神海域带来的意识损伤。瞳对监督能否使用“深潜”系统表示怀疑，认为监督作为非同调者，身体素质难以胜任。然而，曲观玄坚持让监督尝试，并表示即使失败，自己也会保护监督免受精神冲击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">曲观玄提到，监督的体检数据显示其对X辐射完全免疫，这在业内极为罕见。尽管研究尚未透彻，但曲观玄相信监督的能力，并决定将“回廊漫巡”的权限交给他。瞳对此持保留态度，认为仅凭现象无法证明监督的安全性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">曲观玄还提到，自己即将离开海临，并将白荆科技的事务交给监督处理。他相信监督能够应对未来的挑战，尽管这一决定在董事会和投资人中可能引发争议。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在“回廊漫巡”中看到的记忆片段引发了他对系统机制的深入思考，同时也让他意识到自己的体检数据可能隐藏着重要秘密。瞳与曲观玄的对话揭示了“精神深潜”系统的危险性以及监督在其中的特殊地位。曲观玄对监督的信任和托付，为后续剧情的发展埋下了伏笔，同时也暗示了监督将在白荆科技的未来中扮演重要角色。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-4 最高优先级</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一粒“坏种”。<br>它将生出霉菌，停止成长。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·深潜实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 20:51 总部81层</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瞳与曲观玄在深潜实验室进行了深入的对话。曲观玄透露，他即将在凌晨启程前往恩利都，并表示此行是为了“找人”。瞳对此表示疑惑，认为曲观玄似乎一直在寻找或防范某种东西。曲观玄承认，自己近年来越发感到迷茫，但天隙通道的开启已为森罗带来了不可逆转的混乱，他希望通过白荆科技尽可能地阻止这一进程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">曲观玄提到，尽管他即将离开，但对监督和小小的未来十分关注。他叮嘱瞳，在监督接手“精神深潜”和“回廊漫巡”的权限后，必须密切监控其身体状况，并加强相关的保密措施。曲观玄还提到，必要时可以召回温雪名，以确保研究人员的保密性。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瞳指出，曲观玄似乎将保护监督视为最高优先级，尽管在他担任首席执行官期间从未发生过危及人身安全的事件。曲观玄承认，无论监督是否是他要找的人，他都不希望监督成为有心人的目标，并请求瞳在监督需要时提供帮助。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瞳对曲观玄的身体状况表示担忧，认为其近年来衰弱得太快，不太正常。曲观玄对此不以为然，表示自己并不认为恩利都会是他的终点。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次对话揭示了曲观玄离开海临的真正目的——寻找某人，同时也暴露了他对监督的特殊关注和保护。曲观玄对森罗未来的担忧以及对监督的托付，暗示了监督将在未来的剧情中扮演重要角色。瞳对曲观玄身体状况的担忧，则为后续剧情的发展埋下了伏笔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>R1-5 世界的记忆</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“我们将与这个世界无限相关”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 16:26</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在“回廊漫巡”中逐渐意识到，自己可以通过系统看到与自己相关的“记忆”。这些记忆大多源自他的亲身经历，但也可能衍生出与他相关的其他场景，例如他曾长期停留的地方，如医疗部或深潜实验室。监督推测，“我”是触发这些记忆的引子，而当引子发生变化时，漫巡中的“回忆”也可能随之改变。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在“回廊”深处，监督注意到几颗明暗不一的光点，仿佛航标般指引着他前进的方向。Vein系统检测到这些光点的能量聚集，并为监督提供了方向选择，祝他研究顺利。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督对“回廊漫巡”机制的理解逐渐加深，意识到自己可以通过系统看到与自己相关的记忆。光点的出现为后续的探索提供了新的方向，暗示了“回廊”中可能隐藏着更多未知的秘密。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>R1-6 隐痛</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">回忆是一个不断撕裂伤口的过程。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局·R.E.D.</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 16:26</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍带着新同调者洛特斯来到R.E.D.进行身份登记，并见到了队长红玉。红玉对洛特斯的到来表示欢迎，并询问了他在海临医疗中心体检时的情况。昊苍提到，洛特斯在体检过程中因力量失控损坏了两台检测仪器，可能需要支付赔偿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉查看了洛特斯的检测报告，发现其“细胞同步率”为A级，“异化相性指数”高达S级，这意味着他对自身力量的控制能力极强。然而，洛特斯在体检时的表现却与数据不符，引发了红玉的疑虑。她推测，这可能是设备问题，也可能是洛特斯本身存在某种隐情。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍提到，若问题出在洛特斯身上，可能需要联系白荆科技或九旻基地进行进一步调查，甚至可能被列为“高危人员”。洛特斯对此表示拒绝，红玉则安抚他，表示事情仍有回旋余地。最终，红玉代表R.E.D.欢迎洛特斯的加入，并为他拍摄了证件照。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">洛特斯的加入为R.E.D.带来了新的力量，但其体检数据与表现的矛盾引发了红玉的警惕。这一事件暗示了洛特斯身上可能隐藏着不为人知的秘密，也为后续的剧情发展埋下了伏笔。红玉的细心与昊苍的直率形成了鲜明对比，展现了R.E.D.团队的多样性与专业性。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-7 畸变</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">UPD-0015UUUXXUU1-IV</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局·R.E.D.</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 16:26</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">洛特斯（现名祸烨莲）在R.E.D.完成同调者登记表的填写。红玉和昊苍协助他完成了表格，过程中昊苍提到祸烨莲的原名中带有“圣冕”的印记，建议他在森罗使用新名字。祸烨莲对此并未反对，但表现出对黎威尔过往的复杂情绪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在填写“原生世界”一栏时，祸烨莲提到一个未被记录的世界——一个处于永夜之中、充满疯狂与混乱的地方。红玉意识到这可能是一个新的异世界，立即让昊苍将信息同步给白荆科技，并预约了非常规体检项目。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉注意到祸烨莲的检测报告中存在多项异常数值，这些异常大多与他的原生世界相关。她表示，这些“与生俱来”的印记在异世界同调者中并不罕见，并请求祸烨莲在未来的联合行动中帮助照看昊苍，希望他们能尽早走出过往的阴影。祸烨莲对此表示感谢。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局外</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 17:05</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍与祸烨莲在警局外交谈。祸烨莲观察到昊苍在森罗的生活状态与过去截然不同，认为他变得“懈怠”。昊苍回忆起五年前与祸烨莲的初次见面，感叹时间带来的变化。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">昊苍提议，两人应放下彼此间的敌对情绪，尤其是为了抓捕弗雷的目标。祸烨莲回应，这种情绪并非他能完全控制，并提到那个永夜世界的环境会导致人的情绪、思想甚至样貌发生不可逆转的畸变。昊苍对此感到震惊，询问他为何不在警局内提及此事。祸烨莲反问昊苍是否会出卖他，暗示了对昊苍的信任危机。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">海临中央警局·R.E.D.</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">红玉结束与白荆科技的通话，注意到办公室内的盆栽“金翠玉红”突然长高，似乎暗示了某种异常现象的发生。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">祸烨莲的加入为R.E.D.带来了新的信息，揭示了一个未被记录的永夜世界。红玉的细心与昊苍的直率再次展现了R.E.D.团队的多样性。祸烨莲与昊苍的对话暴露了两人之间的复杂关系，尤其是祸烨莲对昊苍的信任危机。盆栽的异常生长则为后续剧情埋下了伏笔，暗示了某种未知力量的介入。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-8 筛查</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">“山雨欲来。”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·空中花园</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 17:35</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">阳铃作为医疗部的新人，偶然发现白荆科技的同调者们正在排队进行“同调者状态季度评估”（俗称“期末考”）。她对此感到紧张，因为她的异化相性指数仅为D级，担心自己会被送回九旻基地。霍冉和狄砚试图安慰她，但阳铃的情绪依然低落。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">瓦卡莎在一旁打瞌睡，霍冉则调侃艾摩诃的异常情绪，推测他可能是因为β小队的外勤任务失败而心情不佳。狄砚提到，艾摩诃的情绪可能与克里斯汀的去世有关，但霍冉认为夜摩的信仰使他们对死亡持有不同态度，不会因此感到悲伤。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">阳铃对此感到困惑，认为不会因为亲近的人去世而伤心是一种奇怪的风俗。霍冉则鼓励她多了解不同世界的文化，逐渐适应这些差异。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次“期末考”的提前引发了同调者们的情绪波动，尤其是阳铃的紧张和艾摩诃的低落。霍冉和狄砚的对话揭示了不同世界文化的差异，同时也暗示了艾摩诃内心深处的隐痛。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-9 克图尔特</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">对于那个地方，不看，不查——装作不知道才是最好。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·监督办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-26 17:44</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督召集了方兰生、瞳、苏筱等人，与R.E.D.的昊苍和祸烨莲进行远程会议，讨论祸烨莲的体检报告和异常数值。苏筱简要介绍了祸烨莲的情况，提到天隙通道可能连接了一个新的世界，暂定编号为“15”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">祸烨莲解释了自己的异化相性指数的变化，提到在穿过天隙通道时曾多次出现失控现象，尤其是在“15号世界”期间，失控感持续存在并逐渐加剧。瞳对此表现出浓厚兴趣，推测“15号世界”的环境可能导致同调者的异化相性指数出现不可逆的变化。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">方兰生提到，之前的同调者普查可能存在漏洞，尤其是“原生世界”一栏的信息可能被有意隐瞒。监督决定通过Vein系统对现有数据库中的同调者进行比对分析，寻找与祸烨莲相似的异常特征。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最终，祸烨莲提议将“15号世界”命名为“克图尔特”，因其境内有一座名为“克图尔特”的高塔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次会议揭示了“15号世界”的特殊性，以及它对同调者异化相性指数的潜在影响。祸烨莲的经历为白荆科技的研究提供了重要线索，同时也暗示了未来可能面临的挑战。监督通过Vein系统的比对分析，试图找出更多与“15号世界”相关的同调者，为后续的行动奠定了基础。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>R1-10 违背定律</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">我们是叛逆者，是疯子，是怪物。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">剧院·Binary Star休息室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-27 22:31</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">芙蕖和司危在休息室讨论“同调者季度数值审查”（俗称“期末考”）的通知。司威对此不屑一顾，认为自己作为机器人，数值不会改变，拒绝参加检测。芙蕖则认为配合调查是对他人的尊重，尽管她也不喜欢被要求的感觉。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">两人交谈时，一名闯入者突然进入休息室，手持反X能源和反同调者的宣传海报，揭露了芙蕖和司危的同调者身份，并指责她们隐瞒身份举办公开活动。司危愤怒地捏碎了闯入者的通讯设备，险些引发冲突。R.E.D.的十手卫和田偌及时赶到，控制了局面，并通知芙蕖和司危前往白荆科技配合调查。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次事件揭示了森罗社会中对同调者的偏见和敌意，尤其是反X能源和反同调者运动的兴起。芙蕖和司危的对话展现了她们对自身身份的复杂态度，同时为后续剧情中同调者与社会的冲突埋下了伏笔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"font-size: 19px;\"><strong>R1-11 高歌</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">我们信奉太阳，我们赞美死亡。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技·停机坪</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-29 06:34</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">艾摩诃和瓦卡莎在停机坪等待送行克里斯汀的队伍。艾摩诃因克里斯汀的去世感到内疚和悲伤，瓦卡莎试图开导他，提到夜摩的信仰和战士的归宿。她强调，夜摩人信奉死亡，但也从中汲取勇气，面对未来的战斗。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">在飞行器上，监督回忆起克里斯汀的遗愿，决定将他安葬在临滨公墓，一个可以俯瞰大海的地方。抵达墓地后，艾摩诃因情绪低落选择留在墙边，瓦卡莎陪他聊天，试图帮他走出阴霾。她提到夜摩的葬歌不仅仅是哀悼，更是一种战歌，象征着夜摩人的勇气和抗争精神。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">最终，艾摩诃和瓦卡莎在墓地旁唱起了夜摩的葬歌，监督和苏筱听到后感到震撼。监督意识到，这首歌不仅是送别克里斯汀的方式，更是夜摩人对生命的礼赞。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次送行仪式展现了夜摩文化的深刻内涵，尤其是他们对死亡的态度和战士的归宿。艾摩诃的挣扎和瓦卡莎的开导揭示了夜摩人内心的矛盾与信仰的力量。葬歌的旋律不仅是对克里斯汀的告别，也是对夜摩人抗争精神的传承，为后续剧情中夜摩文化的进一步探索埋下了伏笔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R1-12 新的起点</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">我触摸到了那个世界。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121-04-29</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在“回廊漫巡”中回忆起近期对同调者的调查，意识到那些筛查出的“相似数据”更像是因相似经历而产生的巧合，而非必然联系。他询问Vein系统关于历次同调者普查档案的比对结果，Vein最终检测到一名高度匹配的同调者——厉小棠。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">厉小棠的档案显示，她曾多次因精神状态异常和异化相性指数不稳定被检测为疑似同调者，但因失踪和逃逸被除名。最后一次记录显示，她因在蒂尔莫当街伤人被送往“乐园岛”收监。监督决定结束此次漫巡，并将这一情况同步给相关人员。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">然而，就在监督准备撤离时，Vein系统检测到异常能量波动，指数迅速攀升至警戒值。监督试图切断漫巡连接，却被一道刺眼的金色光束吸引，进入了一个陌生的地方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这里充满了古老的建筑、机械、齿轮和复杂的回路花纹，仿佛时间被按下了暂停键。监督意识到，这里并非森罗，也非克图尔特。就在他试图寻找线索时，一阵规律的脚步声响起，一个陌生的声音问道：“尊敬的先生，打扰了——请问，你对我的玩具做了什么？”</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次漫巡揭示了厉小棠的失踪事件，为后续的调查提供了新的线索。异常能量波动的出现和陌生空间的闯入，暗示了“回廊”中可能隐藏着更多未知的秘密。陌生人的出现则为剧情增添了新的悬念，预示着监督将面临更大的挑战和谜团。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:55:20', '2025-02-25 15:59:14', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (37, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/qv6voumig0difjs9zxwv05vi0ftmoew_20250219095213A032.png', 11210505, '蜃楼 ＞', '幕间剧情', '监督', '1121年5月5日', '森罗', '洛天依,奈默', '<p>未来，我将与我同谋</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-1 启程</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">目的地：特默里恩</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技总部80层，监督办公室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年5月5日，12:27</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督召见了刘兄和凤无梦，希望他们帮忙确认自己在漫巡中见到的场景是否属于特默里恩。刘兄和凤无梦仔细查看了资料，刘兄认为虽然场景特征与特默里恩相似，但特默里恩并没有完全静默的地方。凤无梦则提到，类似的建筑可能出现在阿洛汀的远郊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 琉辛突然闯入，试图查看资料，但被凤无梦巧妙地阻止。凤无梦解释，琉辛一直想回家，但在确认一些事情之前还不能回去。监督决定暂时不将资料内容告知琉辛，并邀请刘兄和凤无梦前往深潜实验室进行新的漫巡试验。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次对话揭示了琉辛和凤无梦在特默里恩的过往，暗示了她们之间可能存在某种未解决的矛盾。监督对漫巡中见到的场景的疑惑，为后续的探索提供了新的线索。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-2 落点</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">埋在这里的人，不会是孤魂野鬼</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技总部81层，深潜实验室</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年5月5日，12:38</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督、刘兄和凤无梦进入回廊漫巡，监督提醒他们跟紧自己。然而，意识回笼后，监督发现自己被关在一个木箱中，四周一片漆黑。经过一番挣扎，他发现自己竟然从一座坟墓中爬出。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 监督检查了自己的着装，发现心口位置有破损的痕迹，但皮肉完好无损。他环顾四周，发现墓园被精心维护，墓碑上刻着“监督”的名字。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次漫巡的落点异常诡异，监督发现自己竟然身处一座坟墓中，墓碑上刻着他的名字。这一场景为后续剧情增添了神秘感，暗示了监督的身份或命运可能与这个陌生世界有着深刻的联系。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-3 选择</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">选择决定命运，好像是这个道理</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">墓园</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督在异世界的墓园中发现了自己的坟墓，并从坟墓中爬出。守墓少年质问他的身份，监督试图解释自己是来祭拜朋友，但少年并不相信，认为他是来盗墓的。监督面临两个选择：假装离开或听话离开。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> # 选项：假装离开</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定假装离开，暗中折返，观察墓园的情况。他目睹了守墓少年重新填平坟墓，随后一个被称为“老板”的女人和她的手下出现，挖开坟墓发现里面是空的。老板似乎早已知道监督的存在，并暗示他已经暴露。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> # 选项：听话离开</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督决定听从守墓少年的话，离开墓园。他来到附近的城镇，遇到一位老人，老人激动地拥抱他，并询问他为何失踪多日。监督无法回答，老人则开始讲述他采集皮埃尔龙树汁的经历，完全忽略了之前的话题。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次选择揭示了监督在异世界的处境，无论是假装离开还是听话离开，都暗示了他在这个世界的身份和经历并不简单。老板的出现和老人的热情拥抱，为后续剧情的发展埋下了伏笔。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-4 好奇心</strong></span><span style=\"font-size: 15px;\"><br>一场不太成功的“穿越”，和一次不太成功的“重生”</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">墓园</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督的好奇心驱使他选择留下来观察墓园的情况。他目睹了守墓少年重新填平坟墓，随后一个被称为“老板”的女人和她的手下出现，挖开坟墓发现里面是空的。老板似乎早已知道监督的存在，并暗示他已经暴露。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次观察揭示了监督在异世界的身份可能涉及某种阴谋或秘密任务。老板的出现和她的言行，为后续剧情中的冲突和探索提供了新的线索。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-5 危机</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">我有一招秘法，可以轻松化解危机——</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> #选项：假装离开</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督被斯凯拉·劳伦斯带到了她的人偶店。斯凯拉自称是“普普通通的人偶店老板”，但她显然不简单。她质问监督最近接的任务和找到的东西，并威胁要将他变成她的黑兔子。监督意识到自己无法对抗她的力量，决定结束漫巡。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> #选项：听话离开</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督来到“翡翠公爵”阿洛汀分店，遇到药师伊诺克。伊诺克通过药物控制了监督，并要他找回被偷走的东西。监督意识到自己无法完成任务，决定结束漫巡。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">无论是被斯凯拉威胁还是被伊诺克控制，监督都面临了无法解决的危机。他选择结束漫巡，避免了进一步的冲突和危险。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-6 苏醒</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">可以触及的彼岸，可以改变的未来</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\"> </span><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">白荆科技总部81层，深潜实验室</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">监督从漫巡中苏醒，刘兄和凤无梦告诉他，他在漫巡中途突然消失，导致他们被弹出。监督意识到，他在特默里恩的经历并非回忆，而是正在发生的事件。他提出了一个大胆的想法：通过天隙通道，主动干预另一端的事件。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> 总结：</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">这次漫巡的经历让监督意识到，他可以通过天隙通道介入其他世界的事件。这为后续的探索和行动提供了新的思路和可能性。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> R2-6 另一个我</strong></span><span style=\"font-size: 15px;\"><br>未来，我将与我同谋</span></blockquote><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 监督多次尝试再次进入特默里恩，但都失败了。他推测，这可能是因为特默里恩的“他”已经死亡，导致他的意识无法寄存。然而，当他再次遇到异常能量波动时，他成功进入了特默里恩，并发现自己的意识寄居在另一个“自己”的身体中。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\"> 另一个“监督”质问他的身份，并告诉他，他之前的消失给自己带来了麻烦。两人达成了暂时的共识，决定一起应对即将到来的追兵。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\">总结：</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">这次相遇揭示了监督在特默里恩的身份和经历，暗示了他在这个世界的行动可能对另一个“自己”产生了重大影响。两人的合作为后续剧情的发展埋下了伏笔。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-17 11:57:07', '2025-02-26 18:23:20', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (38, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/tsg90f6bgo04f0pbtfnjp3iat8j2wbv_20250219094405A017.png', 20440702, 'JOYRIDE ＞', '幕间剧情', '北洛', '2044年7月2日', '黑曜', '洛天依,奈默', '<p>说出口前，我写下了遗言，也有了遗物</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-1 cough·咳嗽</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">像一场旷日持久的感冒，症状只是咳嗽。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·虹平路宜景园3-2-2</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月2日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在家中独自一人，面对母亲的去世和父亲的冷漠，内心充满了矛盾和痛苦。他与双胞胎哥哥玄戈的关系也因父亲的职业选择而变得紧张。北洛在深夜离家出走，偶然间遇到了一位自称是业余赛车手的司机路远。路远带着北洛在钧天市的夜晚兜风，两人在短暂的交流中建立了某种默契。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-2 lachrymal·泪腺</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">迎着风和阳光，眼泪就可以变成合理的自我保护机制。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·天阿山盘山公路</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月2日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">路远带着北洛来到了天阿山的盘山公路，两人在山顶观看了日出。路远向北洛讲述了自己成为赛车手的原因，并鼓励北洛追求自己喜欢的事物。北洛在日出时分向路远透露了母亲去世的真相，路远则以自己的经历安慰了北洛。两人在日出后分别，北洛回到了家中。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-3 blush·脸红</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">面红耳赤，可以形容吵架，也可以形容喜爱。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天师大附中初中部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月4日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在学校的生活依然平淡，但与玄戈的关系依然紧张。放学后，北洛来到了路远的修车店，偶然间得知路远曾经是一名职业赛车手。路远邀请北洛参加即将举行的赛车比赛，北洛犹豫后决定接受邀请。与此同时，玄戈也发现了北洛与路远的联系，并对路远的背景产生了怀疑。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-4 insomnia·失眠症</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">有些失眠，只是因为有话说却不知道怎么开口。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·虹平路宜景园3-2-2</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月4日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在家中整理母亲的遗物，回忆起母亲生前的点点滴滴。他与玄戈的对话再次陷入了僵局，两人对未来的选择产生了分歧。北洛在深夜无法入睡，决定再次离家出走，前往路远的修车店。与此同时，玄戈也开始调查路远的背景，试图了解北洛与路远之间的关系。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-5 adrenaline·肾上腺素</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">肾上腺素飙升，就是信号灯。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·天阿山盘山公路</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月11日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛跟随路远参加了在天阿山盘山公路举行的赛车比赛。比赛中，路远凭借出色的驾驶技术赢得了冠军，北洛作为领航员也体验到了赛车的刺激与快感。比赛结束后，路远向北洛透露了自己组建车队的计划，并邀请北洛加入。北洛在比赛中找到了自己的兴趣所在，决定追随路远的脚步。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-6 choc·巧克力</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">一碗面，一罐饮料，少盐，要多少钱？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天师大附中初中部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月12日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在学校的生活依然平淡，但与玄戈的关系依然紧张。放学后，北洛来到了路远的修车店，偶然间得知路远曾经是一名职业赛车手。路远邀请北洛参加即将举行的赛车比赛，北洛犹豫后决定接受邀请。与此同时，玄戈也发现了北洛与路远的联系，并对路远的背景产生了怀疑。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-7 cola·可乐</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">得想办法整辆车！</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 PUNK ROSY修理店</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月14日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在路远的修车店中学习赛车知识，并与车队的其他成员逐渐熟悉。路远向北洛讲述了赛车队的名字“PUNK ROSY”的由来，并鼓励北洛在赛车中找到自己的人生方向。北洛在修车店中感受到了前所未有的归属感，决定将赛车作为自己未来的追求。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-8 soda·苏打水</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">无色无味，但又追求刺激。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·天阿山盘山公路</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2044年7月16日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛与路远再次来到天阿山盘山公路，路远向北洛讲述了自己成为赛车手的心路历程，并鼓励北洛勇敢追求自己的梦想。北洛在路远的引导下，逐渐找到了自己的人生方向。两人在盘山公路上度过了愉快的时光，北洛对未来的生活充满了期待。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-9 spore·孢子</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">像不安，会扩散。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天师大附中高中部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2047年7月16日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在高中生活中逐渐找到了自己的兴趣所在，决定将赛车作为自己未来的追求。他与玄戈的关系依然紧张，但北洛已经不再在意玄戈的看法。北洛在路远的引导下，逐渐找到了自己的人生方向，并决定追随路远的脚步，成为一名赛车手。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-10 fever·发烧</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">整理下抽屉，除了感冒药，还有什么？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·虹平路宜景园3-2-2</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年3月29日</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在家中发高烧，玄戈照顾他并试图说服他放弃赛车的梦想。北洛在发烧中回忆起与路远的点点滴滴，坚定了自己追求赛车的决心。与此同时，玄戈也开始意识到北洛的选择并非一时冲动，而是经过深思熟虑的结果。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-11 hickey·吻痕</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">有些痕迹带不走，来不及</span><span style=\"font-size: 15px;\">。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·虹平路宜景园3-2-2</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年4月3日17:30</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">玄戈在家中照顾高烧不退的爸爸和弟弟北洛，记录着他们的体温变化。家中断水断电，玄戈独自守候了三天，手里紧握着爸爸留下的手枪，警惕着外界的混乱。邻居敲门求助，玄戈谨慎地开门递过一瓶水，随后关上门继续守护家人。窗外迷雾弥漫，鸽群盘旋，城市陷入混乱。玄戈感受到异常的震动，时钟停在了13:46，紧接着北洛昏倒。玄戈意识到事态的严重性，心中生出了不祥的预感。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 钧天市·虹平路宜景园3-2-2</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年4月5日17:16</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">玄戈在客厅中醒来，发现爸爸已经变成了“怪物”。在挣扎中，玄戈被迫开枪，结束了爸爸的痛苦。玄戈冷静地处理了爸爸的尸体，将房门反锁。路远来到家中，接走了玄戈和北洛。路远透露自己也曾被迫杀死自己的爱车“Rosy”，并鼓励玄戈坚强面对。玄戈和北洛被带到北麓原的PUNK ROSY补给点，路远将车钥匙交给北洛，随后独自驾车离开，最终在盘山路上结束了自己的生命。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 天阿山 北麓原 PUNK ROSY补给站</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年8月13日5:19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛骑着新机车“加冕者”回到补给点，玄戈提出成立基地的想法，并透露自己觉醒了异能——能够吞噬“安娜”的力量。玄戈认为，建立基地是维持末世秩序的必要选择，并将基地命名为“无争号”。北洛虽然对玄戈的决定有所疑虑，但最终选择支持。两人在晨雾中短暂交流，玄戈祝北洛生日快乐，北洛也回应了玄戈的祝福。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 无争号幸存者基地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2051年12月15日9:57</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛接任无争号总指挥，整理玄戈的遗物时发现了一张撕毁的照片和玄戈留下的警官证。副手交给北洛一个金属容器，里面是玄戈的部分遗体，玄戈生前与一叶城城主旒珠达成协议，死后将遗体提供给一叶城进行研究。北洛决定亲自将容器送往一叶城，途中路过曾经的PUNK ROSY修理店，回忆起过去的种种。北洛遇到一个幸存的小孩，决定带她一起前往一叶城。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗 海临·枫丹区大学城</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年7月12日17:21</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在鹿路运输完成了一天的工作，收到黑曜老熟人的消息和一个小孩送来的花束。北洛骑着电驴回到公司，与同事们打闹闲聊，享受着平凡而温馨的日常。唐路遥将车钥匙交给北洛，周末让他自由使用。北洛感受到家的温暖，心中感慨自己终于找到了新的归处。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-12 birth·初生</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">说出口前，我写下了遗言，也有了遗物。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 天阿山 北麓原 PUNK ROSY补给站</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2049年8月13日5:19</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">玄戈在晨雾中等待北洛归来，提出成立基地的想法，并透露自己觉醒了吞噬“安娜”的异能。玄戈认为，建立基地是维持末世秩序的必要选择，并将基地命名为“无争号”。北洛虽然对玄戈的决定有所疑虑，但最终选择支持。两人在晨雾中短暂交流，玄戈祝北洛生日快乐，北洛也回应了玄戈的祝福。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 无争号幸存者基地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2051年12月15日9:57</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛接任无争号总指挥，整理玄戈的遗物时发现了一张撕毁的照片和玄戈留下的警官证。副手交给北洛一个金属容器，里面是玄戈的部分遗体，玄戈生前与一叶城城主旒珠达成协议，死后将遗体提供给一叶城进行研究。北洛决定亲自将容器送往一叶城，途中路过曾经的PUNK ROSY修理店，回忆起过去的种种。北洛遇到一个幸存的小孩，决定带她一起前往一叶城。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗 海临·枫丹区大学城</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年7月12日17:21</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在鹿路运输完成了一天的工作，收到黑曜老熟人的消息和一个小孩送来的花束。北洛骑着电驴回到公司，与同事们打闹闲聊，享受着平凡而温馨的日常。唐路遥将车钥匙交给北洛，周末让他自由使用。北洛感受到家的温暖，心中感慨自己终于找到了新的归处。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-13 joyride·兜风</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">旷野或是盘山路，去兜风么？</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 无争号幸存者基地</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜时2051年12月15日9:57</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛接任无争号总指挥，整理玄戈的遗物时发现了一张撕毁的照片和玄戈留下的警官证。副手交给北洛一个金属容器，里面是玄戈的部分遗体，玄戈生前与一叶城城主旒珠达成协议，死后将遗体提供给一叶城进行研究。北洛决定亲自将容器送往一叶城，途中路过曾经的PUNK ROSY修理店，回忆起过去的种种。北洛遇到一个幸存的小孩，决定带她一起前往一叶城。</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗 海临·枫丹区大学城</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">森罗历1121年7月12日17:21</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">北洛在鹿路运输完成了一天的工作，收到黑曜老熟人的消息和一个小孩送来的花束。北洛骑着电驴回到公司，与同事们打闹闲聊，享受着平凡而温馨的日常。唐路遥将车钥匙交给北洛，周末让他自由使用。北洛感受到家的温暖，心中感慨自己终于找到了新的归处。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><br></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-19 09:45:04', '2025-02-26 19:27:06', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (39, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/5tbne9qsl63z130we7fr1h2msor2soq_20250219094558A018.png', 20510801, '无价废物 ＞', '幕间剧情', '崔远之', '2051年8月1日', '黑曜', '洛天依,奈默', '<p>在黑曜，死亡是那么轻。即便它落在你的身上，你都无法注意它的重量。</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-1 暗夜</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">生命没有价值的地方，死亡却代价高昂。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">黑曜 区域JT-E-6</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">钧天科技园区曾是繁华的创业中心，如今却成为行尸密度最高的区域之一。天机清扫队在此执行任务，队长叶秉谦带领队员崔远之、易虚舟等人，利用特制戒指的闪光和精准的枪术，迅速清理了大批行尸。崔远之负责感知并处理行尸的“核”，而易虚舟则使用能力探查周围环境，确保任务顺利完成。尽管任务危险重重，三人默契配合，最终成功清理了区域内的行尸，并意外发现了一箱未被开封的压缩燃油。叶秉谦决定将部分物资带回天机，同时考虑将剩余的物资提供给无争号，展现了他在末世中依然保持的人道主义精神。</span></p><p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-2 照常行动</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">事情总是会变得更糟。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 区域JT-E-6</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">天机清扫队在完成任务后，准备设置隔离电网。崔远之与易虚舟因任务分配产生争执，叶秉谦则冷静地处理了冲突。随后，三人遇到了一组自称幸存者的陌生人，崔远之敏锐地察觉到他们的可疑之处，果断驱赶了他们。不久后，天机清扫队遭到行尸和活人的联合袭击，叶秉谦在混乱中击杀了伪装成幸存者的敌人。战斗结束后，叶秉谦得知第三小队失联，决定带领崔远之和易虚舟前往搜寻。尽管任务危险重重，叶秉谦依然坚持救人，展现了他在末世中的人道主义精神。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-3 无人通行</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">黑白之间，太多难言的对峙。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 区域JT-E-6</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">叶秉谦带领崔远之和易虚舟前往搜寻失联的第三小队。易虚舟使用能力重现了第三小队的行动轨迹，三人沿着血迹和线索，最终在行尸潮的中心找到了失踪的队员莫菲。莫菲已变成行尸，叶秉谦不得不亲手结束了她的生命。与此同时，易虚舟在爆炸中受伤，崔远之通过极端手段唤醒了他。三人成功脱险后，叶秉谦决定将发现的物资部分留给无争号，展现了他在末世中依然保持的善良与担当。尽管任务危险重重，三人依然坚持完成了任务，展现了他们的勇气和团队精神。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-4 生死不论</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 19px;\">活要见人，死要见尸。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 区域JT-E-6</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">天机清扫队在行尸潮中艰难求生，最终成功脱险。叶秉谦在战斗中展现了卓越的领导力和枪术，崔远之则通过极端手段唤醒了受伤的易虚舟。任务结束后，叶秉谦与无争号交接，决定将部分物资留给无争号，展现了他在末世中的人道主义精神。尽管任务危险重重，三人依然坚持完成了任务，展现了他们的勇气和团队精神。叶秉谦的领导力和崔远之的果断行动，确保了队伍的生存和任务的完成。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-5 来日方短</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">在黑曜，死亡是那么轻。即便它落在你的身上，你都无法注意它的重量。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 无争号总部</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">时间未知</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">崔远之接任天机清扫队队长后，独自承担了大量任务，引发了队员罗咤的不满。罗咤因情绪失控离开队伍，崔远之决定亲自解决此事。与此同时，易虚舟找到崔远之，试图调解他与罗咤的矛盾。崔远之透露了自己杀死叶秉谦的事实，易虚舟则指出叶秉谦早已死去，崔远之只是结束了一个行尸的生命。最终，崔远之决定说服罗咤回归队伍，展现了他在领导岗位上的成长与担当。尽管任务危险重重，崔远之依然坚持带领队伍完成任务，展现了他在末世中的领导力和责任感。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-19 09:46:29', '2025-02-26 18:02:14', '洛天依', '2972930843');
INSERT INTO `story` (`id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (40, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/2nrh44oca1irhiqsrlako0w3iyewgq1_20250219094730A019.png', 20520901, '返校季 ＞', '幕间剧情', '焰响,赫九逸', '2052年秋', '黑曜', '洛天依,奈默', '<p>开学第一课：童话里都是骗人的，这里不是童话世界。</p>', '<p style=\"line-height: 2;\"><br></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-1 童话书</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">开学第一课：童话里都是骗人的，这里不是童话世界。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 一叶城·城门</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">2052年秋某日，傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">一叶城城门外的逃难者们与守门人发生了激烈的争吵。逃难者们希望进入一叶城避难，但守门人坚持要求他们通过“赌命”的方式获得入住资格，否则只能等待审核。逃难者们对此感到绝望，尤其是其中的小女孩秦书意和她的母亲宁老师。宁老师决定赌命为女儿争取机会，但秦书意坚决反对，表示要与母亲同生共死。最终，宁老师放弃了赌命的念头，带着女儿离开了城门。与此同时，一叶城的打更人焰响和赫九逸目睹了这一切，赫九逸暗中帮助了宁老师母女，给了她们一些食物和水。焰响则对逃难者的遭遇显得冷漠，甚至对试图求情的逃难者使用了异能。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-2 好消息</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">开学第二课：好消息也会变成催命符。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 明庭大学</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">2052年秋某日，清晨</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">赫九逸和焰响驾车前往明庭大学，寻找赫九逸母亲的线索。途中，他们遇到了秦书意，她的母亲宁老师在逃离一叶城后，被逃难者推入行尸群中丧生。秦书意决心为母亲报仇，赫九逸和焰响决定带她一同前往明庭大学。在车上，赫九逸回忆起自己的母亲，焰响则试图安慰他。到达明庭大学后，赫九逸独自进入学校寻找线索，焰响则留在外面等待。赫九逸在学校内遇到了昔日的同学王良和文学院院长罗方圆，得知学校内部的黑暗真相。最终，赫九逸在地下室找到了被囚禁的阿福，并试图带他逃离。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-3 兔子洞</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">开学第三课：兔子洞是兔子的家，也是大灰狼的粮仓。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 明庭大学</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">2052年秋某日，傍晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">赫九逸在学校内发现了被囚禁的幸存者，他们被称为“兔子”，被迫成为了其他人的食物来源。赫九逸找到了阿福，发现他已经失去了双臂，奄奄一息。阿福告诉赫九逸，他手中的翡翠吊坠是从一位温柔的阿姨那里得来的，这位阿姨正是赫九逸的母亲。赫九逸意识到，母亲早已在三年前的黑曜日中去世。与此同时，焰响在学校外遭遇了秦书意，秦书意正在追杀那些害死她母亲的逃难者。焰响目睹了秦书意的复仇，但并未阻止。最终，赫九逸带着阿福和秦书意逃离了明庭大学，但阿福在途中不幸去世。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><blockquote style=\"line-height: 2;\"><span style=\"font-size: 19px;\"><strong> BO-4 后悔药</strong></span><span style=\"font-size: 15px;\"><br></span><span style=\"font-size: 16px;\">开学第四课：这世上没有后悔药。</span></blockquote><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">黑曜 明庭大学</span></p><p style=\"text-align: center; line-height: 2;\"><span style=\"color: rgb(140, 140, 140); font-size: 15px;\">2052年秋某日，夜晚</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"font-size: 15px;\">焰响和赫九逸带着秦书意逃离了明庭大学，秦书意虽然中弹，但因赫九逸放在她背包中的童话书挡住了子弹而幸免于难。与此同时，明庭大学内的王良和罗方圆陷入了绝望。王良后悔自己当初的选择，最终在图书馆内点燃了火焰，将自己和罗方圆困在了火海中。焰响和赫九逸驾车离开，秦书意则带着对母亲的思念和对未来的迷茫，继续前行。</span></p><p style=\"line-height: 2;\"><span style=\"font-size: 15px;\"> </span></p><p style=\"line-height: 2;\"><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-19 09:47:55', '2025-02-26 19:27:49', '洛天依', '2972930843');
