INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (33, 8, 0, NULL, 5, '恶象因果', '主线剧情', '监督', '1121年5月30日', '森罗', '洛天依', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">昨日之因，结今日之果。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">今日之因，又将导向怎样的未来？</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 09:42:26', '2025-02-14 09:42:26', 'admin', 'admin');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (34, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">本监督的美好祝愿镇楼</span><img src=\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\" alt=\"\" data-href=\"\" style=\"\"/></p><hr/><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">1121.6.8 11:26<br>监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。<br>1121.6.9 14:28<br>白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。<br>1121.6.10 13:17<br>临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。<br>码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。<br>当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。<br>两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p>', NULL, '2025-02-14 10:58:45', '2025-02-14 10:58:45', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (35, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">本监督的美好祝愿镇楼</span><img src=\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\" alt=\"\" data-href=\"\" style=\"\"/></p><hr/><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:10:52', '2025-02-14 11:10:52', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (36, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">本监督的美好祝愿镇楼</span><img src=\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\" alt=\"\" data-href=\"\" style=\"\"/></p><hr/><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:11:33', '2025-02-14 11:11:33', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (37, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><img src=\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\" alt=\"\" data-href=\"\" style=\"\"/></p><hr/><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:11:43', '2025-02-14 11:11:43', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (38, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><hr/><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:11:59', '2025-02-14 11:11:59', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (39, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><hr/><p><br></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:12:32', '2025-02-14 11:12:32', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (40, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p><br></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:12:41', '2025-02-14 11:12:41', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (41, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:13:39', '2025-02-14 11:13:39', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (42, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\"><code>1121.6.8 11:26</code></span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\"><code>监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</code></span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:14:10', '2025-02-14 11:14:10', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (43, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">6.15上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:14:36', '2025-02-14 11:14:36', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (44, 12, 0, NULL, 9, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:16:46', '2025-02-14 11:16:46', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (45, 12, 0, NULL, 10900, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞,冰舞ぜ紫灵猫', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。（他好嚣张我好爱）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了（我永远喜欢鹿路运输！）。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查（嫘祖！嫘祖救一下啊！祖宗是私企你是国企啊）。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:21:24', '2025-02-14 11:21:24', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (46, 4, 0, NULL, 10100, '序章-灾厄中心', '间章剧情', '监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖', '1123年10月27日', '森罗', '洛天依', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">我们将在「未来」重逢</span></p>', '<blockquote>这里填写故事梳理</blockquote>', NULL, '2025-02-14 11:21:50', '2025-02-14 11:21:50', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (47, 12, 0, NULL, 10900, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞,冰舞ぜ紫灵猫', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/akkhyvaymhwssel1fp6gij3433x6j45_20250214112458A009.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/0klwiygv5xca96tvstwh310dh61tkc5_20250214112553A010.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b2xedfm7lotuxjxavl43thnpoqcflhu_20250214112710A011.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b7eaqdw9ch05xvoeh7iqohoosmtkx4i_20250214112817A012.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/ebnqmop9zuwepoo2wb81i0dko47bcip_20250214112902A013.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/qo3nkdpbzh3hvy032bdqe073lsbgmjj_20250214112932A014.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/7wwl6nbvwm3agw4bxo2mgmkqoaxf8r5_20250214113020A015.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:30:35', '2025-02-14 11:30:35', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (48, 12, 0, NULL, 10900, '瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞,冰舞ぜ紫灵猫', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/akkhyvaymhwssel1fp6gij3433x6j45_20250214112458A009.jpg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/0klwiygv5xca96tvstwh310dh61tkc5_20250214112553A010.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b2xedfm7lotuxjxavl43thnpoqcflhu_20250214112710A011.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b7eaqdw9ch05xvoeh7iqohoosmtkx4i_20250214112817A012.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/ebnqmop9zuwepoo2wb81i0dko47bcip_20250214112902A013.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/qo3nkdpbzh3hvy032bdqe073lsbgmjj_20250214112932A014.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/7wwl6nbvwm3agw4bxo2mgmkqoaxf8r5_20250214113020A015.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 11:33:25', '2025-02-14 11:33:25', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (49, 15, 0, NULL, 101200, '人世行者', '幕间剧情', '伊琅相思,监督,苏筱,瓦卡莎,艾摩诃,莫莫', '1121年8月3日', '森罗,夜摩', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那些停驻于记忆中的温暖瞬间，便是支撑她存活至今的救命良药。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 12:33:34', '2025-02-14 12:33:34', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (50, 15, 0, NULL, 101200, '人世行者', '幕间剧情', '伊琅相思,监督,苏筱,瓦卡莎,艾摩诃,莫莫', '1121年8月03日', '森罗,夜摩', '洛天依,鸿雁于飞', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那些停驻于记忆中的温暖瞬间，便是支撑她存活至今的救命良药。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 12:33:45', '2025-02-14 12:33:45', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (51, 5, 0, NULL, 10200, '00#森罗', '主线剧情', '监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄', '1121年4月25日', '森罗', '洛天依', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">前路迢迢，凶险未知。我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:05:54', '2025-02-14 13:05:54', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (52, 6, 0, NULL, 10300, '01#世出世间事', '主线剧情', '监督,瞳,苏筱,舞鹤织雪,十手卫', '1121年4月29日', '森罗', '洛天依', '<p><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那些隐藏在谎言表象之下的求救讯号，是否也需要回应。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:06:09', '2025-02-14 13:06:09', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (53, 7, 0, NULL, 10400, '02#雨中人', '主线剧情', '监督', '1121年5月10日', '森罗', '洛天依', '<p><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">他们在帷幕之后，瞭望着一场暴雨的开始。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:06:21', '2025-02-14 13:06:21', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (54, 8, 0, NULL, 10500, '03#恶象因果', '主线剧情', '监督', '1121年5月30日', '森罗', '洛天依', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">昨日之因，结今日之果。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">今日之因，又将导向怎样的未来？</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:06:34', '2025-02-14 13:06:34', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (55, 9, 0, NULL, 10600, '04#劣种', '主线剧情', '监督', '1121年5月31日', '森罗', '洛天依', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">那人如流星般转瞬即逝，却有后来者甘愿成为逐星之人。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:06:43', '2025-02-14 13:06:43', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (56, 10, 0, NULL, 10700, '05#非自愿幸存', '主线剧情', '言御,言雀', '1121年6月02日', '森罗', '洛天依', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">在无声中呼救，于缄默中幸存。</span></p>', '<blockquote></blockquote>', NULL, '2025-02-14 13:06:59', '2025-02-14 13:06:59', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (57, 11, 0, NULL, 10800, '06#如我垂怜', '主线剧情', '鸢', '1121年6月05日', '森罗', '洛天依', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">夜晚荒凉，万物静寂。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">你将内心的一切说给花丛，随后摘下一朵——</span></p><p style=\"text-align: left;\"><span ', '<blockquote></blockquote>', NULL, '2025-02-14 13:07:09', '2025-02-14 13:07:09', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (58, 12, 0, NULL, 10900, '07#瘾', '主线剧情', '监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人', '1121年6月08日', '森罗', '洛天依,鸿雁于飞,冰舞ぜ紫灵猫', '<p style=\"text-align: left;\"><span style=\"color: rgb(32, 33, 34); font-size: 14px;\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>', '<p><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\" alt=\"\" data-href=\"\" style=\"\"/></p><p><span style=\"font-size: 16px;\">本故事梳理由百度贴吧用户 </span><a href=\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\" target=\"_blank\"><span style=\"font-size: 16px;\">冰舞ぜ紫灵猫</span></a><span style=\"font-size: 16px;\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\"line-height: 2;\"><br></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.8 11:26</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.9 14:28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.10 13:17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.11 10：24</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/akkhyvaymhwssel1fp6gij3433x6j45_20250214112458A009.jpg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在这里，监督发现北三岛到处都是X晶石的粉末，虽然不到异常的程度，依然蔓延惊人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">舞鹤指路监督去酒馆，表示那里能看到更多。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 00：23</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/0klwiygv5xca96tvstwh310dh61tkc5_20250214112553A010.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督进入金色羽毛酒吧，一眼看到了唐路遥，两人默契地没有相认，唐路遥找到富运运输人员套话，交谈间天鹿打手到来，透露玄戈“死讯”，疑似凶手为血露薇人员，怀疑背后是枫岛想插手北三岛所以炸了玄戈的车。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">有自称知情人的天鹿打手加入交谈，但刻意压低了声音，监督正愁听不清楚，红衣男人到来，认出了监督，自称“宁”（我就直接打姜宁了），询问监督是否收到了他的委托品。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.12 01：06</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁主动提出和监督玩牌，方便监督提问。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1、金属牌是什么？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：【谒声】的象征。隶属于天鹿但独立行事的“顾问”，与首领关系紧密，负责主持首领葬礼和宣布下一任继任者。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">2、如何保证谒声的运转和安全？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：没有人能保证，谒声的地位是从三代首领手里抢回来的。</span></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">3、姜宁是谒声的人吗？为什么给监督？</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">答：受人所托但不想趟浑水，而监督需要这个身份来介入北三岛。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回问需要什么回报，姜宁说希望监督把继任的时间延后十五天方便他救人</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.13 09:30</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b2xedfm7lotuxjxavl43thnpoqcflhu_20250214112710A011.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督使用金属牌改换身份，抵达墓园参加玄戈的“葬礼”。等待期间从众人的交谈中得知名为左枢的代言人如今声名正盛，且众人并不看好北洛接任。暗示左枢病体缠身活不久的人被柚理出手警告，左枢现身表示不等北洛了请谒声主持葬礼。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督公布玄戈遗嘱，即将公布接任者的时候北洛杀到，嚣张表示左枢这么多年动手了那么多次都没杀掉玄戈，他哥更不可能死于意外。柚理想动手，被左枢阻止，北洛动都没动，甩手走人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛走后，监督顺势宣布玄戈之死有争议，延后十五天再公布继任者，得到左枢认同。左枢把柚理派给监督当保镖（也有监视的意思），监督准备上辟邪车标的豪车时遭遇袭击。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督打电话给老卫交流情况，老卫让监督在北三岛狠狠地查，顺便监督和他的线人接头顺利吗？监督说顺利倒是顺利，但是……大鹅被抓啦！</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督调查玄戈遇袭事件，确认了玄戈当天的行程、现场证人的口供，见到了来自血露薇的嫌疑人大鹅。但众所周知，大鹅玩不来脑子，姜宁在岛上的情况下也根本不可能派她来和玄戈谈交易，监督猜测“血露薇和天鹿有生意”这件事本身才是关键。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门，赶上左枢来送车辆的爆炸报告，左枢疯狂暗示玄戈没死为此不惜把自己放进嫌疑人名单，但监督冷静表示我知道了并不打算搀和天鹿内务。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">柚理偷换了左枢的药，怕他变成怪物，左枢表示现在时局艰难必须要撑住。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音将监督遇袭的消息告诉白荆科技，并劝筱筱冷静下来。听完墙角的瞳也进来安慰筱筱，表示被炸不是坏事。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.15 00:14</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督来酒吧等待姜宁接头，犹豫要不要打听X晶尘的事，发现它已经散入了凛阳的四面八方。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">姜宁到来，两人大致交流了一下天鹿目前的问题和玄戈的解决方案——诈死、打窝、钓鱼。（注意这个姜宁）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">从酒吧出来后监督估计找犄角旮旯钻想实验谒声牌和探索晶尘，被袭击。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上午十点，监督带着子弹壳拜访左枢，以此为筹码要求提高权限等级，左枢同意。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">羽林来汇报新部门情况，左枢顺势让羽林带监督去档案室。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在档案室搜索出世间相关消息未果，但顺便了解了天鹿五代首领的过往。总结就是一代首领和玄戈北洛爷爷长垣起于乱世，一代热血首领二代冷静头脑，从无到有发展了天鹿，但第三代首领是个偏激的疯子，埋下的雷太多，四代昴和五代玄戈拔了几十年都没拔干净。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">（长垣没打算传位给昴，他定下的第三任首领是别人，他说昴不适合当首领；然后，昴是被毒死的……就，一个古三弃婴罪的爹，要用一个变成行尸的爹和一个被毒死的爹来还啊，太惨了）</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺手查了羽林和岚相，发现他俩都被调离了原区域，放在左枢手下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督试探羽林是否相信玄戈死了，羽林沉默。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.16 上午十点</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督到访玄戈宅邸，正巧碰上左枢被北洛赶出来。随后交代北洛在玄戈“葬礼”上的发言是配合监督演戏，但嫌弃现在天鹿的心是真的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">得到北洛允许，监督在宅邸内四处调查，进入玄戈卧室发现来自南半球的橙色晶石，监督推测玄戈一周前患病，后觉醒成为同调者，同时猜测一直在推动手术的戴医生有问题。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.17</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督回到天鹿档案室查了戴医生的资料，得知三年前前代首领昴遭受袭击，左枢拼死相救，被戴医生抢救回来，从而获得提升。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督出门跟柚理套话，得知左枢曾使用过白荆科技的实验药。监督察觉不对找了个休息室开屏蔽，联系筱筱和瞳主任开会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">门外岚相疑似想对谒声下手，被羽林阻拦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">入夜，监督再次来到金色羽毛酒吧，打发时间兼探听消息，意外听到码头仓库的晶石是假的。唐路遥假装不认识跟监督借了通讯器，转头出门和羽林碰头。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人稍微交流了一下信息，羽林确信左枢接管天鹿不是最佳选择，他对北洛有期待；唐路遥收留北洛的时候并不知道北洛的出身，但对于天鹿也有怨气。两人各有不爽，最后决定打一架。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.18凌晨</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督和余音交换信息，决定干一票大的；同时舞鹤织雪和南渚守在码头盯着来往货船，互相试探中透露码头仓库是舞鹤炸的，葵想瓮中捉鳖，江昙想阻止她越陷越深。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.19</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">余音代表白荆和左枢谈合作，提醒他关注白荆马上直播的发布会。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/b7eaqdw9ch05xvoeh7iqohoosmtkx4i_20250214112817A012.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">发布会上瞳发言，巫炤代表遥城研究院背书，公开白荆关于X晶体浓缩液的研究。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">会议结束后姬轩辕的秘书兼保镖兼损友孔阳代表姬轩辕给巫炤安排了接下来的行程。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">夜晚，由于RED被管控导致流动的十手卫和田偌吃烧烤，田偌担心RED会不会因此取消，老卫开解说换个屋又没让你脱警服。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">次日，监督在天鹿内部边听周围的播报边等待余音和左枢的谈判，正愁没有理由接触戴医生，不知名的袭击者攻击了他，被岚相挡下。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督顺理成章来到医务室，戴医生受命拉拢ta，正准备说什么的时候柚理发来通讯，余音也告知左枢旧病复发，戴医生留下一张卡匆匆离去。监督仔细搜索戴医生诊室后拿上电梯卡坐上那部最老旧的电梯，在地下见到了天鹿三代首领，听他讲述了一个关于天鹿的故事。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">这个疯子宁可天鹿崩塌或是被人寄生，也不愿看着玄戈带领天鹿走出一条新路。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">岚相是他的儿子，却一点都不像他。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.21</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛在家里收拾东西准备跑路，被管家夫人拦下。北洛谈起天鹿，很多观点和玄戈不谋而合。两人都认为，如果天鹿沉了，那也得是自己动手沉的。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">北洛询问夫人关于玄戈留下的遗物，夫人表示昴过世的时候玄戈也问过同样的问题。北洛不相信玄戈会这么容易的死了，夫人说那等他回来，我们一起策反他所有的手下，北洛说说好了，我第一个策反你！</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.23夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">监督在南渚的带领下潜入一座存放海临运来X晶石的仓库，在这里遇到了海伦。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">海伦虽然没有染病但已经精神崩溃，且此地藏着异化怪鸟袭击监督和南渚。危急时刻南渚扔出电击枪，效果惊人，监督OS这不是他那部电击枪该有的效果（南渚觉醒了），此时余音赶到，解决了怪鸟，监督也顺势跟南渚摊牌——这就是出世间。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同时，老卫在办公室嘀咕白荆干得漂亮，老刘来找他下班，老卫没看到监督发出的找到海伦的消息。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.27深夜</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">左枢来到墓园找昴聊天，玄戈现身，两人和谈。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一时间，监督在酒吧等到了真正的姜宁，交谈间透露上次来拜访会面的是玄戈假扮的姜宁，目的是确认监督是不是可以托付的人。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">两人正式摊牌，监督对血露薇提出合作，又问了真正谒声的身份，姜宁说你认识。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.28</span></li></ul><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">继任仪式当天，戴医生察觉不对想跑路，玄戈现身，戴医生将浓缩液砸向左枢，导致其异变成鸠。一番战斗后左枢恢复神智，但异变不可逆，且生命垂危，他请求玄戈，让他以左枢的身份死去，玄戈答应了代言人的请求。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/ebnqmop9zuwepoo2wb81i0dko47bcip_20250214112902A013.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">枪响后，羽林抵达，表示清理完毕，问左枢的遗体怎么处置，玄戈刚要回答，身体不支晕了过去。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">同一天的出世间，十手卫被设局引向琴初动手术所在地，琴初命令处刑人解决十手卫，将他“换个身份、换个人生”。处刑人和十手卫交手期间，琴初不停暗示柳池阻拦，但柳池不为所动。琴初交代醒来后要清理出世间的叛徒，并对江昙说希望我醒来时你还在我身边。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">处刑人拖着十手卫往外走，被岳重山拦下，岳重山的能力疑似洗脑？他想把十手卫“流放”，处刑人不想把十手卫交出去，被岳重山嘲讽“你现在又不认识他”。</span></p><ul><li style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">1121.6.30</span></li></ul><p style=\"line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/qo3nkdpbzh3hvy032bdqe073lsbgmjj_20250214112932A014.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">凛阳港口重新开放，迫不及待回家的监督换上白荆制服，提前两个半小时从旅馆出发准备坐船。在港口等待期间，舞鹤织雪发来见面邀请，两人简单交谈，舞鹤立了个硕大的FLAG，但监督答应了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">回到港口，监督遇到了染掉粉发的南渚，他已经正式成为天鹿第七区小队长了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">准备登船时，监督看到了玄戈的座驾，上车和玄戈达成初步合作意向后，监督还拜托天鹿提醒南渚体检，他可能觉醒了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">上船后，监督接到唐路遥电话。与此同时，黑曜北洛放无咎去买票，留在这看海。两人就“在意”展开讨论，同时北洛让唐路遥用称呼区分一下他和森罗洛，省得无咎问东问西。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">在友好和谐（？）的氛围中，北洛一脚油门带着唐路遥和无咎出发去坐飞机了。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">未知时间未知地点，葵的手术成功了，舞鹤嘲讽柳池失去了最接近的报仇机会。江昙说琴初要彻查出世间内鬼，舞鹤表示随便查反正是你不是我。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">琴初苏醒，白荆科技因“技术违规”被彻查。</span></p><p style=\"text-indent: 2em; line-height: 2;\"><img src=\"http://r.qianqiu.info/admin/upload/2025/02/14/7wwl6nbvwm3agw4bxo2mgmkqoaxf8r5_20250214113020A015.jpg\" alt=\"\" data-href=\"\" style=\"\"></p><p style=\"line-height: 2;\"><span style=\"color: rgb(59, 59, 59);\">第七章剧情结束。</span></p>', NULL, '2025-02-14 13:07:19', '2025-02-14 13:07:19', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (59, 4, 0, NULL, 10100, '序章#灾厄中心', '间章剧情', '监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖', '1123年10月27日', '森罗', '洛天依', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">我们将在「未来」重逢</span></p>', '<blockquote>这里填写故事梳理</blockquote>', NULL, '2025-02-14 13:09:28', '2025-02-14 13:09:28', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (60, 4, 0, NULL, 10100, '序章#灾厄中心', '间章剧情', '监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖', '1123年10月27日', '森罗', '洛天依', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">我们将在「未来」重逢</span></p>', '<blockquote>这里填写故事梳理Vein：现在是森罗时间1123年10月27日 17:52</blockquote><hr/><p>Vein：白荆科技首席执行官监督，身份验证成功</p><p>Vein：欢迎回家</p><p><br></p><p>广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p><br></p><p>？？？：唔……天隙通道…………</p><p>？？？：……你终于来了。</p><p>监督：什——！</p><p><br></p><p>广播：这里是海临特殊事件应急指挥部。</p><p>广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p>广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p><br></p><p>监督：………………</p><p>监督：刚才看见的……是幻觉？还是别的什么……</p><p>监督：这里是……中心商业区……发生什么事了？</p><p>监督：不对，我为什么在这里？我明明记得自己是在办——</p><p><br></p><p>通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p>通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p>通讯中的少女：最好再催一催车队，让他们快些出发。</p><p>通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p><br></p><p>监督：……筱筱？</p><p><br></p><p>苏筱：监督！</p><p>苏筱：你怎么还在这里？！</p><p>苏筱：我们不是已经说好了吗？</p><p>苏筱：你是护送任务的最佳人选，如果途中遇到袭击，你的能力就是我们的最后一道保障——</p><p>苏筱：你怎么又折回来了？</p><p><br></p><p>监督：筱筱，我好像遇到了一些问题……唔！</p><p><br></p><p>？？？：……未来……</p><p>？？？：……藏于灾厄中心……</p><p><br></p><p>监督：………………</p><p>监督：我晕过去了吗？</p><p><br></p><p>苏筱：没有，只是突然开始走神，怎么喊也不听……</p><p>苏筱：你的状态有些不对劲，是在护送途中遇见什么事了吗？</p><p><br></p><p>监督：我也不知道。</p><p>监督：先不说这个，筱筱，我记得我们之前明明还在赶往天隙禁区的路上……</p><p><br></p><p>苏筱：哎呀！这种时候就别再提禁区的事了！天隙通道的异变引发了大面积的空问扭曲，现在靠近说不准就要被传送到哪个未知世界！</p><p>苏筱：所有人都在撒离，我们为什么还要回去？</p><p><br></p><p>监督：（为什么这一切看起来都不太对劲……）</p><p><br></p><p>苏筱：为什么不说话？</p><p>苏筱：监督，你一定要冒这个险吗？</p><p><br></p><p>监督：筱筱，从见面开始，你为什么一直叫我\"监督\"？</p><p><br></p><p>苏筱：你是白荆科技的首席执行官，不叫\"监督\"还能叫你什么？</p><p><br></p><p>监督：…………</p><p><br></p><p>苏筱：…………</p><p><br></p><p>监督：……算了，现在不是讨论这个的时候。</p><p>监督：我必须去禁区中心重新确认天隙通道的异变情况，你要一起吗？</p><p><br></p><p>苏筱：虽然有时候真不知道你到底在想些什么。但是既然是你坚持的，就一定有你的道理。</p><p>苏筱：走吧~在这方面，我从来只会跟你的票。</p><p><br></p>', NULL, '2025-02-14 13:17:34', '2025-02-14 13:17:34', 'xingfeng', 'xingfeng');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (61, 4, 0, NULL, 10100, '序章#灾厄中心', '间章剧情', '监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖', '1123年10月27日', '森罗', '洛天依', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">我们将在「未来」重逢</span></p>', '<blockquote>本章节暂无概要梳理，待添加</blockquote><hr/><p>Vein：白荆科技首席执行官监督，身份验证成功</p><p>Vein：欢迎回家</p><p><br></p><p>广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p><br></p><p>？？？：唔……天隙通道…………</p><p>？？？：……你终于来了。</p><p>监督：什——！</p><p><br></p><p>广播：这里是海临特殊事件应急指挥部。</p><p>广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p>广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p><br></p><p>监督：………………</p><p>监督：刚才看见的……是幻觉？还是别的什么……</p><p>监督：这里是……中心商业区……发生什么事了？</p><p>监督：不对，我为什么在这里？我明明记得自己是在办——</p><p><br></p><p>通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p>通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p>通讯中的少女：最好再催一催车队，让他们快些出发。</p><p>通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p><br></p><p>监督：……筱筱？</p><p><br></p><p>苏筱：监督！</p><p>苏筱：你怎么还在这里？！</p><p>苏筱：我们不是已经说好了吗？</p><p>苏筱：你是护送任务的最佳人选，如果途中遇到袭击，你的能力就是我们的最后一道保障——</p><p>苏筱：你怎么又折回来了？</p><p><br></p><p>监督：筱筱，我好像遇到了一些问题……唔！</p><p><br></p><p>？？？：……未来……</p><p>？？？：……藏于灾厄中心……</p><p><br></p><p>监督：………………</p><p>监督：我晕过去了吗？</p><p><br></p><p>苏筱：没有，只是突然开始走神，怎么喊也不听……</p><p>苏筱：你的状态有些不对劲，是在护送途中遇见什么事了吗？</p><p><br></p><p>监督：我也不知道。</p><p>监督：先不说这个，筱筱，我记得我们之前明明还在赶往天隙禁区的路上……</p><p><br></p><p>苏筱：哎呀！这种时候就别再提禁区的事了！天隙通道的异变引发了大面积的空问扭曲，现在靠近说不准就要被传送到哪个未知世界！</p><p>苏筱：所有人都在撒离，我们为什么还要回去？</p><p><br></p><p>监督：（为什么这一切看起来都不太对劲……）</p><p><br></p><p>苏筱：为什么不说话？</p><p>苏筱：监督，你一定要冒这个险吗？</p><p><br></p><p>监督：筱筱，从见面开始，你为什么一直叫我\"监督\"？</p><p><br></p><p>苏筱：你是白荆科技的首席执行官，不叫\"监督\"还能叫你什么？</p><p><br></p><p>监督：…………</p><p><br></p><p>苏筱：…………</p><p><br></p><p>监督：……算了，现在不是讨论这个的时候。</p><p>监督：我必须去禁区中心重新确认天隙通道的异变情况，你要一起吗？</p><p><br></p><p>苏筱：虽然有时候真不知道你到底在想些什么。但是既然是你坚持的，就一定有你的道理。</p><p>苏筱：走吧~在这方面，我从来只会跟你的票。</p><p><br></p>', NULL, '2025-02-14 13:17:59', '2025-02-14 13:17:59', 'xingfeng', 'xingfeng');
