INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (132, 23, 0, NULL, 11210715, '底色', '间章剧情', '十手卫', '1121年7月', '森罗', NULL, '<p><span style=\"font-size: 14px;\">浮生过眼，要去记住那些平凡的、永远不会出现第二次的瞬间。</span></p>', '<p><br></p>', NULL, '2025-02-15 23:32:15', '2025-02-15 23:32:15', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (133, 26, 0, NULL, 11210710, '通往「斑斓」的信号灯', '幕间剧情', '监督，苏筱，北洛，Sweeper-EX，提提亚，景，唐路遥，霍冉，长谣，元桃桃，瓦卡莎，狄砚，尤尼，风晴雪，琉辛，豹富，卡洛琳，莉缇亚，无咎，马尔斯，龙晴，言御，司旸，言雀，岚岚，修', '1121年夏', '森罗', NULL, '<p>有时候……人脉也没有想象中那么复杂……</p>', '<p><br></p>', NULL, '2025-02-15 23:33:43', '2025-02-15 23:33:43', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (134, 25, 0, NULL, 11210705, '不要惊醒奈奥格', '幕间剧情', '监督，提提亚，景', '1121年夏', '森罗', NULL, '<p><span style=\"font-size: 14px;\">服从我，或者，规训我。</span></p>', '<p><br></p>', NULL, '2025-02-15 23:33:57', '2025-02-15 23:33:57', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (135, 24, 0, NULL, 11210701, '苍蓝的达加兹', '幕间剧情', '监督，苏筱，岚岚，尤尼', '1121年夏', '森罗', NULL, '<p><span style=\"font-size: 14px;\">当晨光穿透乌云的瞬间，将会有一个更宽广的新世界在你眼前展开。<br>——Bless you, last&amp;best.</span></p>', '<p><br></p>', NULL, '2025-02-15 23:34:13', '2025-02-15 23:34:13', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (136, 20, 0, NULL, 20490401, '不逢「缘」', '幕间剧情', '珑，林，旒珠，崔远之，易虚舟（逸舟），叶秉谦，焰响，赫九逸，北洛（黑曜）', '2049年4月1日', '黑曜', NULL, '<p><span style=\"font-size: 14px;\">创伤、污秽、鲜血与未流出的眼泪——<br>雨水如死亡般湮没所有。</span></p>', '<p><br></p>', NULL, '2025-02-15 23:35:54', '2025-02-15 23:35:54', '洛天依', '洛天依');
