INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (400, 35, 0, 'http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095157A030.png', 11191005, '万象·回忆', '幕间剧情', '监督,苏筱,曲观玄', '1119年10月05日', '森罗', '洛天依', '<p>现在回想起来……就是在这一天，我们第一次代表这个世界——</p><p>——成功触摸到“回廊”。</p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-28 09:58:56', '2025-02-28 09:58:56', '洛天依', '洛天依');
