INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (402, 41, 0, NULL, 10810000, '西陵重工', '其他剧情', NULL, '1081年', '森罗', NULL, '<p>海临重型机械厂与西陵制造局改组成立西陵重工集团有限公司。</p>', '<p><br></p>', '<p><br></p>', '2025-02-28 10:01:27', '2025-02-28 10:01:27', '洛天依', '洛天依');
INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (403, 32, 0, NULL, 10820000, '南半球事件', '其他剧情', NULL, '1082年', '森罗', '洛天依', '<p>战争蔓延至九旻海。西陵重工被委以重任，成为海隅理事会所主导的建设战时防御体系的主力军之一。</p><p><br></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '<p><span style=\"font-size: 16px;\">暂无</span></p><p><span style=\"font-size: 16px;\">欢迎加入QQ群：</span><span style=\"font-size: 16px;\"><u><em><strong>977786603</strong></em></u></span><span style=\"font-size: 16px;\">，共同建设</span></p>', '2025-02-28 10:01:47', '2025-02-28 10:01:47', '洛天依', '洛天依');
