INSERT INTO `story_back` (`id`, `origin_id`, `parent_id`, `banner`, `sort`, `title`, `type`, `chars`, `s_time`, `world`, `author`, `desc`, `summary`, `otext`, `create_time`, `update_time`, `create_by`, `update_by`) VALUES (405, 42, 0, NULL, 10860209, '停战协议签署', '其他剧情', NULL, '1086年2月9日', '森罗', NULL, '<p style=\"line-height: 2;\">南北半球首脑于蒂尔莫签署停战协议。</p>', '<p><br></p>', '<p><br></p>', '2025-02-28 10:06:12', '2025-02-28 10:06:12', '洛天依', '洛天依');
