INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (31, '金币姐的三花特性应该是专精加成而非刻印专精加成，游戏内右上角确实显示了三花特性给到的专精加成', '已修复，谢谢反馈', '2024-11-27 13:06:23', '236669908662910977', '202.201.10.89', NULL);
