INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (37, '你好，抽卡分析的排行榜里面，按up抽数来看我应该是11名，但是排行榜却显示我是12名，我看了下12名和我的平均抽数是一样的，可能是因为这个显示错误了？', '嗯。这种并列的暂时无法区分，下次我修复下这个问题', '2024-11-30 17:31:30', '252001195565105153', '39.144.152.25', '2024-11-30 17:06:27');
