INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (49, '有没有考虑增加监督刻印搭配以及茶歇布局分享的版块', '监督刻印有在考虑，茶憩这个要想想怎么处理', '2024-12-18 08:44:25', '244613305142992897', '112.48.75.131', '2024-12-18 00:38:15');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (50, '链接1链接2是什么你倒是写出来啊', '<a href=\"https://mp.weixin.qq.com/s/GkHZ3tHSvitb7JU2A2hXjA\">点击查看</a> 或前往微信公众号《白荆小助手》点击公众号菜单中的抽卡分析即可查看教程', '2024-12-18 08:57:18', '236699029954658305', '222.129.134.170', '2024-12-18 06:53:36');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (51, '为什么十几抽抽出来角色，显示的是“1…”这样，看不清楚', '可能是数据导入正在处理中。多刷新几次页面就行', '2024-12-21 18:11:23', '236224451247616002', '223.104.150.81', '2024-12-21 14:12:15');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (52, '请问有抽卡分析哪边可以看到每期卡池抽数？比如：在xx卡池一共投入xx抽数，抽取xxN只', '小助手暂时未实现这个功能，待后续完善', '2024-12-23 17:05:42', '237255601286025218', '180.109.89.225', '2024-12-23 16:02:10');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (53, '请问可以统计一下历史卡池吗？是新手，比较关心复刻池顺序及角色复刻时间。感谢！', '已调整，可使用网页端版本先体验下。微信小程序正在审核', '2024-12-30 14:38:51', '264328532272996354', '111.55.147.108', '2024-12-30 10:23:14');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (54, '玄戈的队长技是不是写错了，游戏里应该是铁杵磨成针，小助手的伤害计算里是擒贼先擒王', '已修复，谢谢反馈', '2025-01-04 09:18:12', '236509718206533634', '36.152.24.132', '2025-01-03 17:12:36');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (55, '可以把垫的抽数归入下个池子一起显示吗？', '目前是以卡池为单位计算的，方便看到每个卡池投入的资源。我想想怎么优化这个显示方案', '2025-01-04 15:48:29', '235944301578788866', '111.18.34.213', '2025-01-04 15:06:54');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (56, '可以搞个不显示时间的抽卡统计吗，类似原神提瓦特小助手那样的，其实主要还是不想把垫的拆开来，明明吃满保底，红得发黑，但是因为垫一下垫一下，导致看起来绿了', '网页端、APP端已更新，小程序端等审核中。可前往抽卡分析界面，点击页面提示中的总览按钮即可查看整体数据', '2025-01-07 13:47:01', '236201540763852802', '112.96.198.102', '2025-01-07 11:29:11');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (57, '你的链接1打开啥都没有，怎么登陆', '这是烛龙官方的链接，如果什么都没有要么是网络问题，要么是链接复制错了。具体请参考教程', '2025-01-11 18:42:22', '', '223.104.70.239', '2025-01-11 16:22:04');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (58, '微信扫码出提示，说该二维码只能通过扫一扫登录\n(¯―¯٥)但我就是用扫一扫的啊', '用的摄像头扫码吗？如果不行可能是被风控了。建议使用网页端导入数据的方案', '2025-01-20 09:36:56', '271784398374883330', '61.149.74.24', '2025-01-19 23:37:37');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (59, '我都登陆不了，搞什么啊，uid不行，QQ号也不行', '小助手的账号和游戏账号没有任何关系，请先注册小助手账号再登录。非官方APP、非官方APP、非官方APP', '2025-01-22 11:51:14', '', '112.50.59.172', '2025-01-22 01:23:33');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (60, '请问现在qq登陆保持不了几天是为什么呢？前天刚登陆过查询抽卡记录，今天想再看的时候提示又要登陆，而且不可以用账号密码，必须扫码，这是版本问题吗？我是在公众号下载的版本呀。', '可能是官网那边的新增的限制，暂时无法解决。只能等需要的时候在导入，或者嫌麻烦的话也可以用网页端导入的方案', '2025-01-24 12:54:31', '236433676297068545', '223.104.149.56', '2025-01-24 10:05:22');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (61, '您好，安装包找到了诶，之前的那个说是需要更新，得进群拿安装包吗？', '在公众号有最新版本的，1.2.0就是最新版本，不需要进群', '2025-01-27 18:30:16', '236990316528308226', '117.151.22.13', '2025-01-27 12:37:18');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (62, '话说有升阶级和技能的材料统计吗', '小助手没有做这个功能，可以前往白荆回廊WIKI查看', '2025-02-10 09:20:16', '235884617186455554', '223.104.86.250', '2025-02-09 18:33:42');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (63, '监督刻印里面新体质卡须臾浮生的数字错位了', '已修复，感谢反馈', '2025-02-14 20:36:48', '235889245701582849', '120.239.72.218', '2025-02-14 09:42:16');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (64, '剧情线详情页向下滑动再点击下一章时，新一章文本位置不会重置到开头，影响阅读，目前可以用雪中春信章节测试。', '已修复，感谢反馈', '2025-02-20 13:18:40', '236173846378520578', '219.239.227.115', '2025-02-20 05:21:44');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (66, '不逢源版本的时间是采用黑曜时间，理论上黑耀日=天隙时间当天，是不是每个世界的剧情做一条时间轴，然后在天隙时间进行交汇？', '嗯，有这个想法。现在剧情补充这边人手不足。进展会慢点，先把森罗的故事处理之后再同步更新', '2025-02-21 15:29:36', '236263948391821313', '113.16.169.58', '2025-02-21 11:38:47');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (67, '配队界面，从配队详情页返回到配队列表时，能否不回到顶部，不然每次返回后需要重新往下翻找', '暂时无法处理，目前建议使用收藏或者筛选功能', '2025-02-28 10:44:47', '241255703981957122', '117.136.73.168', '2025-02-28 09:29:17');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (68, '萌新配卡推荐里面说到特性强化只有十杰有是错的，已经更新多几个了，辛苦各位大大', '已调整，感谢反馈', '2025-03-04 10:39:57', '287254011241906178', '125.91.237.44', '2025-03-03 16:21:10');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (69, '注册不上，没有提交的按钮', '如有疑问，可加QQ群：865686593 反馈', '2025-03-04 10:41:46', '', '112.39.100.200', '2025-03-03 23:13:29');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (70, '计算出错，请联系开发人员是什么情况？', '大部分新角色当天无法计算，这个涉及到数据填写的问题。除非我抽了，当天大概率会更新。', '2025-03-07 14:22:00', '238004952195203074', '124.240.61.125', '2025-03-07 00:49:04');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (71, '配队助手里的方案，最下面2张烙痕会被底栏遮挡一半。', '已修复', '2025-03-07 13:50:06', '235844294741614594', '182.88.220.97', '2025-03-07 03:02:06');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (72, '新烙痕卡泅游的专精和终端数字没有标好，计算的最终结果在防御和终端的时候数字显示不完整', '已修复', '2025-03-07 14:24:51', '235889245701582849', '120.239.72.246', '2025-03-07 14:15:45');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (73, '为什么弹出个连接错误', '未导入抽卡数据', '2025-03-09 07:06:39', '279683313862488066', '222.191.193.107', '2025-03-07 23:01:33');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (74, '登录提示提交错误，无法登陆', '如有疑问，可加QQ群：865686593 反馈', '2025-03-09 07:06:40', '', '121.61.114.170', '2025-03-08 08:46:35');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (75, '上个卡池垫的抽数都没算进下个出金的卡池，导致角色保底被拆成几个卡池的计量条，（例如垫了三个卡池64抽出的老卫，在显示时被拆成了在玄戈卡池的7抽 余音卡池30抽，老卫34抽，一个保底红条被拆成三个绿黄条）伪装成很欧的样子', '可点击上方《当前UP池为卡池模式,点击切换总览模式》中的 总览 二字进行显示模式切换', '2025-03-09 07:07:12', '289115100447535106', '113.67.164.53', '2025-03-08 22:24:25');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (76, '我删除了导入的数据现在一直显示错误  让联系开发人员', '未导入抽卡数据', '2025-03-10 09:04:02', '236050848329822210', '221.14.64.6', '2025-03-09 11:22:17');
