INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (78, '温留无法计算，底部是空的', '新角色第二天或更晚才能计算', '2025-03-28 10:47:35', '281062709601009665', '182.138.171.56', '2025-03-28 10:46:54');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (79, '尖峰共鸣池晶体池子，阶段四的40抽保底六星被算到常驻里面去了，导致下一个六星显示十几抽就出了，哪有那么欧啊，', '联合池子规则问题，我这边不好处理。', '2025-04-02 09:20:34', '', '49.90.27.55', '2025-03-31 22:15:54');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (80, '烙痕池可以和同调一样标记上池子的名字吗？还有我是想看一个池子到底花了多少抽，现在这样看的晕晕的，我都不知道我到底抽了多少出的角色，只知道多少抽后保底歪了什么', 'UP烙痕以及UP角色会显示池子名字，其余常驻池子不会标记。', '2025-04-02 09:21:25', '', '43.250.245.229', '2025-04-01 19:16:22');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (81, '崔远之的特性的无视减伤是5%*3，小程序里计算写的是75%，特性强化效果是20%和30%的独立，小程序计算写的是10%', '已修复，谢谢反馈', '2025-04-04 03:46:34', '', '219.239.227.234', '2025-04-03 20:15:12');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (82, '怎么导入抽卡数据，他那个链接是在哪里', '前往微信公众号《白荆小助手》点击公众号菜单中的抽卡分析即可查看教程', '2025-04-04 03:46:49', '298568348044627969', '111.8.123.33', '2025-04-03 21:28:48');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (83, '为什么导入成功后等待并刷新，出现没有数据', '那就是没有导入成功，请使用网页版或者最新版本的APP导入', '2025-04-04 19:38:56', '279683313862488066', '49.90.21.221', '2025-04-04 13:22:48');
INSERT INTO `suggest` (`suggest_id`, `desc`, `ans`, `time`, `uid`, `ip`, `init_time`) VALUES (84, '崔远之鬼枪上膛是专精百分比加成与芙渠同一乘区', '已修复', '2025-04-08 10:41:11', '', '223.160.226.233', '2025-04-07 17:30:00');
