INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (248, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">我们将在「未来」重逢</span></p>\",\"id\":4,\"params\":{},\"sTime\":\"1123年10月27日\",\"sort\":1,\"summary\":\"<blockquote>这里填写故事梳理</blockquote>\",\"title\":\"序章-灾厄中心\",\"type\":\"主线剧情\",\"updateBy\":\"admin\",\"updateTime\":\"2025-02-14 09:32:15\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:32:15', 21);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (249, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:34:15\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">前路迢迢，凶险未知。我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——</span></p>\",\"id\":5,\"params\":{},\"sTime\":\"1121年4月25日\",\"sort\":2,\"summary\":\"<blockquote></blockquote>\",\"title\":\"森罗\",\"type\":\"主线剧情\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:34:15', 25);
