INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (265, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"鸢\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:44:00\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">夜晚荒凉，万物静寂。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">你将内心的一切说给花丛，随后摘下一朵——</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">送给了我。</span></p>\",\"id\":11,\"params\":{},\"sTime\":\"1121年6月05日\",\"sort\":8,\"summary\":\"<blockquote></blockquote>\",\"title\":\"如我垂怜\",\"type\":\"主线剧情\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:44:00', 10);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (266, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:45:37\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<blockquote></blockquote>\",\"title\":\"瘾\",\"type\":\"主线剧情\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:45:37', 13);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (267, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"缇诗\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:47:31\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">噩梦在将醒未醒时缠身。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">但只要你睁眼。</span></p>\",\"id\":13,\"params\":{},\"sTime\":\"1121年6月09日\",\"sort\":10,\"summary\":\"<blockquote></blockquote>\",\"title\":\"炉·心·缇诗\",\"type\":\"间章剧情\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:47:31', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (268, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"米达斯\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:48:25\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">这是一位胆小鬼的葬身之地，空空的棺椁正在等待它的主人。</span></p>\",\"id\":14,\"params\":{},\"sTime\":\"1121年6月16日\",\"sort\":11,\"summary\":\"<blockquote></blockquote>\",\"title\":\"炉·心·米达斯\",\"type\":\"间章剧情\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:48:25', 10);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (269, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, 'admin', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"伊琅相思,监督,苏筱,瓦卡莎,艾摩诃,莫莫\",\"createBy\":\"admin\",\"createTime\":\"2025-02-14 09:50:14\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">那些停驻于记忆中的温暖瞬间，便是支撑她存活至今的救命良药。</span></p>\",\"id\":15,\"params\":{},\"sTime\":\"1121年8月03日-04日\",\"sort\":12,\"summary\":\"<blockquote></blockquote>\",\"title\":\"人世行者\",\"type\":\"幕间剧情\",\"world\":\"森罗,夜摩\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 09:50:15', 15);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (270, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\\\">本监督的美好祝愿镇楼</span><img src=\\\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><hr/><p><span style=\\\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\\\">1121.6.8 11:26<br>监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。<br>1121.6.9 14:28<br>白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。<br>1121.6.10 13:17<br>临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。<br>码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。<br>当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。<br>两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p>\",\"title\":\"瘾\",\"type\":\"主线剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-14 10:58:44\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 10:58:44', 25);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (271, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\\\">本监督的美好祝愿镇楼</span><img src=\\\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><hr/><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 5', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:10:51', 39);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (272, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\\\">本监督的美好祝愿镇楼</span><img src=\\\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><hr/><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 5', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:11:33', 32);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (273, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/073cecfafbedab64855fa7e7b136afc379311e99_20250214105708A007.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><img src=\\\"https://tb2.bdstatic.com/tb/editor/images/face/i_f16.png?t=20140803\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><hr/><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.11 10：24</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</s', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:11:43', 78);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (274, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><hr/><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.11 10：24</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳出旅馆出门“散步”，在', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:11:58', 42);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (275, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><hr/><p><br></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.11 10：24</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">舞鹤织雪故意透露自己在出世间不被教主信任，拖着监督从十六楼跳', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:12:32', 38);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (276, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.106.116', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":9,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p><br></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">两人谈起玄戈的“葬礼”，余音做为白荆科技的代表收到了邀请函，监督决定藏在余音背后暗中调查。</span></p><ul><li><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.11 10：24</span></li></ul><p><span style=\\\"color: rgb(59, 59, 59);\\\">监督出门闲逛，在码头发现了6.9的停运公告，凛阳戒严了。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">下午三点，监督来到和南渚的碰头处，三两下就从南渚的话里套出出世间人心不齐、有人试图将ta的目光引向天鹿。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">晚上九点，监督和筱筱联络互通情报，窗外传来敲击声，监督挂断电话放进舞鹤织雪。</span></p><p><span style=\\\"color: rgb(59, 59, 59);\\\">舞鹤织雪故意透露自己在出世间不被教主信', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 11:12:41', 40);
