INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (289, '用户头像', 2, 'com.ruoyi.project.system.controller.SysProfileController.avatar()', 'POST', 1, 'xingfeng', '协作', '/system/user/profile/avatar', '182.88.220.110', 'XX XX', '', '{\"msg\":\"操作成功\",\"imgUrl\":\"https://r.qianqiu.info/admin/avatar/2025/02/14/5adb8p7xh0ff09po6qt7zcxzm_20250214130416A016.jpg\",\"code\":200}', 0, NULL, '2025-02-14 13:04:16', 62);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (290, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">前路迢迢，凶险未知。我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——</span></p>\",\"id\":5,\"params\":{},\"sTime\":\"1121年4月25日\",\"sort\":10200,\"summary\":\"<blockquote></blockquote>\",\"title\":\"00#森罗\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:05:54\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:05:54', 24);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (291, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,瞳,苏筱,舞鹤织雪,十手卫\",\"desc\":\"<p><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">那些隐藏在谎言表象之下的求救讯号，是否也需要回应。</span></p>\",\"id\":6,\"params\":{},\"sTime\":\"1121年4月29日\",\"sort\":10300,\"summary\":\"<blockquote></blockquote>\",\"title\":\"01#世出世间事\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:06:09\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:06:09', 19);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (292, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督\",\"desc\":\"<p><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">他们在帷幕之后，瞭望着一场暴雨的开始。</span></p>\",\"id\":7,\"params\":{},\"sTime\":\"1121年5月10日\",\"sort\":10400,\"summary\":\"<blockquote></blockquote>\",\"title\":\"02#雨中人\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:06:21\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:06:21', 16);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (293, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">昨日之因，结今日之果。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">今日之因，又将导向怎样的未来？</span></p>\",\"id\":8,\"params\":{},\"sTime\":\"1121年5月30日\",\"sort\":10500,\"summary\":\"<blockquote></blockquote>\",\"title\":\"03#恶象因果\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:06:34\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:06:34', 14);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (294, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">那人如流星般转瞬即逝，却有后来者甘愿成为逐星之人。</span></p>\",\"id\":9,\"params\":{},\"sTime\":\"1121年5月31日\",\"sort\":10600,\"summary\":\"<blockquote></blockquote>\",\"title\":\"04#劣种\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:06:42\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:06:42', 17);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (295, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"言御,言雀\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">在无声中呼救，于缄默中幸存。</span></p>\",\"id\":10,\"params\":{},\"sTime\":\"1121年6月02日\",\"sort\":10700,\"summary\":\"<blockquote></blockquote>\",\"title\":\"05#非自愿幸存\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:06:59\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:06:59', 43);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (296, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"鸢\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">夜晚荒凉，万物静寂。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">你将内心的一切说给花丛，随后摘下一朵——</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">送给了我。</span></p>\",\"id\":11,\"params\":{},\"sTime\":\"1121年6月05日\",\"sort\":10800,\"summary\":\"<blockquote></blockquote>\",\"title\":\"06#如我垂怜\",\"type\":\"主线剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:07:09\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:07:09', 41);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (297, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞,冰舞ぜ紫灵猫\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":10900,\"summary\":\"<p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\\\"line-height: 2;\\\"><br></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\\\"text-indent: 2em; ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:07:19', 36);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (298, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">我们将在「未来」重逢</span></p>\",\"id\":4,\"params\":{},\"sTime\":\"1123年10月27日\",\"sort\":10100,\"summary\":\"<blockquote>这里填写故事梳理</blockquote>\",\"title\":\"序章#灾厄中心\",\"type\":\"间章剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:09:28\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:09:28', 18);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (299, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">我们将在「未来」重逢</span></p>\",\"id\":4,\"params\":{},\"sTime\":\"1123年10月27日\",\"sort\":10100,\"summary\":\"<blockquote>这里填写故事梳理Vein：现在是森罗时间1123年10月27日 17:52</blockquote><hr/><p>Vein：白荆科技首席执行官监督，身份验证成功</p><p>Vein：欢迎回家</p><p><br></p><p>广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p><br></p><p>？？？：唔……天隙通道…………</p><p>？？？：……你终于来了。</p><p>监督：什——！</p><p><br></p><p>广播：这里是海临特殊事件应急指挥部。</p><p>广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p>广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p><br></p><p>监督：………………</p><p>监督：刚才看见的……是幻觉？还是别的什么……</p><p>监督：这里是……中心商业区……发生什么事了？</p><p>监督：不对，我为什么在这里？我明明记得自己是在办——</p><p><br></p><p>通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p>通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p>通讯中的少女：最好再催一催车队，让他们快些出发。</p><p>通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p><br></p><p>监督：……筱筱？</p><p><br></p><p>苏筱：监督！</p><p>苏筱：你怎么还在这里？！</p><p>苏筱：我们不是已经说好了吗？</p><p>苏筱：你是护送任务的最佳人选，如果途中遇到袭击，你的能力就是我们的最后一道保障——</p><p>苏筱：你怎么又折回来了？</p><p><br></p><p>监督：筱筱，我好像遇到了一些问题……唔！</p><p><br></p><p>？？？：……未来……</p><p>？？？：……藏于灾厄中心……</p><p><br></p><p>监督：………………</p><p>监督：我晕过去了吗？</p><p><br></p><p>苏筱：没有，只是突然开始走神，怎么喊也不听……</p><p>苏筱：你的状态有些不对劲，是在护送途中遇见什么事了吗？</p><p><br></p><p>监督：我也不知道。</p><p>监督：先不说这个，筱筱，我记得我们之前明明还在赶往天隙禁区的路上……</p><p><br></p><p>苏筱：哎呀！这种时候就别再提禁区的事了！天隙通道的异变引发了大面积的空问扭曲，现在靠近说不准就要被传送到哪个未知世界！</p><p>苏筱：所有人都在撒离，我们为什么还要回去？</p><p><br></p><p>监督：（为什么这一切看起来都不太对劲……）</p><p><br></p><p>苏筱：为什么不说话？</p><p>苏筱：监督，你一定要冒这个险吗？</p><p><br></p><p>监督：筱筱，从见面开始，你为什么一直叫我\\\"监督\\\"？</p><p><br></p><p>苏筱：你是白荆科技的首席执行官，不叫\\\"监督\\\"还能叫你什么？</p><p><br></p><p>监督：…………</p><p><br></p><p>苏筱：…………</p><p><br></p><p>监督：……算了，现在不是讨论这个的时候。</p><p>监督：我必须去禁区中心重新确认天隙通道的异变情况，你要一起吗？</p><p><br></p><p>苏筱：虽然有时候真不知道你到底在想些什么。但是既然是你坚持的，就一定有你的道理。</p><p>苏筱：走吧~在这方面，我从来只会跟你的票。</p><p><br></p>\",\"title\":\"序章#灾厄中心\",\"type\":\"间章剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:17:33\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:17:33', 20);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (300, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.110', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"<p><span style=\\\"color: rgb(0, 0, 0); font-size: 14px;\\\">我们将在「未来」重逢</span></p>\",\"id\":4,\"params\":{},\"sTime\":\"1123年10月27日\",\"sort\":10100,\"summary\":\"<blockquote>本章节暂无概要梳理，待添加</blockquote><hr/><p>Vein：白荆科技首席执行官监督，身份验证成功</p><p>Vein：欢迎回家</p><p><br></p><p>广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p><br></p><p>？？？：唔……天隙通道…………</p><p>？？？：……你终于来了。</p><p>监督：什——！</p><p><br></p><p>广播：这里是海临特殊事件应急指挥部。</p><p>广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p>广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p><br></p><p>监督：………………</p><p>监督：刚才看见的……是幻觉？还是别的什么……</p><p>监督：这里是……中心商业区……发生什么事了？</p><p>监督：不对，我为什么在这里？我明明记得自己是在办——</p><p><br></p><p>通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p>通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p>通讯中的少女：最好再催一催车队，让他们快些出发。</p><p>通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p><br></p><p>监督：……筱筱？</p><p><br></p><p>苏筱：监督！</p><p>苏筱：你怎么还在这里？！</p><p>苏筱：我们不是已经说好了吗？</p><p>苏筱：你是护送任务的最佳人选，如果途中遇到袭击，你的能力就是我们的最后一道保障——</p><p>苏筱：你怎么又折回来了？</p><p><br></p><p>监督：筱筱，我好像遇到了一些问题……唔！</p><p><br></p><p>？？？：……未来……</p><p>？？？：……藏于灾厄中心……</p><p><br></p><p>监督：………………</p><p>监督：我晕过去了吗？</p><p><br></p><p>苏筱：没有，只是突然开始走神，怎么喊也不听……</p><p>苏筱：你的状态有些不对劲，是在护送途中遇见什么事了吗？</p><p><br></p><p>监督：我也不知道。</p><p>监督：先不说这个，筱筱，我记得我们之前明明还在赶往天隙禁区的路上……</p><p><br></p><p>苏筱：哎呀！这种时候就别再提禁区的事了！天隙通道的异变引发了大面积的空问扭曲，现在靠近说不准就要被传送到哪个未知世界！</p><p>苏筱：所有人都在撒离，我们为什么还要回去？</p><p><br></p><p>监督：（为什么这一切看起来都不太对劲……）</p><p><br></p><p>苏筱：为什么不说话？</p><p>苏筱：监督，你一定要冒这个险吗？</p><p><br></p><p>监督：筱筱，从见面开始，你为什么一直叫我\\\"监督\\\"？</p><p><br></p><p>苏筱：你是白荆科技的首席执行官，不叫\\\"监督\\\"还能叫你什么？</p><p><br></p><p>监督：…………</p><p><br></p><p>苏筱：…………</p><p><br></p><p>监督：……算了，现在不是讨论这个的时候。</p><p>监督：我必须去禁区中心重新确认天隙通道的异变情况，你要一起吗？</p><p><br></p><p>苏筱：虽然有时候真不知道你到底在想些什么。但是既然是你坚持的，就一定有你的道理。</p><p>苏筱：走吧~在这方面，我从来只会跟你的票。</p><p><br></p>\",\"title\":\"序章#灾厄中心\",\"type\":\"间章剧情\",\"updateBy\":\"xingfeng\",\"updateTime\":\"2025-02-14 13:17:59\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-14 13:17:59', 18);
