INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (348, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"墨惜雨\",\"chars\":\"百里屠苏,十手卫，红玉,欧阳少恭\",\"desc\":\"<p><span style=\\\"color: rgb(102, 102, 102); background-color: rgba(255, 255, 255, 0.9);\\\">你想要去“外面”吗？</span></p>\",\"id\":16,\"otext\":\"<p><br></p>\",\"params\":{},\"sTime\":\"1111年2月1日\",\"sort\":100150,\"summary\":\"<p><br></p>\",\"title\":\"雪中春信·魔盒\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:31:36\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:31:36', 25);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (349, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"墨惜雨\",\"chars\":\"百里屠苏,十手卫，红玉,欧阳少恭\",\"desc\":\"<p><span style=\\\"color: rgb(102, 102, 102); background-color: rgba(255, 255, 255, 0.9);\\\">你想要去“外面”吗？</span></p>\",\"id\":16,\"otext\":\"<p><br></p>\",\"params\":{},\"sTime\":\"1111年2月1日\",\"sort\":10150,\"summary\":\"<p><br></p>\",\"title\":\"雪中春信·魔盒\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:46:53\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:46:54', 340);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (350, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"我们将在「未来」重逢\",\"id\":4,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：白荆科技首席执行官监督，身份验证成功</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：欢迎回家</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：唔……天隙通道…………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：……你终于来了。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：什——！</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：这里是海临特殊事件应急指挥部。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：刚才看见的……是幻觉？还是别的什么……</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：这里是……中心商业区……发生什么事了？</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：不对，我为什么在这里？我明明记得自己是在办——</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：最好再催一催车队，让他们快些出发。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：……筱筱？</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱：监督！</p><p style=\\\"text-alig', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:47:10', 66);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (351, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"我们将在「未来」重逢\",\"id\":4,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：白荆科技首席执行官监督，身份验证成功</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：欢迎回家</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：唔……天隙通道…………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：……你终于来了。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：什——！</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：这里是海临特殊事件应急指挥部。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：刚才看见的……是幻觉？还是别的什么……</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：这里是……中心商业区……发生什么事了？</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：不对，我为什么在这里？我明明记得自己是在办——</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：最好再催一催车队，让他们快些出发。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：……筱筱？</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱：监督！</p><p style=\\\"text-alig', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:47:25', 56);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (352, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"我们将在「未来」重逢\",\"id\":4,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：白荆科技首席执行官监督，身份验证成功</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：欢迎回家</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：唔……天隙通道…………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：……你终于来了。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：什——！</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：这里是海临特殊事件应急指挥部。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：刚才看见的……是幻觉？还是别的什么……</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：这里是……中心商业区……发生什么事了？</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：不对，我为什么在这里？我明明记得自己是在办——</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：最好再催一催车队，让他们快些出发。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：……筱筱？</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱：监督！</p><p style=\\\"text-alig', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:47:34', 60);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (353, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"chars\":\"曲观玄\",\"createBy\":\"洛天依\",\"createTime\":\"2025-02-15 22:48:33\",\"desc\":\"<p>曲观玄创建白荆科技前身“白荆研究院”</p>\",\"id\":17,\"params\":{},\"sTime\":\"1113年\",\"sort\":1,\"summary\":\"<p><br></p>\",\"title\":\"曲观玄\",\"type\":\"角色故事\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:48:33', 30);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (354, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"chars\":\"曲观玄\",\"desc\":\"<p>曲观玄创建白荆科技前身“白荆研究院”</p>\",\"id\":17,\"params\":{},\"sTime\":\"1113年\",\"sort\":11130000,\"summary\":\"<p><br></p>\",\"title\":\"曲观玄\",\"type\":\"角色故事\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:49:14\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:49:14', 47);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (355, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"墨惜雨\",\"chars\":\"百里屠苏,十手卫，红玉,欧阳少恭\",\"desc\":\"<p><span style=\\\"color: rgb(102, 102, 102); background-color: rgba(255, 255, 255, 0.9);\\\">你想要去“外面”吗？</span></p>\",\"id\":16,\"otext\":\"<p><br></p>\",\"params\":{},\"sTime\":\"1111年2月1日\",\"sort\":11110201,\"summary\":\"<p><br></p>\",\"title\":\"雪中春信·魔盒\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:49:27\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:49:27', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (356, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄\",\"desc\":\"前路迢迢，凶险未知。<br>我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——\",\"id\":5,\"otext\":\"<ul><li style=\\\"text-align: start; line-height: 1.5;\\\"><strong>S0-1 天隙禁区</strong></li></ul><p style=\\\"text-align: start; line-height: 1.5;\\\">**战斗前**</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein: 现在是森罗时间1121年4月25日，13:52。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein: 白荆科技首席执行官监督（权限交接中），身份验证成功。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein: 欢迎回家。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: ……………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein: 尊敬的首席执行官（权限交接中），请输入指令。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein: 尊敬的首席执行官（权限交接中），指令输入时间过长，是否取消操作？</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: ……………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: ……嗯，取消吧。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: （森罗……海临……我回来了？）</p><p style=\\\"text-align: start; line-height: 1.5;\\\">垂在身侧的手不自觉地抚上心口。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">那种被利器穿胸而过的尖锐痛感仍未散去，但伤口却消失不见了。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: …………………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: （之前发生的那些事情……）</p><p style=\\\"text-align: start; line-height: 1.5;\\\"><br></p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？: 监督！这里！</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督: ——！</p><p style=\\\"text-align: start; line-height: 1.5;\\\"><br></p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱: 出了一点小意外，让你久等啦~</p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱: 所属世界：森罗（白荆科技）</p><p style=\\\"text-align: start; line-height: 1.5;\\\">世界编号：PD-0000053XXL42S-Ⅱ</p><p style=\\\"text-align: start; line-height: 1.5;\\\">“我”的小师妹，白荆科技初级研究员。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">目前还处于学习阶段，并在监督办公室兼任行政助理一职。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱: 走吧，快上车~天隙禁区那边还等着我们过去呢。</p><p style=\\\"text-align: start; line-heig', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:49:44', 76);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (357, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,瞳,苏筱,舞鹤织雪,十手卫\",\"desc\":\"那些隐藏在谎言表象之下的求救讯号，是否也需要回应。\",\"id\":6,\"params\":{},\"sTime\":\"1121年4月29日\",\"sort\":11210429,\"summary\":\"<ul><li>S1-1 混乱序曲</li></ul><p>白荆科技·X能源研究室</p><p>1121-04-29 17:54 总部81层</p><p><br></p><p>瞳与监督讨论了最新的X辐射检验报告，结果显示监督的细胞异化率和异常活跃指数均为0%，异化风险等级为N级，表明监督并非细胞异化综合征的易感人群。监督对此感到失望，并询问是否存在从非易感人群转变为同调者的可能性。瞳解释，理论上可行，但早年海外实验室的尝试以失败告终，被植入者出现严重排异反应，最终死亡。</p><p><br></p><p>监督提到克里斯汀的死因让自己对体质产生了怀疑，瞳则提醒监督，曲观玄辞职后，监督的研究课题已经停摆很久，要求其一周内提交最新的实验设计和原始数据。与此同时，苏筱通过留言催促监督下班，并提到两人约定一起喝奶茶散心。</p><p><br></p><p>---</p><p><br></p><p>白荆科技·正门</p><p>1121-04-29 18:03</p><p><br></p><p>监督与苏筱汇合，苏筱已经喝完了自己的奶茶，并毫不客气地捧起了监督的那杯。监督告诉苏筱，瞳要求他们明天一起去研究室报到，苏筱对此感到惊讶。</p><p><br></p><p>就在这时，一个男孩突然从角落跑出来，撞在苏筱的腰上，导致她的奶茶洒在裙子上。男孩道歉后，又朝监督撞来，监督扶住了他。男孩随后鞠躬离开，监督发现衣兜里多了一张纸条，上面写着：“对不起，冒昧地用这种方式打扰您。前几天禁区的事我在新闻上看到了，思索再三，我想我必须提醒您，引发禁区事件的始作俑者就在今晚八点，垂花街口。救救我们，救救孩子。”</p><p><br></p><p>苏筱看到纸条后，惊讶地询问这是否是刚才那个男孩塞给监督的。监督对此感到困惑，意识到这可能与禁区事件的幕后黑手有关。</p><p><br></p><ul><li>S1-2 苦难温床</li></ul><p>战斗前</p><p>雅松区·垂花街</p><p>1121-04-29 19:34 熔岩烤肉</p><p><br></p><p>监督与苏筱在垂花街的熔岩烤肉店等待与写信人见面。两人讨论了信件的内容和可能的意图，监督认为写信人可能想找的是曲观玄，而自己穿着白荆科技的衣服是为了表明自己可以代表曲观玄。苏筱提到旧城区居民对同调者和白荆科技的态度通常是“敬而远之”，不支持、不交流、不发声。</p><p><br></p><p>朱阿姨为她们送上了特制冰粉，并提到最近旧城区不太平，出现了几起同调者伤人的案件，导致居民人心惶惶。朱阿姨劝她们不要再冒险开发X能源，但监督表示她们有坚持下去的理由。</p><p><br></p><p>苏筱感叹旧城区仿佛被按下了暂停键，停留在天隙事件发生的那一年，与新城区的快速发展形成鲜明对比。监督认为，X能源的发掘与提取建立在旧城区居民家破人亡的记忆之上，很难治愈他们的创伤。</p><p><br></p><p>时间流逝，垂花街口始终没有出现要等的人。就在两人准备离开时，监督注意到路口有一个红衣服的女孩一直看着她们。女孩突然跑过来，向她们求救，喊道：“白荆科技？求求你们……救救我！有人要——”</p><p><br></p><ul><li>S1-3 求救者</li></ul><p>战斗后</p><p><br></p><p>监督与苏筱在垂花街口处理了一起袭击事件，袭击者精神状态异常，最终被R.E.D.副队长十手卫带走。十手卫提到，旧城区最近发生了多起同调者伤人的案件，但凶手是否为同调者尚未确定。这些案件与一桩旧案有关，十手卫的徒弟刑舟和专案组在侦办旧案时失踪，至今下落不明。</p><p><br></p><p>遇袭少女千鹤承认自己是写信求救的人，并表示找白荆科技是因为他们愿意前来帮助。十手卫希望监督和苏筱能暂时照看千鹤，并劝她到R.E.D.配合问话。十手卫透露，旧城区的情况最近变得复杂，水越来越浑。</p><p><br></p><p>随着战术防御终端的屏障取消，周围的人群逐渐散去。千鹤向监督自我介绍，监督也表明了自己的身份。</p><p><br></p><ul><li>S1-4 强势介入</li></ul><p>战斗后</p><p>雅松区·垂花街</p><p>1121-04-29 20:15</p><p><br></p><p>千鹤与监督、苏筱的对话被自称“星辰之子”的南渚打断。南渚声称千鹤陷害了他的朋友群晏（即之前的袭击者），', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:49:55', 41);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (358, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督\",\"desc\":\"他们在帷幕之后，瞭望着一场暴雨的开始。\",\"id\":7,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\"><br></p>\",\"params\":{},\"sTime\":\"1121年5月10日\",\"sort\":11210510,\"summary\":\"<p>S2-1 曲外之音</p><p>西旻大剧院</p><p>森罗历1121-05-10 16:35</p><p><br></p><p>监督与白荆科技的同僚们参加杜望的音乐会，剧院外人群拥挤，气氛热烈。霍冉兴奋地谈论杜望的八卦，而监督则对音乐会的人气感到意外。</p><p><br></p><p>音乐会开始前，VIP席的众人轻松交谈，霍冉提到传闻中的神秘嘉宾可能是云无月。与此同时，隔壁包厢的白衣女人与神秘少年“提里”讨论一场即将发生的晶石交易，提里决定单独行动阻止交易。</p><p><br></p><p>音乐会正式开始时，杜望的琴声瞬间平息了全场的喧嚣，监督试图查看曲目单，却发现周围的人已经沉浸在音乐中，无人回应。</p><p><br></p><p>S2-2 意识幻城</p><p>战斗前</p><p><br></p><p>监督发现自己身处一个寂静的空间，疑似杜望的意识幻城。云无月出现，解释这是杜望的异核能力创造的幻城，需要唤醒被困的人才能脱离。监督与云无月合作，试图找到其他同调者。</p><p><br></p><p>战斗中</p><p><br></p><p>监督和云无月在幻城中遇到了由负面情绪凝聚的敌人。通过聚光灯驱散恶意，他们逐渐接近真相。</p><p><br></p><p>战斗后</p><p><br></p><p>霍冉加入，监督解释这可能是杜望的异核觉醒事件。云无月指出杜望并非初次觉醒，可能是故意为之。霍冉虽然对杜望的行为感到失望，但仍决定帮助救人。监督和云无月继续寻找其他被困者。</p><p><br></p><p>S2-3 笼中鸟</p><p>战斗前</p><p><br></p><p>监督、霍冉和云无月进入另一个意识幻城，发现小鸢的朋友七叶患有X细胞异化综合征。小鸢试图通过白荆科技的关系获取阻断药，但瞳指出七叶的病情已无法逆转。</p><p><br></p><p>战斗中</p><p><br></p><p>杜望的外力介入，试图通过负面情绪控制小鸢的意识。监督等人成功击退恶意，保护了小鸢。</p><p><br></p><p>战斗后</p><p><br></p><p>小鸢恢复清醒，监督安慰她并表示愿意帮助她。云无月解释杜望可能已经锁定他们，监督意识到杜望的意图可能是通过异核能力控制他人。小鸢最终同意监督在事件结束后拜访七叶。</p><p><br></p><p>S2-4 海醒时分</p><p>战斗前</p><p><br></p><p>监督、霍冉、云无月和鸢进入艾摩诃的记忆幻城，发现夜摩世界的“海醒季”提前到来。艾摩诃试图阻止哥哥阿兰那出城参战，但阿兰那坚持履行战士的职责。</p><p><br></p><p>战斗中</p><p><br></p><p>艾摩诃的情绪激动，揭示了他对哥哥的深厚情感和对夜摩未来的担忧。云无月发现杜望的身影出现在城外，暗示他可能正在操控这场幻境。</p><p><br></p><p>战斗后</p><p><br></p><p>艾摩诃的内心挣扎和杜望的出现，使得局势更加复杂。监督等人必须尽快找到艾摩诃，并应对杜望的潜在威胁。</p><p><br></p><p>S2-5 恐惧回响</p><p>战斗前</p><p><br></p><p>艾摩诃因过度消耗陷入深眠，霍冉和鸢决定留下照顾他。监督和云无月继续寻找苏筱，发现她的意识幻城与其他人的不同，似乎是多重幻境的交迭。</p><p><br></p><p>战斗中</p><p><br></p><p>监督和云无月进入苏筱的意识幻城，看到她童年的记忆片段，揭示了她作为战争孤儿的过去。幻城突然崩塌，监督和云无月努力抓住苏筱，防止她坠入深渊。</p><p><br></p><p>战斗后</p><p><br></p><p>苏筱逐渐清醒，意识到自己身处杜望的意识幻城。幻城再次扭曲，云无月指出杜望现身，并引导监督和苏筱跟随她，寻找离开幻城的方法。</p><p><br></p><p>S2-6 尘中网</p><p>战斗前</p><p><br></p><p>监督、苏筱和云无月进入杜望的意识幻城，发现他童年的记忆片段，揭示了他与父母之间的复杂关系。杜望的父母对他的期望和失望，以及他们对他的忽视和争吵，深深影响了他的成长。</p><p><br></p><p>战斗中</p><p><br></p><p>监督试图与杜望沟通', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:50:08', 36);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (359, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督\",\"desc\":\"昨日之因，结今日之果。<br>今日之因，又将导向怎样的未来？\",\"id\":8,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\"><br></p>\",\"params\":{},\"sTime\":\"1121年5月30日\",\"sort\":11210530,\"summary\":\"<p>S3-1 第一案·怪物</p><p>战斗前</p><p><br></p><p>故事发生在海临医疗中心，柳业医生与病人交谈时表现出对“怪化病”（X细胞异化综合征）的歧视。白汲医生前来与柳业讨论近期误诊率上升的问题，并暗示柳业可能涉及精神异变。</p><p><br></p><p>战斗中</p><p><br></p><p>白汲被绑架，直播中他替绑匪转达了三个需求：公开天隙事件和X辐射的真实情况、公开X细胞异化综合征的真实信息、官方承诺负责感染者的医疗费用和赔偿。直播结束后，监督和苏筱尝试追踪直播地址，但未能成功。</p><p><br></p><p>战斗后</p><p><br></p><p>十手卫与监督和苏筱通话，询问绑匪针对白荆科技的可能性以及白汲的可信度。监督为白汲担保，并表示可以协助提供资料。与此同时，R.E.D.组员通知十手卫，刑侦部门抓到了一名与直播有关的嫌疑人，要求白荆科技派人协助调查。</p><p><br></p><p>S3-2 第二案·凶宅</p><p>战斗前</p><p><br></p><p>故事发生在雅松区的柏露园小区，逸虚（易虚舟）作为私家侦探，受雇调查柳业的婚外情。他潜入柳家，发现柳业和其夫人袁一念的尸体，现场被大火烧毁。逸虚在调查过程中发现柳业的行为异常，尤其是夜间频繁出入垂花街。与此同时，白汲被绑架的直播事件仍在进行，绑匪要求公开天隙事件和X细胞异化综合征的真实信息。</p><p><br></p><p>战斗中</p><p><br></p><p>逸虚在柳家现场发现了焦尸、血脚印、儿童水杯等线索，推测柳业可能涉及违禁药品交易。他试图逃离现场，但被巡警抓住。在R.E.D.的审讯中，逸虚向十手卫和监督汇报了自己的调查结果，推测柳家案件可能与绑架案有关联，并提出了“黑吃黑”的可能性。</p><p><br></p><p>战斗后</p><p><br></p><p>十手卫决定将逸虚交给刑侦部门进一步审讯。就在此时，一名身着黑色长风衣的男人破门而入，直呼逸虚的本名“易虚舟”，暗示两人之间有过往的纠葛，案件背后的真相逐渐浮出水面。</p><p><br></p><p>S3-3 侦查方向</p><p>战斗前</p><p><br></p><p>崔远之抵达R.E.D.，要求取回外编证，并建议将逸虚送回九旻基地。十手卫同意崔远之的征调，并安排他去解剖中心进行尸检。与此同时，R.E.D.与白荆科技合作，准备通过CHATMORE发布绑匪要求的信息。</p><p><br></p><p>战斗中</p><p><br></p><p>绑匪再次开启直播，要求公开重症者信息和提供阻断药。白荆科技通过内部通讯系统成功接收到白汲的信号，确认他安全且能够与外界联系。逸虚通过分析绑匪的言行，推测绑匪可能是柳业，尽管柳业已被认定为柏露园小区案件的死者之一。</p><p><br></p><p>战斗后</p><p><br></p><p>R.E.D.组员对逸虚的推测表示怀疑，但十手卫决定继续追踪这一线索。白荆科技和R.E.D.继续合作，试图通过绑匪的要求和内部通讯系统获取更多信息，以尽快解救白汲和人质。</p><p><br></p><p>S3-4 第三案·柳叶刀</p><p>战斗前</p><p><br></p><p>崔远之抵达解剖中心，与法医一起研究柳业和袁一念的尸体。通过翻阅R.E.D.的档案，崔远之发现“柳叶刀”连环杀人案的作案手法与柳家的案件有相似之处，推测柳业可能与连环杀人案有关。与此同时，逸虚在R.E.D.会议室继续分析案件，提出柳业可能是绑匪的假设，并推测柳业的儿子柳泊远可能患有X细胞异化综合征。</p><p><br></p><p>战斗中</p><p><br></p><p>白汲通过内部通讯系统与R.E.D.保持联系，试图与绑匪柳业谈判。白汲提出用阻断药的资料换取自己的自由，并暗示柳业可以通过他逃离海临。柳业虽然半信半疑，但最终同意交易，并决定由自己指定交易地点。</p><p><br></p><p>战斗后</p><p><br></p><p>R.E.D.成功定位到柳业的位置，准备展开行动。田偌前往福利院寻找柳业的养子小池，以获取更多信息。与此同时，逸虚通过柳业家窗外发现的糖果，推测田莹可能与柳泊远有联系。白汲的谈判策略逐渐奏效，R.E.D.团队也在', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:50:15', 37);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (360, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">那人如流星般转瞬即逝，却有后来者甘愿成为逐星之人。</span></p>\",\"id\":9,\"otext\":\"<p><br></p>\",\"params\":{},\"sTime\":\"1121年5月31日\",\"sort\":11210531,\"summary\":\"<p> S4-1 始作俑者</p><p><br></p><p>森罗历1121年5月31日，昊苍和祸烨莲在伊南纳-沙玛什边境的阿达帕平原追踪弗雷德里克·达弗戴尔，发现他近期频繁在固定区域徘徊，似乎寻找某样东西。昊苍推测弗雷的行动可能与“出世间”有关，而祸烨莲则认为弗雷只是“圣冕”的傀儡，背后另有主导者。</p><p><br></p><p>与此同时，伊南纳驻军遭遇沙玛什的“沙虫”袭击，随后一场突如其来的巨大风旋引发士兵们的恐慌，认为这是神迹显灵。白荆科技的飞行器因异常能量波动失控坠毁，监督和狄砚被伊南纳士兵捕获并关押。</p><p><br></p><p>监督在昏迷中回忆起三年前与曲观玄的对话，曲观玄坚持将X晶石能源化视为保全森罗的唯一解法，而白汲则质疑其选择的正确性，最终选择离开白荆科技。监督在坠机后醒来，发现自己身处伊南纳监狱，与狄砚一同被关押。</p><p><br></p><p>在监狱中，监督和狄砚遇到一名沙玛什雇佣兵，对方言语挑衅，试图试探他们的来历。监督冷静应对，但内心意识到伊南纳与海临的环境截然不同，局势更加复杂。</p><p><br></p><p> S4-2 越狱</p><p><br></p><p>森罗历1121年5月31日16时41分，监督和狄砚被关押在伊南纳军营的监狱中，沙玛什雇佣兵提醒他们不要指望伊南纳士兵的仁慈，并提议合作越狱。他透露自己受沙玛什委托在阿达帕沙漠寻找“珍宝”，并认为伊南纳士兵会在消息走漏前处决他们。</p><p><br></p><p>监督和狄砚同意合作，但狄砚试图破坏笼门时发现铁栏经过强化，无法轻易打破。沙玛什雇佣兵展现出同调者的力量，轻松击倒笼门并缴获武器。三人分头突围，雇佣兵吸引主要火力，监督和狄砚趁机逃脱。</p><p><br></p><p>17时22分，监督和狄砚成功甩掉追兵，计划等雇佣兵团与伊南纳士兵交火后再伺机离开。他们发现伊南纳军营中混入了提丰子体，推测这与舞鹤织雪的行动有关。突然，监狱方向传来震动，黑色雾气开始蔓延，狄砚发现金发身影在黑雾深处，两人决定立即逃离。</p><p><br></p><p> S4-3 小小监督</p><p><br></p><p>战斗前</p><p>森罗历1121年5月31日17时35分，苏筱在沙玛什的未知小巷中追捕舞鹤织雪。舞鹤织雪声称自己救了苏筱，并透露关押她们的地方是毒气室。苏筱用X能禁制手铐控制住舞鹤织雪，逼问阻断药资料的下落。舞鹤织雪声称资料已被转移，并透露自己来南半球的目的是再偷一份资料。</p><p><br></p><p>苏筱试图联系昊苍和监督，但通讯信号出现问题。最终，她成功联系到昊苍，得知监督和狄砚下落不明，伊南纳军营情况混乱，到处都是尸体。</p><p><br></p><p>战斗中</p><p>监督和狄砚在伊南纳的未知街道中遭遇追兵。他们利用废弃的液化气罐制造爆炸，成功击退追兵。监督发现追兵身上有奇怪的沙子屏障，但沙子可以被击散。尽管追兵不断增援，监督和狄砚仍设法脱身。</p><p><br></p><p>战斗后</p><p>17时44分，监督和狄砚躲藏在巷中，观察到伊南纳士兵对他们的追捕并不十分在意。狄砚推测，只要他们不在军营，伊南纳士兵并不关心他们的死活。监督和狄砚决定继续撤离，但突然，一只手从监督背后伸出，狄砚惊呼提醒。</p><p><br></p><p> S4-4 一线生机</p><p><br></p><p>战斗前</p><p>森罗历1121年5月31日17时52分，昊苍和祸烨莲在伊南纳军营调查风暴后的混乱。祸烨莲感知到强烈的神力残留，并发现监狱深处有黑雾涌动，黑雾对祸烨莲表现出亲昵，但被他斩散。他们发现大量伊南纳士兵和提丰子体的尸体，尸体呈现出与X晶石相似的结晶状态。祸烨莲推测这是“圣冕”在恢复自身力量，并决定离开营地寻找埃斯特班。</p><p><br></p><p>昊苍因目睹惨状情绪失控，祸烨莲用巨镰逼他冷静，提醒他不要浪费力量，凶手死亡才是对亡者最好的慰藉。昊苍最终恢复理智，与祸烨莲一同离开。</p><p><br></p><p>战斗中</p><p>监督和狄砚在伊南纳的未知街道中遭遇伊南纳上尉米达斯·奈格尔图。米达斯声称自己已是', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:50:37', 51);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (361, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"言御,言雀\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">在无声中呼救，于缄默中幸存。</span></p>\",\"id\":10,\"params\":{},\"sTime\":\"1121年6月02日\",\"sort\":11210602,\"summary\":\"<blockquote></blockquote>\",\"title\":\"05#非自愿幸存\",\"type\":\"主线剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:50:47\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:50:47', 45);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (362, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"鸢\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">夜晚荒凉，万物静寂。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">你将内心的一切说给花丛，随后摘下一朵——</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">送给了我。</span></p>\",\"id\":11,\"params\":{},\"sTime\":\"1121年6月05日\",\"sort\":11210605,\"summary\":\"<blockquote></blockquote>\",\"title\":\"06#如我垂怜\",\"type\":\"主线剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:50:58\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:50:58', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (363, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞,冰舞ぜ紫灵猫\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"id\":12,\"params\":{},\"sTime\":\"1121年6月08日\",\"sort\":11210608,\"summary\":\"<p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\\\"line-height: 2;\\\"><br></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监督和余音在旅馆交流分析情报，监督认为码头工厂爆炸可能是饵，南渚不能全信但他是目前唯一的不确定因素，所以可以试着交流。</span></p><p style=\\\"text-indent: 2e', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:51:07', 71);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (364, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"缇诗\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">噩梦在将醒未醒时缠身。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">但只要你睁眼。</span></p>\",\"id\":13,\"params\":{},\"sTime\":\"1121年6月09日\",\"sort\":11210609,\"summary\":\"<blockquote></blockquote>\",\"title\":\"炉·心·缇诗\",\"type\":\"间章剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:51:15\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:51:15', 28);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (365, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依\",\"chars\":\"米达斯\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">这是一位胆小鬼的葬身之地，空空的棺椁正在等待它的主人。</span></p>\",\"id\":14,\"params\":{},\"sTime\":\"1121年6月16日\",\"sort\":11210616,\"summary\":\"<blockquote></blockquote>\",\"title\":\"炉·心·米达斯\",\"type\":\"间章剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:51:23\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:51:24', 34);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (366, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞\",\"chars\":\"伊琅相思,监督,苏筱,瓦卡莎,艾摩诃,莫莫\",\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">那些停驻于记忆中的温暖瞬间，便是支撑她存活至今的救命良药。</span></p>\",\"id\":15,\"params\":{},\"sTime\":\"1121年8月03日\",\"sort\":11210803,\"summary\":\"<blockquote></blockquote>\",\"title\":\"人世行者\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:51:33\",\"world\":\"森罗,夜摩\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:51:33', 37);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (367, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"洛天依,奈默\",\"chars\":\"监督,苏筱,曲观玄,阳玲,马尔斯,莫红袖\",\"desc\":\"我们将在「未来」重逢\",\"id\":4,\"otext\":\"<p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：白荆科技首席执行官监督，身份验证成功</p><p style=\\\"text-align: start; line-height: 1.5;\\\">Vein：欢迎回家</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：【一级异变警报】天隙通道直径急速扩张，预计将于12小时内覆盖全部城区，请听到广播的海临居民……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：唔……天隙通道…………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">？？？：……你终于来了。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：什——！</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：这里是海临特殊事件应急指挥部。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：第三批撤离行动现已开始，请中心商业区的滞留人员听从现场工作人员安排，有序离开当前区域。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">广播：请听到广播的幸存者尽快前往救助点，或就近寻找掩体、等待救援，切勿长时问暴露于空旷环境中。</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：………………</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：刚才看见的……是幻觉？还是别的什么……</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：这里是……中心商业区……发生什么事了？</p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：不对，我为什么在这里？我明明记得自己是在办——</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：……对，通讯断了，这次异变波及的范回很广，除海临城外，其他地方都联系不上。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：异变造成的影响已经不只局限于天隙禁区内了，各个地方的异常能量波动指数都在持续上升。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：最好再催一催车队，让他们快些出发。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">通讯中的少女：如果能在路上遇见白荆科技的队伍，就让他们的首席执行官在信号恢复后跟我报个平安……</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">监督：……筱筱？</p><p style=\\\"text-align: start; line-height: 1.5;\\\"> </p><p style=\\\"text-align: start; line-height: 1.5;\\\">苏筱：监督！</p><p style=\\\"text-alig', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:51:41', 43);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (368, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"createBy\":\"洛天依\",\"createTime\":\"2025-02-15 22:52:33\",\"desc\":\"<p>天隙事件爆发</p>\",\"id\":18,\"params\":{},\"sTime\":\"1116年4月1日\",\"sort\":11160401,\"summary\":\"<p><br></p>\",\"title\":\"天隙事件\",\"type\":\"世界描述\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:52:33', 14);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (369, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"createBy\":\"洛天依\",\"createTime\":\"2025-02-15 22:53:41\",\"desc\":\"<p>因森罗历1116年5月7日，金玲区爆发大规模精神异化事件，于7月建立天隙禁区</p>\",\"id\":19,\"params\":{},\"sTime\":\"1116年5月7日\",\"sort\":11160507,\"summary\":\"<p><br></p>\",\"title\":\"天隙禁区\",\"type\":\"世界描述\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:53:41', 14);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (370, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"chars\":\"珑，林，旒珠，崔远之，易虚舟（逸舟），叶秉谦，焰响，赫九逸，北洛（黑曜）\",\"createBy\":\"洛天依\",\"createTime\":\"2025-02-15 22:55:06\",\"desc\":\"<p><span style=\\\"color: rgb(32, 33, 34); background-color: rgb(255, 255, 255); font-size: 14px;\\\">创伤、污秽、鲜血与未流出的眼泪——<br>雨水如死亡般湮没所有。</span></p>\",\"id\":20,\"params\":{},\"sTime\":\"2049年4月1日\",\"sort\":20490401,\"summary\":\"<p><br></p>\",\"title\":\"不逢「缘」\",\"type\":\"幕间剧情\",\"world\":\"黑曜\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:55:06', 17);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (371, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '112.193.245.55', 'XX XX', '{\"author\":\"墨惜雨\",\"chars\":\"百里屠苏,十手卫，红玉,欧阳少恭\",\"desc\":\"<p><span style=\\\"color: rgb(102, 102, 102);\\\">你想要去“外面”吗？</span></p>\",\"id\":16,\"otext\":\"<p><br></p>\",\"params\":{},\"sTime\":\"1111年2月1日\",\"sort\":11110201,\"summary\":\"<p><br></p>\",\"title\":\"雪中春信·魔盒\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-15 22:57:07\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-15 22:57:07', 26);
