INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (465, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞,冰舞ぜ紫灵猫\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/17/lm3epnssunl5murcltixqvpg445df70_20250217120043A011.png\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"children\":[],\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"hasChildren\":false,\"id\":12,\"otext\":\"<p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\\\"line-height: 2;\\\"><br></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:25:13', 281);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (466, '故事线', 1, 'com.ruoyi.project.system.controller.StoryController.add()', 'POST', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/tsg90f6bgo04f0pbtfnjp3iat8j2wbv_20250219094405A017.png\",\"chars\":\"北洛\",\"children\":[],\"createBy\":\"洛天依\",\"createTime\":\"2025-02-19 09:45:04\",\"desc\":\"<p>说出口前，我写下了遗言，也有了遗物</p>\",\"hasChildren\":false,\"id\":38,\"otext\":\"<p>暂无</p>\",\"params\":{},\"sTime\":\"2044年7月2日\",\"sort\":20440702,\"summary\":\"<p>暂无</p>\",\"title\":\"JOYRIDE\",\"type\":\"幕间剧情\",\"world\":\"黑曜\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:45:04', 69);
