INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (475, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/kwa9rfjae9ifgqd9azt3w91b1lbdz8o_20250219095029A026.png\",\"chars\":\"监督，苏筱，岚岚，尤尼\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">当晨光穿透乌云的瞬间，将会有一个更宽广的新世界在你眼前展开。<br>——Bless you, last&amp;best.</span></p>\",\"hasChildren\":false,\"id\":24,\"params\":{},\"parentId\":0,\"sTime\":\"1121年夏\",\"sort\":11210701,\"summary\":\"<p><br></p>\",\"title\":\"苍蓝的达加兹\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:50:31\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:50:31', 90);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (476, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/nlk4z5i2j4icff2ov45alcgjo2s3dr6_20250219095042A027.png\",\"chars\":\"花时，乐无异，雪长夏，筱筱，监督，风清洛，卯绒绒，风晴雪\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">尽情体验吧，这全新的人生。</span></p>\",\"hasChildren\":false,\"id\":21,\"params\":{},\"parentId\":0,\"sTime\":\"1121年6月04日\",\"sort\":11210604,\"summary\":\"<p><br></p>\",\"title\":\"格兰索历险记\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:50:43\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:50:43', 48);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (477, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/iw5s1aykmp1ierxm46s543ge7kpe8b2_20250219095119A028.png\",\"chars\":\"岑缨，监督，凤无梦，琉辛\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">游荡在馆中深处的影子先生已经悄悄离开，而岑缨这边则迎来了几位令人头疼的新成员。</span></p>\",\"hasChildren\":false,\"id\":22,\"params\":{},\"parentId\":0,\"sTime\":\"1121年初夏某日\",\"sort\":11210504,\"summary\":\"<p><br></p>\",\"title\":\"远航者与不朽之影\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:51:22\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:51:22', 48);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (478, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"奈默\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/g4zhut1bd34cxhe70hvqmcf67of2cae_20250219095129A029.png\",\"chars\":\"十手卫,红玉,百里屠苏,监督,苏筱,唐路遥,狄砚,乐无异,昊苍,田偌,紫都,北洛,风清洛,无咎,岑缨,襄铃\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">灿烂的瞬间会在记忆中永远闪耀，直到蜷缩的心重新开始期待，直到往后每日皆是庆典。</span></p>\",\"hasChildren\":false,\"id\":34,\"otext\":\"<p><br></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1121年2月9日\",\"sort\":11210209,\"summary\":\"<p><span style=\\\"font-family: 宋体;\\\">【花车巡游01-0 故地，故人】</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">海临机场 - 通讯中</span></p><p><span style=\\\"font-family: 宋体;\\\">十手卫联系红玉，告知未能接到百里屠苏。红玉担心是否出了意外，但十手卫解释百里屠苏已经入境，并独自购买了前往银铃路的机场快列车票。十手卫请求红玉前往银铃路车站接人，并表示自己会尽快赶到。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">白荆科技·监督办公室 - 通讯中</span></p><p><span style=\\\"font-family: 宋体;\\\">十手卫联系监督，请求他帮忙拖延时间，以便为归队的百里屠苏准备惊喜。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">银铃路地铁站</span></p><p><span style=\\\"font-family: 宋体;\\\">百里屠苏在地铁站被一名旅游推销员搭讪。推销员试图拉他加入雪终节三日游的旅行团，但百里屠苏冷漠拒绝，并表示自己不需要朋友。推销员不依不饶，最终惹恼了百里屠苏，他严厉警告推销员离开。推销员悻悻离去，并暗自嘲讽百里屠苏的孤僻。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">银铃路车站</span></p><p><span style=\\\"font-family: 宋体;\\\">十手卫与红玉赶到车站，发现了百里屠苏的身影。红玉高声呼唤他的名字，百里屠苏转身确认了他们的身份。他向R.E.D.正式报到，完成了归队。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">百里屠苏结束了在九旻基地的训练，独自返回海临。尽管他在途中表现出冷漠与孤僻，但十手卫与红玉的热情迎接为他的归队增添了一丝温暖。R.E.D.的成员们为他准备了惊喜，展现了团队之间的默契与关怀。百里屠苏的归队标志着新的任务与冒险即将开始。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">【花车巡游01-1 花车巡游始发站】</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">义卖会现场</span></p><p><span style=\\\"font-family: 宋体;\\\">十手卫询问百里屠苏为何独自来到义卖会，百里屠苏解释是从群里得知这里有治安管理任务。红玉提醒他刚归队应休假调整，但百里屠苏表示不需要。十手卫调侃红玉的话从她口中说出显得幽默，红玉则强调百里屠苏与自己', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:51:30', 59);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (479, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095157A030.png\",\"chars\":\"监督,苏筱,曲观玄\",\"children\":[],\"desc\":\"<p>现在回想起来……就是在这一天，我们第一次代表这个世界——</p><p>——成功触摸到“回廊”。</p>\",\"hasChildren\":false,\"id\":35,\"params\":{},\"parentId\":0,\"sTime\":\"1119年10月05\",\"sort\":11191005,\"summary\":\"<p><br></p>\",\"title\":\"万象·回忆\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:51:59\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:51:59', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (480, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095207A031.png\",\"chars\":\"监督\",\"children\":[],\"desc\":\"<p>我触摸到了那个世界。</p>\",\"hasChildren\":false,\"id\":36,\"params\":{},\"parentId\":0,\"sTime\":\"1121年4月26日\",\"sort\":11210426,\"summary\":\"<p><br></p>\",\"title\":\"万象\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:52:08\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:52:08', 24);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (481, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/qv6voumig0difjs9zxwv05vi0ftmoew_20250219095213A032.png\",\"chars\":\"监督\",\"children\":[],\"desc\":\"<p>未来，我将与我同谋</p>\",\"hasChildren\":false,\"id\":37,\"params\":{},\"parentId\":0,\"sTime\":\"1121年5月5日\",\"sort\":11210505,\"summary\":\"<p><br></p>\",\"title\":\"蜃楼\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:52:16\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:52:16', 18);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (482, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/iw5s1aykmp1ierxm46s543ge7kpe8b2_20250219095119A028.png\",\"chars\":\"岑缨，监督，凤无梦，琉辛\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">游荡在馆中深处的影子先生已经悄悄离开，而岑缨这边则迎来了几位令人头疼的新成员。</span></p>\",\"hasChildren\":false,\"id\":22,\"params\":{},\"parentId\":0,\"sTime\":\"1121年初夏某日\",\"sort\":11210504,\"summary\":\"<p><br></p>\",\"title\":\"远航者与不朽之影\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:52:27\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:52:27', 20);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (483, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/nlk4z5i2j4icff2ov45alcgjo2s3dr6_20250219095042A027.png\",\"chars\":\"花时，乐无异，雪长夏，筱筱，监督，风清洛，卯绒绒，风晴雪\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">尽情体验吧，这全新的人生。</span></p>\",\"hasChildren\":false,\"id\":21,\"params\":{},\"parentId\":0,\"sTime\":\"1121年6月04日\",\"sort\":11210604,\"summary\":\"<p><br></p>\",\"title\":\"格兰索历险记\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:52:31\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:52:31', 33);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (484, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/cneguq5qjtqvk5x6ogpx76odo0nto2k_20250219095332A033.png\",\"chars\":\"十手卫\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">浮生过眼，要去记住那些平凡的、永远不会出现第二次的瞬间。</span></p>\",\"hasChildren\":false,\"id\":23,\"params\":{},\"parentId\":0,\"sTime\":\"1121年7月\",\"sort\":11210715,\"summary\":\"<p><br></p>\",\"title\":\"底色\",\"type\":\"间章剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-19 09:53:33\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:53:33', 20);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (485, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依,奈默\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/mbgsui47r9b4xfnc9qg8k04sqk14hqn_20250219095340A034.png\",\"chars\":\"米达斯\",\"children\":[],\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">这是一位胆小鬼的葬身之地，空空的棺椁正在等待它的主人。</span></p>\",\"hasChildren\":false,\"id\":14,\"params\":{},\"parentId\":0,\"sTime\":\"1121年6月16日\",\"sort\":11210616,\"summary\":\"<p><span style=\\\"font-family: 宋体;\\\">RB-M-1 橙月</span></p><p><span style=\\\"font-family: 宋体;\\\">米达斯在伊南纳与沙玛什边境的夜晚守夜时，回忆起过去与战神的种种关联。他遇到一名小女孩齐齐和她的父亲巴布姆，巴布姆曾是伊南纳的士兵，因伤退役。齐齐天真地询问米达斯是否是战神，米达斯否认了这一身份。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">随后，枪声打破了宁静，米达斯赶到现场，发现一群伊南纳士兵正在围捕一名身上覆满橙色晶石的男人。米达斯认出了其中一名军官卡尔布，曾是自己的副官。卡尔布对米达斯表现出极大的崇敬，称他为“迦路大人”，并试图说服他回归伊南纳军队。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">米达斯拒绝了卡尔布的提议，并质问他将人命视为何物。卡尔布开枪杀死了那名被围捕的佣兵，声称这是为了米达斯的回归。米达斯深感愧疚，最终决定将佣兵的遗物交给他的团长，履行他的遗愿。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">这一章节通过米达斯与卡尔布的对话，揭示了米达斯对战神身份的挣扎与对战争残酷的反思。卡尔布的狂热信仰与米达斯的人性关怀形成鲜明对比，而米达斯对佣兵遗愿的承诺则象征着他对自己道路的选择。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">RB-M-2 保重</span></p><p><span style=\\\"font-family: 宋体;\\\">伊南纳·阿达帕平原营地 - 森罗历1121年6月16日</span></p><p><span style=\\\"font-family: 宋体;\\\">监督通过监控系统观察到米达斯在营地平民的协助下安葬了西姆。这位佣兵的遗体被斗篷严密包裹，未引起他人注意。米达斯用匕首刻写碑文时，思绪逐渐清晰——他决定先寻找怒蛇的下落，再前往宁胡尔塔哨站。与巴布姆的对话中，米达斯得知怒蛇的兵团曾在边境酒馆活动，而巴布姆对佣兵的敌意源于过往的背叛与伤痛。巴布姆提到，怒蛇曾收拾了“鬣狗佣兵团”，这让他对怒蛇的行踪产生了兴趣。米达斯在告别巴布姆父女后，悄然留下了一把老式手枪、子弹和创伤膏，附上一张写着“路上小心”的纸条。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">伊南纳·边境酒馆 - 森罗历1121年6月16日10:02</span></p><p><span style=\\\"font-family: 宋体;\\\">米达斯踏入酒馆，空气中弥漫着辛辣的气息。酒馆老板费尔南多冷眼旁观，指出米达斯的通缉令虽被撤下，但悬赏仍在。米达斯以五瓶金砂酒的价格换取了情报，得知怒蛇及其兵团因寻找莎拉塔尔的神器而被伊南纳士兵押送至宁胡尔塔。酒馆老板暗示，怒蛇的兵团成员拥有与米达斯相似的力量，这或许是他们被送往哨站的原因。米达斯用一枚士兵荣勋领章换取了防身的手枪和子弹，酒馆老板额外赠送了一瓶创伤膏和一枝塔木紫花，低声说了句“保重”。</span></p><p><span', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:53:43', 42);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (486, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依,奈默\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/8rrhas47zrz5e3rjt55f9pqmhpgwp4s_20250219095347A035.png\",\"chars\":\"缇诗\",\"children\":[],\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">噩梦在将醒未醒时缠身。</span></p><p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">但只要你睁眼。</span></p>\",\"hasChildren\":false,\"id\":13,\"params\":{},\"parentId\":0,\"sTime\":\"1121年6月09日\",\"sort\":11210609,\"summary\":\"<p><span style=\\\"font-family: 宋体;\\\">RB-T-1 烈日之下</span></p><p><span style=\\\"font-family: 宋体;\\\">伊南纳-沙玛什边境小镇 安那基</span></p><p><span style=\\\"font-family: 宋体;\\\">森罗历1121年6月9日，14:47</span></p><p><span style=\\\"font-family: 宋体;\\\">沙玛什士兵在边境发现伊南纳的入侵踪迹，指挥官下令支援。突然，一个白色身影出现在战场，迅速击溃了伊南纳的突击队。伊南纳士兵认出她是莎拉塔尔，曾经的伊南纳战神，但她却宣布自己将代表沙玛什向伊南纳开战。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">沙玛什境内</span></p><p><span style=\\\"font-family: 宋体;\\\">森罗历1121年6月16日，13:37</span></p><p><span style=\\\"font-family: 宋体;\\\">奇美拉佣兵团的成员们在沙漠中逃亡，讨论着最近的追击行动。他们发现沙玛什的追击方式发生了变化，似乎更注重观察而非直接攻击。纳加尔推测沙玛什人对缇诗有所顾虑，可能因为她的特殊能力。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">缇诗表示自己不愿再使用那种“吃人”的能力，纳加尔支持她的决定，强调奇美拉佣兵团将依靠真本事应对敌人。卡拉玛提到几天前出现的“莎拉塔尔”，引发了团队的沉默。纳加尔坚信那个“莎拉塔尔”并非真正的将军，因为真正的莎拉塔尔绝不会与伊南纳或沙玛什合作。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">战斗后</span></p><p><span style=\\\"font-family: 宋体;\\\">奇美拉佣兵团围坐在篝火旁，分享食物和水。卡拉玛质疑纳加尔对莎拉塔尔的看法，纳加尔则强调自己亲眼见证了莎拉塔尔的“复生”，并坚信她的怒火将席卷整个厄亚大陆。缇诗表示自己将与纳加尔站在一起。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">就在此时，米达斯的通讯请求接入，预示着新的任务或危机即将到来。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">这一章节通过奇美拉佣兵团的逃亡与讨论，揭示了莎拉塔尔的身份之谜与团队的内部矛盾。沙玛什的追击与缇诗的能力成为故事的关键点，而米达斯的通讯则暗示着更大的挑战即将展开。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">RB-T-2 飞鸟余温</span></p><p><span style=\\\"font', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 09:53:48', 27);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (487, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '118.116.109.255', 'XX XX', '{\"author\":\"洛天依,奈默\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/17/8i54524sbgebp4hushibf82rkjoeqs8_20250217115925A004.png\",\"chars\":\"监督,狄砚,克里斯汀,霍冉,舞鹤织雪,田偌,昊苍,「洛特斯」,曲观玄\",\"children\":[],\"desc\":\"前路迢迢，凶险未知。<br>我希望，白荆科技的首席执行官做出的每一次取舍，不仅仅是因为利益、舆论或是其他——\",\"hasChildren\":false,\"id\":5,\"otext\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1121年4月25日\",\"sort\":11210425,\"summary\":\"<p style=\\\"text-align: center; line-height: 2;\\\"><a href=\\\"https://wiki.biligame.com/bjhl/%E6%95%85%E4%BA%8B%E7%BA%BF/%E6%A3%AE%E7%BD%97\\\" target=\\\"_blank\\\"><span style=\\\"color: rgb(89, 89, 89); font-size: 15px;\\\"><u>以下为剧情概括，点击查看原文</u></span></a></p><blockquote style=\\\"line-height: 2;\\\"><span style=\\\"font-size: 14px;\\\">S0-1 天隙禁区</span><br>现在是森罗时间1121-04-25 13:52<br>白荆科技首席执行官，身份验证成功。</blockquote><p style=\\\"text-indent: 2em; line-height: 2;\\\">监督与苏筱正驱车前往天隙禁区，途中得知禁区外聚集了大量示威者。这些幸存者因五年前的天隙事件而饱受创伤，如今对白荆科技及其开发的X能源充满敌意，甚至将同调者视为异类。监督心中泛起一丝怅然，回忆起昔日的城市公园如今已成为禁区的一部分。</p><p style=\\\"text-indent: 2em; line-height: 2;\\\">抵达禁区外围，监督目睹了示威者与行动组队员狄砚、克里斯汀的对峙。示威者们言辞激烈，指责白荆科技是X辐射蔓延的罪魁祸首，要求停止X能源研发并驱逐同调者。就在局势即将失控之际，禁区警报突然响起——提丰子体正从矿区涌出，对众人构成威胁。</p><p style=\\\"text-indent: 2em; line-height: 2;\\\">监督意识到事态异常：这些原本只在黎威尔世界出现的虫群，为何会出现在禁区？它们的行动模式也变得更为狡猾。面对突如其来的危机，监督与行动组迅速投入战斗，试图阻止提丰子体的扩散。然而，这一切似乎只是更大风暴的前兆，监督心中隐隐不安，预感着某种未知的危险正在逼近。</p><blockquote style=\\\"line-height: 2;\\\">S0-2 虚实之辨<br>假如，我们曾陷入同一场噩梦。</blockquote><p style=\\\"text-indent: 2em; line-height: 2;\\\">在激烈的战斗中，监督敏锐地察觉到苏筱对“提丰子体”的了解似乎超出了常理。面对监督的疑问，苏筱支支吾吾地表示自己曾做过一个梦，梦中得知了这种虫群的存在。监督对此半信半疑，但无暇深究。</p><p style=\\\"text-indent: 2em; line-height: 2;\\\">随着战局推进，众人发现一处被提丰子体冲破的防线缺口，虫群正源源不断地从中涌出。狄砚提议趁敌人与机器人纠缠之际迅速清剿虫群。就在此时，一架无人机突然出现在战场上空，引起了苏筱的注意。</p><p style=\\\"text-indent: 2em; line-height: 2;\\\">狄砚的沉默让苏筱意识到，这架无人机很可能与外围的示威者有关。她惊讶于示威者的行动竟已如此猖獗，甚至动用无人机介入禁区事务。监督意识到事态正在进一步恶化，必须尽快查明真相，阻止更', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 12:41:44', 28);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (488, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.226', 'XX XX', '{\"author\":\"洛天依,鸿雁于飞,冰舞ぜ紫灵猫\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/17/lm3epnssunl5murcltixqvpg445df70_20250217120043A011.png\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"children\":[],\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"hasChildren\":false,\"id\":12,\"otext\":\"<p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\\\"line-height: 2;\\\"><br></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜里，监', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 16:58:59', 94);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (489, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.226', 'XX XX', '{\"author\":\"洛天依,奈默,鸿雁于飞,冰舞ぜ紫灵猫\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/17/lm3epnssunl5murcltixqvpg445df70_20250217120043A011.png\",\"chars\":\"监督,唐路遥,北洛（森罗）,姜宁,苏筱,霍冉,柚理,余音,十手卫,舞鹤织雪,左枢,白鸟梓,岚相,瞳,羽林,罗尼亚夫人,巫炤（森罗）,孔阳,田偌,弗吉利奥·杰诺维斯,陀螺,海伦,玄戈,北洛（黑曜）,无咎,江昙,琴初,柳叶刀,岳重山,处刑人\",\"children\":[],\"desc\":\"<p style=\\\"text-align: left;\\\"><span style=\\\"color: rgb(32, 33, 34); font-size: 14px;\\\">借一抹莹石之火，映出藏于夤夜的诡相。</span></p>\",\"hasChildren\":false,\"id\":12,\"otext\":\"<p><img src=\\\"http://r.qianqiu.info/admin/upload/2025/02/14/61e7vybb2qcnnegm0eqzal5jzryy21y_20250214112347A008.jpg\\\" alt=\\\"\\\" data-href=\\\"\\\" style=\\\"\\\"/></p><p><span style=\\\"font-size: 16px;\\\">本故事梳理由百度贴吧用户 </span><a href=\\\"https://tieba.baidu.com/home/main?id=tb.1.a5524ae5.6Srl92RL6-Zatm48rZFBUg?t=1394074424&fr=pb\\\" target=\\\"_blank\\\"><span style=\\\"font-size: 16px;\\\">冰舞ぜ紫灵猫</span></a><span style=\\\"font-size: 16px;\\\"> &nbsp;提供</span></p><p><br></p><hr/><p style=\\\"line-height: 2;\\\"><br></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.8 11:26</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">监督在船上吹海风，唐路遥给ta拿了一杯苹果茶，两人稍微聊了下森罗洛，红衣男人出现搭讪又消失了。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.9 14:28</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">白荆科技受到举报，苏筱在前台等候上门调查的刘警官和小齐警官，霍冉提醒刘警官笑里藏刀让苏筱别被套话，最后查出来举报是个网瘾少年上头行为。</span></p><ul><li style=\\\"line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">1121.6.10 13:17</span></li></ul><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">临近下船，监督换上唐路遥准备的“北三岛”当地服装“入乡随俗”。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">码头，天鹿派人来接北洛，唐路遥看出不对挡住监督，言语试探后北洛支走了唐路遥自己回去。下船时南渚放水让监督过了安检，监督顺着南渚的提示来到小巷，两人碰头，监督套话（这久违的智商压制的感觉），南渚想跑路，被余音拦下，最后约定明天再聊。</span></p><p style=\\\"text-indent: 2em; line-height: 2;\\\"><span style=\\\"color: rgb(59, 59, 59);\\\">当天夜', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 16:59:17', 56);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (490, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.226', 'XX XX', '{\"author\":\"洛天依,奈默\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/nlk4z5i2j4icff2ov45alcgjo2s3dr6_20250219095042A027.png\",\"chars\":\"花时，乐无异，雪长夏，筱筱，监督，风清洛，卯绒绒，风晴雪\",\"children\":[],\"desc\":\"<p><span style=\\\"font-size: 14px;\\\">尽情体验吧，这全新的人生。</span></p>\",\"hasChildren\":false,\"id\":21,\"otext\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1121年6月04日\",\"sort\":11210604,\"summary\":\"<p><br></p><p><span style=\\\"font-family: 宋体;\\\">海临中央警局</span></p><p><span style=\\\"font-family: 宋体;\\\">森罗历1121-06-28</span></p><p><span style=\\\"font-family: 宋体;\\\">花时报警称她的朋友雪长夏被吸进了电脑里。警局将电话转接到特殊事件处理小队，但接电话的十手卫正在执行任务，未能及时回应。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">格兰索私立高级中学</span></p><p><span style=\\\"font-family: 宋体;\\\">监督、苏筱和风清洛在格兰索私立高级中学的礼堂天台发现了雪长夏的电脑。电脑屏幕上显示着“11111……”的代码，暗示雪长夏可能被困在游戏空间中。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">初遇之章·如何成为一名勇者</span></p><p><span style=\\\"font-family: 宋体;\\\">监督、苏筱和风清洛被吸入了游戏空间《格兰索历险记》。监督变成了史莱姆，苏筱成为了勇者，风清洛则昏迷不醒。他们在游戏空间中遇到了花时、乐无异和风晴雪，逐渐揭开了游戏空间的真相。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">初遇之章·如何避免嫁给王子</span></p><p><span style=\\\"font-family: 宋体;\\\">监督等人遇到了被森林王子逼婚的花时。花时表示自己是来找乐无异和雪长夏的，但森林王子坚持要她嫁给王子。监督通过史莱姆分身术帮助花时脱身，并与森林王子展开战斗。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">初遇之章·如何摆脱王位继承</span></p><p><span style=\\\"font-family: 宋体;\\\">监督等人进入森林王子的领地，发现森林王子实际上是卯卯和绒绒。卯卯被鸡啄中后变成了狗，绒绒则继续与监督等人合作。监督通过修改任务条件，帮助卯卯和绒绒脱身。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">初遇之章·如何不被魔女毒死</span></p><p><span style=\\\"font-family: 宋体;\\\">监督等人来到魔女茶会，遇到了风晴雪。风晴雪透露自己也在寻找离开游戏空间的方法，并表示自己并不是反派。监督通过修改任务条件，将风晴雪的任务改为“保护公主”。</span></p><p><span styl', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 17:31:10', 53);
INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (491, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, 'xingfeng', '协作', '/system/story', '182.88.220.226', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095207A031.png\",\"chars\":\"监督\",\"children\":[],\"desc\":\"<p>我触摸到了那个世界。</p>\",\"hasChildren\":false,\"id\":36,\"otext\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1121年4月26日\",\"sort\":11210426,\"summary\":\"<p><br></p><p><span style=\\\"font-family: 宋体;\\\"> R1-1 回廊漫巡</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">天隙禁区·S-0-1区</span></p><p><span style=\\\"font-family: 宋体;\\\">森罗历1119-10-05 14:22</span></p><p><span style=\\\"font-family: 宋体;\\\">监督与团队在天隙禁区的S-0-1区进行“回廊漫巡”设备的铺设工作。设备调试完毕后，团队检查了电路、网络和X能辐射等各项指标，确认一切正常运行。然而，在准备启动深潜系统时，系统突然触发了多次警报，检测到天隙通道内出现了异常能量波动，疑似有异世同调者出现。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">监督通过“回廊漫巡”系统，意外看到了自己的记忆片段，回忆起1119年天隙禁区的设备铺设现场。这次实验的目的是通过深潜系统将操纵者的精神海域与天隙通道相连，从而探索通道内部的秘密。尽管遭遇了突发状况，团队在艾摩诃的指挥下迅速应对，最终成功解决了问题。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">实验成功后，白荆科技首次触摸到了“回廊”，为后续的探索奠定了基础。监督意识到，这次实验不仅是对天隙通道的探索，更是对精神海域与意识连接的突破。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">总结：</span></p><p><span style=\\\"font-family: 宋体;\\\">这次“回廊漫巡”实验标志着白荆科技在天隙通道探索中的重要突破。尽管遭遇了突发状况，但团队通过高效的协作成功完成了任务，为后续的深入研究奠定了基础。监督在实验过程中意外触发了自己的记忆片段，意识到“回廊漫巡”不仅是对天隙通道的探索，更是对精神海域与意识连接的突破。这次实验的成功为白荆科技未来的研究提供了重要的数据和经验。</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\"> R1-2 监测</span></p><p><span style=\\\"font-family: 宋体;\\\"> </span></p><p><span style=\\\"font-family: 宋体;\\\">白荆科技·高层医疗室</span></p><p><span style=\\\"font-family: 宋体;\\\">森罗历1119-10-06 18:35</span></p><p><span style=\\\"font-family: 宋体;\\\">监督前往医疗室查看体检报告，', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-19 18:42:04', 26);
