INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (685, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '218.88.28.195', 'XX XX', '{\"author\":\"洛天依\",\"banner\":\"http://r.qianqiu.info/admin/upload/2025/02/19/lurfsasa9z9g5d2dnee47ryk4los5xm_20250219095157A030.png\",\"chars\":\"监督,苏筱,曲观玄\",\"children\":[],\"desc\":\"<p>现在回想起来……就是在这一天，我们第一次代表这个世界——</p><p>——成功触摸到“回廊”。</p>\",\"hasChildren\":false,\"id\":35,\"otext\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1119年10月05日\",\"sort\":11191005,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"title\":\"万象·回忆\",\"type\":\"幕间剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-28 09:58:56\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-28 09:58:56', 34);
