INSERT INTO `sys_oper_log` (`oper_id`, `title`, `business_type`, `method`, `request_method`, `operator_type`, `oper_name`, `dept_name`, `oper_url`, `oper_ip`, `oper_location`, `oper_param`, `json_result`, `status`, `error_msg`, `oper_time`, `cost_time`) VALUES (690, '故事线', 2, 'com.ruoyi.project.system.controller.StoryController.edit()', 'PUT', 1, '洛天依', '协作', '/system/story', '218.88.28.195', 'XX XX', '{\"author\":\"洛天依\",\"children\":[],\"desc\":\"<p>战争蔓延至九旻海。西陵重工被委以重任，成为海隅理事会所主导的建设战时防御体系的主力军之一。</p><p><br></p>\",\"hasChildren\":false,\"id\":32,\"otext\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"params\":{},\"parentId\":0,\"sTime\":\"1082年\",\"sort\":10820000,\"summary\":\"<p><span style=\\\"font-size: 16px;\\\">暂无</span></p><p><span style=\\\"font-size: 16px;\\\">欢迎加入QQ群：</span><span style=\\\"font-size: 16px;\\\"><u><em><strong>977786603</strong></em></u></span><span style=\\\"font-size: 16px;\\\">，共同建设</span></p>\",\"title\":\"南半球事件\",\"type\":\"其他剧情\",\"updateBy\":\"洛天依\",\"updateTime\":\"2025-02-28 10:01:47\",\"world\":\"森罗\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2025-02-28 10:01:47', 18);
